import { Hash, Check, X } from "lucide-react";
import { useState } from "react";

import { Badge } from "~/components/ui/badge";
import { Button } from "~/components/ui/button";
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "~/components/ui/card";

interface HashTagPreset {
  id: string;
  name: string;
  tags: string;
  description?: string | null;
}

interface HashtagPresetSelectorProps {
  presets: HashTagPreset[];
  selectedPresetId?: string | null;
  onSelect: (presetId: string | null, hashtags: string) => void;
  disabled?: boolean;
}

export function HashtagPresetSelector({
  presets,
  selectedPresetId,
  onSelect,
  disabled = false,
}: HashtagPresetSelectorProps) {
  const [isExpanded, setIsExpanded] = useState(false);

  const selectedPreset = presets.find((p) => p.id === selectedPresetId);

  const handlePresetClick = (preset: HashTagPreset) => {
    if (selectedPresetId === preset.id) {
      // Deselect if clicking on already selected preset
      onSelect(null, "");
    } else {
      onSelect(preset.id, preset.tags);
    }
  };

  const handleClearSelection = () => {
    onSelect(null, "");
  };

  const countHashtags = (tags: string): number => {
    return tags
      .split(/\s+/)
      .filter((tag) => tag.startsWith("#") && tag.length > 1).length;
  };

  if (presets.length === 0) {
    return (
      <Card className="w-full">
        <CardHeader className="pb-3">
          <CardTitle className="flex items-center gap-2 text-sm">
            <Hash className="h-4 w-4" />
            Hashtag Presets
          </CardTitle>
          <CardDescription className="text-xs">
            No hashtag presets available. Create some in Settings to reuse
            hashtags across your posts.
          </CardDescription>
        </CardHeader>
      </Card>
    );
  }

  return (
    <Card className="w-full">
      <CardHeader className="pb-3">
        <div className="flex items-center justify-between">
          <div>
            <CardTitle className="flex items-center gap-2 text-sm">
              <Hash className="h-4 w-4" />
              Hashtag Presets
            </CardTitle>
            <CardDescription className="text-xs">
              {selectedPreset
                ? `Using "${selectedPreset.name}" preset`
                : "Choose a hashtag preset for this post"}
            </CardDescription>
          </div>

          {selectedPreset ? (
            <Button
              type="button"
              size="sm"
              variant="ghost"
              onClick={handleClearSelection}
              disabled={disabled}
              className="h-6 px-2 text-xs"
            >
              <X className="mr-1 h-3 w-3" />
              Clear
            </Button>
          ) : null}
        </div>

        {selectedPreset && !isExpanded ? (
          <div className="mt-3 rounded-lg bg-muted/50 p-3">
            <div className="mb-2 flex items-center gap-2">
              <h4 className="text-sm font-medium">{selectedPreset.name}</h4>
              <Badge variant="secondary" className="text-xs">
                {countHashtags(selectedPreset.tags)} tags
              </Badge>
            </div>

            {selectedPreset.description ? (
              <p className="mb-2 text-xs text-muted-foreground">
                {selectedPreset.description}
              </p>
            ) : null}

            <div className="mb-2 flex flex-wrap gap-1">
              {selectedPreset.tags
                .split(/\s+/)
                .filter((tag) => tag.startsWith("#") && tag.length > 1)
                .slice(0, 5)
                .map((tag) => (
                  <Badge
                    key={tag}
                    variant="outline"
                    className="px-2 py-0 text-xs"
                  >
                    {tag}
                  </Badge>
                ))}
              {countHashtags(selectedPreset.tags) > 5 ? (
                <Badge variant="outline" className="px-2 py-0 text-xs">
                  +{countHashtags(selectedPreset.tags) - 5} more
                </Badge>
              ) : null}
            </div>

            <Button
              type="button"
              size="sm"
              variant="ghost"
              onClick={() => setIsExpanded(true)}
              disabled={disabled}
              className="h-6 px-2 text-xs"
            >
              Change Preset
            </Button>
          </div>
        ) : null}

        {!selectedPreset || isExpanded ? (
          <Button
            type="button"
            size="sm"
            variant="ghost"
            onClick={() => setIsExpanded(!isExpanded)}
            disabled={disabled}
            className="mt-2 h-6 px-2 text-xs"
          >
            {isExpanded ? "Show Less" : "Show Presets"}
          </Button>
        ) : null}
      </CardHeader>

      {!selectedPreset || isExpanded ? (
        <CardContent className="pt-0">
          <div className="max-h-64 overflow-y-auto">
            <div className="space-y-2">
              {presets.map((preset) => {
                const handleKeyDown = (e: React.KeyboardEvent) => {
                  if (!disabled && (e.key === "Enter" || e.key === " ")) {
                    e.preventDefault();
                    handlePresetClick(preset);
                  }
                };

                return (
                  <div
                    key={preset.id}
                    className={`cursor-pointer rounded-lg border p-3 transition-colors ${
                      selectedPresetId === preset.id
                        ? "border-primary bg-primary/10"
                        : "hover:bg-accent/50"
                    } ${disabled ? "cursor-not-allowed opacity-50" : ""}`}
                    onClick={() => !disabled && handlePresetClick(preset)}
                    onKeyDown={handleKeyDown}
                    role="button"
                    tabIndex={disabled ? -1 : 0}
                  >
                    <div className="flex items-start justify-between">
                      <div className="min-w-0 flex-1">
                        <div className="mb-1 flex items-center gap-2">
                          <h4 className="text-sm font-medium">{preset.name}</h4>
                          <Badge variant="secondary" className="text-xs">
                            {countHashtags(preset.tags)} tags
                          </Badge>
                          {selectedPresetId === preset.id ? (
                            <Check className="h-4 w-4 text-primary" />
                          ) : null}
                        </div>

                        {preset.description ? (
                          <p className="mb-2 text-xs text-muted-foreground">
                            {preset.description}
                          </p>
                        ) : null}

                        <div className="flex flex-wrap gap-1">
                          {preset.tags
                            .split(/\s+/)
                            .filter(
                              (tag) => tag.startsWith("#") && tag.length > 1,
                            )
                            .slice(0, 3)
                            .map((tag) => (
                              <Badge
                                key={tag}
                                variant="outline"
                                className="px-2 py-0 text-xs"
                              >
                                {tag}
                              </Badge>
                            ))}
                          {countHashtags(preset.tags) > 3 ? (
                            <Badge
                              variant="outline"
                              className="px-2 py-0 text-xs"
                            >
                              +{countHashtags(preset.tags) - 3} more
                            </Badge>
                          ) : null}
                        </div>
                      </div>
                    </div>
                  </div>
                );
              })}
            </div>
          </div>

          {isExpanded && selectedPreset ? (
            <Button
              type="button"
              size="sm"
              variant="ghost"
              onClick={() => setIsExpanded(false)}
              disabled={disabled}
              className="mt-2 h-6 w-full px-2 text-xs"
            >
              Show Selected Only
            </Button>
          ) : null}
        </CardContent>
      ) : null}
    </Card>
  );
}

import { Badge } from "~/components/ui/badge";
import { Checkbox } from "~/components/ui/checkbox";
import { Label } from "~/components/ui/label";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "~/components/ui/select";

interface HashTagPreset {
  id: string;
  name: string;
  tags: string;
  description?: string | null;
}

interface QueueType {
  id: string;
  name: string;
  hashTagPreset?: HashTagPreset | null;
}

interface HashtagPresetToggleProps {
  presets: HashTagPreset[];
  selectedPresetId?: string | null;
  onSelect: (presetId: string | null, hashtags: string) => void;
  disabled?: boolean;
  showQueuePreset?: boolean;
  queueType?: QueueType | null;
  useHashtagPresets?: boolean;
  onUseHashtagPresetsChange?: (enabled: boolean) => void;
}

export function HashtagPresetToggle({
  presets,
  selectedPresetId,
  onSelect,
  disabled = false,
  showQueuePreset = false,
  queueType = null,
  useHashtagPresets = false,
  onUseHashtagPresetsChange,
}: HashtagPresetToggleProps) {
  const selectedPreset = presets.find((p) => p.id === selectedPresetId);

  const handlePresetChange = (value: string) => {
    if (value === "none") {
      onSelect(null, "");
    } else {
      const preset = presets.find((p) => p.id === value);
      onSelect(preset?.id ?? null, preset?.tags ?? "");
    }
  };

  const countHashtags = (tags: string): number => {
    return tags
      .split(/\s+/)
      .filter((tag) => tag.startsWith("#") && tag.length > 1).length;
  };

  return (
    <div className="space-y-4">
      {/* Toggle checkbox for hashtag presets */}
      <div className="flex items-center space-x-2">
        <Checkbox
          id="use-hashtag-presets"
          checked={useHashtagPresets}
          onCheckedChange={(checked) => onUseHashtagPresetsChange?.(!!checked)}
          disabled={disabled}
        />
        <Label
          htmlFor="use-hashtag-presets"
          className="cursor-pointer text-sm font-medium text-gray-700 dark:text-gray-300"
        >
          Use Hashtag Presets
        </Label>
      </div>

      {/* Show queue type's hashtag preset info when available */}
      {showQueuePreset && queueType?.hashTagPreset ? (
        <div
          className={`rounded-lg p-3 ${
            useHashtagPresets
              ? "border border-gray-200 bg-gray-50 dark:border-gray-700 dark:bg-gray-800"
              : "border border-green-200 bg-green-50 dark:border-green-800 dark:bg-green-900/20"
          }`}
        >
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-2">
              <span className="text-sm font-medium text-gray-700 dark:text-gray-300">
                {useHashtagPresets ? "Queue Default:" : "Using Queue Default:"}
              </span>
              <Badge variant="secondary" className="text-xs">
                {queueType.hashTagPreset.name}
              </Badge>
              <span className="text-xs text-gray-500 dark:text-gray-400">
                ({countHashtags(queueType.hashTagPreset.tags)} tags)
              </span>
            </div>
          </div>
          {!useHashtagPresets ? (
            <div className="mt-2 flex flex-wrap gap-1">
              {queueType.hashTagPreset.tags
                .split(/\s+/)
                .filter((tag) => tag.startsWith("#") && tag.length > 1)
                .slice(0, 4)
                .map((tag) => (
                  <Badge
                    key={tag}
                    variant="outline"
                    className="px-2 py-0.5 text-xs"
                  >
                    {tag}
                  </Badge>
                ))}
              {countHashtags(queueType.hashTagPreset.tags) > 4 ? (
                <Badge variant="outline" className="px-2 py-0.5 text-xs">
                  +{countHashtags(queueType.hashTagPreset.tags) - 4} more
                </Badge>
              ) : null}
            </div>
          ) : null}
        </div>
      ) : null}

      {/* Hashtag preset selector */}
      {useHashtagPresets ? (
        <div className="space-y-3">
          {presets.length === 0 ? (
            <div className="rounded-lg border border-yellow-200 bg-yellow-50 p-3 dark:border-yellow-800 dark:bg-yellow-900/20">
              <p className="text-sm text-yellow-700 dark:text-yellow-300">
                No hashtag presets available. Create some in Settings to reuse
                hashtags across your posts.
              </p>
            </div>
          ) : (
            <>
              <div className="space-y-2">
                <Label className="text-sm font-medium text-gray-700 dark:text-gray-300">
                  Choose Hashtag Preset
                </Label>
                <Select
                  value={selectedPresetId ?? "none"}
                  onValueChange={handlePresetChange}
                  disabled={disabled}
                >
                  <SelectTrigger className="w-full">
                    <SelectValue placeholder="Select a hashtag preset" />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="none">
                      <span className="text-gray-500">No hashtag preset</span>
                    </SelectItem>
                    {presets.map((preset) => (
                      <SelectItem key={preset.id} value={preset.id}>
                        <div className="flex w-full items-center justify-between">
                          <span className="font-medium">{preset.name}</span>
                          <Badge variant="secondary" className="ml-2 text-xs">
                            {countHashtags(preset.tags)}
                          </Badge>
                        </div>
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>

              {/* Selected preset preview */}
              {selectedPreset ? (
                <div className="rounded-lg border border-gray-200 bg-gray-50 p-3 dark:border-gray-700 dark:bg-gray-800">
                  <div className="mb-2 flex items-center gap-2">
                    <span className="text-sm font-medium text-gray-700 dark:text-gray-300">
                      {selectedPreset.name}
                    </span>
                    <Badge variant="secondary" className="text-xs">
                      {countHashtags(selectedPreset.tags)} tags
                    </Badge>
                  </div>
                  {selectedPreset.description ? (
                    <p className="mb-2 text-xs text-gray-500 dark:text-gray-400">
                      {selectedPreset.description}
                    </p>
                  ) : null}
                  <div className="flex flex-wrap gap-1">
                    {selectedPreset.tags
                      .split(/\s+/)
                      .filter((tag) => tag.startsWith("#") && tag.length > 1)
                      .slice(0, 6)
                      .map((tag) => (
                        <Badge
                          key={tag}
                          variant="outline"
                          className="px-2 py-0.5 text-xs"
                        >
                          {tag}
                        </Badge>
                      ))}
                    {countHashtags(selectedPreset.tags) > 6 ? (
                      <Badge variant="outline" className="px-2 py-0.5 text-xs">
                        +{countHashtags(selectedPreset.tags) - 6} more
                      </Badge>
                    ) : null}
                  </div>
                </div>
              ) : null}
            </>
          )}
        </div>
      ) : null}
    </div>
  );
}

import { PlayIcon } from "@heroicons/react/20/solid";
import React from "react";
interface MediaThumbnailProps {
  src: string | undefined | null;
  alt?: string;
  className?: string;
  onClick?: () => void;
  forceType?: "image" | "video";
  onError?: () => void;
  fallback?: React.ReactNode;
  hidePlayButton?: boolean;
}

const MediaThumbnail: React.FC<MediaThumbnailProps> = ({
  src,
  alt = "Media thumbnail",
  className = "",
  onClick,
  forceType,
  onError,
  fallback,
  hidePlayButton = false,
}) => {
  const [hasError, setHasError] = React.useState(false);

  // Reset error state when src changes
  React.useEffect(() => {
    setHasError(false);
  }, [src]);

  // Determine if the source is a video based on extension, unless forceType is provided
  const isVideo = React.useMemo(() => {
    if (forceType === "video") return true;
    if (forceType === "image") return false;
    // Handle undefined/null src safely
    if (!src || typeof src !== "string") return false;
    const lower = src.toLowerCase();
    const videoExtensions = [
      ".mp4",
      ".webm",
      ".ogg",
      ".mov",
      ".avi",
      ".mkv",
      ".m4v",
    ];
    return videoExtensions.some((ext) => lower.includes(ext));
  }, [src, forceType]);

  // Handle missing src early
  if (!src || typeof src !== "string") {
    if (fallback) return <>{fallback}</>;
    return (
      <div
        className={`flex items-center justify-center bg-gray-100 text-xs font-medium text-gray-500 dark:bg-gray-700 dark:text-gray-400 ${className}`}
      >
        NO MEDIA
      </div>
    );
  }

  const handleImageError = () => {
    setHasError(true);
    onError?.();
  };

  const handleImageLoad = () => {
    // Image loaded successfully
  };

  // Return fallback if there's an error
  if (hasError && fallback) {
    return <>{fallback}</>;
  }

  // Return generic fallback for broken images
  if (hasError) {
    return (
      <div
        className={`flex items-center justify-center bg-gray-100 text-xs font-medium text-gray-500 dark:bg-gray-700 dark:text-gray-400 ${className}`}
      >
        TEXT
      </div>
    );
  }

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (onClick && (e.key === "Enter" || e.key === " ")) {
      e.preventDefault();
      onClick();
    }
  };

  if (!isVideo) {
    // Render image thumbnail
    return (
      // eslint-disable-next-line jsx-a11y/no-noninteractive-element-interactions -- Image thumbnails need click handlers for preview
      <img
        src={src}
        alt={alt}
        className={`${className} ${onClick ? "cursor-pointer hover:opacity-75" : ""}`}
        onClick={onClick}
        onKeyDown={onClick ? handleKeyDown : undefined}
        role={onClick ? "button" : undefined}
        tabIndex={onClick ? 0 : undefined}
        loading="lazy"
        onError={handleImageError}
        onLoad={handleImageLoad}
      />
    );
  }

  // Render video thumbnail with play button overlay
  return (
    // eslint-disable-next-line jsx-a11y/no-static-element-interactions -- onClick is optional, role and tabIndex are conditionally set
    <div
      className={`relative ${className} ${onClick ? "cursor-pointer hover:opacity-75" : ""}`}
      onClick={onClick}
      onKeyDown={onClick ? handleKeyDown : undefined}
      {...(onClick && { role: "button", tabIndex: 0 })}
    >
      {}
      <video
        src={src}
        className="h-full w-full object-cover"
        preload="metadata"
        muted
        controls={false}
        disablePictureInPicture
        onError={handleImageError}
        onLoadedData={handleImageLoad}
      />
      {!hidePlayButton ? (
        <div className="absolute inset-0 flex items-center justify-center">
          <div className="rounded-full bg-black bg-opacity-60 p-2 shadow-lg">
            <PlayIcon className="h-6 w-6 text-white drop-shadow-sm" />
          </div>
        </div>
      ) : null}
    </div>
  );
};

export default MediaThumbnail;

