import { Link, useFetcher, useLocation } from "@remix-run/react";
import { useCallback } from "react";

import { Avatar, AvatarFallback, AvatarImage } from "~/components/ui/avatar";
import { Button } from "~/components/ui/button";
import { handleAsyncError } from "~/lib/error-handler.client";
import { useOptionalUser } from "~/lib/remix-utils";
export default function NostrAuthButton() {
  const user = useOptionalUser() ?? null;
  const fetcher = useFetcher();
  const location = useLocation();

  const handleNostrLogin = useCallback(() => {
    void (async () => {
      try {
        // Load and initialize nostr-login when button is clicked
        // @ts-ignore - Dynamic imports work in client-side Remix bundles
        const { init } = await import("nostr-login");

        await init({
          methods: ["connect", "extension"],
          noBanner: true,
          onAuth: () => {
            void (async () => {
              try {
                // @ts-ignore - window.nostr is injected by browser extensions at runtime
                if (!window.nostr) {
                  throw new Error(
                    "Nostr extension not found. Please install a Nostr extension like Alby or nos2x."
                  );
                }

                const randomKeys = () => {
                  const chars =
                    "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789";
                  let result = "";
                  for (let i = 0; i < 10; i++) {
                    result += chars.charAt(
                      Math.floor(Math.random() * chars.length)
                    );
                  }
                  return result;
                };
                const contentSign = `Login request ${randomKeys()}`;
                const event = {
                  kind: 27235,
                  created_at: Math.floor(Date.now() / 1000),
                  tags: [],
                  content: contentSign,
                };

                // @ts-ignore - window.nostr is injected by browser extensions at runtime
                const signedEvent = await window.nostr.signEvent(event);

                const formData = new FormData();
                formData.append("pubkey", signedEvent.pubkey);
                formData.append("signature", signedEvent.sig);
                formData.append("event", JSON.stringify(signedEvent));
                formData.append("contentSign", contentSign);

                // Submit auth request
                fetcher.submit(formData, {
                  method: "post",
                  action: "/nostr-auth",
                });
              } catch (authError) {
                handleAsyncError(
                  authError,
                  {
                    component: "NostrAuthButton",
                    action: "onAuth",
                  },
                  true
                );
              }
            })();
          },
        });

        // Trigger the login modal
        document.dispatchEvent(
          new CustomEvent("nlLaunch", { detail: "welcome" })
        );
      } catch (error) {
        // Log and handle error
        handleAsyncError(
          error,
          {
            component: "NostrAuthButton",
            action: "handleNostrLogin",
          },
          true
        );
      }
    })();
  }, [fetcher]);

  const handleLogout = useCallback(
    (event: React.FormEvent<HTMLFormElement>) => {
      event.preventDefault();
      // Dispatch nostr logout event
      document.dispatchEvent(new Event("nlLogout"));

      // Submit the logout form after a small delay to ensure nostr logout completes
      setTimeout(() => {
        if (event.target instanceof HTMLFormElement) {
          event.target.submit();
        }
      }, 100);
    },
    []
  );

  return (
    <>
      {user ? (
        <>
          <div className="flex items-center gap-3">
            <Avatar>
              <AvatarImage
                src={
                  typeof user === "object" &&
                  "nostrProfile" in user &&
                  typeof user.nostrProfile === "object" &&
                  user.nostrProfile !== null &&
                  "picture" in user.nostrProfile
                    ? String(user.nostrProfile["picture"])
                    : undefined
                }
                alt="Profile"
              />
              <AvatarFallback>
                {typeof user === "object" &&
                "nostrProfile" in user &&
                typeof user.nostrProfile === "object" &&
                user.nostrProfile !== null
                  ? (("name" in user.nostrProfile && user.nostrProfile["name"]
                      ? String(user.nostrProfile["name"])[0]
                      : null) ??
                    ("display_name" in user.nostrProfile &&
                    user.nostrProfile["display_name"]
                      ? String(user.nostrProfile["display_name"])[0]
                      : null) ??
                    "U")
                  : "U"}
              </AvatarFallback>
            </Avatar>
            <span className="hidden sm:inline">
              {typeof user === "object" &&
              "nostrProfile" in user &&
              typeof user.nostrProfile === "object" &&
              user.nostrProfile !== null
                ? (("name" in user.nostrProfile && user.nostrProfile["name"]
                    ? String(user.nostrProfile["name"])
                    : null) ??
                  ("display_name" in user.nostrProfile &&
                  user.nostrProfile["display_name"]
                    ? String(user.nostrProfile["display_name"])
                    : null) ??
                  ("npub" in user && user.npub
                    ? `${String(user.npub).slice(0, 12)}...${String(user.npub).slice(-8)}`
                    : ""))
                : typeof user === "object" &&
                    "npub" in user &&
                    user.npub
                  ? `${String(user.npub).slice(0, 12)}...${String(user.npub).slice(-8)}`
                  : ""}
            </span>
            {location.pathname === "/" ? (
              <Button variant="outline" size="sm" asChild>
                <Link to="/dashboard">Dashboard</Link>
              </Button>
            ) : null}
            <form action="/logout" method="post" onSubmit={handleLogout}>
              <Button variant="outline" size="sm" type="submit">
                Logout
              </Button>
            </form>
          </div>
        </>
      ) : (
        <Button
          onClick={handleNostrLogin}
          disabled={fetcher.state === "submitting"}
          className="bg-gradient-to-r from-purple-500 to-indigo-600 font-bold text-white hover:from-purple-600 hover:to-indigo-700"
          size="lg"
          type="button"
        >
          {fetcher.state === "submitting"
            ? "Logging in..."
            : "Login with Nostr 🪿"}
        </Button>
      )}
    </>
  );
}

import { formatDate } from "~/lib/helpers";

import type { ChildReply } from "../hooks/useNotificationActions";
interface ChildRepliesPanelProps {
  isLoading: boolean;
  replies: ChildReply[];
  metadata: Record<string, unknown>;
}

export function ChildRepliesPanel({
  isLoading,
  replies,
  metadata,
}: ChildRepliesPanelProps) {
  if (isLoading) {
    return (
      <div className="mt-3 border-l-2 border-indigo-200 pl-3 dark:border-indigo-800">
        <div className="flex items-center gap-2 text-xs text-gray-500 dark:text-gray-400">
          <svg className="h-4 w-4 animate-spin" fill="none" viewBox="0 0 24 24">
            <circle
              className="opacity-25"
              cx="12"
              cy="12"
              r="10"
              stroke="currentColor"
              strokeWidth="4"
            ></circle>
            <path
              className="opacity-75"
              fill="currentColor"
              d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"
            ></path>
          </svg>
          Loading replies...
        </div>
      </div>
    );
  }

  if (replies.length === 0) {
    return (
      <div className="mt-3 border-l-2 border-indigo-200 pl-3 dark:border-indigo-800">
        <div className="text-xs text-gray-500 dark:text-gray-400">
          No replies yet
        </div>
      </div>
    );
  }

  return (
    <div className="mt-3 space-y-2 border-l-2 border-indigo-200 pl-3 dark:border-indigo-800">
      {replies.map((reply) => {
        const replyMetadata = metadata[reply.pubkey];
        let replyAuthorName =
          reply.pubkey.substring(0, 8) + "..." + reply.pubkey.slice(-4);
        let replyAuthorPicture = null;

        if (replyMetadata) {
          try {
            const metadataContent =
              typeof replyMetadata === "object" &&
              !Array.isArray(replyMetadata) &&
              "content" in replyMetadata
                ? (replyMetadata as { content?: unknown }).content
                : null;
            const profile =
              typeof metadataContent === "string"
                ? (JSON.parse(metadataContent) as Record<string, unknown>)
                : metadataContent &&
                    typeof metadataContent === "object" &&
                    !Array.isArray(metadataContent)
                  ? (metadataContent as Record<string, unknown>)
                  : null;
            if (profile && typeof profile === "object") {
              replyAuthorName =
                (profile as { display_name?: string; name?: string })
                  .display_name ??
                (profile as { name?: string }).name ??
                replyAuthorName;
              replyAuthorPicture =
                (profile as { picture?: string | null }).picture ?? null;
            }
          } catch (_e) {
            // Ignore parsing errors
          }
        }

        return (
          <div
            key={reply.id}
            className="rounded-lg border border-gray-200 bg-gray-50 p-2 dark:border-gray-700 dark:bg-gray-800/50"
          >
            <div className="mb-1 flex items-center gap-2">
              {replyAuthorPicture ? (
                <img
                  src={replyAuthorPicture}
                  alt={replyAuthorName}
                  className="h-6 w-6 rounded-full"
                />
              ) : (
                <div className="h-6 w-6 rounded-full bg-gray-300 dark:bg-gray-600" />
              )}
              <span className="text-xs font-semibold text-gray-900 dark:text-gray-100">
                {replyAuthorName}
              </span>
              <span className="text-xs text-gray-500 dark:text-gray-400">
                {formatDate(new Date(reply.created_at * 1000).toISOString())}
              </span>
            </div>
            <p className="whitespace-pre-wrap break-words text-xs text-gray-700 dark:text-gray-300">
              {reply.content}
            </p>
          </div>
        );
      })}
    </div>
  );
}

