import { useFetcher, useLoaderData } from "@remix-run/react";
import { useEffect, useState } from "react";
import { toast } from "react-hot-toast";

import MediaThumbnail from "~/components/ui/MediaThumbnail";
import { handleErrorSafely } from "~/lib/error-handler.client";
import { isVideoFile } from "~/lib/helpers";
import { nostrAdapter } from "~/lib/nostr-adapter.client";

import type { QueueType, UserData } from "../../types";

import type { CalendarPost } from "./PostBlock.types";
interface RescheduleData {
  post: CalendarPost;
  newDateTime: Date;
  wasAutoScheduled: boolean;
  queueName: string | null;
  isEdit: boolean;
  isLongform: boolean;
}

interface RescheduleModalProps {
  data: RescheduleData | null;
  onClose: () => void;
  onConfirm: (success?: boolean) => void;
  user?: UserData | null;
  queueTypes?: QueueType[];
}

export function RescheduleModal({
  data,
  onClose,
  onConfirm,
  user: userProp,
  queueTypes,
}: RescheduleModalProps) {
  interface FetcherData {
    success?: boolean;
    needsSigning?: boolean;
    error?: string;
  }

  const fetcher = useFetcher<FetcherData>();
  const loaderData = useLoaderData<{ user?: UserData }>();
  const user = userProp ?? loaderData.user;
  const [isSigningEvent, setIsSigningEvent] = useState(false);
  const [signingError, setSigningError] = useState<string | null>(null);
  const [editableDateTime, setEditableDateTime] = useState<Date | null>(null);
  const [validationError, setValidationError] = useState<string | null>(null);
  const [selectedQueueType, setSelectedQueueType] = useState<string | null>(
    null
  );

  useEffect(() => {
    if (fetcher.data?.success) {
      if (fetcher.data.needsSigning) {
        // Event was rescheduled but needs re-signing, keep modal open
        return;
      }
      toast.success("Post rescheduled and re-signed successfully!");
      onConfirm(true);
    }
    if (fetcher.data?.error) {
      toast.error(`Reschedule failed: ${fetcher.data.error}`);
    }
  }, [fetcher.data, onConfirm]);

  // Initialize editable datetime and queue type when data changes
  useEffect(() => {
    if (data) {
      setEditableDateTime(data.newDateTime);
      setValidationError(null);
      setSelectedQueueType(data.post.queueType?.id ?? null);
    }
  }, [data]);

  if (!data) return null;

  const { post, wasAutoScheduled, isEdit } = data;

  const getFirstMedia = (): string | null => {
    if (data.isLongform && post.image) {
      return post.image;
    }

    if (post.fileUrl.length > 0) {
      try {
        const firstFileUrl = post.fileUrl[0];
        if (typeof firstFileUrl === "string") {
          try {
            const parsed = JSON.parse(firstFileUrl) as string[] | string;
            return Array.isArray(parsed) ? (parsed[0] ?? null) : firstFileUrl;
          } catch {
            return firstFileUrl;
          }
        }
        return (firstFileUrl as string | undefined) ?? null;
      } catch (error) {
        handleErrorSafely(error, {
          component: "RescheduleModal",
          action: "getFirstMedia",
        });
        return null;
      }
    }
    return null;
  };

  const formatDateTime = (date: Date): string => {
    const userTimezone = user?.timezone ?? "Etc/UTC";
    return date.toLocaleDateString("en-US", {
      weekday: "long",
      month: "long",
      day: "numeric",
      hour: "2-digit",
      minute: "2-digit",
      timeZone: userTimezone,
    });
  };

  const validateDateTime = (dateTime: Date | null): boolean => {
    if (!dateTime) return false;
    const now = new Date();
    const userTimezone = user?.timezone ?? "Etc/UTC";
    const nowInUserTz = new Date(
      now.toLocaleString("en-US", { timeZone: userTimezone })
    );

    if (dateTime <= nowInUserTz) {
      setValidationError("Cannot schedule posts in the past");
      return false;
    }

    setValidationError(null);
    return true;
  };

  const handleDateTimeChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const newValue = new Date(e.target.value);
    setEditableDateTime(newValue);
    validateDateTime(newValue);
  };

  const formatDateTimeForInput = (date: Date): string => {
    const userTimezone = user?.timezone ?? "Etc/UTC";
    // Create date string in format needed for datetime-local input
    const dateInUserTz = new Date(
      date.toLocaleString("en-US", { timeZone: userTimezone })
    );
    const year = dateInUserTz.getFullYear();
    const month = String(dateInUserTz.getMonth() + 1).padStart(2, "0");
    const day = String(dateInUserTz.getDate()).padStart(2, "0");
    const hours = String(dateInUserTz.getHours()).padStart(2, "0");
    const minutes = String(dateInUserTz.getMinutes()).padStart(2, "0");
    return `${year}-${month}-${day}T${hours}:${minutes}`;
  };

  const handleConfirm = async (shouldOverride = false) => {
    // Validate the selected time
    if (!validateDateTime(editableDateTime)) {
      return;
    }

    if (!editableDateTime) return;

    const newTimeUnix = Math.floor(editableDateTime.getTime() / 1000);

    try {
      setIsSigningEvent(true);

      // Use the exact same content and tags from the original signed event
      const originalSignedEvent = post.signedEvent as
        | { content: string; kind?: number; tags?: string[][] }
        | undefined;
      const originalNostrEvent = post.nostrEvent;

      if (!originalSignedEvent || !originalNostrEvent) {
        throw new Error(
          "Original event not found. Cannot reschedule unsigned posts."
        );
      }

      // Re-sign with the same content but new timestamp
      const { nostrEvent, signedEvent } = await nostrAdapter.signEvent({
        content: originalSignedEvent.content, // Use exact same content
        created_at: newTimeUnix, // Only change the timestamp
        kind: originalSignedEvent.kind ?? 1,
        tags: originalSignedEvent.tags ?? [], // Use exact same tags
      });

      // Submit the reschedule action with signed event
      const formData = new FormData();
      formData.append("action", "reschedule");
      formData.append("postId", post.id);
      formData.append("newTime", newTimeUnix.toString());
      formData.append("overrideQueue", shouldOverride.toString());
      formData.append("signedEvent", JSON.stringify(signedEvent));
      formData.append("nostrEvent", JSON.stringify(nostrEvent));
      if (selectedQueueType) {
        formData.append("queueTypeId", selectedQueueType);
      }

      fetcher.submit(formData, { method: "post" });
    } catch (error) {
      console.error("Error re-signing event:", error);
      setIsSigningEvent(false);
      const errorMessage =
        error instanceof Error
          ? error.message
          : "Failed to sign event. Please try again.";
      setSigningError(errorMessage);
      toast.error(errorMessage);
    }
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 p-4">
      <div className="w-full max-w-md rounded-lg bg-white shadow-xl dark:bg-gray-800">
        <div className="p-6">
          {/* Header */}
          <div className="mb-4 flex items-center justify-between">
            <h3 className="text-lg font-semibold text-gray-900 dark:text-white">
              {isEdit
                ? "Edit Post Schedule"
                : wasAutoScheduled
                  ? "Override Queue Logic?"
                  : "Update Post Time?"}
            </h3>
            <button
              onClick={onClose}
              className="text-gray-400 hover:text-gray-600 dark:hover:text-gray-200"
            >
              <svg
                className="h-6 w-6"
                fill="none"
                stroke="currentColor"
                viewBox="0 0 24 24"
              >
                <path
                  strokeLinecap="round"
                  strokeLinejoin="round"
                  strokeWidth={2}
                  d="M6 18L18 6M6 6l12 12"
                />
              </svg>
            </button>
          </div>

          {/* Content */}
          <div className="space-y-4">
            {/* Post preview */}
            <div className="rounded-lg bg-gray-50 p-3 dark:bg-gray-700">
              <div className="mb-2 text-sm font-medium text-gray-900 dark:text-white">
                Post Preview:
              </div>

              {/* Show media thumbnail if available */}
              {getFirstMedia() ? (
                <div className="mb-2">
                  <div className="post-thumbnail h-20 w-full overflow-hidden rounded-md">
                    <MediaThumbnail
                      src={getFirstMedia()}
                      alt="Post preview"
                      className="h-full w-full rounded-md"
                      forceType={
                        isVideoFile(getFirstMedia()!) ? "video" : "image"
                      }
                      hidePlayButton={false}
                      fallback={
                        <div className="flex h-full w-full items-center justify-center bg-gray-100 text-xs font-medium text-gray-500 dark:bg-gray-700 dark:text-gray-400">
                          {post.postType === "VIDEO" ||
                          isVideoFile(getFirstMedia()!)
                            ? "VIDEO"
                            : "MEDIA"}
                        </div>
                      }
                    />
                  </div>
                </div>
              ) : null}

              <div className="text-sm text-gray-600 dark:text-gray-300">
                {post.caption ? (
                  <span
                    style={{
                      display: "inline-block",
                      maxWidth: "100%",
                      wordBreak: "break-word",
                      whiteSpace: "pre-line",
                      overflowWrap: "anywhere",
                    }}
                  >
                    {post.caption}
                  </span>
                ) : (
                  "No caption"
                )}
                {post.fileUrl.length > 0 ? (
                  <span className="ml-2 text-xs text-gray-500">
                    ({post.fileUrl.length} file
                    {post.fileUrl.length > 1 ? "s" : ""})
                  </span>
                ) : null}
              </div>
            </div>

            {/* New time */}
            <div className="space-y-2">
              <label
                htmlFor="reschedule-datetime"
                className="block text-sm font-medium text-gray-700 dark:text-gray-300"
              >
                {isEdit ? "Edit scheduled time:" : "New time:"}
              </label>
              <div className="flex items-center space-x-2">
                <svg
                  className="h-4 w-4 text-gray-400"
                  fill="none"
                  stroke="currentColor"
                  viewBox="0 0 24 24"
                >
                  <path
                    strokeLinecap="round"
                    strokeLinejoin="round"
                    strokeWidth={2}
                    d="M8 7V3m8 4V3m-9 8h10M5 21h14a2 2 0 002-2V7a2 2 0 00-2-2H5a2 2 0 00-2 2v12a2 2 0 002 2z"
                  />
                </svg>
                <input
                  id="reschedule-datetime"
                  type="datetime-local"
                  value={
                    editableDateTime
                      ? formatDateTimeForInput(editableDateTime)
                      : ""
                  }
                  onChange={handleDateTimeChange}
                  className="flex-1 rounded-md border border-gray-300 bg-white px-3 py-2 text-sm text-gray-900 focus:border-blue-500 focus:ring-2 focus:ring-blue-500 dark:border-gray-600 dark:bg-gray-800 dark:text-white"
                />
              </div>
              {editableDateTime ? (
                <div className="text-xs text-gray-500 dark:text-gray-400">
                  {formatDateTime(editableDateTime)}
                </div>
              ) : null}
            </div>

            {/* Queue Type Selection */}
            <div className="space-y-2">
              <label
                htmlFor="reschedule-queue-type"
                className="block text-sm font-medium text-gray-700 dark:text-gray-300"
              >
                Queue Type:
              </label>
              <select
                id="reschedule-queue-type"
                value={selectedQueueType ?? ""}
                onChange={(e) => setSelectedQueueType(e.target.value || null)}
                className="w-full rounded-md border border-gray-300 bg-white px-3 py-2 text-sm text-gray-900 focus:border-blue-500 focus:ring-2 focus:ring-blue-500 dark:border-gray-600 dark:bg-gray-800 dark:text-white"
              >
                <option value="">Manual (No Queue)</option>
                {queueTypes
                  ? queueTypes.map((queueType) => (
                      <option key={queueType.id} value={queueType.id}>
                        {queueType.name}
                      </option>
                    ))
                  : null}
              </select>
              <div className="text-xs text-gray-500 dark:text-gray-400">
                {selectedQueueType
                  ? "Post will be managed by the selected queue type"
                  : "Post will be manually scheduled"}
              </div>
            </div>

            {/* Re-signing warning */}
            <div className="rounded-lg border border-blue-200 bg-blue-50 p-3 dark:border-blue-800 dark:bg-blue-900/20">
              <div className="flex items-start space-x-2">
                <svg
                  className="mt-0.5 h-5 w-5 flex-shrink-0 text-blue-600 dark:text-blue-400"
                  fill="currentColor"
                  viewBox="0 0 20 20"
                >
                  <path
                    fillRule="evenodd"
                    d="M18 10a8 8 0 11-16 0 8 8 0 0116 0zm-7-4a1 1 0 11-2 0 1 1 0 012 0zM9 9a1 1 0 000 2v3a1 1 0 001 1h1a1 1 0 100-2v-3a1 1 0 00-1-1H9z"
                    clipRule="evenodd"
                  />
                </svg>
                <div>
                  <div className="text-sm font-medium text-blue-800 dark:text-blue-200">
                    {isEdit ? "Editing this post" : "Rescheduling this post"}{" "}
                    requires re-signing the Nostr event
                  </div>
                  <div className="mt-1 text-xs text-blue-700 dark:text-blue-300">
                    Your Nostr client will prompt you to sign the updated event
                    with the new timestamp.
                  </div>
                </div>
              </div>
            </div>

            {/* Validation error */}
            {validationError ? (
              <div className="rounded-lg border border-red-200 bg-red-50 p-3 dark:border-red-800 dark:bg-red-900/20">
                <div className="text-sm text-red-800 dark:text-red-200">
                  {validationError}
                </div>
              </div>
            ) : null}

            {/* Error display */}
            {(fetcher.data?.error ?? signingError) ? (
              <div className="rounded-lg border border-red-200 bg-red-50 p-3 dark:border-red-800 dark:bg-red-900/20">
                <div className="text-sm text-red-800 dark:text-red-200">
                  {fetcher.data?.error ?? signingError}
                </div>
              </div>
            ) : null}
          </div>

          {/* Actions */}
          <div className="mt-6 flex items-center justify-end space-x-3">
            <button
              onClick={onClose}
              className="px-4 py-2 text-sm font-medium text-gray-700 hover:text-gray-900 dark:text-gray-300 dark:hover:text-white"
            >
              Cancel
            </button>

            {wasAutoScheduled && Boolean(wasAutoScheduled) ? (
              <button
                onClick={() => void handleConfirm(false)}
                className="rounded-lg border border-blue-300 px-4 py-2 text-sm font-medium text-blue-600 hover:bg-blue-50 hover:text-blue-700 dark:border-blue-600 dark:text-blue-400 dark:hover:bg-blue-900/20 dark:hover:text-blue-300"
              >
                Keep Queue Rule
              </button>
            ) : null}

            <button
              onClick={() => void handleConfirm(wasAutoScheduled)}
              className="rounded-lg bg-blue-600 px-4 py-2 text-sm font-medium text-white hover:bg-blue-700 disabled:cursor-not-allowed disabled:opacity-50"
              disabled={
                fetcher.state === "submitting" ||
                isSigningEvent ||
                !!validationError
              }
            >
              {isSigningEvent
                ? "Signing Event..."
                : fetcher.state === "submitting"
                  ? "Updating..."
                  : isEdit
                    ? "Save Changes"
                    : wasAutoScheduled
                      ? "Convert to Manual"
                      : "Confirm"}
            </button>
          </div>
        </div>
      </div>
    </div>
  );
}

import type { PostFetcher } from "../types";

const PROCESSING_TEXT = "Processing...";

interface ContentBulkActionsProps {
  type: "scheduled" | "draft" | "posted";
  selectedCount: number;
  onBulkDelete: () => void;
  onBulkRepost?: () => void;
  onBulkScheduledRepost?: () => void;
  onBulkQuote?: () => void;
  bulkDeleteState: string;
  repostFetcher?: PostFetcher;
}

export function ContentBulkActions({
  type,
  selectedCount,
  onBulkDelete,
  onBulkRepost,
  onBulkScheduledRepost,
  onBulkQuote,
  bulkDeleteState,
  repostFetcher,
}: ContentBulkActionsProps) {
  if (selectedCount === 0) return null;

  return (
    <div className="mb-4 flex items-center justify-between rounded-lg border border-blue-200 bg-blue-50 p-4 dark:border-blue-700 dark:bg-blue-900/50">
      <span className="text-sm font-medium text-blue-800 dark:text-blue-200">
        {selectedCount} item{selectedCount !== 1 ? "s" : ""} selected
      </span>
      <div className="flex gap-2">
        {type === "posted" ? (
          <>
            <button
              onClick={onBulkRepost}
              disabled={
                repostFetcher ? repostFetcher.state !== "idle" : undefined
              }
              className="inline-flex items-center justify-center gap-2 rounded-lg border border-blue-200 bg-white px-3 py-2 text-sm leading-5 font-semibold text-blue-800 hover:border-blue-300 hover:text-blue-900 hover:shadow-sm focus:ring focus:ring-blue-300/25 active:border-blue-200 active:shadow-none disabled:opacity-50 dark:border-blue-700 dark:bg-gray-800 dark:text-blue-300 dark:hover:border-blue-600 dark:hover:text-blue-200 dark:focus:ring-blue-600/40 dark:active:border-blue-700"
            >
              {repostFetcher && repostFetcher.state !== "idle"
                ? PROCESSING_TEXT
                : `Recycle ${selectedCount} Item${selectedCount !== 1 ? "s" : ""}`}
            </button>
            <button
              onClick={onBulkScheduledRepost}
              disabled={
                repostFetcher ? repostFetcher.state !== "idle" : undefined
              }
              className="inline-flex items-center justify-center gap-2 rounded-lg border border-purple-200 bg-white px-3 py-2 text-sm leading-5 font-semibold text-purple-800 hover:border-purple-300 hover:text-purple-900 hover:shadow-sm focus:ring focus:ring-purple-300/25 active:border-purple-200 active:shadow-none disabled:opacity-50 dark:border-purple-700 dark:bg-gray-800 dark:text-purple-300 dark:hover:border-purple-600 dark:hover:text-purple-200 dark:focus:ring-purple-600/40 dark:active:border-purple-700"
            >
              {repostFetcher && repostFetcher.state !== "idle"
                ? PROCESSING_TEXT
                : `Repost ${selectedCount} Item${selectedCount !== 1 ? "s" : ""}`}
            </button>
            <button
              onClick={onBulkQuote}
              disabled={
                repostFetcher ? repostFetcher.state !== "idle" : undefined
              }
              className="inline-flex items-center justify-center gap-2 rounded-lg border border-green-200 bg-white px-3 py-2 text-sm leading-5 font-semibold text-green-800 hover:border-green-300 hover:text-green-900 hover:shadow-sm focus:ring focus:ring-green-300/25 active:border-green-200 active:shadow-none disabled:opacity-50 dark:border-green-700 dark:bg-gray-800 dark:text-green-300 dark:hover:border-green-600 dark:hover:text-green-200 dark:focus:ring-green-600/40 dark:active:border-green-700"
            >
              {repostFetcher && repostFetcher.state !== "idle"
                ? PROCESSING_TEXT
                : `Quote ${selectedCount} Item${selectedCount !== 1 ? "s" : ""}`}
            </button>
          </>
        ) : null}
        <button
          onClick={onBulkDelete}
          disabled={bulkDeleteState !== "idle"}
          className="inline-flex items-center justify-center gap-2 rounded-lg border border-red-200 bg-white px-3 py-2 text-sm leading-5 font-semibold text-red-800 hover:border-red-300 hover:text-red-900 hover:shadow-sm focus:ring focus:ring-red-300/25 active:border-red-200 active:shadow-none disabled:opacity-50 dark:border-red-700 dark:bg-gray-800 dark:text-red-300 dark:hover:border-red-600 dark:hover:text-red-200 dark:focus:ring-red-600/40 dark:active:border-red-700"
        >
          {bulkDeleteState !== "idle"
            ? "Deleting..."
            : `Delete ${selectedCount} item${selectedCount !== 1 ? "s" : ""}`}
        </button>
      </div>
    </div>
  );
}

import { Link } from "@remix-run/react";

import MediaThumbnail from "~/components/ui/MediaThumbnail";

import type {
  CombinedContent,
  LongFormPostData,
  PostData,
  PostFetcher,
} from "../types";
import {
  formatDate,
  getContentPreview,
  getContentTitle,
  getContentTypeBadge,
  getImageUrls,
  getQueueTypeDisplay,
  getStatusColor,
  getStatusText,
} from "../utils/content-helpers";

// Helper to safely access formData from a fetcher
function getFetcherFormData(
  fetcher: PostFetcher | undefined
): FormData | null | undefined {
  return (fetcher as { formData?: FormData | null }).formData;
}

interface ContentTableRowProps {
  item: CombinedContent;
  type: "scheduled" | "draft" | "posted";
  userTimezone?: string;
  showBulkActions: boolean;
  selectedItems: Set<string>;
  onToggleSelection?: (id: string) => void;
  onPostSelect?: (content: CombinedContent) => void;
  onEditPost?: (post: PostData | LongFormPostData) => void;
  onReschedulePost?: (post: PostData | LongFormPostData) => void;
  deleteFetcher: PostFetcher;
  individualRepostFetcher?: PostFetcher;
  longformRepostFetcher?: PostFetcher;
  longformQuoteFetcher?: PostFetcher;
}

export function ContentTableRow({
  item,
  type,
  userTimezone,
  showBulkActions,
  selectedItems,
  onToggleSelection,
  onPostSelect,
  onEditPost,
  onReschedulePost,
  deleteFetcher,
  individualRepostFetcher,
  longformRepostFetcher,
  longformQuoteFetcher,
}: ContentTableRowProps) {
  const typeBadge = getContentTypeBadge(item);
  const queueDisplay = getQueueTypeDisplay(item.queueType);

  return (
    <tr
      key={`${item.type}-${item.id}`}
      className="cursor-pointer even:bg-gray-50 hover:bg-gray-100 dark:even:bg-gray-900/50 dark:hover:bg-gray-700/50"
      onClick={() => onPostSelect?.(item)}
    >
      {showBulkActions ? (
        <td className="p-3 text-center">
          <input
            type="checkbox"
            checked={selectedItems.has(item.id)}
            onChange={() => onToggleSelection?.(item.id)}
            onClick={(e) => e.stopPropagation()}
            className="h-4 w-4 rounded border-gray-300 text-blue-600 focus:ring-blue-500 dark:border-gray-600 dark:bg-gray-700"
          />
        </td>
      ) : null}
      <td className="p-3">
        <span className={typeBadge.className}>{typeBadge.text}</span>
      </td>
      <td className="p-3">
        {(() => {
          // For posts, get the first valid image URL
          if (item.type === "post" && item.fileUrl && item.fileUrl.length > 0) {
            const imageUrls = getImageUrls(item.fileUrl);
            const firstImageUrl = imageUrls.length > 0 ? imageUrls[0] : null;

            if (firstImageUrl) {
              return (
                <MediaThumbnail
                  src={firstImageUrl}
                  alt="Post preview"
                  className="h-12 w-12 rounded object-cover"
                  fallback={
                    <div className="flex h-12 w-12 items-center justify-center rounded bg-gray-100 text-xs font-medium text-gray-500 dark:bg-gray-700 dark:text-gray-400">
                      TEXT
                    </div>
                  }
                />
              );
            }
          }

          // For longform posts with images
          if (item.type === "longform" && item.image) {
            return (
              <MediaThumbnail
                src={item.image}
                alt="Article cover"
                className="h-12 w-12 rounded object-cover"
                fallback={
                  <div className="flex h-12 w-12 items-center justify-center rounded bg-gray-100 text-xs font-medium text-gray-500 dark:bg-gray-700 dark:text-gray-400">
                    ART
                  </div>
                }
              />
            );
          }

          // Default fallback based on content type
          return (
            <div className="flex h-12 w-12 items-center justify-center rounded bg-gray-100 text-xs font-medium text-gray-500 dark:bg-gray-700 dark:text-gray-400">
              {item.type === "post" ? "TEXT" : "ART"}
            </div>
          );
        })()}
      </td>
      <td className="p-3">
        <p className="font-medium">{getContentTitle(item)}</p>
      </td>
      <td className="p-3">
        <p className="text-sm text-gray-600 dark:text-gray-400">
          {getContentPreview(item)?.slice(0, 20) ?? ""}
          {(getContentPreview(item)?.length ?? 0) > 20 ? "…" : ""}
        </p>
      </td>
      <td className="p-3">
        {type === "scheduled"
          ? formatDate(item.scheduledFor, true, userTimezone)
          : type === "posted"
            ? formatDate(item.postedAt, false, userTimezone)
            : formatDate(item.createdAt, false, userTimezone)}
      </td>
      <td className="p-3 text-center">
        <div className={queueDisplay.className} style={queueDisplay.style}>
          {queueDisplay.name}
        </div>
      </td>
      <td className="p-3 text-center">
        <div
          className={`inline-flex rounded-full border border-transparent px-2 py-1 text-xs leading-4 font-semibold ${getStatusColor(item)}`}
        >
          {getStatusText(item)}
        </div>
      </td>
      <td className="p-3 text-center">
        <ContentRowActions
          item={item}
          type={type}
          onEditPost={onEditPost}
          onReschedulePost={onReschedulePost}
          deleteFetcher={deleteFetcher}
          individualRepostFetcher={individualRepostFetcher}
          longformRepostFetcher={longformRepostFetcher}
          longformQuoteFetcher={longformQuoteFetcher}
        />
      </td>
    </tr>
  );
}

function ContentRowActions({
  item,
  type,
  onEditPost,
  onReschedulePost,
  deleteFetcher,
  individualRepostFetcher,
  longformRepostFetcher,
  longformQuoteFetcher,
}: {
  item: CombinedContent;
  type: "scheduled" | "draft" | "posted";
  onEditPost?: (post: PostData | LongFormPostData) => void;
  onReschedulePost?: (post: PostData | LongFormPostData) => void;
  deleteFetcher: PostFetcher;
  individualRepostFetcher?: PostFetcher;
  longformRepostFetcher?: PostFetcher;
  longformQuoteFetcher?: PostFetcher;
}) {
  return (
    <div className="flex items-center justify-center gap-2">
      {type === "posted" ? (
        <>
          {/* View Link - different for posts vs longform */}
          {item.type === "post" && item.originalData.signedEvent?.id ? (
            <Link
              to={`https://primal.net/e/${item.originalData.signedEvent.id}`}
              target="_blank"
              rel="noreferrer"
              onClick={(e) => e.stopPropagation()}
              className="font-montserrat inline-block rounded-full bg-black/50 px-4 py-1 text-sm text-white transition-colors duration-200 hover:bg-black/70"
            >
              View Note
            </Link>
          ) : null}
          {item.type === "longform" &&
          (item.originalData.nostrEventId ||
            item.originalData.signedEvent?.id) ? (
            <Link
              to={`https://primal.net/a/${item.originalData.nostrEventId ?? item.originalData.signedEvent?.id ?? ""}`}
              target="_blank"
              rel="noreferrer"
              onClick={(e) => e.stopPropagation()}
              className="font-montserrat inline-block rounded-full bg-black/50 px-4 py-1 text-sm text-white transition-colors duration-200 hover:bg-black/70"
            >
              View Article
            </Link>
          ) : null}

          {/* Post Actions - Regular posts */}
          {item.type === "post" && individualRepostFetcher
            ? (() => {
                const fetcher = individualRepostFetcher;
                const formData = getFetcherFormData(fetcher);
                return (
                  <>
                    <fetcher.Form
                      method="post"
                      onClick={(e) => e.stopPropagation()}
                    >
                      <input type="hidden" name="postId" value={item.id} />
                      <input type="hidden" name="_action" value="repost" />
                      <button
                        type="submit"
                        disabled={
                          fetcher.state !== "idle" ||
                          (formData
                            ? (formData.get("postId") as string | null) ===
                              item.id
                            : false)
                        }
                        className="inline-flex items-center justify-center gap-2 rounded-lg border border-purple-200 bg-white px-2 py-1 text-sm leading-5 font-semibold text-purple-800 hover:border-purple-300 hover:text-purple-900 hover:shadow-sm focus:ring focus:ring-purple-300/25 active:border-purple-200 active:shadow-none disabled:opacity-50 dark:border-purple-700 dark:bg-gray-800 dark:text-purple-300 dark:hover:border-purple-600 dark:hover:text-purple-200 dark:focus:ring-purple-600/40 dark:active:border-purple-700"
                      >
                        {fetcher.state !== "idle" &&
                        (formData
                          ? (formData.get("postId") as string | null) ===
                            item.id
                          : false)
                          ? "Reposting..."
                          : "Repost"}
                      </button>
                    </fetcher.Form>
                    <fetcher.Form
                      method="post"
                      onClick={(e) => e.stopPropagation()}
                    >
                      <input type="hidden" name="postId" value={item.id} />
                      <input type="hidden" name="_action" value="quote" />
                      <button
                        type="submit"
                        disabled={
                          fetcher.state !== "idle" ||
                          (formData
                            ? (formData.get("postId") as string | null) ===
                              item.id
                            : false)
                        }
                        className="inline-flex items-center justify-center gap-2 rounded-lg border border-green-200 bg-white px-2 py-1 text-sm leading-5 font-semibold text-green-800 hover:border-green-300 hover:text-green-900 hover:shadow-sm focus:ring focus:ring-green-300/25 active:border-green-200 active:shadow-none disabled:opacity-50 dark:border-green-700 dark:bg-gray-800 dark:text-green-300 dark:hover:border-green-600 dark:hover:text-green-200 dark:focus:ring-green-600/40 dark:active:border-green-700"
                      >
                        {fetcher.state !== "idle" &&
                        (formData
                          ? (formData.get("postId") as string | null) ===
                            item.id
                          : false)
                          ? "Quoting..."
                          : "Quote Post"}
                      </button>
                    </fetcher.Form>
                  </>
                );
              })()
            : null}

          {/* Longform Actions */}
          {item.type === "longform" && longformRepostFetcher
            ? (() => {
                const fetcher = longformRepostFetcher;
                const formData = getFetcherFormData(fetcher);
                return (
                  <fetcher.Form
                    method="post"
                    onClick={(e) => e.stopPropagation()}
                  >
                    <input type="hidden" name="postId" value={item.id} />
                    <input
                      type="hidden"
                      name="_action"
                      value="longformRepost"
                    />
                    <button
                      type="submit"
                      disabled={
                        fetcher.state !== "idle" ||
                        (formData
                          ? (formData.get("postId") as string | null) ===
                            item.id
                          : false)
                      }
                      className="inline-flex items-center justify-center gap-2 rounded-lg border border-purple-200 bg-white px-2 py-1 text-sm leading-5 font-semibold text-purple-800 hover:border-purple-300 hover:text-purple-900 hover:shadow-sm focus:ring focus:ring-purple-300/25 active:border-purple-200 active:shadow-none disabled:opacity-50 dark:border-purple-700 dark:bg-gray-800 dark:text-purple-300 dark:hover:border-purple-600 dark:hover:text-purple-200 dark:focus:ring-purple-600/40 dark:active:border-purple-700"
                    >
                      {fetcher.state !== "idle" &&
                      (formData
                        ? (formData.get("postId") as string | null) === item.id
                        : false)
                        ? "Reposting..."
                        : "Repost"}
                    </button>
                  </fetcher.Form>
                );
              })()
            : null}
          {item.type === "longform" && longformQuoteFetcher
            ? (() => {
                const fetcher = longformQuoteFetcher;
                const formData = getFetcherFormData(fetcher);
                return (
                  <fetcher.Form
                    method="post"
                    onClick={(e) => e.stopPropagation()}
                  >
                    <input type="hidden" name="postId" value={item.id} />
                    <input type="hidden" name="_action" value="longformQuote" />
                    <button
                      type="submit"
                      disabled={
                        fetcher.state !== "idle" ||
                        (formData
                          ? (formData.get("postId") as string | null) ===
                            item.id
                          : false)
                      }
                      className="inline-flex items-center justify-center gap-2 rounded-lg border border-green-200 bg-white px-2 py-1 text-sm leading-5 font-semibold text-green-800 hover:border-green-300 hover:text-green-900 hover:shadow-sm focus:ring focus:ring-green-300/25 active:border-green-200 active:shadow-none disabled:opacity-50 dark:border-green-700 dark:bg-gray-800 dark:text-green-300 dark:hover:border-green-600 dark:hover:text-green-200 dark:focus:ring-green-600/40 dark:active:border-green-700"
                    >
                      {fetcher.state !== "idle" &&
                      (formData
                        ? (formData.get("postId") as string | null) === item.id
                        : false)
                        ? "Quoting..."
                        : "Quote Post"}
                    </button>
                  </fetcher.Form>
                );
              })()
            : null}
        </>
      ) : null}
      {/* Edit and Reschedule actions - only for scheduled content */}
      {type === "scheduled" ? (
        <>
          <button
            onClick={(e) => {
              e.stopPropagation();
              onEditPost?.(item.originalData);
            }}
            className="inline-flex items-center justify-center gap-2 rounded-lg border border-blue-200 bg-white px-2 py-1 text-sm leading-5 font-semibold text-blue-800 hover:border-blue-300 hover:text-blue-900 hover:shadow-sm focus:ring focus:ring-blue-300/25 active:border-blue-200 active:shadow-none dark:border-blue-700 dark:bg-gray-800 dark:text-blue-300 dark:hover:border-blue-600 dark:hover:text-blue-200 dark:focus:ring-blue-600/40 dark:active:border-blue-700"
          >
            Edit
          </button>
          <button
            onClick={(e) => {
              e.stopPropagation();
              onReschedulePost?.(item.originalData);
            }}
            className="inline-flex items-center justify-center gap-2 rounded-lg border border-green-200 bg-white px-2 py-1 text-sm leading-5 font-semibold text-green-800 hover:border-green-300 hover:text-green-900 hover:shadow-sm focus:ring focus:ring-green-300/25 active:border-green-200 active:shadow-none dark:border-green-700 dark:bg-gray-800 dark:text-green-300 dark:hover:border-green-600 dark:hover:text-green-200 dark:focus:ring-green-600/40 dark:active:border-green-700"
          >
            Reschedule
          </button>
        </>
      ) : null}

      {/* Delete action - always available */}
      <deleteFetcher.Form method="post" onClick={(e) => e.stopPropagation()}>
        <input type="hidden" name="postId" value={item.id} />
        <input
          type="hidden"
          name="_action"
          value={item.type === "post" ? "delete" : "deleteLongForm"}
        />
        <button
          type="submit"
          disabled={deleteFetcher.state !== "idle"}
          className="inline-flex items-center justify-center gap-2 rounded-lg border border-red-200 bg-white px-2 py-1 text-sm leading-5 font-semibold text-red-800 hover:border-red-300 hover:text-red-900 hover:shadow-sm focus:ring focus:ring-red-300/25 active:border-red-200 active:shadow-none disabled:opacity-50 dark:border-red-700 dark:bg-gray-800 dark:text-red-300 dark:hover:border-red-600 dark:hover:text-red-200 dark:focus:ring-red-600/40 dark:active:border-red-700"
        >
          {deleteFetcher.state !== "idle" &&
          (deleteFetcher.formData
            ? (deleteFetcher.formData.get("postId") as string | null) ===
              item.id
            : false)
            ? "Deleting..."
            : "Delete"}
        </button>
      </deleteFetcher.Form>
    </div>
  );
}

import { useFetcher } from "@remix-run/react";
import { useState, useEffect } from "react";

import { nostrAdapter } from "~/lib/nostr-adapter.client";
import { useOptionalUser } from "~/lib/remix-utils";

import { getSelectedQueueStyle } from "../queue-colors";
import { isIntervalScheduleConfig, isFixedSlotsScheduleConfig } from "../types";
import type { QueueType, PostData } from "../types";

interface DraftBulkResumeProps {
  selectedDrafts: PostData[];
  queueTypes: QueueType[];
  onCancel: () => void;
}

export default function DraftBulkResume({
  selectedDrafts,
  queueTypes,
  onCancel,
}: DraftBulkResumeProps) {
  const fetcher = useFetcher();
  const user = useOptionalUser();
  const scheduleIntervals =
    user && typeof user === "object" && "scheduleInterval" in user
      ? user.scheduleInterval
      : null;
  const [isSubmitting, setIsSubmitting] = useState(false);

  // State for bulk operations similar to bulkposts
  const [posts, setPosts] = useState(
    selectedDrafts.map((draft, index) => {
      const now = new Date();
      const userTimezone = user?.timezone ?? "UTC";
      const localDate = new Date(
        now.toLocaleString("en-US", { timeZone: userTimezone })
      );

      // Schedule posts with 2-hour intervals by default
      localDate.setHours(
        localDate.getHours() + index * (Number(scheduleIntervals?.[0]) || 2)
      );
      return {
        id: draft.id,
        content: draft.content ?? draft.caption,
        caption: draft.caption,
        fileUrl: draft.fileUrl,
        postType: draft.postType,
        queueType: draft.queueType?.name ?? draft.queueType ?? "unassigned",
        scheduledFor: localDate
          .toLocaleString("en-US", {
            year: "numeric",
            month: "2-digit",
            day: "2-digit",
            hour: "2-digit",
            minute: "2-digit",
            hour12: false,
          })
          .replace(/(\d+)\/(\d+)\/(\d+),\s(\d+):(\d+)/, "$3-$1-$2T$4:$5"),
      };
    })
  );

  const calculateQueueScheduleTime = async (
    queueTypeName: string,
    baseIndex = 0
  ): Promise<string> => {
    if (queueTypeName === "unassigned") {
      return "";
    }

    try {
      const response = await fetch("/api/queue-schedule", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          queueTypeName,
          userId: user?.id,
        }),
      });

      if (response.ok) {
        const dataRaw: unknown = await response.json();
        const data =
          dataRaw && typeof dataRaw === "object" && !Array.isArray(dataRaw)
            ? (dataRaw as { scheduledTime?: unknown })
            : {};
        const scheduledTime =
          typeof data.scheduledTime === "string"
            ? data.scheduledTime
            : undefined;
        if (!scheduledTime) return "";

        // For bulk posts, add interval offset based on index
        if (baseIndex > 0) {
          const queueType = queueTypes.find((qt) => {
            const name = typeof qt === "string" ? qt : qt.name;
            return name === queueTypeName;
          });

          if (
            queueType &&
            typeof queueType === "object" &&
            "scheduleType" in queueType
          ) {
            const baseDate = new Date(scheduledTime);

            if (queueType.scheduleType === "INTERVAL") {
              const config =
                typeof queueType === "object" && "scheduleConfig" in queueType
                  ? queueType.scheduleConfig
                  : null;
              let intervalHours = 4; // default

              if (config && isIntervalScheduleConfig(config)) {
                if (config.useGlobalInterval) {
                  const userIntervalRaw =
                    user &&
                    typeof user === "object" &&
                    "scheduleInterval" in user &&
                    Array.isArray(user.scheduleInterval) &&
                    user.scheduleInterval.length > 0
                      ? user.scheduleInterval[0]
                      : null;
                  const userInterval =
                    typeof userIntervalRaw === "number"
                      ? userIntervalRaw
                      : typeof userIntervalRaw === "string"
                        ? Number(userIntervalRaw)
                        : null;
                  intervalHours =
                    userInterval && !isNaN(userInterval) ? userInterval : 4;
                } else {
                  intervalHours = config.intervalHours ?? 4;
                }
              }

              baseDate.setHours(
                baseDate.getHours() + baseIndex * intervalHours
              );
            } else if (queueType.scheduleType === "FIXED_SLOTS") {
              const config =
                typeof queueType === "object" && "scheduleConfig" in queueType
                  ? queueType.scheduleConfig
                  : null;
              const slots =
                config && isFixedSlotsScheduleConfig(config)
                  ? config.slots
                  : [];

              if (slots.length > 0) {
                // Sort slots to ensure consistent ordering
                const sortedSlots = slots
                  .map((slot: string) => {
                    const parts = slot.split(":");
                    const hours = parts[0] ? Number(parts[0]) : 0;
                    const minutes = parts[1] ? Number(parts[1]) : 0;
                    return {
                      slot,
                      hours,
                      minutes,
                      totalMinutes: hours * 60 + minutes,
                    };
                  })
                  .sort(
                    (
                      a: { totalMinutes: number },
                      b: { totalMinutes: number }
                    ) => a.totalMinutes - b.totalMinutes
                  );

                // Get the current slot index based on the base time
                const baseHours = baseDate.getHours();
                const baseMinutes = baseDate.getMinutes();
                const baseTotalMinutes = baseHours * 60 + baseMinutes;

                let currentSlotIndex = 0;
                for (let i = 0; i < sortedSlots.length; i++) {
                  const slot = sortedSlots[i];
                  if (slot && slot.totalMinutes >= baseTotalMinutes) {
                    currentSlotIndex = i;
                    break;
                  }
                }

                // Calculate which slot this post should use
                const targetSlotIndex =
                  (currentSlotIndex + baseIndex) % sortedSlots.length;
                const targetSlot = sortedSlots[targetSlotIndex];

                if (targetSlot) {
                  // Calculate how many days to add
                  const daysToAdd = Math.floor(
                    (currentSlotIndex + baseIndex) / sortedSlots.length
                  );

                  // Set the time to the target slot
                  baseDate.setHours(targetSlot.hours, targetSlot.minutes, 0, 0);
                  baseDate.setDate(baseDate.getDate() + daysToAdd);
                }
              }
            }

            // Format back to datetime-local format
            const year = baseDate.getFullYear();
            const month = String(baseDate.getMonth() + 1).padStart(2, "0");
            const day = String(baseDate.getDate()).padStart(2, "0");
            const hours = String(baseDate.getHours()).padStart(2, "0");
            const minutes = String(baseDate.getMinutes()).padStart(2, "0");

            return `${year}-${month}-${day}T${hours}:${minutes}`;
          }
        }

        return scheduledTime;
      }
    } catch (error) {
      const { handleErrorSafely } = await import("~/lib/error-handler.client");
      handleErrorSafely(error, {
        component: "DraftBulkResume",
        action: "calculateQueueScheduleTime",
      });
    }

    return "";
  };

  const handleQueueTypeChange = async (
    index: number,
    value: string | QueueType
  ) => {
    const updatedPosts = [...posts];
    const postToUpdate = updatedPosts[index];
    if (!postToUpdate) return;
    postToUpdate.queueType = value;

    // Auto-calculate schedule time if not unassigned
    const queueTypeName = typeof value === "string" ? value : value.name;
    if (queueTypeName !== "unassigned") {
      const scheduledTime = await calculateQueueScheduleTime(queueTypeName, 0);
      if (scheduledTime) {
        postToUpdate.scheduledFor = scheduledTime;
      }
    } else {
      postToUpdate.scheduledFor = "";
    }

    setPosts(updatedPosts);
  };

  const handleDateChange = (index: number, value: string) => {
    const updatedPosts = [...posts];
    const postToUpdate = updatedPosts[index];
    if (!postToUpdate) return;
    postToUpdate.scheduledFor = value;
    setPosts(updatedPosts);
  };

  const handleScheduleIntervalClick = (interval: number) => {
    if (posts.length === 0) return;

    const updatedPosts = [...posts];
    const firstPost = updatedPosts[0];
    if (!firstPost?.scheduledFor) return;
    const baseDate = new Date(firstPost.scheduledFor);

    updatedPosts.forEach((post, index) => {
      const newDate = new Date(baseDate);
      newDate.setHours(baseDate.getHours() + index * interval);

      const year = newDate.getFullYear();
      const month = String(newDate.getMonth() + 1).padStart(2, "0");
      const day = String(newDate.getDate()).padStart(2, "0");
      const hours = String(newDate.getHours()).padStart(2, "0");
      const minutes = String(newDate.getMinutes()).padStart(2, "0");

      post.scheduledFor = `${year}-${month}-${day}T${hours}:${minutes}`;
    });

    setPosts(updatedPosts);
  };

  const handleBulkQueueUpdate = async (queueType: QueueType | string) => {
    if (posts.length === 0) return;

    const updatedPosts = await Promise.all(
      posts.map(async (post, index) => {
        let scheduledFor = post.scheduledFor;

        // Auto-calculate schedule time if not unassigned
        const queueTypeName =
          typeof queueType === "string" ? queueType : queueType.name;
        if (queueTypeName !== "unassigned") {
          const calculatedTime = await calculateQueueScheduleTime(
            queueTypeName,
            index
          );
          if (calculatedTime) {
            scheduledFor = calculatedTime;
          }
        } else {
          scheduledFor = "";
        }

        return {
          ...post,
          queueType,
          scheduledFor,
        };
      })
    );

    setPosts(updatedPosts);
  };

  const handleSignAndResume = async () => {
    setIsSubmitting(true);
    try {
      const signedPosts = await Promise.all(
        posts.map(async (post) => {
          const userTimezone = user?.timezone ?? "UTC";
          let scheduledTime;

          if (userTimezone !== "UTC" && userTimezone !== "Etc/GMT") {
            const utcDate = new Date(post.scheduledFor);
            const userDate = new Date(post.scheduledFor).toLocaleString(
              "en-US",
              {
                timeZone: userTimezone,
              }
            );
            const userOffset =
              (new Date(userDate).getTime() -
                new Date(post.scheduledFor).getTime()) /
              60000;
            utcDate.setMinutes(utcDate.getMinutes() - userOffset);
            scheduledTime = utcDate.getTime();
          } else {
            const dateObj = new Date(post.scheduledFor + "Z");
            scheduledTime = dateObj.getTime();
          }

          const scheduledForUnix = Math.floor(scheduledTime / 1000);

          // Get effective hashtags based on queue type
          let tagsString = "";
          try {
            const response = await fetch("/api/effective-hashtags", {
              method: "POST",
              headers: {
                "Content-Type": "application/json",
              },
              body: JSON.stringify({
                userId: user?.id,
                queueTypeName: post.queueType,
              }),
            });
            const data = (await response.json()) as { hashtags?: string };
            tagsString = data.hashtags ?? "";
          } catch (error) {
            const { handleErrorSafely } =
              await import("~/lib/error-handler.client");
            handleErrorSafely(error, {
              component: "DraftBulkResume",
              action: "getEffectiveHashtags",
            });
            // Fallback to user's default hashtags
            // Note: User doesn't have hashTags property - this would need to come from hashTagPresets relation
            tagsString = "";
          }

          const tagArray = tagsString
            .split(" ")
            .filter((tag) => tag.length > 0)
            .map((tag) => ["t", tag.replace("#", "")]);

          const contentToSign = user?.showHashTagsinPosts
            ? `${post.content ?? ""}\n${tagsString}`
            : (post.content ?? "");

          const { nostrEvent, signedEvent } = await nostrAdapter.signEvent({
            content: contentToSign,
            created_at: scheduledForUnix,
            kind: 1,
            tags: tagArray,
          });

          return {
            id: post.id,
            content: post.content,
            caption: post.caption,
            queueType: post.queueType,
            scheduledFor: scheduledForUnix.toString(),
            signedEvent: JSON.stringify(signedEvent),
            nostrEvent: JSON.stringify(nostrEvent),
          };
        })
      );

      const formData = new FormData();
      formData.append("_action", "bulkSignAndResume");
      signedPosts.forEach((post) => {
        formData.append("postIds", post.id);
        formData.append("contents", post.content ?? "");
        formData.append("captions", post.caption ?? "");
        const queueTypeValue =
          typeof post.queueType === "string"
            ? post.queueType
            : post.queueType.name;
        formData.append("queueTypes", queueTypeValue);
        formData.append("scheduledFors", post.scheduledFor);
        formData.append("signedEvents", post.signedEvent);
        formData.append("nostrEvents", post.nostrEvent);
      });

      fetcher.submit(formData, { method: "post", action: "/dashboard/drafts" });
    } catch (error) {
      console.error("Error signing drafts:", error);
      alert("Error signing drafts. Please try again.");
      setIsSubmitting(false);
    }
  };

  const getImageUrls = (fileUrl: string[] | null | undefined) => {
    if (!fileUrl || fileUrl.length === 0) return [];

    if (typeof fileUrl[0] === "string" && fileUrl[0].startsWith("[")) {
      try {
        return JSON.parse(fileUrl[0]) as string[];
      } catch (e) {
        console.error("Error parsing fileUrl:", e);
        return [];
      }
    }

    return fileUrl;
  };

  interface _FetcherData {
    success?: boolean;
  }

  useEffect(() => {
    const dataRaw = fetcher.data;
    const data =
      dataRaw && typeof dataRaw === "object" && !Array.isArray(dataRaw)
        ? (dataRaw as { success?: unknown })
        : null;
    if (data && typeof data.success === "boolean" && data.success) {
      onCancel(); // Close the modal and refresh
    }
  }, [fetcher.data, onCancel]);

  return (
    <div className="min-h-screen bg-gradient-to-br from-gray-50 to-gray-100 p-6 dark:from-gray-900 dark:to-gray-800">
      <div className="mx-auto max-w-7xl">
        {/* Header */}
        <div className="mb-8 text-center">
          <h1 className="text-3xl font-bold text-gray-900 dark:text-white">
            Resume Draft Posts
          </h1>
          <p className="mt-2 text-gray-600 dark:text-gray-400">
            Configure and sign {posts.length} draft posts before scheduling
          </p>
        </div>

        {/* Schedule Interval Buttons */}
        {posts.length > 0 ? (
          <div className="mt-4 mb-4 flex justify-center">
            {scheduleIntervals
              ? scheduleIntervals.map((interval) => (
                  <button
                    key={interval}
                    type="button"
                    onClick={() =>
                      handleScheduleIntervalClick(
                        typeof interval === "string"
                          ? parseInt(interval, 10)
                          : interval
                      )
                    }
                    disabled={isSubmitting}
                    className="mx-2 rounded-md bg-gray-100 px-4 py-2 text-sm font-medium text-gray-700 shadow-md transition-all hover:scale-105 hover:bg-gray-200 disabled:cursor-not-allowed disabled:opacity-50 disabled:hover:scale-100 dark:bg-gray-800 dark:text-gray-300 dark:hover:bg-gray-700"
                  >
                    +{interval}h
                  </button>
                ))
              : null}
          </div>
        ) : null}

        {/* Bulk Queue Selection */}
        {posts.length > 0 ? (
          <div className="mb-6">
            <h3 className="mb-3 text-sm font-medium text-gray-700 dark:text-gray-300">
              Bulk Queue Selection
            </h3>
            <div className="flex flex-wrap justify-center gap-2">
              {queueTypes.map((queue) => {
                const queueName =
                  typeof queue === "string" ? queue : queue.name;
                const queueColor =
                  typeof queue === "object" ? queue.color : null;
                return (
                  <button
                    key={queueName}
                    type="button"
                    onClick={() => void handleBulkQueueUpdate(queueName)}
                    disabled={isSubmitting}
                    className={`rounded-full px-4 py-2 text-sm font-medium transition-all duration-200 hover:scale-105 disabled:cursor-not-allowed disabled:opacity-50 disabled:hover:scale-100 ${getSelectedQueueStyle(queueName, false)}`}
                    style={{
                      backgroundColor: queueColor ?? undefined,
                      borderColor: queueColor ?? undefined,
                    }}
                  >
                    {queueName}
                  </button>
                );
              })}
            </div>
            <p className="mt-2 text-center text-xs text-gray-500 dark:text-gray-400">
              Click a queue to update all posts
            </p>
          </div>
        ) : null}

        {/* Posts Configuration Table */}
        <div className="overflow-x-auto">
          <table className="w-full border-collapse">
            <thead>
              <tr className="border-b">
                <th className="p-4 text-left">Media</th>
                <th className="p-4 text-left">Content</th>
                <th className="p-4 text-left">Queue</th>
                <th className="p-4 text-left">Schedule</th>
              </tr>
            </thead>
            <tbody>
              {posts.map((post, index) => (
                <tr key={post.id} className="border-b">
                  <td className="p-4">
                    {post.fileUrl.length > 0 ? (
                      <img
                        src={getImageUrls(post.fileUrl)[0]}
                        alt="Preview"
                        className="h-24 w-24 rounded object-cover"
                      />
                    ) : (
                      <div className="flex h-24 w-24 items-center justify-center rounded bg-gray-100 text-xs font-medium text-gray-500 dark:bg-gray-700 dark:text-gray-400">
                        TEXT
                      </div>
                    )}
                  </td>
                  <td className="p-4">
                    <div className="max-h-20 overflow-y-auto">
                      <p className="text-sm text-gray-700 dark:text-gray-300">
                        {post.content?.substring(0, 150) ?? ""}
                        {(post.content?.length ?? 0) > 150 ? "..." : null}
                      </p>
                    </div>
                  </td>
                  <td className="p-4">
                    <div className="flex flex-wrap gap-1">
                      {queueTypes.map((queue) => {
                        const queueName =
                          typeof queue === "string" ? queue : queue.name;
                        const queueColor =
                          typeof queue === "object" ? queue.color : null;
                        return (
                          <button
                            key={queueName}
                            type="button"
                            onClick={() => {
                              void handleQueueTypeChange(index, queueName);
                            }}
                            disabled={isSubmitting}
                            className={`rounded-full px-3 py-1 text-xs font-medium transition-all duration-200 ${getSelectedQueueStyle(queueName, post.queueType === queueName)}`}
                            style={{
                              backgroundColor: queueColor ?? undefined,
                              borderColor: queueColor ?? undefined,
                            }}
                          >
                            {queueName}
                          </button>
                        );
                      })}
                    </div>
                  </td>
                  <td className="p-4">
                    <input
                      type="datetime-local"
                      value={post.scheduledFor}
                      onChange={(e) => handleDateChange(index, e.target.value)}
                      disabled={isSubmitting}
                      className="rounded-lg border p-2 text-gray-900 dark:bg-gray-800 dark:text-gray-100"
                    />
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>

        {/* Action Buttons */}
        <div className="mt-8 flex justify-center gap-4">
          <button
            onClick={onCancel}
            disabled={isSubmitting}
            className="rounded-lg border border-gray-300 bg-white px-6 py-3 text-sm font-medium text-gray-700 shadow-sm transition-all hover:bg-gray-50 hover:shadow-md dark:border-gray-600 dark:bg-gray-800 dark:text-gray-300 dark:hover:bg-gray-700"
          >
            Cancel
          </button>
          <button
            onClick={() => void handleSignAndResume()}
            disabled={isSubmitting}
            className="rounded-lg bg-gradient-to-r from-green-500 to-green-600 px-8 py-3 text-sm font-medium text-white shadow-lg transition-all hover:from-green-600 hover:to-green-700 hover:shadow-xl disabled:cursor-not-allowed disabled:from-green-300 disabled:to-green-400"
          >
            {isSubmitting ? (
              <span className="flex items-center gap-2">
                <svg className="h-4 w-4 animate-spin" viewBox="0 0 24 24">
                  <circle
                    className="opacity-25"
                    cx="12"
                    cy="12"
                    r="10"
                    stroke="currentColor"
                    strokeWidth="4"
                    fill="none"
                  />
                  <path
                    className="opacity-75"
                    fill="currentColor"
                    d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"
                  />
                </svg>
                Signing & Scheduling...
              </span>
            ) : (
              `Sign & Schedule ${posts.length} Posts`
            )}
          </button>
        </div>
      </div>
    </div>
  );
}

import { useFetcher } from "@remix-run/react";
import { useState, useEffect, useCallback } from "react";
import { toast } from "react-hot-toast";

import { resizeImage } from "~/features/upload/image-resize";
import { useOptionalUser } from "~/lib/remix-utils";

import { getDynamicQueueStyle } from "../queue-colors";
import type { QueueType } from "../types";

const ERROR_PROCESSING_IMAGES =
  "Error processing images. Using original files.";

interface PreparedEventData {
  content: string;
  type: "image";
  queueType: string;
}

interface ImagePostProps {
  files: File[];
  setFiles: React.Dispatch<React.SetStateAction<File[]>>;
  setShowImagePreview: (show: boolean) => void;
  setPreparedImageEvent: (data: PreparedEventData[]) => void;
  queueTypes?: Array<string | QueueType>;
  onQueueTypeChange?: (queueType: string) => void;
}

export default function ImagePost({
  files,
  setFiles,
  setShowImagePreview,
  setPreparedImageEvent,
  queueTypes = [],
  onQueueTypeChange,
}: ImagePostProps) {
  interface FetcherData {
    success?: boolean;
    fileUrls?: Array<{
      fileUrl: string;
      scheduledFor: string;
      queueType: string;
    }>;
    error?: string;
  }

  const fetcher = useFetcher<FetcherData>();
  const user = useOptionalUser();

  const scheduleIntervals =
    user && typeof user === "object" && "scheduleInterval" in user
      ? user.scheduleInterval
      : null;
  const [scheduledFor, setScheduledFor] = useState("");
  const [timeError, setTimeError] = useState("");
  const [isRecyclable, setIsRecyclable] = useState(false);

  // Determine initial queue selection - default to "unassigned"
  const getInitialQueue = () => {
    return "unassigned";
  };

  const [selectedQueue, setSelectedQueue] = useState(getInitialQueue());

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const selectedFiles = e.target.files ? Array.from(e.target.files) : [];

    // Process files to remove metadata for privacy
    try {
      const processedFiles = await Promise.all(
        selectedFiles.map(async (file) => {
          if (file.type.startsWith("image/")) {
            return await resizeImage(file);
          }
          return file;
        })
      );
      setFiles((prev: File[]) => [...prev, ...processedFiles]);
    } catch (error: unknown) {
      const { handleAsyncErrorWithMessage } =
        await import("~/lib/error-handler.client");
      handleAsyncErrorWithMessage(
        error,
        ERROR_PROCESSING_IMAGES,
        {
          component: "ImagePost",
          action: "handleFileChange",
        },
        false // Don't show toast, we call toast.error instead
      );
      toast.error(ERROR_PROCESSING_IMAGES);
      setFiles((prev: File[]) => [...prev, ...selectedFiles]);
    }
  };

  const handleDrop = async (e: React.DragEvent<HTMLDivElement>) => {
    e.preventDefault();
    const droppedFiles = Array.from(e.dataTransfer.files);
    if (droppedFiles.length > 0) {
      // Check if files are images
      const imageFiles = droppedFiles.filter((file) =>
        file.type.startsWith("image/")
      );
      if (imageFiles.length === 0) {
        toast.error("Please drop only image files");
        return;
      }

      // Process files to remove metadata for privacy
      try {
        const processedFiles = await Promise.all(
          imageFiles.map(async (file) => await resizeImage(file))
        );
        setFiles((prev: File[]) => [...prev, ...processedFiles]);
      } catch (error: unknown) {
        const { handleAsyncErrorWithMessage } =
          await import("~/lib/error-handler.client");
        handleAsyncErrorWithMessage(
          error,
          ERROR_PROCESSING_IMAGES,
          {
            component: "ImagePost",
            action: "handleDrop",
          },
          false // Don't show toast, we call toast.error instead
        );
        toast.error(ERROR_PROCESSING_IMAGES);
        setFiles((prev: File[]) => [...prev, ...imageFiles]);
      }
    }
  };

  const handleDragOver = (e: React.DragEvent<HTMLDivElement>) => {
    e.preventDefault();
  };

  const handleImagePreview = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();

    // Check if scheduledFor is empty
    if (!scheduledFor) {
      setTimeError("Please set a scheduled time before uploading");
      toast.error("Please set a scheduled time before uploading");
      return;
    }

    setTimeError("");
    const form = e.target as HTMLFormElement;
    const formData = new FormData(form);
    formData.set("_action", "upload-images-preview");
    formData.set("queueType", selectedQueue);
    // Set isRecyclable checkbox state
    if (isRecyclable) {
      formData.set("isRecyclable", "on");
    }

    // Remove any existing files from formData
    formData.delete("files");

    // Append each file individually to formData
    files.forEach((file) => {
      formData.append("files", file);
    });

    fetcher.submit(formData, {
      method: "post",
      encType: "multipart/form-data",
    });
  };

  const calculateQueueScheduleTime = useCallback(
    async (queueTypeName: string) => {
      if (queueTypeName === "unassigned") {
        setScheduledFor("");
        return;
      }

      // Find the queue type object to get its ID
      const selectedQueueType = queueTypes.find((qt) => {
        if (typeof qt === "string") {
          return qt === queueTypeName;
        }
        if (
          typeof qt === "object" &&
          "name" in qt &&
          typeof qt.name === "string"
        ) {
          return qt.name === queueTypeName;
        }
        return false;
      });
      const queueTypeId =
        selectedQueueType &&
        typeof selectedQueueType === "object" &&
        "id" in selectedQueueType &&
        typeof selectedQueueType.id === "string"
          ? selectedQueueType.id
          : null;

      try {
        const response = await fetch("/api/queue-schedule", {
          method: "POST",
          headers: {
            "Content-Type": "application/json",
          },
          body: JSON.stringify({
            queueTypeId,
            queueTypeName, // Keep for backward compatibility
            userId:
              user &&
              typeof user === "object" &&
              "id" in user &&
              typeof user.id === "string"
                ? user.id
                : undefined,
          }),
        });

        if (response.ok) {
          const dataRaw: unknown = await response.json();
          const data =
            dataRaw && typeof dataRaw === "object" && !Array.isArray(dataRaw)
              ? (dataRaw as { scheduledTime?: unknown })
              : {};
          const scheduledTime =
            typeof data.scheduledTime === "string"
              ? data.scheduledTime
              : undefined;
          if (scheduledTime) {
            setScheduledFor(scheduledTime);
          }
          setTimeError("");
        }
      } catch (error: unknown) {
        console.error("Error calculating schedule time:", error);
      }
    },
    [queueTypes, user]
  );

  useEffect(() => {
    if (selectedQueue !== "unassigned") {
      void calculateQueueScheduleTime(selectedQueue);
    }
    // Notify parent component of queue type change
    if (onQueueTypeChange) {
      onQueueTypeChange(selectedQueue);
    }
  }, [selectedQueue, onQueueTypeChange, calculateQueueScheduleTime]);

  const handleScheduleIntervalClick = (intervalHours: string | number) => {
    // Find the currently selected queue type
    const selectedQueueType = queueTypes.find((qt) => {
      if (typeof qt === "string") {
        return qt === selectedQueue;
      }
      if (
        typeof qt === "object" &&
        "name" in qt &&
        typeof qt.name === "string"
      ) {
        return qt.name === selectedQueue;
      }
      return false;
    });

    // If this is a fixed slot queue, use the API to get the next scheduled time instead
    if (
      selectedQueueType &&
      typeof selectedQueueType === "object" &&
      "scheduleType" in selectedQueueType &&
      selectedQueueType.scheduleType === "FIXED_SLOTS"
    ) {
      // For fixed slot queues, recalculate the schedule time instead of adding hours
      void calculateQueueScheduleTime(selectedQueue);
      return;
    }

    const now = new Date();
    const intervalHoursNum =
      typeof intervalHours === "string"
        ? parseInt(intervalHours, 10)
        : intervalHours;
    const hoursLater = new Date(
      now.getTime() + intervalHoursNum * 60 * 60 * 1000
    );

    // Format the date in the user's timezone
    const userTimezone =
      user &&
      typeof user === "object" &&
      "timezone" in user &&
      typeof user.timezone === "string"
        ? user.timezone
        : "UTC";
    const formattedDate = hoursLater.toLocaleString("en-US", {
      timeZone: userTimezone,
      year: "numeric",
      month: "2-digit",
      day: "2-digit",
      hour: "2-digit",
      minute: "2-digit",
      hour12: false,
    });

    // Parse the formatted date back into components
    const [datePart, timePart] = formattedDate.split(", ");
    const [month, day, year] = datePart?.split("/") ?? ["", "", ""];
    const [hours, minutes] = timePart?.split(":") ?? ["", ""];

    // Create the datetime-local format (YYYY-MM-DDTHH:mm)
    if (!year || !month || !day || !hours || !minutes) {
      return "";
    }
    const formattedForInput = `${year}-${month}-${day}T${hours}:${minutes}`;

    setScheduledFor(formattedForInput);
    setTimeError("");
  };

  // Handle fetcher success data
  const fetcherDataRaw = fetcher.data;
  const fetcherData =
    fetcherDataRaw &&
    typeof fetcherDataRaw === "object" &&
    !Array.isArray(fetcherDataRaw)
      ? (fetcherDataRaw as {
          success?: unknown;
          fileUrls?: unknown;
          error?: unknown;
        })
      : null;
  const isSuccess =
    fetcherData &&
    typeof fetcherData.success === "boolean" &&
    fetcherData.success;
  const fileUrls =
    fetcherData &&
    "fileUrls" in fetcherData &&
    Array.isArray(fetcherData.fileUrls)
      ? fetcherData.fileUrls
      : null;
  const error =
    fetcherData && typeof fetcherData.error === "string"
      ? fetcherData.error
      : null;

  if (isSuccess && fileUrls) {
    toast.success("Images uploaded successfully!");

    const preparedData: PreparedEventData[] = fileUrls.map((url: unknown) => {
      const urlObj =
        url && typeof url === "object" && !Array.isArray(url)
          ? (url as {
              fileUrl?: unknown;
              scheduledFor?: unknown;
              queueType?: unknown;
            })
          : {};
      const fileUrl = typeof urlObj.fileUrl === "string" ? urlObj.fileUrl : "";
      const queueType =
        typeof urlObj.queueType === "string" ? urlObj.queueType : selectedQueue;
      return {
        content: fileUrl,
        type: "image",
        queueType, // Include queue type information
      };
    });

    setShowImagePreview(true);
    setPreparedImageEvent(preparedData);
    setFiles([]);
  }

  // Add error handling
  if (
    fetcherData &&
    typeof fetcherData.success === "boolean" &&
    !fetcherData.success &&
    error
  ) {
    toast.error(error);
  }

  const isUploaded = Boolean(isSuccess && fileUrls);

  return (
    <fetcher.Form
      method="post"
      className="w-full"
      encType="multipart/form-data"
      onSubmit={(e) => {
        handleImagePreview(e);
      }}
    >
      <input type="hidden" name="_action" value="upload-images-preview" />
      <label
        className={`block ${isUploaded ? "cursor-not-allowed" : "cursor-pointer"}`}
      >
        <input
          type="file"
          name="files"
          className="hidden"
          accept="image/*"
          multiple
          onChange={(e) => {
            void handleFileChange(e);
          }}
          disabled={fetcher.state !== "idle" || isUploaded}
        />
        <div
          className={`rounded-lg border-2 border-dashed border-gray-300 p-12 text-center ${!isUploaded && "hover:border-gray-400"}`}
          onDrop={
            !isUploaded
              ? (e) => {
                  void handleDrop(e);
                }
              : undefined
          }
          onDragOver={!isUploaded ? handleDragOver : undefined}
        >
          {files.length > 0 ? (
            <div className="flex flex-wrap gap-4">
              {files.map((file, index) => (
                // eslint-disable-next-line react/no-array-index-key -- Stable list of files, no unique ID available
                <div key={index} className="relative">
                  <img
                    src={URL.createObjectURL(file)}
                    alt="Preview"
                    className="h-32 w-32 object-cover"
                  />
                  <button
                    type="button"
                    onClick={() =>
                      setFiles(files.filter((_, i) => i !== index))
                    }
                    className="absolute -top-2 -right-2 rounded-full bg-red-500 p-1 text-white hover:bg-red-600"
                    disabled={fetcher.state !== "idle"}
                  >
                    ×
                  </button>
                </div>
              ))}
              <div className="flex h-32 w-32 items-center justify-center border-2 border-dashed border-gray-300 hover:border-gray-400">
                <span className="text-4xl text-gray-500">+</span>
              </div>
            </div>
          ) : (
            <div className="flex flex-col items-center gap-4">
              <div className="text-green-500">
                <svg
                  xmlns="http://www.w3.org/2000/svg"
                  className="h-12 w-12"
                  fill="none"
                  viewBox="0 0 24 24"
                  stroke="currentColor"
                >
                  <path
                    strokeLinecap="round"
                    strokeLinejoin="round"
                    strokeWidth={2}
                    d="M7 16a4 4 0 01-.88-7.903A5 5 0 1115.9 6L16 6a5 5 0 011 9.9M15 13l-3-3m0 0l-3 3m3-3v12"
                  />
                </svg>
              </div>
              <div>
                <p className="text-xl font-medium text-gray-900 dark:text-gray-100">
                  Click to upload or drag and drop
                </p>
                <p className="mt-1 text-sm text-gray-500">
                  Multiple images (max 100MB total)
                </p>
              </div>
            </div>
          )}
        </div>
      </label>
      <div className="mt-4">
        <textarea
          name="caption"
          className="w-full rounded-lg border p-4 text-gray-900"
          placeholder="Add a caption to your image(s)..."
          rows={3}
          disabled={fetcher.state !== "idle" || isUploaded}
        />
      </div>
      <div className="mt-4 flex items-center justify-between gap-4">
        <div className="flex flex-col gap-2">
          <div className="mb-2">
            <label
              htmlFor="queue-type-selector"
              className="mb-2 block text-sm font-medium text-gray-700 dark:text-gray-300"
            >
              Queue Type
            </label>
            <div className="flex flex-wrap gap-2">
              {/* Unassigned option */}
              <button
                type="button"
                onClick={() => setSelectedQueue("unassigned")}
                disabled={fetcher.state !== "idle" || isUploaded}
                className={`rounded-full px-4 py-2 text-sm ${getDynamicQueueStyle(null, selectedQueue === "unassigned")} disabled:cursor-not-allowed disabled:opacity-50`}
              >
                Unassigned
              </button>

              {/* Queue types */}
              {queueTypes
                .filter((queue) => {
                  return typeof queue === "object"
                    ? queue.isEnabled !== false
                    : true;
                })
                .map((queue) => {
                  const queueName =
                    typeof queue === "string" ? queue : queue.name;
                  const queueColor =
                    typeof queue === "object" ? queue.color : null;
                  return (
                    <button
                      key={queueName}
                      type="button"
                      onClick={() => setSelectedQueue(queueName)}
                      disabled={fetcher.state !== "idle" || isUploaded}
                      className={`rounded-full px-4 py-2 text-sm ${getDynamicQueueStyle(queueColor ?? null, selectedQueue === queueName)} disabled:cursor-not-allowed disabled:opacity-50`}
                      style={{
                        backgroundColor: queueColor ?? undefined,
                        borderColor: queueColor ?? undefined,
                      }}
                    >
                      {queueName}
                    </button>
                  );
                })}
            </div>
            <input type="hidden" name="queueType" value={selectedQueue} />
          </div>
          <div className="mb-2 flex items-center gap-2">
            <input
              type="checkbox"
              id="isRecyclable"
              name="isRecyclable"
              checked={isRecyclable}
              onChange={(e) => setIsRecyclable(e.target.checked)}
              disabled={fetcher.state !== "idle" || isUploaded}
              className="h-4 w-4 rounded border-gray-300 text-blue-600 focus:ring-blue-500"
            />
            <label
              htmlFor="isRecyclable"
              className="text-sm text-gray-700 dark:text-gray-300"
            >
              Make this post recyclable
            </label>
          </div>
          <div className="flex items-center gap-4">
            <input
              type="datetime-local"
              name="scheduledFor"
              value={scheduledFor}
              onChange={(e) => {
                setScheduledFor(e.target.value);
                setTimeError("");
              }}
              className={`rounded-md border ${timeError ? "border-red-500" : "border-gray-300"} p-2 text-gray-900`}
              disabled={fetcher.state !== "idle" || isUploaded}
            />
          </div>
          {timeError ? (
            <p className="text-sm text-red-500">{timeError}</p>
          ) : null}
          <div className="flex flex-wrap gap-2">
            {(() => {
              // Find the currently selected queue type
              const selectedQueueType = queueTypes.find((qt) => {
                if (typeof qt === "string") {
                  return qt === selectedQueue;
                }
                if (
                  typeof qt === "object" &&
                  "name" in qt &&
                  typeof qt.name === "string"
                ) {
                  return qt.name === selectedQueue;
                }
                return false;
              });

              // For fixed slot queues, show a different UI
              if (
                selectedQueueType &&
                typeof selectedQueueType === "object" &&
                "scheduleType" in selectedQueueType &&
                selectedQueueType.scheduleType === "FIXED_SLOTS"
              ) {
                return (
                  <button
                    type="button"
                    onClick={() => {
                      void calculateQueueScheduleTime(selectedQueue);
                    }}
                    className="rounded-md bg-blue-100 px-2.5 py-1.5 text-xs font-medium text-blue-700 hover:bg-blue-200 dark:bg-blue-800 dark:text-blue-300 dark:hover:bg-blue-700"
                    disabled={fetcher.state !== "idle" || isUploaded}
                  >
                    Next Slot
                  </button>
                );
              }

              // For interval-based queues, show the hour buttons
              if (scheduleIntervals && Array.isArray(scheduleIntervals)) {
                return scheduleIntervals
                  .map((interval: unknown) => {
                    const intervalValue =
                      typeof interval === "string"
                        ? interval
                        : typeof interval === "number"
                          ? String(interval)
                          : "";
                    if (!intervalValue) return null;
                    return (
                      <button
                        key={intervalValue}
                        type="button"
                        onClick={() =>
                          handleScheduleIntervalClick(intervalValue)
                        }
                        className="rounded-md bg-gray-100 px-2.5 py-1.5 text-xs font-medium text-gray-700 hover:bg-gray-200 dark:bg-gray-800 dark:text-gray-300 dark:hover:bg-gray-700"
                        disabled={fetcher.state !== "idle" || isUploaded}
                      >
                        +{intervalValue}h
                      </button>
                    );
                  })
                  .filter((button): button is JSX.Element => button !== null);
              }
              return null;
            })()}
          </div>
        </div>
        <button
          type="submit"
          className="rounded-lg bg-green-500 px-8 py-4 text-white hover:bg-green-600 disabled:opacity-50"
          disabled={
            fetcher.state !== "idle" || isUploaded || files.length === 0
          }
        >
          {fetcher.state !== "idle" ? "Uploading..." : "Upload Images →"}
        </button>
      </div>
    </fetcher.Form>
  );
}

import { useFetcher, Link } from "@remix-run/react";
import { useState } from "react";

import { Badge } from "~/components/ui/badge";
import { Button } from "~/components/ui/button";
import type {
  LongFormPostType,
  LongFormPostData,
} from "~/features/posts/server";
import { handleErrorSafely } from "~/lib/error-handler.client";

import type { EditorJSBlock } from "../types/editorjs.types";
interface LongFormDetailsModalProps {
  post: LongFormPostType | LongFormPostData;
  onClose: () => void;
  type: "draft" | "scheduled" | "posted";
  showSignedEvent?: boolean;
  userTimezone?: string;
}

export default function LongFormDetailsModal({
  post,
  onClose,
  type,
  showSignedEvent = false,
  userTimezone = "UTC",
}: LongFormDetailsModalProps) {
  const [showEventData, setShowEventData] = useState(false);
  const deleteFetcher = useFetcher();

  const convertEditorJSToHTML = (content: string) => {
    if (!content || content.trim() === "") {
      return '<p class="text-gray-500 italic">No content available</p>';
    }

    try {
      const editorData = JSON.parse(content) as { blocks?: EditorJSBlock[] };

      if (!editorData.blocks || !Array.isArray(editorData.blocks)) {
        return '<p class="text-gray-500 italic">No content blocks found</p>';
      }

      let html = "";

      editorData.blocks.forEach((block: EditorJSBlock) => {
        switch (block.type) {
          case "header": {
            const levelValue = block.data["level"];
            const level = typeof levelValue === "number" ? levelValue : 3;
            const levelStr = String(level);
            const textValue = block.data["text"];
            const text = typeof textValue === "string" ? textValue : "";
            html += `<h${levelStr} class="text-${level === 2 ? "2xl" : level === 3 ? "xl" : "lg"} font-bold mb-4 text-gray-900 dark:text-white">${text}</h${levelStr}>`;
            break;
          }
          case "paragraph": {
            const textValue = block.data["text"];
            const text = typeof textValue === "string" ? textValue : "";
            html += `<p class="mb-4 text-gray-700 dark:text-gray-300 leading-relaxed">${text}</p>`;
            break;
          }
          case "list": {
            const listType = block.data["style"] === "ordered" ? "ol" : "ul";
            const listClass =
              block.data["style"] === "ordered" ? "list-decimal" : "list-disc";
            html += `<${listType} class="${listClass} ml-6 mb-4 text-gray-700 dark:text-gray-300">`;
            if (Array.isArray(block.data["items"])) {
              const items = block.data["items"];
              if (Array.isArray(items)) {
                items.forEach((item: string) => {
                  html += `<li class="mb-1">${item}</li>`;
                });
              }
            }
            html += `</${listType}>`;
            break;
          }
          case "quote": {
            const textValue = block.data["text"];
            const text = typeof textValue === "string" ? textValue : "";
            const captionValue = block.data["caption"];
            const caption =
              typeof captionValue === "string" ? captionValue : "";
            html += `<blockquote class="border-l-4 border-blue-500 pl-4 py-2 mb-4 italic text-gray-600 dark:text-gray-400 bg-gray-50 dark:bg-gray-800 rounded-r">
              <p>${text}</p>
              ${caption ? `<footer class="text-sm mt-2">— ${caption}</footer>` : ""}
            </blockquote>`;
            break;
          }
          case "code": {
            const codeValue = block.data["code"];
            const code = typeof codeValue === "string" ? codeValue : "";
            html += `<pre class="bg-gray-900 dark:bg-gray-800 text-green-400 p-4 rounded-lg mb-4 overflow-x-auto"><code>${code}</code></pre>`;
            break;
          }
          case "linkTool": {
            const link =
              typeof block.data["link"] === "string" ? block.data["link"] : "";
            const meta =
              typeof block.data["meta"] === "object" &&
              block.data["meta"] !== null
                ? (block.data["meta"] as {
                    title?: string;
                    description?: string;
                  })
                : null;
            html += `<div class="border border-gray-200 dark:border-gray-700 rounded-lg p-4 mb-4">
              <a href="${link}" target="_blank" rel="noopener noreferrer" class="text-blue-600 dark:text-blue-400 hover:underline">
                <div class="font-semibold">${meta?.title ?? link}</div>
                ${meta?.description ? `<div class="text-gray-600 dark:text-gray-400 text-sm mt-1">${meta.description}</div>` : ""}
              </a>
            </div>`;
            break;
          }
          case "embed": {
            const embed =
              typeof block.data["embed"] === "string"
                ? block.data["embed"]
                : "";
            html += `<div class="mb-4">
              <iframe src="${embed}" class="w-full aspect-video rounded-lg" frameborder="0" allowfullscreen></iframe>
            </div>`;
            break;
          }
          case "image": {
            const file =
              typeof block.data["file"] === "object" &&
              block.data["file"] !== null
                ? (block.data["file"] as { url?: string })
                : null;
            const url =
              typeof block.data["url"] === "string" ? block.data["url"] : "";
            const imageUrl = file?.url ?? url;
            const caption =
              typeof block.data["caption"] === "string"
                ? block.data["caption"]
                : "";
            if (imageUrl) {
              html += `<figure class="mb-6">
                <img src="${imageUrl}" alt="${caption}" class="w-full rounded-lg shadow-sm" style="max-height: 500px; object-fit: contain;" />
                ${caption ? `<figcaption class="text-center text-sm text-gray-600 dark:text-gray-400 mt-2 italic">${caption}</figcaption>` : ""}
              </figure>`;
            }
            break;
          }
          default:
            if (typeof block.data["text"] === "string") {
              html += `<p class="mb-4 text-gray-700 dark:text-gray-300">${block.data["text"]}</p>`;
            } else {
              const file =
                block.data["file"] && typeof block.data["file"] === "object"
                  ? (block.data["file"] as { url?: string })
                  : null;
              if (file?.url) {
                // Handle any other block types that might have images
                html += `<div class="mb-4">
                  <img src="${file.url}" alt="" class="w-full rounded-lg" style="max-height: 400px; object-fit: contain;" />
                </div>`;
              }
            }
        }
      });

      return (
        html ||
        '<p class="text-gray-500 italic">Content could not be rendered</p>'
      );
    } catch (error) {
      handleErrorSafely(error, {
        component: "LongFormDetailsModal",
        action: "parseEditorJSContent",
      });
      // Try to display as plain text if JSON parsing fails
      const plainTextContent = content.replace(/<[^>]*>/g, "");
      return `<p class="text-gray-700 dark:text-gray-300">${plainTextContent}</p>`;
    }
  };

  const formatDate = (dateInput?: string | Date | number) => {
    if (!dateInput) return "—";

    let date: Date;

    // Handle different input formats
    if (typeof dateInput === "string") {
      // Check if it's a Unix timestamp string
      const unixTimestamp = parseInt(dateInput);
      if (!isNaN(unixTimestamp) && dateInput.length <= 13) {
        // Unix timestamp (seconds or milliseconds)
        date = new Date(unixTimestamp * (dateInput.length <= 10 ? 1000 : 1));
      } else {
        // ISO string
        date = new Date(dateInput);
      }
    } else if (typeof dateInput === "number") {
      // Unix timestamp (seconds or milliseconds)
      date = new Date(
        dateInput * (dateInput.toString().length <= 10 ? 1000 : 1)
      );
    } else {
      // Date object
      date = new Date(dateInput);
    }

    return date.toLocaleString("en-US", {
      timeZone: userTimezone,
      month: "2-digit",
      day: "2-digit",
      year: "numeric",
      hour: "numeric",
      minute: "2-digit",
      hour12: true,
    });
  };

  const getReadingTime = (content?: string) => {
    if (!content) return "0 min read";

    try {
      let wordCount = 0;

      // If it's JSON (EditorJS format), extract text from blocks
      if (content.startsWith("{")) {
        const editorData = JSON.parse(content) as { blocks?: EditorJSBlock[] };
        editorData.blocks?.forEach((block: EditorJSBlock) => {
          if (block.type === "paragraph" || block.type === "header") {
            const text =
              typeof block.data["text"] === "string"
                ? block.data["text"].replace(/<[^>]*>/g, "")
                : "";
            wordCount += text
              .split(/\s+/)
              .filter((word: string) => word.length > 0).length;
          } else if (block.type === "list") {
            const items = Array.isArray(block.data["items"])
              ? block.data["items"]
              : [];
            items.forEach((item: unknown) => {
              const text =
                typeof item === "string" ? item.replace(/<[^>]*>/g, "") : "";
              wordCount += text
                .split(/\s+/)
                .filter((word: string) => word.length > 0).length;
            });
          }
        });
      } else {
        // Plain text or markdown
        const text = content.replace(/<[^>]*>/g, "");
        wordCount = text.split(/\s+/).filter((word) => word.length > 0).length;
      }

      const readingTime = Math.ceil(wordCount / 200); // Average 200 words per minute
      return `${readingTime} min read`;
    } catch {
      return "— min read";
    }
  };

  const getStatusBadge = () => {
    if (type === "draft") {
      return (
        <Badge
          variant="secondary"
          className="bg-orange-100 text-orange-900 dark:bg-orange-700/10 dark:text-orange-200"
        >
          Draft
        </Badge>
      );
    } else if (type === "scheduled") {
      return (
        <Badge
          variant="secondary"
          className="bg-blue-100 text-blue-900 dark:bg-blue-700/10 dark:text-blue-200"
        >
          Scheduled
        </Badge>
      );
    } else {
      return (
        <Badge
          variant="secondary"
          className="bg-green-100 text-green-900 dark:bg-green-700/10 dark:text-green-200"
        >
          Published
        </Badge>
      );
    }
  };

  const getModalTitle = () => {
    if (type === "draft") return "Draft Article";
    if (type === "scheduled") return "Scheduled Article";
    return "Published Article";
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 backdrop-blur-sm">
      <div className="mx-4 flex max-h-[90vh] w-full max-w-5xl flex-col overflow-hidden rounded-xl bg-white shadow-2xl dark:bg-gray-900">
        {/* Header */}
        <div className="sticky top-0 z-10 border-b border-gray-200 bg-white/95 px-6 py-4 backdrop-blur-sm dark:border-gray-700 dark:bg-gray-900/95">
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-3">
              <h2 className="text-xl font-semibold text-gray-900 dark:text-white">
                {getModalTitle()}
              </h2>
              {getStatusBadge()}
            </div>
            <button
              onClick={onClose}
              className="flex h-8 w-8 items-center justify-center rounded-full text-gray-400 transition-colors hover:bg-gray-100 hover:text-gray-600 dark:hover:bg-gray-800 dark:hover:text-gray-300"
            >
              ✕
            </button>
          </div>
        </div>

        {/* Content */}
        <div className="flex flex-1 overflow-hidden">
          {/* Preview Panel */}
          <div className="flex-1 overflow-y-auto">
            {/* Article Preview - Primal/NOSTR style */}
            <div className="mx-auto max-w-3xl p-6">
              {/* Author Header */}
              <div className="mb-4 flex items-center gap-3">
                <div className="flex h-12 w-12 items-center justify-center rounded-full bg-gradient-to-br from-blue-500 to-purple-600 text-lg font-semibold text-white">
                  A
                </div>
                <div>
                  <div className="font-semibold text-gray-900 dark:text-white">
                    You
                  </div>
                </div>
                <div className="ml-auto">
                  <svg
                    className="h-6 w-6 text-gray-400"
                    fill="none"
                    stroke="currentColor"
                    viewBox="0 0 24 24"
                  >
                    <path
                      strokeLinecap="round"
                      strokeLinejoin="round"
                      strokeWidth={2}
                      d="M12 5v.01M12 12v.01M12 19v.01M12 6a1 1 0 110-2 1 1 0 010 2zm0 7a1 1 0 110-2 1 1 0 010 2zm0 7a1 1 0 110-2 1 1 0 010 2z"
                    />
                  </svg>
                </div>
              </div>

              {/* Date and Reading Time */}
              <div className="mb-4 flex items-center gap-2 text-sm text-gray-500 dark:text-gray-400">
                <span>
                  {formatDate(
                    type === "posted"
                      ? (post.publishedAt ?? undefined)
                      : type === "scheduled"
                        ? (post.scheduledFor ?? undefined)
                        : post.createdAt
                  )}
                </span>
                <span>•</span>
                <span>{getReadingTime(post.content ?? undefined)}</span>
                <span>•</span>
                <span>via SmartFlow</span>
                <div className="ml-auto">
                  <svg
                    className="h-5 w-5"
                    fill="none"
                    stroke="currentColor"
                    viewBox="0 0 24 24"
                  >
                    <path
                      strokeLinecap="round"
                      strokeLinejoin="round"
                      strokeWidth={2}
                      d="M5 5a2 2 0 012-2h10a2 2 0 012 2v16l-7-3.5L5 21V5z"
                    />
                  </svg>
                </div>
              </div>

              {/* Title */}
              <h1 className="mb-6 text-3xl leading-tight font-bold text-gray-900 dark:text-white">
                {post.title ?? "Untitled Article"}
              </h1>

              {/* Cover Image */}
              {post.image ? (
                <div className="mb-6 overflow-hidden rounded-2xl">
                  <img
                    src={post.image}
                    alt="Cover"
                    className="h-80 w-full object-cover"
                  />
                </div>
              ) : null}

              {/* Summary */}
              {post.summary ? (
                <div className="mb-6 rounded-xl bg-gray-50 p-6 dark:bg-gray-800">
                  <p className="text-lg leading-relaxed font-medium text-gray-700 dark:text-gray-300">
                    {post.summary}
                  </p>
                </div>
              ) : null}

              {/* Content */}
              <div
                className="prose prose-lg dark:prose-invert max-w-none text-gray-900 dark:text-white"
                style={{
                  fontSize: "1.1rem",
                  lineHeight: "1.7",
                  color: "inherit",
                }}
                dangerouslySetInnerHTML={{
                  __html: convertEditorJSToHTML(post.content ?? ""),
                }}
              />

              {/* Tags */}
              {post.tags.length > 0 ? (
                <div className="mt-8 flex items-center gap-2 border-t border-gray-200 pt-6 dark:border-gray-700">
                  {post.tags.map((tag) => (
                    <span
                      key={tag}
                      className="cursor-pointer text-sm text-blue-600 hover:underline dark:text-blue-400"
                    >
                      #{tag}
                    </span>
                  ))}
                </div>
              ) : null}
            </div>
          </div>

          {/* Details Sidebar */}
          <div className="w-80 overflow-y-auto border-l border-gray-200 dark:border-gray-700">
            <div className="space-y-6 p-6">
              <div>
                <h3 className="mb-3 text-sm font-medium text-gray-700 dark:text-gray-300">
                  Article Details
                </h3>
                <div className="space-y-4">
                  <div>
                    <span className="text-xs text-gray-500 dark:text-gray-400">
                      Status
                    </span>
                    <div className="mt-1">{getStatusBadge()}</div>
                  </div>

                  <div>
                    <span className="text-xs text-gray-500 dark:text-gray-400">
                      {type === "posted"
                        ? "Published"
                        : type === "scheduled"
                          ? "Scheduled For"
                          : "Created"}
                    </span>
                    <p className="mt-1 text-sm text-gray-900 dark:text-white">
                      {formatDate(
                        type === "posted"
                          ? (post.publishedAt ?? undefined)
                          : type === "scheduled"
                            ? (post.scheduledFor ?? undefined)
                            : post.createdAt
                      )}
                    </p>
                  </div>

                  <div>
                    <span className="text-xs text-gray-500 dark:text-gray-400">
                      Reading Time
                    </span>
                    <p className="mt-1 text-sm text-gray-900 dark:text-white">
                      {getReadingTime(post.content ?? undefined)}
                    </p>
                  </div>

                  {post.tags.length > 0 ? (
                    <div>
                      <span className="text-xs text-gray-500 dark:text-gray-400">
                        Tags
                      </span>
                      <div className="mt-1 flex flex-wrap gap-1">
                        {post.tags.map((tag) => (
                          <span
                            key={tag}
                            className="rounded bg-gray-100 px-2 py-1 text-xs text-gray-700 dark:bg-gray-800 dark:text-gray-300"
                          >
                            #{tag}
                          </span>
                        ))}
                      </div>
                    </div>
                  ) : null}
                </div>
              </div>

              {/* Signed Event Data */}
              {showSignedEvent && post.signedEvent ? (
                <div>
                  <div className="mb-3 flex items-center justify-between">
                    <h3 className="text-sm font-medium text-gray-700 dark:text-gray-300">
                      Signed Event Data
                    </h3>
                    <button
                      onClick={() => setShowEventData(!showEventData)}
                      className="text-xs text-blue-600 hover:underline dark:text-blue-400"
                    >
                      {showEventData ? "Hide" : "Show"}
                    </button>
                  </div>
                  {showEventData ? (
                    <div className="rounded-lg bg-gray-100 p-3 dark:bg-gray-800">
                      <pre className="max-h-64 overflow-auto text-xs break-words whitespace-pre-wrap text-gray-800 dark:text-gray-200">
                        {JSON.stringify(post.signedEvent, null, 2)}
                      </pre>
                    </div>
                  ) : null}
                </div>
              ) : null}
            </div>
          </div>
        </div>

        {/* Footer */}
        <div className="sticky bottom-0 border-t border-gray-200 bg-white/95 px-6 py-4 backdrop-blur-sm dark:border-gray-700 dark:bg-gray-900/95">
          <div className="flex items-center justify-between">
            <div className="flex gap-3">
              {type === "posted" &&
              (post.nostrEventId ??
                (typeof post.signedEvent === "object" &&
                post.signedEvent !== null &&
                "id" in post.signedEvent
                  ? (post.signedEvent as { id?: string }).id
                  : undefined)) ? (
                <Link
                  to={`https://primal.net/a/${String(post.nostrEventId ?? (typeof post.signedEvent === "object" && post.signedEvent !== null && "id" in post.signedEvent ? (post.signedEvent as { id?: string }).id : "") ?? "")}`}
                  target="_blank"
                  rel="noreferrer"
                  className="inline-flex items-center rounded-lg bg-gray-900 px-4 py-2 text-sm font-medium text-white transition-colors hover:bg-gray-800 focus:ring-2 focus:ring-gray-500 focus:ring-offset-2 focus:outline-none dark:bg-gray-700 dark:hover:bg-gray-600"
                >
                  View Article
                </Link>
              ) : null}

              {type === "draft" ? (
                <Link
                  to={`/dashboard/drafts/longform/edit/${post.id}`}
                  className="inline-flex items-center rounded-lg border border-blue-200 bg-white px-4 py-2 text-sm font-medium text-blue-800 transition-colors hover:bg-blue-50 focus:ring-2 focus:ring-blue-500 focus:ring-offset-2 focus:outline-none dark:border-blue-700 dark:bg-gray-800 dark:text-blue-300 dark:hover:bg-blue-950/50"
                >
                  Edit Draft
                </Link>
              ) : null}
            </div>

            <div className="flex gap-3">
              <deleteFetcher.Form
                method="post"
                onClick={(e) => e.stopPropagation()}
              >
                <input type="hidden" name="postId" value={post.id} />
                <input type="hidden" name="_action" value="deleteLongForm" />
                <button
                  type="submit"
                  disabled={deleteFetcher.state !== "idle"}
                  className="inline-flex items-center rounded-lg border border-red-300 bg-white px-4 py-2 text-sm font-medium text-red-700 transition-colors hover:bg-red-50 focus:ring-2 focus:ring-red-500 focus:ring-offset-2 focus:outline-none disabled:opacity-50 dark:border-red-600 dark:bg-gray-800 dark:text-red-400 dark:hover:bg-red-950/50"
                >
                  {deleteFetcher.state !== "idle" &&
                  deleteFetcher.formData?.get("postId") === post.id
                    ? "Deleting..."
                    : "Delete"}
                </button>
              </deleteFetcher.Form>

              <Button onClick={onClose}>Close</Button>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

import { useFetcher, Link } from "@remix-run/react";
import { useState, useEffect, useMemo } from "react";

import type { LongFormPostType } from "~/features/posts/server";

import type { PostFetcher, LongFormPostData } from "../types";
import type { EditorJSBlock } from "../types/editorjs.types";

// Helper to safely access formData from a fetcher
function getFetcherFormData(
  fetcher: PostFetcher | undefined
): FormData | null | undefined {
  return fetcher
    ? (fetcher as { formData?: FormData | null }).formData
    : undefined;
}

interface LongFormListingProps {
  posts: Array<LongFormPostType | LongFormPostData>;
  type: "draft" | "scheduled" | "posted";
  onPostSelect?: (post: LongFormPostType | LongFormPostData) => void;
  searchTerm?: string;
  onSearchChange?: (term: string) => void;
  userTimezone?: string;
  longformRepostFetcher?: PostFetcher;
  longformQuoteFetcher?: PostFetcher;
  onEditPost?: (post: LongFormPostType | LongFormPostData) => void;
  onReschedulePost?: (post: LongFormPostType | LongFormPostData) => void;
}

export default function LongFormListing({
  posts,
  type,
  onPostSelect,
  searchTerm = "",
  onSearchChange,
  userTimezone = "UTC",
  longformRepostFetcher,
  longformQuoteFetcher,
  onEditPost,
  onReschedulePost,
}: LongFormListingProps) {
  const [sortConfig, setSortConfig] = useState({
    key:
      type === "posted"
        ? "publishedAt"
        : type === "scheduled"
          ? "scheduledFor"
          : "createdAt",
    direction:
      type === "posted" ? "desc" : type === "scheduled" ? "asc" : "desc",
  });
  const [selectedPosts, setSelectedPosts] = useState(new Set<string>());
  const [countdowns, setCountdowns] = useState<Record<string, string>>({});
  const deleteFetcher = useFetcher();
  interface BulkDeleteFetcherData {
    success?: boolean;
  }
  const bulkDeleteFetcher = useFetcher<BulkDeleteFetcherData>();

  const sortedPosts = [...posts].sort((a, b) => {
    let aValue, bValue;

    if (sortConfig.key === "publishedAt") {
      aValue = a.publishedAt ? new Date(a.publishedAt).getTime() : 0;
      bValue = b.publishedAt ? new Date(b.publishedAt).getTime() : 0;
    } else if (sortConfig.key === "scheduledFor") {
      // Handle scheduledFor as Unix timestamp string
      aValue = a.scheduledFor ? parseInt(a.scheduledFor) * 1000 : 0;
      bValue = b.scheduledFor ? parseInt(b.scheduledFor) * 1000 : 0;
    } else if (sortConfig.key === "createdAt") {
      aValue = new Date(a.createdAt).getTime();
      bValue = new Date(b.createdAt).getTime();
    } else {
      const aVal = a[sortConfig.key as keyof LongFormPostType];
      const bVal = b[sortConfig.key as keyof LongFormPostType];

      if (typeof aVal === "string" && typeof bVal === "string") {
        return sortConfig.direction === "asc"
          ? aVal.localeCompare(bVal)
          : bVal.localeCompare(aVal);
      }

      aValue = typeof aVal === "number" ? aVal : 0;
      bValue = typeof bVal === "number" ? bVal : 0;
    }

    return sortConfig.direction === "asc" ? aValue - bValue : bValue - aValue;
  });

  const filteredPosts = sortedPosts.filter(
    (post) =>
      post.title?.toLowerCase().includes(searchTerm.toLowerCase()) ??
      post.summary?.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const requestSort = (key: string) => {
    setSortConfig((current) => ({
      key,
      direction:
        current.key === key && current.direction === "asc" ? "desc" : "asc",
    }));
  };

  const formatDate = (dateInput?: string | Date | number) => {
    if (!dateInput) return "—";

    let date: Date;

    // Handle different input formats
    if (typeof dateInput === "string") {
      // Check if it's a Unix timestamp string
      const unixTimestamp = parseInt(dateInput);
      if (!isNaN(unixTimestamp) && dateInput.length <= 13) {
        // Unix timestamp (seconds or milliseconds)
        date = new Date(unixTimestamp * (dateInput.length <= 10 ? 1000 : 1));
      } else {
        // ISO string
        date = new Date(dateInput);
      }
    } else if (typeof dateInput === "number") {
      // Unix timestamp (seconds or milliseconds)
      date = new Date(
        dateInput * (dateInput.toString().length <= 10 ? 1000 : 1)
      );
    } else {
      // Date object
      date = new Date(dateInput);
    }

    return date.toLocaleString("en-US", {
      timeZone: userTimezone,
      month: "2-digit",
      day: "2-digit",
      year: "numeric",
      hour: "numeric",
      minute: "2-digit",
      hour12: true,
    });
  };

  const getReadingTime = (content?: string) => {
    if (!content) return "0 min read";

    try {
      let wordCount = 0;

      // If it's JSON (EditorJS format), extract text from blocks
      if (content.startsWith("{")) {
        const editorData = JSON.parse(content) as { blocks?: EditorJSBlock[] };
        editorData.blocks?.forEach((block: EditorJSBlock) => {
          if (block.type === "paragraph" || block.type === "header") {
            const text =
              typeof block.data["text"] === "string"
                ? block.data["text"].replace(/<[^>]*>/g, "")
                : "";
            wordCount += text
              .split(/\s+/)
              .filter((word: string) => word.length > 0).length;
          } else if (block.type === "list") {
            const items = Array.isArray(block.data["items"])
              ? block.data["items"]
              : [];
            items.forEach((item: unknown) => {
              const text =
                typeof item === "string" ? item.replace(/<[^>]*>/g, "") : "";
              wordCount += text
                .split(/\s+/)
                .filter((word: string) => word.length > 0).length;
            });
          }
        });
      } else {
        // Plain text or markdown
        const text = content.replace(/<[^>]*>/g, "");
        wordCount = text.split(/\s+/).filter((word) => word.length > 0).length;
      }

      const readingTime = Math.ceil(wordCount / 200); // Average 200 words per minute
      return `${readingTime} min read`;
    } catch {
      return "— min read";
    }
  };

  const togglePostSelection = (postId: string) => {
    setSelectedPosts((prev) => {
      const newSet = new Set(prev);
      if (newSet.has(postId)) {
        newSet.delete(postId);
      } else {
        newSet.add(postId);
      }
      return newSet;
    });
  };

  const toggleSelectAll = () => {
    if (selectedPosts.size === filteredPosts.length) {
      setSelectedPosts(new Set());
    } else {
      setSelectedPosts(new Set(filteredPosts.map((post) => post.id)));
    }
  };

  const handleBulkDelete = () => {
    if (selectedPosts.size === 0) return;

    const formData = new FormData();
    formData.append("_action", "bulkDeleteLongForm");
    formData.append("postIds", JSON.stringify(Array.from(selectedPosts)));

    bulkDeleteFetcher.submit(formData, { method: "post" });
  };

  // Memoize post IDs to avoid infinite loops when posts array reference changes
  const postIds = useMemo(
    () => posts.map((post) => post.id).join(","),
    [posts]
  );

  // Countdown functionality for scheduled posts
  useEffect(() => {
    if (type !== "scheduled") return;

    const updateCountdowns = () => {
      // Get current time in user's timezone
      const now = new Date(
        new Date().toLocaleString("en-US", { timeZone: userTimezone })
      ).getTime();
      const newCountdowns: Record<string, string> = {};

      posts.forEach((post) => {
        if (!post.scheduledFor) return;

        // Handle scheduledFor as Unix timestamp string (similar to regular posts)
        const utcTime = parseInt(post.scheduledFor) * 1000;
        const userTime = new Date(utcTime).toLocaleString("en-US", {
          timeZone: userTimezone,
        });
        const scheduledTime = new Date(userTime).getTime();

        const distance = scheduledTime - now;

        if (distance > 0) {
          const days = Math.floor(distance / (1000 * 60 * 60 * 24));
          const hours = Math.floor(
            (distance % (1000 * 60 * 60 * 24)) / (1000 * 60 * 60)
          );
          const minutes = Math.floor(
            (distance % (1000 * 60 * 60)) / (1000 * 60)
          );

          newCountdowns[post.id] = `${days}d ${hours}h ${minutes}m`;
        } else {
          newCountdowns[post.id] = "Due now";
        }
      });

      setCountdowns((prev) => {
        // Only update if countdowns actually changed to prevent unnecessary re-renders
        const hasChanged =
          Object.keys(newCountdowns).some(
            (id) => prev[id] !== newCountdowns[id]
          ) || Object.keys(prev).length !== Object.keys(newCountdowns).length;

        return hasChanged ? newCountdowns : prev;
      });
    };

    // Update immediately on mount
    updateCountdowns();

    const timer = setInterval(updateCountdowns, 60000); // Update every minute

    return () => clearInterval(timer);
    // Use postIds instead of posts to avoid infinite loops
    // eslint-disable-next-line react-hooks/exhaustive-deps -- Dependencies are intentionally limited to avoid infinite loops
  }, [postIds, userTimezone, type]);

  useEffect(() => {
    if (bulkDeleteFetcher.data?.success) {
      setSelectedPosts(new Set());
    }
  }, [bulkDeleteFetcher.data]);

  const getStatusBadge = (_post: LongFormPostType | LongFormPostData) => {
    if (type === "draft") {
      return (
        <div className="inline-flex rounded-full border border-transparent bg-orange-100 px-2 py-1 text-xs font-semibold leading-4 text-orange-900 dark:border-orange-900/75 dark:bg-orange-700/10 dark:text-orange-200">
          Draft
        </div>
      );
    } else if (type === "scheduled") {
      return (
