import { useFetcher } from "@remix-run/react";
import React, { useEffect } from "react";
import type { z } from "zod";

import { handleErrorSafely } from "~/lib/error-handler.client";
import { nostrAdapter } from "~/lib/nostr-adapter.client";
import {
  rescheduleModalClientSchema,
  rescheduleLongformModalClientSchema,
} from "~/lib/validation";
import { useZodForm } from "~/lib/validation/utils.client";

import type { PostData, LongFormPostData, UserData, QueueType } from "../types";

interface SimpleRescheduleModalProps {
  post: PostData | LongFormPostData;
  onClose: () => void;
  onConfirm: () => void;
  user?: UserData;
  queueTypes?: QueueType[];
}

export function SimpleRescheduleModal({
  post,
  onClose,
  onConfirm,
  user,
  queueTypes = [],
}: SimpleRescheduleModalProps) {
  interface FetcherData {
    success?: boolean;
    error?: string;
    needsSigning?: boolean;
  }
  const fetcher = useFetcher<FetcherData>();
  const [isSigningEvent, setIsSigningEvent] = React.useState(false);
  const [signingError, setSigningError] = React.useState<string | null>(null);

  // Determine if this is a longform post
  const isLongform = "title" in post;

  // Initialize form with appropriate schema
  const schema = isLongform
    ? rescheduleLongformModalClientSchema
    : rescheduleModalClientSchema;

  const initialScheduledFor =
    isLongform && "publishedAt" in post
      ? post.publishedAt
        ? new Date(post.publishedAt)
        : new Date()
      : !isLongform && "scheduledFor" in post
        ? post.scheduledFor
          ? new Date(parseInt(post.scheduledFor) * 1000)
          : new Date()
        : new Date();

  const form = useZodForm(schema, {
    defaultValues: {
      scheduledFor: initialScheduledFor,
      ...(!isLongform && "queueType" in post
        ? { queueTypeId: post.queueType?.id ?? "" }
        : {}),
    },
  });

  const scheduledFor = form.watch("scheduledFor");
  // queueTypeId is conditionally in the schema, so we need to access it safely
  // Type assertion needed because queueTypeId only exists in non-longform schema
  interface FormValues {
    scheduledFor: Date;
    queueTypeId?: string;
  }
  const formValues = form.getValues() as FormValues;
  const selectedQueueType = !isLongform ? formValues.queueTypeId : undefined;

  useEffect(() => {
    if (fetcher.data?.success) {
      if (fetcher.data.needsSigning) {
        return; // Keep modal open for re-signing
      }
      onConfirm();
    }
    if (fetcher.data?.error) {
      setSigningError(fetcher.data.error);
    }
  }, [fetcher.data, onConfirm]);

  const formatDateTimeForInput = (date: Date) => {
    const userTimezone = user?.timezone ?? "UTC";
    const dateInUserTz = new Date(
      date.toLocaleString("en-US", { timeZone: userTimezone })
    );
    const year = dateInUserTz.getFullYear();
    const month = String(dateInUserTz.getMonth() + 1).padStart(2, "0");
    const day = String(dateInUserTz.getDate()).padStart(2, "0");
    const hours = String(dateInUserTz.getHours()).padStart(2, "0");
    const minutes = String(dateInUserTz.getMinutes()).padStart(2, "0");
    return `${year}-${month}-${day}T${hours}:${minutes}`;
  };

  const handleSubmit = form.handleSubmit(async (data) => {
    try {
      setIsSigningEvent(true);
      setSigningError(null);

      const newTimeUnix = Math.floor(data.scheduledFor.getTime() / 1000);

      // Use the exact same content and tags from the original signed event
      const originalSignedEvent = post.signedEvent;
      const originalNostrEvent = post.nostrEvent;

      if (!originalSignedEvent || !originalNostrEvent) {
        throw new Error(
          "Original event not found. Cannot reschedule unsigned posts."
        );
      }

      // Re-sign with the same content but new timestamp
      const { nostrEvent, signedEvent } = await nostrAdapter.signEvent({
        content: originalSignedEvent.content, // Use exact same content
        created_at: newTimeUnix, // Only change the timestamp
        kind: originalSignedEvent.kind,
        tags: originalSignedEvent.tags, // Use exact same tags
      });

      // Submit the reschedule action with signed event
      const formData = new FormData();
      formData.append(
        "_action",
        isLongform ? "rescheduleLongform" : "reschedule"
      );
      formData.append("postId", post.id);
      formData.append("newTime", newTimeUnix.toString());
      formData.append("signedEvent", JSON.stringify(signedEvent));
      formData.append("nostrEvent", JSON.stringify(nostrEvent));

      if (!isLongform) {
        const regularData = data as z.infer<typeof rescheduleModalClientSchema>;
        formData.append("overrideQueue", "false");
        if (regularData.queueTypeId) {
          formData.append("queueTypeId", regularData.queueTypeId);
        }
      }

      fetcher.submit(formData, { method: "post" });
    } catch (error: unknown) {
      const { handleAsyncErrorWithMessage, getErrorMessage } =
        await import("~/lib/error-handler.client");
      handleAsyncErrorWithMessage(
        error,
        "Failed to sign event. Please try again.",
        {
          component: "SimpleRescheduleModal",
          action: "handleReschedule",
        },
        false // Don't show toast, we set signingError instead
      );
      setIsSigningEvent(false);
      setSigningError(
        getErrorMessage(error) || "Failed to sign event. Please try again."
      );
    }
  });

  const getFirstImage = () => {
    if ("fileUrl" in post && post.fileUrl.length > 0) {
      try {
        const firstFileUrl = post.fileUrl[0];
        if (typeof firstFileUrl === "string") {
          try {
            const parsed = JSON.parse(firstFileUrl) as string[] | string;
            return Array.isArray(parsed) ? parsed[0] : firstFileUrl;
          } catch {
            return firstFileUrl;
          }
        }
        return firstFileUrl;
      } catch (error) {
        handleErrorSafely(error, {
          component: "SimpleRescheduleModal",
          action: "getFirstImage",
        });
        return null;
      }
    }
    return null;
  };

  const formatDateTime = (date: Date) => {
    const userTimezone = user?.timezone ?? "UTC";
    return date.toLocaleDateString("en-US", {
      weekday: "long",
      month: "long",
      day: "numeric",
      hour: "2-digit",
      minute: "2-digit",
      timeZone: userTimezone,
    });
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 p-4">
      <div className="w-full max-w-md rounded-lg bg-white shadow-xl dark:bg-gray-800">
        <div className="p-6">
          {/* Header */}
          <div className="mb-4 flex items-center justify-between">
            <h3 className="text-lg font-semibold text-gray-900 dark:text-white">
              Reschedule {isLongform ? "Article" : "Post"}
            </h3>
            <button
              onClick={onClose}
              className="text-gray-400 hover:text-gray-600 dark:hover:text-gray-200"
            >
              <svg
                className="h-6 w-6"
                fill="none"
                stroke="currentColor"
                viewBox="0 0 24 24"
              >
                <path
                  strokeLinecap="round"
                  strokeLinejoin="round"
                  strokeWidth={2}
                  d="M6 18L18 6M6 6l12 12"
                />
              </svg>
            </button>
          </div>

          {/* Content */}
          <div className="space-y-4">
            {/* Post preview */}
            <div className="rounded-lg bg-gray-50 p-3 dark:bg-gray-700">
              <div className="mb-2 text-sm font-medium text-gray-900 dark:text-white">
                {isLongform ? "Article" : "Post"} Preview:
              </div>

              {/* Show image thumbnail if available */}
              {getFirstImage() ? (
                <div className="mb-2">
                  <div className="h-20 w-full overflow-hidden rounded-md">
                    <img
                      src={getFirstImage()!}
                      alt="Post preview"
                      className="h-full w-full object-cover"
                      loading="lazy"
                    />
                  </div>
                </div>
              ) : null}

              <div className="text-sm text-gray-600 dark:text-gray-300">
                {isLongform && "title" in post
                  ? (post.title ?? "Untitled Article")
                  : "caption" in post
                    ? (post.caption ?? "No caption")
                    : "No caption"}
                {"fileUrl" in post && post.fileUrl.length > 0 ? (
                  <span className="ml-2 text-xs text-gray-500">
                    ({post.fileUrl.length} file
                    {post.fileUrl.length > 1 ? "s" : ""})
                  </span>
                ) : null}
              </div>
            </div>

            {/* New time */}
            <div className="space-y-2">
              <label
                htmlFor="simple-reschedule-datetime"
                className="block text-sm font-medium text-gray-700 dark:text-gray-300"
              >
                New scheduled time:
              </label>
              <div className="flex items-center space-x-2">
                <svg
                  className="h-4 w-4 text-gray-400"
                  fill="none"
                  stroke="currentColor"
                  viewBox="0 0 24 24"
                >
                  <path
                    strokeLinecap="round"
                    strokeLinejoin="round"
                    strokeWidth={2}
                    d="M8 7V3m8 4V3m-9 8h10M5 21h14a2 2 0 002-2V7a2 2 0 00-2-2H5a2 2 0 00-2 2v12a2 2 0 002 2z"
                  />
                </svg>
                <input
                  id="simple-reschedule-datetime"
                  type="datetime-local"
                  value={formatDateTimeForInput(scheduledFor)}
                  onChange={(e) => {
                    const newValue = e.target.value
                      ? new Date(e.target.value)
                      : null;
                    if (newValue) {
                      form.setValue("scheduledFor", newValue, {
                        shouldValidate: true,
                      });
                    }
                  }}
                  className="flex-1 rounded-md border border-gray-300 bg-white px-3 py-2 text-sm text-gray-900 focus:border-blue-500 focus:ring-2 focus:ring-blue-500 dark:border-gray-600 dark:bg-gray-800 dark:text-white"
                />
              </div>
              <div className="text-xs text-gray-500 dark:text-gray-400">
                {formatDateTime(scheduledFor)}
              </div>
            </div>

            {/* Queue Type Selection for regular posts */}
            {!isLongform ? (
              <div className="space-y-2">
                <label
                  htmlFor="simple-reschedule-queue-type"
                  className="block text-sm font-medium text-gray-700 dark:text-gray-300"
                >
                  Queue Type:
                </label>
                <select
                  id="simple-reschedule-queue-type"
                  {...form.register("queueTypeId" as never)}
                  value={selectedQueueType ?? ""}
                  onChange={(e) => {
                    // Type assertion needed because queueTypeId only exists in non-longform schema
                    (form.setValue as (name: string, value: string) => void)(
                      "queueTypeId",
                      e.target.value
                    );
                  }}
                  className="w-full rounded-md border border-gray-300 bg-white px-3 py-2 text-sm text-gray-900 focus:border-blue-500 focus:ring-2 focus:ring-blue-500 dark:border-gray-600 dark:bg-gray-800 dark:text-white"
                >
                  <option value="">Manual (No Queue)</option>
                  {queueTypes.map((queueType) => (
                    <option key={queueType.id} value={queueType.id}>
                      {queueType.name}
                    </option>
                  ))}
                </select>
                <div className="text-xs text-gray-500 dark:text-gray-400">
                  {selectedQueueType
                    ? "Post will be managed by the selected queue type"
                    : "Post will be manually scheduled"}
                </div>
              </div>
            ) : null}

            {/* Re-signing warning */}
            <div className="rounded-lg border border-blue-200 bg-blue-50 p-3 dark:border-blue-800 dark:bg-blue-900/20">
              <div className="flex items-start space-x-2">
                <svg
                  className="mt-0.5 h-5 w-5 flex-shrink-0 text-blue-600 dark:text-blue-400"
                  fill="currentColor"
                  viewBox="0 0 20 20"
                >
                  <path
                    fillRule="evenodd"
                    d="M18 10a8 8 0 11-16 0 8 8 0 0116 0zm-7-4a1 1 0 11-2 0 1 1 0 012 0zM9 9a1 1 0 000 2v3a1 1 0 001 1h1a1 1 0 100-2v-3a1 1 0 00-1-1H9z"
                    clipRule="evenodd"
                  />
                </svg>
                <div>
                  <div className="text-sm font-medium text-blue-800 dark:text-blue-200">
                    Rescheduling this {isLongform ? "article" : "post"} requires
                    re-signing the Nostr event
                  </div>
                </div>
              </div>
            </div>

            {/* Validation error */}
            {form.formState.errors.scheduledFor ? (
              <div className="rounded-lg border border-red-200 bg-red-50 p-3 dark:border-red-800 dark:bg-red-900/20">
                <div className="text-sm text-red-800 dark:text-red-200">
                  {form.formState.errors.scheduledFor.message}
                </div>
              </div>
            ) : null}

            {/* Error display */}
            {(fetcher.data?.error ?? signingError) ? (
              <div className="rounded-lg border border-red-200 bg-red-50 p-3 dark:border-red-800 dark:bg-red-900/20">
                <div className="text-sm text-red-800 dark:text-red-200">
                  {fetcher.data?.error ?? signingError}
                </div>
              </div>
            ) : null}
          </div>

          {/* Actions */}
          <div className="mt-6 flex items-center justify-end space-x-3">
            <button
              onClick={onClose}
              className="px-4 py-2 text-sm font-medium text-gray-700 hover:text-gray-900 dark:text-gray-300 dark:hover:text-white"
            >
              Cancel
            </button>
            <button
              onClick={() => void handleSubmit()}
              disabled={fetcher.state === "submitting" || isSigningEvent}
              className="rounded-lg bg-blue-600 px-4 py-2 text-sm font-medium text-white hover:bg-blue-700 disabled:cursor-not-allowed disabled:opacity-50"
            >
              {isSigningEvent
                ? "Signing Event..."
                : fetcher.state === "submitting"
                  ? "Rescheduling..."
                  : "Confirm Reschedule"}
            </button>
          </div>
        </div>
      </div>
    </div>
  );
}

import { useFetcher } from "@remix-run/react";
import React from "react";

import { HashtagPresetToggle } from "~/components/dashboard/HashtagPresetToggle";
import { Button } from "~/components/ui/button";
import { Input } from "~/components/ui/input";
import { Label } from "~/components/ui/label";
import { Textarea } from "~/components/ui/textarea";
import AssetBrowser from "~/features/assets/components/AssetBrowser";
import type { Asset } from "~/features/assets/types";
import { nostrAdapter } from "~/lib/nostr-adapter.client";
import { useOptionalUser } from "~/lib/remix-utils";
import { textPostClientSchema } from "~/lib/validation";
import { useZodForm } from "~/lib/validation/utils.client-safe";

import { usePostScheduling } from "../hooks/usePostScheduling";
import type { QueueType } from "../types";

import { QueueSelector } from "./QueueSelector";
import { SchedulingSection } from "./SchedulingSection";

interface TextPostProps {
  queueTypes?: Array<string | QueueType>;
  assets?: Asset[];
  hashTagPresets?: Array<{ id: string; name: string; tags: string }>;
  onQueueTypeChange?: (queueType: string) => void;
  selectedHashTagPresetId?: string | null | undefined;
  onHashtagPresetChange?: (presetId: string | null, hashtags: string) => void;
}

export default function TextPost({
  queueTypes = [],
  assets = [],
  hashTagPresets = [],
  onQueueTypeChange,
  selectedHashTagPresetId,
  onHashtagPresetChange,
}: TextPostProps) {
  const fetcher = useFetcher();
  const user = useOptionalUser();
  // Note: User doesn't have hashTags property - this would need to come from hashTagPresets relation
  const tags: string[] = [];
  const [showAssetBrowser, setShowAssetBrowser] = React.useState(false);
  const [selectedHashtags, setSelectedHashtags] = React.useState("");

  // Initialize form with React Hook Form
  const form = useZodForm(textPostClientSchema, {
    defaultValues: {
      content: "",
      scheduledFor: "",
      queueType: "unassigned",
      isRecyclable: false,
      useHashtagPresets: false,
      hashTagPresetId: selectedHashTagPresetId ?? undefined,
    },
  });

  const content = form.watch("content");
  const useHashtagPresets = form.watch("useHashtagPresets");
  const selectedHashtagPresetId = form.watch("hashTagPresetId");

  // Use the shared scheduling hook
  const {
    selectedQueue,
    setSelectedQueue,
    scheduledFor: schedulingScheduledFor,
    setScheduledFor: setSchedulingScheduledFor,
    calculateQueueScheduleTime,
    handleScheduleIntervalClick,
    scheduleIntervals,
  } = usePostScheduling({
    queueTypes,
    scheduleIntervals: user?.scheduleInterval as number[] | undefined,
    userTimezone: user?.timezone ?? undefined,
    initialQueue: "unassigned",
    onQueueTypeChange,
  });

  // Sync form's queueType with scheduling hook
  React.useEffect(() => {
    form.setValue("queueType", selectedQueue);
  }, [selectedQueue, form]);

  // Sync form's scheduledFor with scheduling hook
  React.useEffect(() => {
    if (schedulingScheduledFor) {
      form.setValue("scheduledFor", schedulingScheduledFor);
    }
  }, [schedulingScheduledFor, form]);

  // Sync scheduling hook when form's scheduledFor changes
  const formScheduledFor = form.watch("scheduledFor");
  React.useEffect(() => {
    if (formScheduledFor !== schedulingScheduledFor) {
      setSchedulingScheduledFor(formScheduledFor ?? "");
    }
  }, [formScheduledFor, schedulingScheduledFor, setSchedulingScheduledFor]);

  const handleSubmit = form.handleSubmit(async (data, event) => {
    const submitter = event?.nativeEvent
      ? ((event.nativeEvent as SubmitEvent).submitter as HTMLButtonElement)
      : undefined;
    const submitType = submitter?.value ?? "";

    // For draft saves, we don't need to sign the event
    if (submitType === "draft-text") {
      const formData = new FormData();
      formData.set("_action", submitType);
      formData.set("content", data.content);
      formData.set("queueType", data.queueType);
      if (data.isRecyclable) {
        formData.set("isRecyclable", "on");
      }
      if (data.useHashtagPresets && data.hashTagPresetId) {
        formData.set("hashTagPresetId", data.hashTagPresetId);
        formData.set("useHashtagPresets", "on");
      }
      fetcher.submit(formData, { method: "post" });
      return;
    }

    try {
      const userTimezone = user?.timezone ?? "UTC";
      let scheduledTime;

      if (submitType === "post-text") {
        scheduledTime = Date.now();
      } else {
        const scheduledForStr = data.scheduledFor ?? "";

        // Only convert timezone if not UTC/Etc/GMT
        if (userTimezone !== "UTC" && userTimezone !== "Etc/GMT") {
          const utcDate = new Date(scheduledForStr);

          // Get timezone offset in minutes between user timezone and UTC
          const userDateStr = new Date(scheduledForStr).toLocaleString(
            "en-US",
            {
              timeZone: userTimezone,
            }
          );
          const userDate = new Date(userDateStr);
          const scheduledDate = new Date(scheduledForStr);
          const userOffset =
            (userDate.getTime() - scheduledDate.getTime()) / 60000;

          // Adjust the date by the offset
          utcDate.setMinutes(utcDate.getMinutes() - userOffset);
          scheduledTime = utcDate.getTime();
        } else {
          // Parse date string and ensure it's in UTC
          const dateObj = new Date(scheduledForStr + "Z");
          scheduledTime = dateObj.getTime();
        }
      }

      const scheduledForUnix = Math.floor(scheduledTime / 1000);

      // Get effective hashtags - prioritize manual selection over queue defaults
      let effectiveHashtags = "";

      if (data.useHashtagPresets) {
        // Manual hashtag presets are enabled
        if (selectedHashtags) {
          // Use manually selected hashtag preset
          effectiveHashtags = selectedHashtags;
        }
        // If useHashtagPresets is true but no manual preset selected, use no hashtags
        // This ensures manual hashtag preset selection overrides queue defaults
      } else {
        // Manual hashtag presets are disabled, use queue type's default hashtags
        // Find the queue type object to get its ID
        const selectedQueueType = queueTypes.find(
          (qt) => (typeof qt === "string" ? qt : qt.name) === selectedQueue
        );
        const queueTypeId =
          typeof selectedQueueType === "object" ? selectedQueueType.id : null;

        try {
          const response = await fetch("/api/effective-hashtags", {
            method: "POST",
            headers: {
              "Content-Type": "application/json",
            },
            body: JSON.stringify({
              userId: user?.id,
              queueTypeId,
              queueTypeName: selectedQueue, // Keep for backward compatibility
            }),
          });

          if (response.ok) {
            const data = (await response.json()) as { hashtags?: string };
            effectiveHashtags = data.hashtags ?? "";
          } else {
            // Fallback to user's default hashtags
            effectiveHashtags = tags.join(" ");
          }
        } catch (error) {
          const { handleErrorSafely } =
            await import("~/lib/error-handler.client");
          handleErrorSafely(error, {
            component: "TextPost",
            action: "fetchEffectiveHashtags",
          });
          // Fallback to user's default hashtags
          effectiveHashtags = tags.join(" ");
        }
      }

      const tagArray = effectiveHashtags
        .split(" ")
        .filter((tag) => tag.length > 0)
        .map((tag) => ["t", tag.replace("#", "")]);

      const contentToSign = user?.showHashTagsinPosts
        ? `${data.content}\n${effectiveHashtags}`
        : data.content;

      const { nostrEvent, signedEvent } = await nostrAdapter.signEvent({
        content: contentToSign,
        created_at: scheduledForUnix,
        kind: 1,
        tags: tagArray,
      });

      const formData = new FormData();
      formData.set("_action", submitType);
      formData.set("content", data.content);
      formData.set("queueType", data.queueType);
      formData.append("nostrEvent", JSON.stringify(nostrEvent));
      formData.append("signedEvent", JSON.stringify(signedEvent));
      formData.append("scheduledFor", scheduledForUnix.toString());
      if (data.isRecyclable) {
        formData.set("isRecyclable", "on");
      }
      if (data.useHashtagPresets && data.hashTagPresetId) {
        formData.set("hashTagPresetId", data.hashTagPresetId);
        formData.set("useHashtagPresets", "on");
      }

      fetcher.submit(formData, { method: "post" });
    } catch (error) {
      const { handleAsyncError } = await import("~/lib/error-handler.client");
      handleAsyncError(
        error,
        {
          component: "TextPost",
          action: "handleSubmit",
        },
        false
      ); // Don't show toast, let component handle it
    }
  });

  const handleHashtagPresetSelect = (
    presetId: string | null,
    hashtags: string
  ) => {
    form.setValue("hashTagPresetId", presetId ?? undefined);
    setSelectedHashtags(hashtags);
    if (onHashtagPresetChange) {
      onHashtagPresetChange(presetId, hashtags);
    }
  };

  const handleAssetsSelected = (selectedAssets: Asset[]) => {
    // Separate text assets and image assets
    const textAssets: string[] = [];
    const imageAssets: string[] = [];

    selectedAssets.forEach((asset) => {
      if (asset.assetType === "TEXT") {
        const textContent = asset.content ?? asset.title ?? "";
        if (textContent) {
          textAssets.push(textContent);
        }
      } else if (asset.assetType === "IMAGE") {
        const imageUrl = asset.fileUrl ?? "";
        if (imageUrl) {
          imageAssets.push(imageUrl);
        }
      }
    });

    // Combine text assets first, then image URLs
    const allAssets = [...textAssets, ...imageAssets];
    const newContent = allAssets.join("\n");

    // Always append assets below existing content
    const updatedContent = content ? content + "\n" + newContent : newContent;
    form.setValue("content", updatedContent);
  };

  return (
    <fetcher.Form
      method="post"
      className="w-full"
      onSubmit={(e) => {
        e.preventDefault();
        void handleSubmit(e);
      }}
    >
      <div className="relative">
        <Textarea
          {...form.register("content")}
          className={form.formState.errors.content ? "border-red-500" : ""}
          placeholder="Start writing your post here..."
          rows={6}
          disabled={fetcher.state !== "idle"}
        />
        <Button
          type="button"
          variant="outline"
          size="sm"
          onClick={() => setShowAssetBrowser(true)}
          disabled={fetcher.state !== "idle"}
          className="absolute top-2 right-2"
        >
          <svg
            xmlns="http://www.w3.org/2000/svg"
            className="mr-1 h-4 w-4"
            fill="none"
            viewBox="0 0 24 24"
            stroke="currentColor"
          >
            <path
              strokeLinecap="round"
              strokeLinejoin="round"
              strokeWidth={2}
              d="M19 11H5m14 0a2 2 0 012 2v6a2 2 0 01-2 2H5a2 2 0 01-2-2v-6a2 2 0 012-2m14 0V9a2 2 0 00-2-2M5 11V9a2 2 0 012-2m0 0V5a2 2 0 012 2v2M7 7h10"
            />
          </svg>
          Assets
        </Button>
      </div>
      {form.formState.errors.content ? (
        <div className="mt-1 text-sm text-red-500">
          {form.formState.errors.content.message}
        </div>
      ) : null}
      <div className="mt-2 text-right text-sm text-gray-500">
        {content.length}/5000
      </div>
      <div className="mt-6 flex flex-col gap-6 sm:flex-row sm:items-center sm:justify-between">
        <div className="space-y-4">
          <QueueSelector
            queueTypes={queueTypes}
            selectedQueue={selectedQueue}
            onQueueChange={setSelectedQueue}
            disabled={fetcher.state !== "idle"}
            className="mb-2"
          />

          {/* Hashtag Preset Toggle */}
          <HashtagPresetToggle
            presets={hashTagPresets}
            selectedPresetId={selectedHashtagPresetId}
            onSelect={handleHashtagPresetSelect}
            disabled={fetcher.state !== "idle"}
            useHashtagPresets={useHashtagPresets}
            onUseHashtagPresetsChange={(enabled) => {
              form.setValue("useHashtagPresets", enabled);
            }}
            showQueuePreset={selectedQueue !== "unassigned"}
            queueType={
              queueTypes.find(
                (q) => (typeof q === "string" ? q : q.name) === selectedQueue
              ) as QueueType | undefined
            }
          />
          <div className="flex items-center gap-2">
            <input
              type="checkbox"
              id="isRecyclable"
              {...form.register("isRecyclable")}
              disabled={fetcher.state !== "idle"}
              className="h-4 w-4 rounded border-gray-300 text-blue-600 focus:ring-blue-500"
            />
            <Label
              htmlFor="isRecyclable"
              className="text-sm text-gray-700 dark:text-gray-300"
            >
              Make this post recyclable
            </Label>
          </div>
          <div className="flex flex-col gap-2">
            <Label htmlFor="scheduledFor">Schedule for later</Label>
            <div className="flex flex-col gap-3 sm:flex-row sm:items-center">
              <Input
                type="datetime-local"
                id="scheduledFor"
                {...form.register("scheduledFor")}
                disabled={fetcher.state !== "idle"}
              />
              <Button
                type="submit"
                value="schedule-text"
                name="_action"
                disabled={fetcher.state !== "idle"}
                className="text-white"
              >
                <svg
                  xmlns="http://www.w3.org/2000/svg"
                  className="mr-1.5 h-5 w-5"
                  viewBox="0 0 20 20"
                  fill="currentColor"
                >
                  <path
                    fillRule="evenodd"
                    d="M10 18a8 8 0 100-16 8 8 0 000 16zm1-12a1 1 0 10-2 0v4a1 1 0 00.293.707l2.828 2.829a1 1 0 101.415-1.415L11 9.586V6z"
                    clipRule="evenodd"
                  />
                </svg>
                {fetcher.state !== "idle"
                  ? "Scheduling..."
                  : "Sign and Schedule"}
              </Button>
            </div>
            <SchedulingSection
              scheduledFor={formScheduledFor ?? schedulingScheduledFor}
              onScheduledForChange={(value) => {
                form.setValue("scheduledFor", value);
                setSchedulingScheduledFor(value);
              }}
              scheduleIntervals={scheduleIntervals}
              queueTypes={queueTypes}
              selectedQueue={selectedQueue}
              onScheduleIntervalClick={(intervalHours) =>
                void handleScheduleIntervalClick(intervalHours)
              }
              onCalculateNextSlot={() => {
                void calculateQueueScheduleTime(selectedQueue);
              }}
              disabled={fetcher.state !== "idle"}
              showTimeInput={false}
            />
          </div>
        </div>
        <div className="flex flex-col gap-2 sm:flex-row">
          <Button
            type="submit"
            value="draft-text"
            name="_action"
            variant="outline"
            disabled={fetcher.state !== "idle"}
          >
            <svg
              xmlns="http://www.w3.org/2000/svg"
              className="mr-1.5 h-5 w-5"
              viewBox="0 0 20 20"
              fill="currentColor"
            >
              <path d="M17.414 2.586a2 2 0 00-2.828 0L7 10.172V13h2.828l7.586-7.586a2 2 0 000-2.828z" />
              <path
                fillRule="evenodd"
                d="M2 6a2 2 0 012-2h4a1 1 0 010 2H4v10h10v-4a1 1 0 112 0v4a2 2 0 01-2 2H4a2 2 0 01-2-2V6z"
                clipRule="evenodd"
              />
            </svg>
            {fetcher.state !== "idle" ? "Saving..." : "Save as Draft"}
          </Button>
          <Button
            type="submit"
            value="post-text"
            name="_action"
            className="bg-green-600 text-white hover:bg-green-700"
            disabled={fetcher.state !== "idle"}
          >
            <svg
              xmlns="http://www.w3.org/2000/svg"
              className="mr-1.5 h-5 w-5"
              viewBox="0 0 20 20"
              fill="currentColor"
            >
              <path
                fillRule="evenodd"
                d="M10 18a8 8 0 100-16 8 8 0 000 16zm3.707-8.707l-3-3a1 1 0 00-1.414 0l-3 3a1 1 0 001.414 1.414L9 9.414V13a1 1 0 102 0V9.414l1.293 1.293a1 1 0 001.414-1.414z"
                clipRule="evenodd"
              />
            </svg>
            {fetcher.state !== "idle" ? "Posting..." : "Post Now"}
          </Button>
        </div>
      </div>

      {showAssetBrowser ? (
        <AssetBrowser
          assets={assets}
          onAssetsSelected={handleAssetsSelected}
          onClose={() => setShowAssetBrowser(false)}
        />
      ) : null}
    </fetcher.Form>
  );
}

/**
 * Queue Type Handlers for Bulk Posts
 *
 * Handles queue type changes for individual and bulk posts
 */

import { logClientError } from "~/lib/error-handler.client";

import type { BulkPostsHandlerDeps } from "../types";
import { isIntervalScheduleConfig, isFixedSlotsScheduleConfig } from "../types";

import { updateDisplayedHashtags } from "./hashtag.handler";

/**
 * Handle queue type change for a single post
 */
export async function handleQueueTypeChange(
  index: number,
  value: string,
  deps: Pick<
    BulkPostsHandlerDeps,
    | "posts"
    | "setPosts"
    | "queueTypes"
    | "tags"
    | "user"
    | "setDisplayedHashtags"
    | "setSelectedQueueType"
  >
): Promise<void> {
  const {
    posts,
    setPosts,
    queueTypes,
    tags,
    user,
    setDisplayedHashtags,
    setSelectedQueueType,
  } = deps;
  const updatedPosts = [...posts];
  const postToUpdate = updatedPosts[index];
  if (!postToUpdate) return;
  postToUpdate.queueType = value;

  // Find the queue type object to get its ID
  const selectedQueueType = queueTypes.find(
    (qt) => (typeof qt === "string" ? qt : qt.name) === value
  );
  const queueTypeId =
    typeof selectedQueueType === "object" ? selectedQueueType.id : null;

  // Auto-calculate schedule time if not unassigned
  if (value !== "unassigned" && queueTypeId) {
    try {
      const requestBody = {
        queueTypeId,
        queueTypeName: value, // Keep for backward compatibility
        userId: user?.id,
      };

      const response = await fetch("/api/queue-schedule", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify(requestBody),
      });

      if (response.ok) {
        const responseData = (await response.json()) as {
          scheduledTime?: string;
        };
        const { scheduledTime } = responseData;
        if (scheduledTime) {
          const postToUpdate = updatedPosts[index];
          if (postToUpdate) {
            postToUpdate.scheduledFor = scheduledTime;
          }
        }
      }
    } catch (error) {
      logClientError(
        error instanceof Error ? error : new Error(String(error)),
        {
          component: "bulkposts",
          action: "handleQueueTypeChange",
          queueType: value,
        }
      );
    }
  } else {
    const postToUpdate = updatedPosts[index];
    if (postToUpdate) {
      postToUpdate.scheduledFor = "";
    }
  }

  setPosts(updatedPosts);

  // Update displayed hashtags if this is the predominant queue type
  const queueTypeCounts: Record<string, number> = {};
  updatedPosts.forEach((post) => {
    queueTypeCounts[post.queueType] =
      (queueTypeCounts[post.queueType] ?? 0) + 1;
  });

  const mostUsedQueueType = Object.keys(queueTypeCounts).reduce(
    (a, b) => ((queueTypeCounts[a] ?? 0) > (queueTypeCounts[b] ?? 0) ? a : b),
    "unassigned"
  );

  if (mostUsedQueueType !== value) {
    await updateDisplayedHashtags(
      mostUsedQueueType,
      queueTypes,
      tags,
      setSelectedQueueType,
      setDisplayedHashtags
    );
  }
}

/**
 * Handle bulk queue update for all posts
 */
export async function handleBulkQueueUpdate(
  queueType: string,
  deps: Pick<
    BulkPostsHandlerDeps,
    | "posts"
    | "setPosts"
    | "queueTypes"
    | "tags"
    | "user"
    | "setDisplayedHashtags"
    | "setSelectedQueueType"
    | "firstItemTimeManuallyChanged"
  >
): Promise<void> {
  const {
    posts,
    setPosts,
    queueTypes,
    tags,
    user,
    setDisplayedHashtags,
    setSelectedQueueType,
    firstItemTimeManuallyChanged,
  } = deps;

  if (posts.length === 0) return Promise.resolve();

  // Update displayed hashtags
  await updateDisplayedHashtags(
    queueType,
    queueTypes,
    tags,
    setSelectedQueueType,
    setDisplayedHashtags
  );

  // Get the base schedule time from the API (this is the next available time after last scheduled post)
  let baseTime: string | null = null;
  if (queueType !== "unassigned") {
    // If first item time was manually changed, use it as base
    const firstPost = posts[0];
    if (firstItemTimeManuallyChanged && firstPost?.scheduledFor) {
      baseTime = firstPost.scheduledFor;
    } else {
      // Original behavior - fetch from API
      const selectedQueueType = queueTypes.find(
        (qt) => (typeof qt === "string" ? qt : qt.name) === queueType
      );
      const queueTypeId =
        typeof selectedQueueType === "object" ? selectedQueueType.id : null;

      const requestBody = {
        queueTypeId,
        queueTypeName: queueType, // Keep for backward compatibility
        userId: user?.id,
      };

      const response = await fetch("/api/queue-schedule", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify(requestBody),
      });

      if (response.ok) {
        const responseData = (await response.json()) as {
          scheduledTime?: string;
        };
        const { scheduledTime } = responseData;
        baseTime = scheduledTime ?? null;
      }
    }
  }

  // Find the queue type configuration for bulk scheduling
  const queueTypeConfig = queueTypes.find((qt) => qt.name === queueType);

  const updatedPosts = posts.map((post, index) => {
    let scheduledFor = post.scheduledFor;

    // Auto-calculate schedule time if not unassigned
    if (queueType !== "unassigned" && baseTime && queueTypeConfig) {
      // Calculate each post's time based on the base time + offsets
      const baseDate = new Date(baseTime);
      let calculatedTime = "";

      if (queueTypeConfig.scheduleType === "INTERVAL") {
        const config = queueTypeConfig.scheduleConfig;
        let intervalHours = 4; // default

        if (config && isIntervalScheduleConfig(config)) {
          if (config.useGlobalInterval) {
            intervalHours = user?.scheduleInterval?.[0] ?? 4;
          } else {
            intervalHours = config.intervalHours ?? 4;
          }
        }

        // Add interval * index to base time
        const newDate = new Date(baseDate);
        newDate.setHours(newDate.getHours() + index * intervalHours);

        // Format back to datetime-local format
        const year = newDate.getFullYear();
        const month = String(newDate.getMonth() + 1).padStart(2, "0");
        const day = String(newDate.getDate()).padStart(2, "0");
        const hours = String(newDate.getHours()).padStart(2, "0");
        const minutes = String(newDate.getMinutes()).padStart(2, "0");

        calculatedTime = `${year}-${month}-${day}T${hours}:${minutes}`;
      } else if (queueTypeConfig.scheduleType === "FIXED_SLOTS") {
        const config = queueTypeConfig.scheduleConfig;
        const slots =
          config && isFixedSlotsScheduleConfig(config) ? config.slots : [];

        if (slots.length > 0) {
          // Sort slots to ensure consistent ordering
          const sortedSlots = slots
            .map((slot) => {
              const parts = slot.split(":");
              const hours = parts[0] ? Number(parts[0]) : 0;
              const minutes = parts[1] ? Number(parts[1]) : 0;
              return {
                slot,
                hours,
                minutes,
                totalMinutes: hours * 60 + minutes,
              };
            })
            .sort((a, b) => a.totalMinutes - b.totalMinutes);

          // Get the current slot index based on the base time
          const baseHours = baseDate.getHours();
          const baseMinutes = baseDate.getMinutes();
          const baseTotalMinutes = baseHours * 60 + baseMinutes;

          let currentSlotIndex = 0;
          for (let i = 0; i < sortedSlots.length; i++) {
            const slot = sortedSlots[i];
            if (slot && slot.totalMinutes >= baseTotalMinutes) {
              currentSlotIndex = i;
              break;
            }
          }

          // Calculate which slot this post should use
          const targetSlotIndex =
            (currentSlotIndex + index) % sortedSlots.length;
          const targetSlot = sortedSlots[targetSlotIndex];
          if (!targetSlot) {
            calculatedTime = post.scheduledFor;
          } else {
            // Calculate how many days to add
            const daysToAdd = Math.floor(
              (currentSlotIndex + index) / sortedSlots.length
            );

            // Set the time to the target slot
            const newDate = new Date(baseDate);
            newDate.setHours(targetSlot.hours, targetSlot.minutes, 0, 0);
            newDate.setDate(newDate.getDate() + daysToAdd);

            // Format back to datetime-local format
            const year = newDate.getFullYear();
            const month = String(newDate.getMonth() + 1).padStart(2, "0");
            const day = String(newDate.getDate()).padStart(2, "0");
            const hours = String(newDate.getHours()).padStart(2, "0");
            const minutes = String(newDate.getMinutes()).padStart(2, "0");

            calculatedTime = `${year}-${month}-${day}T${hours}:${minutes}`;
          }
        }
      }

      if (calculatedTime) {
        scheduledFor = calculatedTime;
      }
    } else if (queueType === "unassigned") {
      scheduledFor = "";
    }

    return {
      ...post,
      queueType,
      scheduledFor,
    };
  });

  setPosts(updatedPosts);
}

