    error,
  };
}

import { useState, useEffect, useRef } from "react";
import { toast } from "react-hot-toast";

import {
  convertEditorJSToMarkdown,
  convertMarkdownToEditorJS,
} from "~/features/posts/utils/editorjs-conversion";
import { resizeImage } from "~/features/upload/image-resize";
import { logClientError } from "~/lib/error-handler.client";
import {
  editPostClientSchema,
  editLongformPostClientSchema,
} from "~/lib/validation";
import { useZodForm } from "~/lib/validation/utils.client";

import type {
  PostData,
  LongFormPostData,
  UserData,
  HashTagPreset,
} from "../types";
import type {
  EditorJSInstance as EditorJSInstanceType,
  EditorJSAPI,
} from "../types/editorjs.types";

interface UseEditPostModalProps {
  post: PostData | LongFormPostData;
  user?: UserData;
  hashTagPresets?: HashTagPreset[];
  isLongform: boolean;
}

export function useEditPostModal({
  post,
  user,
  hashTagPresets: _hashTagPresets = [],
  isLongform,
}: UseEditPostModalProps) {
  // Get initial values for form
  const getInitialValues = () => {
    if (isLongform && typeof post === "object" && "title" in post) {
      const postTitle = typeof post.title === "string" ? post.title : "";
      const postSummary = typeof post.summary === "string" ? post.summary : "";
      const postImage = typeof post.image === "string" ? post.image : "";
      const publishedAt =
        typeof post === "object" && "publishedAt" in post
          ? post.publishedAt
          : null;
      const scheduledForStr = publishedAt
        ? new Date(publishedAt).toISOString().slice(0, 16)
        : "";
      const queueType =
        typeof post === "object" &&
        "queueType" in post &&
        post.queueType &&
        typeof post.queueType === "object" &&
        "name" in post.queueType &&
        typeof post.queueType.name === "string"
          ? post.queueType.name
          : "";

      const hashTagPresetId =
        typeof post === "object" &&
        "hashTagPresetId" in post &&
        typeof post.hashTagPresetId === "string"
          ? post.hashTagPresetId
          : undefined;

      return {
        title: postTitle,
        summary: postSummary,
        content: "",
        image: postImage,
        scheduledFor: scheduledForStr,
        queueType,
        useHashtagPresets: !!hashTagPresetId,
        hashTagPresetId,
        customTags: "",
      };
    } else {
      const postCaption =
        typeof post === "object" &&
        "caption" in post &&
        typeof post.caption === "string"
          ? post.caption
          : "";
      const queueTypeId =
        typeof post === "object" &&
        "queueType" in post &&
        post.queueType &&
        typeof post.queueType === "object" &&
        "id" in post.queueType &&
        typeof post.queueType.id === "string"
          ? post.queueType.id
          : "";
      const scheduledForValue =
        typeof post === "object" && "scheduledFor" in post
          ? (post as { scheduledFor?: unknown }).scheduledFor
          : null;
      const scheduledForStr =
        scheduledForValue && typeof scheduledForValue === "string"
          ? new Date(parseInt(scheduledForValue, 10) * 1000)
              .toISOString()
              .slice(0, 16)
          : "";

      const hashTagPresetId =
        typeof post === "object" &&
        "hashTagPresetId" in post &&
        typeof post.hashTagPresetId === "string"
          ? post.hashTagPresetId
          : undefined;

      const existingHashtags =
        typeof post === "object" &&
        "hashtags" in post &&
        typeof post.hashtags === "string"
          ? post.hashtags
          : "";

      return {
        caption: postCaption,
        queueType: queueTypeId,
        scheduledFor: scheduledForStr,
        isRecyclable: false,
        useHashtagPresets: !!hashTagPresetId,
        hashTagPresetId,
        manualHashtags: existingHashtags,
      };
    }
  };

  // Initialize form with React Hook Form
  const schema = isLongform
    ? editLongformPostClientSchema
    : editPostClientSchema;
  const form = useZodForm(schema, {
    defaultValues: getInitialValues(),
  });

  // Image/media handling (not part of form schema)
  const [existingImages, setExistingImages] = useState<string[]>([]);
  const [newFiles, setNewFiles] = useState<File[]>([]);
  const [isUploadingImages, setIsUploadingImages] = useState(false);

  // Hashtag preset tags (derived state, not form field)
  const [selectedHashtagPresetTags, setSelectedHashtagPresetTags] =
    useState("");

  // EditorJS state for longform content
  const editorRef = useRef<EditorJSInstanceType | null>(null);
  const editorInitialized = useRef(false);
  const [editorReady, setEditorReady] = useState(false);

  // Load initial content for longform posts
  useEffect(() => {
    if (isLongform && typeof post === "object" && "content" in post) {
      const postContent = typeof post.content === "string" ? post.content : "";
      if (postContent) {
        form.setValue("content", postContent);
      }
    }
  }, [isLongform, post, form]);

  // Initialize EditorJS for longform posts
  useEffect(() => {
    if (!isLongform) return;

    const loadEditor = async () => {
      if (
        typeof window !== "undefined" &&
        !editorRef.current &&
        !editorInitialized.current
      ) {
        editorInitialized.current = true;

        try {
          const EditorJS = (await import("@editorjs/editorjs")).default;

          const toolsConfig = {
            header: {
              class: (await import("@editorjs/header")).default,
              config: {
                placeholder: "Enter a header",
                levels: [2, 3, 4],
                defaultLevel: 3,
              },
            },
            list: {
              class: (await import("@editorjs/list")).default,
              inlineToolbar: true,
            },
            quote: {
              class: (await import("@editorjs/quote")).default,
              inlineToolbar: true,
              config: {
                quotePlaceholder: "Enter a quote",
                captionPlaceholder: "Quote's author",
              },
            },
            code: {
              class: (await import("@editorjs/code")).default,
              config: {
                placeholder: "Enter code here...",
              },
            },
            inlineCode: {
              class: (await import("@editorjs/inline-code")).default,
            },
            linkTool: {
              class: (await import("@editorjs/link")).default,
              config: {
                endpoint: "/api/link-preview",
              },
            },
            embed: {
              class: (await import("@editorjs/embed")).default,
              config: {
                services: {
                  youtube: true,
                  twitter: true,
                },
              },
            },
            image: {
              class: (await import("@editorjs/image")).default,
              config: {
                buttonContent: "Select Image",
                captionPlaceholder: "",
                withBorder: false,
                withBackground: false,
                stretched: false,
                uploader: {
                  uploadByFile: async (file: File) => {
                    try {
                      const formData = new FormData();
                      formData.append("image", file);

                      const response = await fetch(
                        "/api/upload-editorjs-image",
                        {
                          method: "POST",
                          body: formData,
                        }
                      );

                      if (!response.ok) {
                        throw new Error(`Server error: ${response.status}`);
                      }

                      const resultRaw: unknown = await response.json();
                      const result =
                        resultRaw &&
                        typeof resultRaw === "object" &&
                        !Array.isArray(resultRaw)
                          ? (resultRaw as {
                              success?: unknown;
                              file?: unknown;
                              error?: unknown;
                            })
                          : {};
                      const success =
                        typeof result.success === "number"
                          ? result.success
                          : undefined;
                      const fileResult =
                        result.file &&
                        typeof result.file === "object" &&
                        !Array.isArray(result.file)
                          ? (result.file as { url?: unknown })
                          : undefined;
                      const fileUrl =
                        fileResult && typeof fileResult.url === "string"
                          ? fileResult.url
                          : undefined;
                      const error =
                        typeof result.error === "string"
                          ? result.error
                          : undefined;

                      if (success === 1 && fileUrl) {
                        return {
                          success: 1,
                          file: {
                            url: fileUrl,
                          },
                        };
                      } else {
                        throw new Error(error ?? "Upload failed");
                      }
                    } catch (error: unknown) {
                      const { handleAsyncError } =
                        await import("~/lib/error-handler.client");
                      handleAsyncError(
                        error,
                        {
                          component: "EditPostModal",
                          action: "uploadImage",
                        },
                        false
                      );
                      throw error;
                    }
                  },
                },
              },
            },
          };

          const editorInstance = new EditorJS({
            holder: "longform-editorjs",
            minHeight: 300,
            // @ts-expect-error - EditorJS types don't match exactly but work at runtime
            tools: toolsConfig,
            // @ts-expect-error - EditorJS onChange signature doesn't match types but works at runtime
            // eslint-disable-next-line @typescript-eslint/no-misused-promises -- EditorJS onChange is async but types don't reflect this
            onChange: async (api: EditorJSAPI) => {
              try {
                const outputData = await api.saver.save();
                const markdownContent = convertEditorJSToMarkdown(outputData);
                form.setValue("content", markdownContent);
              } catch (error: unknown) {
                console.error("Editor save error:", error);
              }
            },
          }) as EditorJSInstanceType;

          editorRef.current = editorInstance;
          await editorRef.current.isReady;
          setEditorReady(true);
        } catch (error: unknown) {
          console.error("Error loading EditorJS:", error);
          editorInitialized.current = false;
        }
      }
    };

    void loadEditor();

    return () => {
      if (editorRef.current) {
        try {
          editorRef.current.destroy();
        } catch (error) {
          logClientError(
            error instanceof Error ? error : new Error(String(error)),
            {
              component: "useEditPostModal",
              action: "cleanup",
              message: "Error during editor cleanup",
            },
            "warning"
          );
        } finally {
          editorRef.current = null;
          editorInitialized.current = false;
          setEditorReady(false);
        }
      }
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps -- Dependencies are intentionally limited to avoid unnecessary re-renders
  }, [isLongform]);

  // Load initial content into EditorJS for longform posts
  const formContent = form.watch("content");
  useEffect(() => {
    if (!isLongform || !editorReady || !editorRef.current || !formContent)
      return;

    const loadInitialContent = async () => {
      if (!editorRef.current) return;
      try {
        await editorRef.current.isReady;
        const contentString =
          typeof formContent === "string" ? formContent : "";
        const editorJSData = convertMarkdownToEditorJS(contentString);
        await editorRef.current.render(editorJSData);
      } catch (error: unknown) {
        console.error("Error loading initial content into EditorJS:", error);
      }
    };

    const timeoutId = setTimeout(() => {
      void loadInitialContent();
    }, 100);
    return () => clearTimeout(timeoutId);
  }, [isLongform, editorReady, formContent]);

  const formatDateTimeForInput = (date: Date) => {
    const userTimezone =
      user &&
      typeof user === "object" &&
      "timezone" in user &&
      typeof user.timezone === "string"
        ? user.timezone
        : "UTC";
    const dateInUserTz = new Date(
      date.toLocaleString("en-US", { timeZone: userTimezone })
    );
    const year = dateInUserTz.getFullYear();
    const month = String(dateInUserTz.getMonth() + 1).padStart(2, "0");
    const day = String(dateInUserTz.getDate()).padStart(2, "0");
    const hours = String(dateInUserTz.getHours()).padStart(2, "0");
    const minutes = String(dateInUserTz.getMinutes()).padStart(2, "0");
    return `${year}-${month}-${day}T${hours}:${minutes}`;
  };

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const selectedFiles = Array.from(e.target.files ?? []);
    if (selectedFiles.length === 0) return;

    try {
      const processedFiles = await Promise.all(
        selectedFiles.map(async (file) => {
          if (file.type.startsWith("image/")) {
            return await resizeImage(file);
          }
          return file;
        })
      );
      setNewFiles((prev) => [...prev, ...processedFiles]);
    } catch (error: unknown) {
      console.error("Error processing files:", error);
      toast.error("Error processing files");
    }
  };

  const removeExistingImage = (index: number) => {
    setExistingImages((prev) => prev.filter((_, i) => i !== index));
  };

  const removeNewFile = (index: number) => {
    setNewFiles((prev) => prev.filter((_, i) => i !== index));
  };

  const handleHashtagPresetSelect = (
    presetId: string | null,
    hashtags: string
  ) => {
    form.setValue("hashTagPresetId", presetId ?? undefined);
    form.setValue("useHashtagPresets", !!presetId);
    setSelectedHashtagPresetTags(hashtags);
  };

  // Watch form values for easy access
  const caption = isLongform ? "" : String(form.watch("caption") ?? "");
  const title = isLongform ? String(form.watch("title") ?? "") : "";
  const summary = isLongform ? String(form.watch("summary") ?? "") : "";
  const content = isLongform ? String(form.watch("content") ?? "") : "";
  const image = isLongform ? String(form.watch("image") ?? "") : "";
  const scheduledForStr = form.watch("scheduledFor");
  const scheduledFor = scheduledForStr ? new Date(scheduledForStr) : null;
  const selectedQueueType = String(form.watch("queueType") ?? "");
  // eslint-disable-next-line @typescript-eslint/no-unnecessary-condition -- Runtime type guard for Remix serialized data
  const useHashtagPresets = Boolean(form.watch("useHashtagPresets") ?? false);
  const selectedHashtagPresetId = form.watch("hashTagPresetId") ?? null;
  const manualHashtags = isLongform
    ? ""
    : String(form.watch("manualHashtags") ?? "");

  // Setter functions for backward compatibility
  const setCaption = (value: string) => {
    if (!isLongform) form.setValue("caption", value);
  };
  const setTitle = (value: string) => {
    if (isLongform) form.setValue("title", value);
  };
  const setSummary = (value: string) => {
    if (isLongform) form.setValue("summary", value);
  };
  const setImage = (value: string) => {
    if (isLongform) form.setValue("image", value);
  };
  const setScheduledFor = (value: Date | null) => {
    form.setValue(
      "scheduledFor",
      value ? value.toISOString().slice(0, 16) : ""
    );
  };
  const setSelectedQueueType = (value: string) => {
    form.setValue("queueType", value);
  };
  const setUseHashtagPresets = (value: boolean) => {
    form.setValue("useHashtagPresets", value);
  };
  const setManualHashtags = (value: string) => {
    if (!isLongform) form.setValue("manualHashtags", value);
  };
  const setContent = (value: string) => {
    if (isLongform) form.setValue("content", value);
  };

  return {
    // Form instance
    form,
    // Form values (for backward compatibility)
    caption,
    title,
    summary,
    content,
    image,
    scheduledFor,
    selectedQueueType,
    useHashtagPresets,
    selectedHashtagPresetId,
    selectedHashtagPresetTags,
    manualHashtags,
    // Setter functions (for backward compatibility)
    setCaption,
    setTitle,
    setSummary,
    setImage,
    setScheduledFor,
    setSelectedQueueType,
    setUseHashtagPresets,
    setManualHashtags,
    setContent,
    // Non-form state
    existingImages,
    newFiles,
    isUploadingImages,
    setIsUploadingImages,
    editorRef,
    editorReady,
    // Handlers
    handleFileChange,
    removeExistingImage,
    removeNewFile,
    handleHashtagPresetSelect,
    formatDateTimeForInput,
  };
}

/**
 * Hook for handling longform post submission logic
 * Extracts the complex submission logic from LongFormPost component
 */

import {
  convertEditorJSToMarkdown,
  generateArticleIdentifier,
} from "~/features/posts/utils/editorjs-conversion";
import { nostrAdapter } from "~/lib/nostr-adapter.client";

import type { EditorJSBlock } from "../types";
import { generateSummaryFromContent } from "../utils/editorjs-content";

interface UseLongFormSubmissionProps {
  title: string;
  summary: string;
  content: string;
  image: string;
  customTags: string;
  selectedQueueType: string;
  scheduledFor: string | null;
  displayedHashtags: string | null;
  useHashtagPresets: boolean;
  selectedHashtags: string;
}

export function useLongFormSubmission({
  title,
  summary,
  content,
  image,
  customTags,
  selectedQueueType,
  scheduledFor,
  displayedHashtags,
  useHashtagPresets,
  selectedHashtags,
}: UseLongFormSubmissionProps) {
  const handleSchedule = async (actionType: "schedule" | "publish") => {
    if (!title.trim() || !content.trim()) {
      return;
    }

    try {
      let markdownContent;
      try {
        const editorData = JSON.parse(content) as { blocks?: EditorJSBlock[] };
        markdownContent = convertEditorJSToMarkdown(
          editorData as { blocks: EditorJSBlock[] }
        );
      } catch {
        markdownContent = content;
      }

      const finalSummary = summary || generateSummaryFromContent(content);
      const identifier = generateArticleIdentifier(title);

      let scheduledTimestamp: number | undefined;
      if (actionType === "schedule" && scheduledFor) {
        const scheduledTime = new Date(scheduledFor);
        if (!isNaN(scheduledTime.getTime())) {
          scheduledTimestamp = Math.floor(scheduledTime.getTime() / 1000);
        }
      }

      // Get effective hashtags - prioritize manual selection over queue defaults
      let effectiveHashtags = "";

      if (useHashtagPresets) {
        // Manual hashtag presets are enabled
        if (selectedHashtags) {
          // Use manually selected hashtag preset
          effectiveHashtags = selectedHashtags;
        }
        // If useHashtagPresets is true but no manual preset selected, use no hashtags
      } else {
        // Manual hashtag presets are disabled, use displayed hashtags (queue defaults)
        effectiveHashtags = displayedHashtags ?? "";
      }

      const hashtagsFromQueue = effectiveHashtags
        ? effectiveHashtags
            .split(" ")
            .map((tag) => tag.replace("#", "").trim())
            .filter(Boolean)
        : [];
      const customTagsList = customTags
        ? customTags
            .split(",")
            .map((tag) => tag.trim())
            .filter(Boolean)
        : [];
      // Combine and deduplicate tags (case insensitive)
      const allTags = [...hashtagsFromQueue, ...customTagsList];
      const uniqueTags = allTags.filter(
        (tag, index) =>
          allTags.findIndex((t) => t.toLowerCase() === tag.toLowerCase()) ===
          index
      );

      const eventData = {
        title,
        content: markdownContent,
        summary: finalSummary,
        image,
        tags: uniqueTags,
        identifier,
        publishedAt:
          actionType === "publish"
            ? Math.floor(Date.now() / 1000)
            : scheduledTimestamp,
      };

      const { nostrEvent, signedEvent } =
        await nostrAdapter.signLongFormEvent(eventData);

      const form = document.createElement("form");
      form.method = "POST";
      form.style.display = "none";

      const fields: Array<[string, string]> = [
        [
          "_action",
          actionType === "schedule" ? "schedule-longform" : "publish",
        ],
        ["title", title],
        ["content", content],
        ["summary", finalSummary],
        ["image", image],
        ["tags", uniqueTags.join(",")],
        ["queueType", selectedQueueType],
        [
          "scheduledFor",
          scheduledTimestamp ? scheduledTimestamp.toString() : "",
        ],
        ["signedEvent", JSON.stringify(signedEvent)],
        ["nostrEvent", JSON.stringify(nostrEvent)],
      ];

      fields.forEach(([name, value]) => {
        const input = document.createElement("input");
        input.type = "hidden";
        input.name = name;
        input.value = value || "";
        form.appendChild(input);
      });

      document.body.appendChild(form);
      form.submit();
    } catch (error) {
      const { handleAsyncError } = await import("~/lib/error-handler.client");
      handleAsyncError(
        error,
        {
          component: "LongFormPost",
          action: "handleSubmit",
        },
        false
      ); // Don't show toast, let component handle it
    }
  };

  return { handleSchedule };
}

/**
 * TanStack Query hooks for posted posts
 * Provides caching, background refetching, and optimistic updates
 */

import {
  useFetcher,
  useLoaderData,
  useParams,
  useSearchParams,
} from "@remix-run/react";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";

import type { User as _User } from "~/features/user";
import { safeValidateLoaderResponse } from "~/lib/validation/loader-responses";
import {
  postedPostsLoaderDataSchema,
  type PostedPostsLoaderData,
} from "~/lib/validation/schemas/loader-responses.schemas";
import { validateUserData } from "~/lib/validation/user-data";
import type { UserData } from "~/lib/validation/user-data";

import { combineContent } from "../combined";
import type { PostDTO, LongFormPostDTO } from "../dtos";
import { fromPostDTOArray, fromLongFormPostDTOArray } from "../dtos";
import type { PostStats } from "../stats.server";
import type {
  PostData,
  LongFormPostData,
  CombinedContent,
  QueueType,
} from "../types";
import { convertJsonValueToScheduleConfig } from "../types";

// PostedPostsLoaderData is now exported from schemas

/**
 * Query key factory for posted posts
 */
export const postedPostsKeys = {
  all: ["posted-posts"] as const,
  lists: () => [...postedPostsKeys.all, "list"] as const,
  list: (queueType?: string, tab?: string, page?: number) =>
    [...postedPostsKeys.lists(), queueType, tab, page] as const,
  detail: (id: string) => [...postedPostsKeys.all, "detail", id] as const,
};

/**
 * Hook to fetch posted posts with TanStack Query
 * Uses Remix loader data as initial data and enables client-side refetching
 */
export function usePostedPostsQuery() {
  const params = useParams();
  const [searchParams] = useSearchParams();
  const queueType = params["queueType"] ?? "all";
  const currentTab = searchParams.get("tab") ?? "all";
  const page = parseInt(searchParams.get("page") ?? "1", 10);

  // Import loader dynamically to avoid circular dependency
  const loaderDataRaw = useLoaderData();
  const fetcher = useFetcher();

  // Validate initial loader data
  const validatedLoaderData = safeValidateLoaderResponse(
    loaderDataRaw,
    postedPostsLoaderDataSchema
  );

  return useQuery({
    queryKey: postedPostsKeys.list(queueType, currentTab, page),
    queryFn: async () => {
      // Use fetcher to refetch data
      const url = `/dashboard/posted${queueType !== "all" ? `/${queueType}` : ""}?tab=${currentTab}&page=${page}`;
      fetcher.load(url);

      // Wait for fetcher to complete
      return new Promise<PostedPostsLoaderData>((resolve, reject) => {
        const checkFetcher = () => {
          if (fetcher.state === "idle") {
            if (fetcher.data) {
              const validated = safeValidateLoaderResponse(
                fetcher.data,
                postedPostsLoaderDataSchema
              );
              if (validated) {
                resolve(validated);
              } else {
                reject(new Error("Invalid data received from fetcher"));
              }
            } else if (validatedLoaderData) {
              resolve(validatedLoaderData);
            } else {
              reject(new Error("Invalid loader data"));
            }
          } else if (fetcher.state === "loading") {
            setTimeout(checkFetcher, 50);
          } else {
            reject(new Error("Failed to fetch data"));
          }
        };
        checkFetcher();
      });
    },
    initialData: validatedLoaderData,
    staleTime: 30 * 1000, // 30 seconds - data is fresh for 30 seconds
    gcTime: 5 * 60 * 1000, // 5 minutes - keep in cache for 5 minutes
    refetchOnWindowFocus: true,
    refetchOnMount: false, // Don't refetch on mount if data is fresh
  });
}

/**
 * Hook to get processed post data from query
 */
export function usePostedPostsData() {
  const { data, isLoading, error } = usePostedPostsQuery();

  if (!data) {
    return {
      posts: [] as PostData[],
      longformPosts: [] as LongFormPostData[],
      allContent: [] as CombinedContent[],
      isLoading,
      error,
      user: null,
      queueTypes: [] satisfies QueueType[],
      pagination: { total: 0, pages: 0, currentPage: 1, limit: 50 },
      stats: {} satisfies Record<string, PostStats>,
    };
  }

  // Data is already validated by the query hook
  const typedData = data;
  const postsRaw =
    "posts" in typedData && Array.isArray(typedData.posts)
      ? typedData.posts
      : [];
  const longformPostsRaw =
    "longformPosts" in typedData && Array.isArray(typedData.longformPosts)
      ? typedData.longformPosts
      : [];
  const userRaw = "user" in typedData ? typedData.user : null;
  const user: UserData | null = userRaw ? validateUserData(userRaw) : null;
  const queueTypesRaw =
    "queueTypes" in typedData && Array.isArray(typedData.queueTypes)
      ? typedData.queueTypes
      : [];
  const paginationRaw =
    "pagination" in typedData ? typedData.pagination : undefined;
  const statsRaw = "stats" in typedData ? typedData.stats : undefined;

  const posts: PostData[] = Array.isArray(postsRaw)
    ? fromPostDTOArray(postsRaw as PostDTO[])
    : [];
  const longformPosts: LongFormPostData[] = Array.isArray(longformPostsRaw)
    ? fromLongFormPostDTOArray(longformPostsRaw as LongFormPostDTO[])
    : [];
  // Reconstruct allContent on client from deserialized posts/longformPosts
  const allContent: CombinedContent[] = combineContent(
    posts,
    longformPosts,
    "postedAt",
    "desc"
  );
  const queueTypes: QueueType[] = Array.isArray(queueTypesRaw)
    ? queueTypesRaw.map((qt: unknown) => {
        if (typeof qt !== "object" || qt === null) {
          throw new Error("Invalid queue type");
        }
        const q = qt as {
          id?: unknown;
          name?: unknown;
          color?: unknown;
          scheduleType?: unknown;
          scheduleConfig?: unknown;
          isEnabled?: unknown;
          userId?: unknown;
        };
        const id = typeof q.id === "string" ? q.id : String(q.id ?? "");
        const name = typeof q.name === "string" ? q.name : String(q.name ?? "");
        const color =
          q.color !== null && q.color !== undefined
            ? typeof q.color === "string"
              ? q.color
              : String(q.color)
            : null;
        const scheduleType =
          typeof q.scheduleType === "string" &&
          (q.scheduleType === "INTERVAL" || q.scheduleType === "FIXED_SLOTS")
            ? q.scheduleType
            : undefined;
        const scheduleConfig = convertJsonValueToScheduleConfig(
          q.scheduleConfig
        );
        const isEnabled =
          typeof q.isEnabled === "boolean"
            ? q.isEnabled
            : q.isEnabled !== false;
        const userId = typeof q.userId === "string" ? q.userId : "";
        const queueType: QueueType = {
          id,
          name,
          color,
          description: undefined,
          scheduleType,
          scheduleConfig,
          isEnabled,
          userId,
        };
        return queueType;
      })
    : [];
  const pagination =
    paginationRaw &&
    typeof paginationRaw === "object" &&
    !Array.isArray(paginationRaw) &&
    "total" in paginationRaw &&
    "pages" in paginationRaw &&
    "currentPage" in paginationRaw &&
    "limit" in paginationRaw
      ? {
          total:
            typeof paginationRaw.total === "number" ? paginationRaw.total : 0,
          pages:
            typeof paginationRaw.pages === "number" ? paginationRaw.pages : 0,
          currentPage:
            typeof paginationRaw.currentPage === "number"
              ? paginationRaw.currentPage
              : 1,
          limit:
            typeof paginationRaw.limit === "number" ? paginationRaw.limit : 50,
        }
      : { total: 0, pages: 0, currentPage: 1, limit: 50 };
  const stats: Record<string, PostStats> =
    statsRaw && typeof statsRaw === "object" && !Array.isArray(statsRaw)
      ? statsRaw
      : {};

  return {
    posts,
    longformPosts,
    allContent,
    user,
    queueTypes,
    pagination,
    stats,
    isLoading,
    error,
    rawData: typedData,
  };
}

/**
 * Mutation hook for bulk delete with optimistic updates
 */
export function useBulkDeletePostsMutation() {
  const queryClient = useQueryClient();
  const params = useParams();
  const [searchParams] = useSearchParams();
  const queueType = params["queueType"] ?? "all";
  const currentTab = searchParams.get("tab") ?? "all";
  const page = parseInt(searchParams.get("page") ?? "1", 10);

  return useMutation({
    mutationFn: async (postIds: string[]) => {
      const formData = new FormData();
      formData.append("_action", "bulk-delete");
      postIds.forEach((id) => {
        formData.append("postIds", id);
      });

      const response = await fetch("/dashboard/posted", {
        method: "POST",
        body: formData,
      });

      if (!response.ok) {
        throw new Error("Failed to delete posts");
      }

      return response.json();
    },
    onMutate: async (postIds) => {
      // Cancel outgoing refetches
      await queryClient.cancelQueries({
        queryKey: postedPostsKeys.list(queueType, currentTab, page),
      });

      // Snapshot previous value
      const previousData = queryClient.getQueryData<PostedPostsLoaderData>(
        postedPostsKeys.list(queueType, currentTab, page)
      );

      // Optimistically update
      if (previousData) {
        queryClient.setQueryData<PostedPostsLoaderData>(
          postedPostsKeys.list(queueType, currentTab, page),
          (old) => {
            if (!old) return old;
            return {
              ...old,
              posts:
                "posts" in old && Array.isArray(old.posts)
                  ? old.posts.filter(
                      (p: unknown) =>
                        p &&
                        typeof p === "object" &&
                        "id" in p &&
                        typeof p.id === "string" &&
                        !postIds.includes(p.id)
                    )
                  : [],
              allContent:
                "allContent" in old && Array.isArray(old.allContent)
                  ? old.allContent.filter(
                      (c: unknown) =>
                        c &&
                        typeof c === "object" &&
                        "id" in c &&
                        typeof c.id === "string" &&
                        !postIds.includes(c.id)
                    )
                  : [],
            };
          }
        );
      }

      return { previousData };
    },
    onError: (err, variables, context) => {
      // Rollback on error
      if (context?.previousData) {
        queryClient.setQueryData(
          postedPostsKeys.list(queueType, currentTab, page),
          context.previousData
        );
      }
    },
    onSettled: () => {
      // Refetch after mutation
      void queryClient.invalidateQueries({
        queryKey: postedPostsKeys.lists(),
      });
    },
  });
}

import type { FetcherWithComponents, useFetcher } from "@remix-run/react";
import { useState, useEffect } from "react";

import { nostrAdapter } from "~/lib/nostr-adapter.client";

import type { PostData } from "../types";

interface Post {
  id: string;
  caption?: string | null;
  postedAt: Date | null;
  fileUrl: string[];
  signedEvent: { id: string };
  queueType?: { name: string; color?: string | null } | null;
  status?: string;
  [key: string]: unknown; // Allow additional properties from Prisma
}

type Stats = Record<
  string,
  {
    likes?: number;
    replies?: number;
    mentions?: number;
    reposts?: number;
    zaps?: number;
    satszapped?: number;
  }
>;

interface User {
  timezone?: string | null;
  relays?: string[];
}

interface RepostFetcherData {
  repostData?: PostData[];
  scheduledRepostData?: PostData[];
  quotePostData?: {
    caption?: string;
    fileUrl?: string | string[];
    queueType?: string;
    scheduledFor?: string;
    originalPostId?: string;
    originalEventId?: string;
    originalEventPubkey?: string;
    [key: string]: unknown;
  };
}

export interface IndividualRepostFetcherData {
  repostEventData?: {
    kind: number;
    content: string;
    tags: string[][];
    created_at: number;
    pubkey: string;
    [key: string]: unknown;
  };
  quotePostData?: {
    caption?: string;
    fileUrl?: string | string[];
    queueType?: string;
    scheduledFor?: string;
    originalPostId?: string;
    originalEventId?: string;
    originalEventPubkey?: string;
    [key: string]: unknown;
  };
  error?: boolean;
  message?: string;
}

interface UseRecyclablesStateProps {
  posts: Post[] | PostData[]; // Accept any post type from loader
  stats: Stats;
  user?: User | null;
  repostFetcher:
    | FetcherWithComponents<RepostFetcherData>
    | FetcherWithComponents<unknown>;
  // eslint-disable-next-line @typescript-eslint/no-explicit-any -- Remix fetcher type requires any for dynamic action types
  bulkDeleteFetcher: ReturnType<typeof useFetcher<any>>;
  bulkRepostFetcher: ReturnType<typeof useFetcher>;
  individualRepostFetcher: FetcherWithComponents<IndividualRepostFetcherData>;
}

interface SortConfig {
  key: string;
  direction: "asc" | "desc";
}

/**
 * Custom hook for managing recyclables posts state and operations
 */
export function useRecyclablesState({
  posts,
  stats,
  user,
  repostFetcher,
  bulkDeleteFetcher,
  bulkRepostFetcher,
  individualRepostFetcher,
}: UseRecyclablesStateProps) {
  const [sortConfig, setSortConfig] = useState<SortConfig>({
    key: "postedAt",
    direction: "desc",
  });
  const [searchTerm, setSearchTerm] = useState("");
  const [selectedPost, setSelectedPost] = useState<Post | null>(null);
  const [selectedPosts, setSelectedPosts] = useState<Set<string>>(new Set());
  const [toast, setToast] = useState<{
    type: "success" | "error";
    message: string;
    link?: string;
    linkText?: string;
  } | null>(null);

  // Sort and filter posts
  const sortedPosts = [...posts].sort((a, b) => {
    if (sortConfig.key === "postedAt") {
      const dateA = new Date(a[sortConfig.key] ?? 0).getTime();
      const dateB = new Date(b[sortConfig.key] ?? 0).getTime();
      return sortConfig.direction === "asc" ? dateA - dateB : dateB - dateA;
    }

    // Handle engagement metrics sorting
    if (
      [
        "likes",
        "replies",
        "mentions",
        "reposts",
        "zaps",
        "satszapped",
      ].includes(sortConfig.key)
    ) {
      const aEventId =
        a.signedEvent &&
        typeof a.signedEvent === "object" &&
        "id" in a.signedEvent &&
        typeof a.signedEvent.id === "string"
          ? a.signedEvent.id
          : null;
      const bEventId =
        b.signedEvent &&
        typeof b.signedEvent === "object" &&
        "id" in b.signedEvent &&
        typeof b.signedEvent.id === "string"
          ? b.signedEvent.id
          : null;
      const aStats =
        aEventId &&
        aEventId in stats &&
        typeof stats[aEventId] === "object" &&
        !Array.isArray(stats[aEventId])
          ? stats[aEventId]
          : {};
      const bStats =
        bEventId &&
        bEventId in stats &&
        typeof stats[bEventId] === "object" &&
        !Array.isArray(stats[bEventId])
          ? stats[bEventId]
          : {};
      const aValue = Number(aStats[sortConfig.key as keyof typeof aStats] ?? 0);
      const bValue = Number(bStats[sortConfig.key as keyof typeof bStats] ?? 0);
      return sortConfig.direction === "asc" ? aValue - bValue : bValue - aValue;
    }

    const aValue = (a as Record<string, unknown>)[sortConfig.key] as
      | string
      | number
      | undefined;
    const bValue = (b as Record<string, unknown>)[sortConfig.key] as
      | string
      | number
      | undefined;

    // Handle null/undefined values
    if (aValue == null && bValue == null) return 0;
    if (aValue == null) return sortConfig.direction === "asc" ? -1 : 1;
    if (bValue == null) return sortConfig.direction === "asc" ? 1 : -1;

    if (aValue < bValue) return sortConfig.direction === "asc" ? -1 : 1;
    if (aValue > bValue) return sortConfig.direction === "asc" ? 1 : -1;
    return 0;
  });

  const filteredPosts = sortedPosts.filter((post) =>
    post.caption?.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const requestSort = (key: string) => {
    setSortConfig((current) => ({
      key,
      direction:
        current.key === key && current.direction === "asc" ? "desc" : "asc",
    }));
  };

  const togglePostSelection = (postId: string) => {
    setSelectedPosts((prev) => {
      const newSet = new Set(prev);
      if (newSet.has(postId)) {
        newSet.delete(postId);
      } else {
        newSet.add(postId);
      }
      return newSet;
    });
  };

  const toggleSelectAll = () => {
    if (selectedPosts.size === filteredPosts.length) {
      setSelectedPosts(new Set());
    } else {
      setSelectedPosts(new Set(filteredPosts.map((post) => post.id)));
    }
  };

  const handleBulkDelete = () => {
    if (selectedPosts.size === 0) return;

    const formData = new FormData();
    formData.append("_action", "bulkDelete");
    formData.append("postIds", JSON.stringify(Array.from(selectedPosts)));

    bulkDeleteFetcher.submit(formData, { method: "post" });
  };

  const handleBulkRepost = () => {
    if (selectedPosts.size === 0) return;

    const formData = new FormData();
    formData.append("_action", "bulkRepost");
    formData.append("postIds", JSON.stringify(Array.from(selectedPosts)));

    bulkRepostFetcher.submit(formData, { method: "post" });
  };

  const handleBulkScheduledRepost = () => {
    if (selectedPosts.size === 0) return;

    const formData = new FormData();
    formData.append("_action", "bulkScheduledRepost");
    formData.append("postIds", JSON.stringify(Array.from(selectedPosts)));

    bulkRepostFetcher.submit(formData, { method: "post" });
  };

  const handleBulkQuote = () => {
    if (selectedPosts.size === 0) return;

    const formData = new FormData();
    formData.append("_action", "bulkQuote");
    formData.append("postIds", JSON.stringify(Array.from(selectedPosts)));

    bulkRepostFetcher.submit(formData, { method: "post" });
  };

  // Handle bulk delete success
  useEffect(() => {
    // eslint-disable-next-line @typescript-eslint/no-unsafe-assignment -- Remix fetcher data type is complex, validated at runtime
    const dataRaw = bulkDeleteFetcher.data;
    const data =
      dataRaw && typeof dataRaw === "object" && !Array.isArray(dataRaw)
        ? (dataRaw as { success?: unknown })
        : null;
    if (data && typeof data.success === "boolean" && data.success) {
      setSelectedPosts(new Set());
    }
  }, [bulkDeleteFetcher.data]);

  // Handle repost data and navigation
  useEffect(() => {
    const fetcherDataRaw: unknown = repostFetcher.data;
    const fetcherData: RepostFetcherData | null =
      fetcherDataRaw &&
      typeof fetcherDataRaw === "object" &&
      !Array.isArray(fetcherDataRaw) &&
      "repostData" in fetcherDataRaw
        ? (fetcherDataRaw as RepostFetcherData)
        : null;
    if (
      fetcherData &&
      "repostData" in fetcherData &&
      Array.isArray(fetcherData.repostData)
    ) {
      const postsData = fetcherData.repostData;

      // Prepare repost data with 1 hour default scheduling
      const now = new Date();
      const userTimezone =
        user &&
        typeof user === "object" &&
        "timezone" in user &&
        typeof user.timezone === "string"
          ? user.timezone
          : "UTC";
      const localDate = new Date(
        now.toLocaleString("en-US", { timeZone: userTimezone })
      );
      localDate.setHours(localDate.getHours() + 1);

      const repostData = postsData.map((post: PostData, index: number) => {
        const scheduleDate = new Date(localDate);
        scheduleDate.setHours(scheduleDate.getHours() + index);

        return {
          caption: post.caption ?? "",
          fileUrl:
            Array.isArray(post.fileUrl) && post.fileUrl.length > 0
              ? post.fileUrl[0]
              : "",
          queueType: post.queueType?.name ?? "unassigned",
          scheduledFor: scheduleDate
            .toLocaleString("en-US", {
              year: "numeric",
              month: "2-digit",
              day: "2-digit",
              hour: "2-digit",
              minute: "2-digit",
              hour12: false,
            })
            .replace(/(\d+)\/(\d+)\/(\d+),\s(\d+):(\d+)/, "$3-$1-$2T$4:$5"),
          originalPostId: post.id,
        };
      });

      sessionStorage.setItem("repostData", JSON.stringify(repostData));
      window.location.href = "/dashboard/bulkposts?mode=recycle";
      setSelectedPosts(new Set());
    }

    if (
      fetcherData &&
      "scheduledRepostData" in fetcherData &&
      Array.isArray(fetcherData.scheduledRepostData)
    ) {
      const postsData = fetcherData.scheduledRepostData;

      const now = new Date();
      const userTimezoneForScheduled =
        user &&
        typeof user === "object" &&
        "timezone" in user &&
        typeof user.timezone === "string"
          ? user.timezone
          : "UTC";
      const localDate = new Date(
        now.toLocaleString("en-US", { timeZone: userTimezoneForScheduled })
      );
      localDate.setHours(localDate.getHours() + 1);

      const scheduledRepostData = postsData.map(
        (post: PostData, index: number) => {
          const scheduleDate = new Date(localDate);
          scheduleDate.setHours(scheduleDate.getHours() + index);

          return {
            caption: "",
            fileUrl: "",
            queueType: post.queueType?.name ?? "unassigned",
            scheduledFor: scheduleDate
              .toLocaleString("en-US", {
                year: "numeric",
                month: "2-digit",
                day: "2-digit",
                hour: "2-digit",
                minute: "2-digit",
                hour12: false,
              })
              .replace(/(\d+)\/(\d+)\/(\d+),\s(\d+):(\d+)/, "$3-$1-$2T$4:$5"),
            originalPostId: post.id,
            originalEventId:
              post.signedEvent &&
              typeof post.signedEvent === "object" &&
              "id" in post.signedEvent &&
              typeof post.signedEvent.id === "string"
                ? post.signedEvent.id
                : undefined,
            originalEventPubkey:
              post.signedEvent &&
              typeof post.signedEvent === "object" &&
              "pubkey" in post.signedEvent &&
              typeof post.signedEvent.pubkey === "string"
                ? post.signedEvent.pubkey
                : undefined,
            isKind6Repost: true,
          };
        }
      );

      sessionStorage.setItem(
        "scheduledRepostData",
        JSON.stringify(scheduledRepostData)
      );
      window.location.href = "/dashboard/bulkposts?mode=repost";
      setSelectedPosts(new Set());
    }

    if (
      fetcherData &&
      "quotePostData" in fetcherData &&
      fetcherData.quotePostData
    ) {
      const quoteData = fetcherData.quotePostData;
      sessionStorage.setItem("quotePostData", JSON.stringify(quoteData));
      window.location.href = "/dashboard/bulkposts?mode=quote";
      setSelectedPosts(new Set());
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps -- Dependencies are intentionally limited to avoid unnecessary re-renders
  }, [repostFetcher.data, user?.timezone, repostFetcher]);

  // Handle individual repost actions
  useEffect(() => {
    const handleRepost = async () => {
      const dataRaw = individualRepostFetcher.data;
      const data =
        dataRaw && typeof dataRaw === "object" && !Array.isArray(dataRaw)
          ? (dataRaw as {
              repostEventData?: unknown;
              quotePostData?: unknown;
              error?: unknown;
              message?: unknown;
            })
          : null;

      if (
        data &&
        "repostEventData" in data &&
        data.repostEventData &&
        typeof data.repostEventData === "object" &&
        !Array.isArray(data.repostEventData)
      ) {
        try {
          const eventDataRaw = data.repostEventData as {
            kind?: unknown;
            content?: unknown;
            tags?: unknown;
            created_at?: unknown;
            pubkey?: unknown;
            [key: string]: unknown;
          };

          // Convert to NostrEventData format expected by signEventFn
          const eventData = {
            kind: typeof eventDataRaw.kind === "number" ? eventDataRaw.kind : 1,
            content:
              typeof eventDataRaw.content === "string"
                ? eventDataRaw.content
                : "",
            tags: Array.isArray(eventDataRaw.tags) ? eventDataRaw.tags : [],
            created_at:
              typeof eventDataRaw.created_at === "number"
                ? eventDataRaw.created_at
                : Math.floor(Date.now() / 1000),
            pubkey:
              typeof eventDataRaw.pubkey === "string"
                ? eventDataRaw.pubkey
                : "",
          };

          // Sign the event using client-side signing
          const { signedEvent } = await nostrAdapter.signEvent(eventData);

          // Get user relays from user data
          const sanitizedRelays =
            user &&
            typeof user === "object" &&
            "relays" in user &&
            Array.isArray(user.relays)
              ? user.relays
              : ["wss://relay.primal.net"];

          // Publish the signed event
          const response = await fetch("/api/publish", {
            method: "POST",
            headers: {
              "Content-Type": "application/json",
            },
            body: JSON.stringify({
              relays: sanitizedRelays,
              event: signedEvent,
            }),
          });

          if (!response.ok) {
            throw new Error("Failed to publish repost");
          }

          // Add delay before showing success toast
          setTimeout(() => {
            const tags = Array.isArray(eventData.tags) ? eventData.tags : [];
            const eTag: unknown = tags.find(
              (tag: unknown) => Array.isArray(tag) && tag[0] === "e"
            );
            const eventId =
              Array.isArray(eTag) && typeof eTag[1] === "string" ? eTag[1] : "";
            setToast({
              type: "success",
              message: "Post reposted successfully!",
              link: eventId ? `https://primal.net/e/${eventId}` : undefined,
              linkText: "View Original Post",
            });

            // Hide toast after 8 seconds for success with link
            setTimeout(() => setToast(null), 8000);
          }, 1000); // 1 second delay
        } catch (error: unknown) {
          console.error("Repost signing/publishing error:", error);
          const errorMessage =
            error instanceof Error
              ? error.message
              : "Failed to sign or publish repost";
          setToast({
            type: "error",
            message: errorMessage,
          });

          // Hide toast after 5 seconds for errors
          setTimeout(() => setToast(null), 5000);
        }
      } else if (data && "quotePostData" in data && data.quotePostData) {
        // Handle individual quote post - redirect to bulk posts with single item
        const quoteData = data.quotePostData;

        // Store quote post data in sessionStorage
        sessionStorage.setItem("quotePostData", JSON.stringify(quoteData));

        // Navigate to bulk posts page with quote mode
        window.location.href = "/dashboard/bulkposts?mode=quote";
      } else if (data && "error" in data && data.error) {
        const message =
          typeof data.message === "string"
            ? data.message
            : "Failed to create repost";
        setToast({
          type: "error",
          message,
        });

        // Hide toast after 5 seconds for errors
        setTimeout(() => setToast(null), 5000);
      }
    };

    if (individualRepostFetcher.data) {
      void handleRepost();
    }
  }, [
    individualRepostFetcher.data,
    user?.relays,
    individualRepostFetcher,
    user,
  ]);

  return {
    sortConfig,
    searchTerm,
    selectedPost,
    selectedPosts,
    toast,
    filteredPosts,
    requestSort,
    setSearchTerm,
    setSelectedPost,
    togglePostSelection,
    toggleSelectAll,
    handleBulkDelete,
    handleBulkRepost,
    handleBulkScheduledRepost,
    handleBulkQuote,
    setToast,
  };
}

/**
 * TanStack Query hooks for scheduled posts
 * Provides caching and background refetching for scheduled posts page
 */

import {
  useFetcher,
  useLoaderData,
  useParams,
  useSearchParams,
} from "@remix-run/react";
import { useQuery } from "@tanstack/react-query";

import { validateHashTagPresets } from "~/lib/validation/hashtag-presets";
import { safeValidateLoaderResponse } from "~/lib/validation/loader-responses";
import {
  scheduledPostsLoaderDataSchema,
  type ScheduledPostsLoaderData,
} from "~/lib/validation/schemas/loader-responses.schemas";

import { combineContent } from "../combined";
import type { PostDTO, LongFormPostDTO } from "../dtos";
import { fromPostDTOArray, fromLongFormPostDTOArray } from "../dtos";
import type {
  PostData,
  LongFormPostData,
  CombinedContent,
  QueueType,
  UserData,
  HashTagPreset,
} from "../types";
import { convertJsonValueToScheduleConfig } from "../types";

/**
 * Query key factory for scheduled posts
 */
export const scheduledPostsKeys = {
  all: ["scheduled-posts"] as const,
  lists: () => [...scheduledPostsKeys.all, "list"] as const,
  list: (queueType?: string, tab?: string) =>
    [...scheduledPostsKeys.lists(), queueType, tab] as const,
};

// ScheduledPostsLoaderData is now exported from schemas

/**
 * Hook to fetch scheduled posts with TanStack Query
 */
export function useScheduledPostsQuery() {
  const params = useParams();
  const [searchParams] = useSearchParams();
  const queueType = params["queueType"] ?? "all";
  const currentTab = searchParams.get("tab") ?? "all";

  const loaderDataRaw = useLoaderData();
  const fetcher = useFetcher();

  // Validate initial loader data
  const validatedLoaderData = safeValidateLoaderResponse(
    loaderDataRaw,
    scheduledPostsLoaderDataSchema
  );

  return useQuery({
    queryKey: scheduledPostsKeys.list(queueType, currentTab),
    queryFn: async () => {
      const url = `/dashboard/scheduled${queueType !== "all" ? `/${queueType}` : ""}?tab=${currentTab}`;
      fetcher.load(url);

      return new Promise<ScheduledPostsLoaderData>((resolve, reject) => {
        const checkFetcher = () => {
          if (fetcher.state === "idle") {
            if (fetcher.data) {
              const validated = safeValidateLoaderResponse(
                fetcher.data,
                scheduledPostsLoaderDataSchema
              );
              if (validated) {
                resolve(validated);
              } else {
                reject(new Error("Invalid data received from fetcher"));
              }
            } else if (validatedLoaderData) {
              resolve(validatedLoaderData);
            } else {
              reject(new Error("Invalid loader data"));
            }
          } else if (fetcher.state === "loading") {
            setTimeout(checkFetcher, 50);
          } else {
            reject(new Error("Failed to fetch data"));
          }
        };
        checkFetcher();
      });
    },
    initialData: validatedLoaderData,
    staleTime: 30 * 1000, // 30 seconds
    gcTime: 5 * 60 * 1000, // 5 minutes
    refetchOnWindowFocus: true,
    refetchOnMount: false,
  });
}

/**
 * Hook to get processed scheduled posts data from query
 */
export function useScheduledPostsData() {
  const { data, isLoading, error } = useScheduledPostsQuery();

  if (!data) {
    return {
      posts: [] as PostData[],
      longformPosts: [] as LongFormPostData[],
      allContent: [] as CombinedContent[],
      user: null as UserData | null,
      queueTypes: [] as QueueType[],
      hashTagPresets: [] as HashTagPreset[],
      isLoading,
      error,
    };
  }

  const typedData = data;
  const postsRaw =
    "posts" in typedData && Array.isArray(typedData.posts)
      ? typedData.posts
      : [];
  const longformPostsRaw =
    "longformPosts" in typedData && Array.isArray(typedData.longformPosts)
      ? typedData.longformPosts
      : [];
  const userRaw = "user" in typedData ? typedData.user : null;
  const queueTypesRaw =
    "queueTypes" in typedData && Array.isArray(typedData.queueTypes)
      ? typedData.queueTypes
      : [];
  const hashTagPresetsRaw =
    "hashTagPresets" in typedData && Array.isArray(typedData.hashTagPresets)
      ? typedData.hashTagPresets
      : [];

  const posts: PostData[] = Array.isArray(postsRaw)
    ? fromPostDTOArray(postsRaw as PostDTO[])
    : [];
  const longformPosts: LongFormPostData[] = Array.isArray(longformPostsRaw)
    ? fromLongFormPostDTOArray(longformPostsRaw as LongFormPostDTO[])
    : [];
  // Reconstruct allContent on client from deserialized posts/longformPosts
  const allContent: CombinedContent[] = combineContent(
    posts,
    longformPosts,
    "scheduledFor",
    "asc"
  );
  const queueTypes: QueueType[] = Array.isArray(queueTypesRaw)
    ? queueTypesRaw
        .map((qt: unknown) => {
          if (
            qt &&
            typeof qt === "object" &&
            !Array.isArray(qt) &&
            "id" in qt &&
            "name" in qt
          ) {
            const q = qt as {
              id?: unknown;
              name?: unknown;
              color?: unknown;
              scheduleType?: unknown;
              scheduleConfig?: unknown;
              isEnabled?: unknown;
              userId?: unknown;
            };
            const id = typeof q.id === "string" ? q.id : String(q.id ?? "");
            const name =
              typeof q.name === "string" ? q.name : String(q.name ?? "");
            const color =
              q.color !== null && q.color !== undefined
                ? typeof q.color === "string"
                  ? q.color
                  : String(q.color)
                : null;
            const scheduleType =
              typeof q.scheduleType === "string" &&
              (q.scheduleType === "INTERVAL" ||
                q.scheduleType === "FIXED_SLOTS")
                ? q.scheduleType
                : undefined;
            const scheduleConfig = convertJsonValueToScheduleConfig(
              q.scheduleConfig
            );
            const isEnabled =
              typeof q.isEnabled === "boolean"
                ? q.isEnabled
                : q.isEnabled !== false;
            const userId = typeof q.userId === "string" ? q.userId : "";
            const queueType: QueueType = {
              id,
              name,
              color,
              description: undefined,
              scheduleType,
              scheduleConfig,
              isEnabled,
              userId,
            };
            return queueType;
          }
          return null;
        })
        .filter((qt): qt is QueueType => qt !== null)
    : [];
  // Validate HashTagPreset array with Zod schema
  const hashTagPresets: HashTagPreset[] =
    validateHashTagPresets(hashTagPresetsRaw);

  return {
    posts,
    longformPosts,
    allContent,
    user: userRaw,
    queueTypes,
    hashTagPresets,
    isLoading,
    error,
  };
}

import { getPublicKey, finalizeEvent, nip19 } from "nostr-tools";

import { sanitizeMarkdown } from "~/lib/markdown-sanitizer.server";

import type { EditorJSOutput, EditorJSBlock } from "./types/editorjs.types";

export function createLongFormEvent({
  privateKey,
  title,
  content,
  summary,
  image,
  tags = [],
  dTag,
  publishedAt,
}: {
  privateKey: string;
  title: string;
  content: string;
  summary?: string;
  image?: string;
  tags?: string[];
  dTag?: string;
  publishedAt?: number;
}) {
  // Convert privateKey (hex string or nsec) to Uint8Array
  let privateKeyBytes: Uint8Array;
  try {
    if (privateKey.startsWith("nsec")) {
      const decoded = nip19.decode(privateKey);
      if (decoded.type === "nsec") {
        privateKeyBytes = decoded.data;
      } else {
        throw new Error("Invalid nsec format");
      }
    } else {
      // Assume hex string
      privateKeyBytes = new Uint8Array(
        privateKey.match(/.{1,2}/g)?.map((byte) => parseInt(byte, 16)) ?? []
      );
    }
  } catch {
    // Fallback: treat as hex string
    privateKeyBytes = new Uint8Array(
      privateKey.match(/.{1,2}/g)?.map((byte) => parseInt(byte, 16)) ?? []
    );
  }

  const publicKey = getPublicKey(privateKeyBytes);

  const eventTags = [];

  if (dTag) {
    eventTags.push(["d", dTag]);
  }

  if (title) {
    eventTags.push(["title", title]);
  }

  if (summary) {
    eventTags.push(["summary", summary]);
  }

  if (image) {
    eventTags.push(["image", image]);
  }

  if (publishedAt) {
    eventTags.push(["published_at", publishedAt.toString()]);
  }

  tags.forEach((tag) => {
    if (tag.trim()) {
      eventTags.push(["t", tag.trim().toLowerCase()]);
    }
  });

  const sanitizedContent = sanitizeMarkdown(content);

  const event = {
    kind: 30023,
    pubkey: publicKey,
    created_at: Math.floor(Date.now() / 1000),
    tags: eventTags,
    content: sanitizedContent,
  };

  return finalizeEvent(event, privateKeyBytes);
}

export function generateArticleIdentifier(title: string): string {
  return title
    .toLowerCase()
    .replace(/[^a-z0-9\s-]/g, "")
    .replace(/\s+/g, "-")
    .replace(/-+/g, "-")
    .trim()
    .substring(0, 64);
}

export function convertEditorJSToMarkdown(editorData: EditorJSOutput): string {
  if (editorData.blocks.length === 0) {
    return "";
  }

  let markdown = "";

  editorData.blocks.forEach((block: EditorJSBlock) => {
    switch (block.type) {
      case "header": {
        const level =
          typeof block.data["level"] === "number" ? block.data["level"] : 1;
        const text =
          typeof block.data["text"] === "string" ? block.data["text"] : "";
        markdown += `${"#".repeat(level)} ${text}\n\n`;
        break;
      }

      case "paragraph": {
        const textValue = block.data["text"];
        const text = typeof textValue === "string" ? textValue : "";
        markdown += `${text}\n\n`;
        break;
      }

      case "list":
        if (Array.isArray(block.data["items"])) {
          if (block.data["style"] === "ordered") {
            const items = block.data["items"];
            if (Array.isArray(items)) {
              items.forEach((item: unknown, index: number) => {
                markdown += `${index + 1}. ${typeof item === "string" ? item : String(item)}\n`;
              });
            }
          } else {
            const items = block.data["items"];
            if (Array.isArray(items)) {
              items.forEach((item: unknown) => {
                markdown += `- ${typeof item === "string" ? item : String(item)}\n`;
              });
            }
          }
        }
        markdown += "\n";
        break;

      case "quote": {
        const textValue = block.data["text"];
        const text = typeof textValue === "string" ? textValue : "";
        const captionValue = block.data["caption"];
        const caption = typeof captionValue === "string" ? captionValue : "";
        markdown += `> ${text}\n`;
        if (caption) {
          markdown += `> \n> — ${caption}\n`;
        }
        markdown += "\n";
        break;
      }

      case "code": {
        const codeValue = block.data["code"];
        const code = typeof codeValue === "string" ? codeValue : "";
        markdown += "```\n";
        markdown += code;
        markdown += "\n```\n\n";
        break;
      }

      case "linkTool": {
        const link =
          typeof block.data["link"] === "string" ? block.data["link"] : "";
        const meta =
          block.data["meta"] &&
          typeof block.data["meta"] === "object" &&
          "title" in block.data["meta"]
            ? (block.data["meta"] as { title?: string })
            : { title: undefined };
        if (meta.title) {
          markdown += `[${meta.title}](${link})\n\n`;
        } else {
          markdown += `${link}\n\n`;
        }
        break;
      }

      case "embed": {
        const serviceValue = block.data["service"];
        const sourceValue = block.data["source"];
        const service = typeof serviceValue === "string" ? serviceValue : "";
        const source = typeof sourceValue === "string" ? sourceValue : "";
        if (service === "youtube") {
          markdown += `[![YouTube Video](https://img.youtube.com/vi/${source}/0.jpg)](${source})\n\n`;
        } else {
          markdown += `${source}\n\n`;
        }
        break;
      }

      case "image": {
        const file =
          block.data["file"] &&
          typeof block.data["file"] === "object" &&
          "url" in block.data["file"]
            ? (block.data["file"] as { url?: string })
            : { url: undefined };
        const url =
          typeof block.data["url"] === "string" ? block.data["url"] : undefined;
        const imageUrl = file.url ?? url;
        const caption =
          typeof block.data["caption"] === "string"
            ? block.data["caption"]
            : undefined;
        if (imageUrl) {
          if (caption?.trim()) {
            markdown += `![${caption}](${imageUrl})\n\n`;
          } else {
            markdown += `![](${imageUrl})\n\n`;
          }
        }
        break;
      }

      default: {
        const textValue = block.data["text"];
        const text = typeof textValue === "string" ? textValue : "";
        if (text) {
          markdown += `${text}\n\n`;
        }
        break;
      }
    }
  });

  return markdown.trim();
}

export function convertMarkdownToEditorJS(markdown: string): EditorJSOutput {
  if (!markdown || markdown.trim() === "") {
    return { blocks: [] };
  }

  const blocks: EditorJSBlock[] = [];
  const lines = markdown.split("\n");
  let i = 0;

  while (i < lines.length) {
    const currentLine = lines[i];
    if (currentLine === undefined) break;
    const line = currentLine.trim();

    if (line === "") {
      i++;
      continue;
    }

    // Headers
    if (line.startsWith("#")) {
      const match = line.match(/^#+/);
      const level = match?.[0]?.length ?? 1;
      const text = line.replace(/^#+\s*/, "");
      blocks.push({
        id: generateBlockId(),
        type: "header",
        data: {
          text: text,
          level: Math.min(Math.max(level, 1), 6),
        },
      });
    }
    // Images
    else if (line.match(/^!\[([^\]]*)\]\(([^)]+)\)$/)) {
      const match = line.match(/^!\[([^\]]*)\]\(([^)]+)\)$/);
      if (match) {
        const caption = match[1];
        const url = match[2];
        if (caption !== undefined && url !== undefined) {
          blocks.push({
            id: generateBlockId(),
            type: "image",
            data: {
              file: {
                url: url,
              },
              caption: caption,
              withBorder: false,
              withBackground: false,
              stretched: false,
            },
          });
        }
      }
    }
    // Blockquotes
    else if (line.startsWith("> ")) {
      let quoteText = "";
      let caption = "";

      // Collect all consecutive quote lines
      while (i < lines.length) {
        const currentQuoteLine = lines[i];
        if (currentQuoteLine === undefined) break;
        if (!currentQuoteLine.trim().startsWith("> ")) break;
        const quoteLine = currentQuoteLine.trim().substring(2);
        if (quoteLine.startsWith("— ")) {
          caption = quoteLine.substring(2);
        } else if (quoteLine !== "") {
          if (quoteText) quoteText += " ";
          quoteText += quoteLine;
        }
        i++;
      }
      i--; // Adjust for the loop increment

      blocks.push({
        id: generateBlockId(),
        type: "quote",
        data: {
          text: quoteText,
          caption: caption,
        },
      });
    }
    // Code blocks
    else if (line === "```") {
      let code = "";
      i++; // Skip the opening ```

      while (i < lines.length) {
        const currentCodeLine = lines[i];
        if (currentCodeLine === undefined) break;
        if (currentCodeLine.trim() === "```") break;
        if (code) code += "\n";
        code += currentCodeLine;
        i++;
      }

      blocks.push({
        id: generateBlockId(),
        type: "code",
        data: {
          code: code,
        },
      });
    }
    // Ordered lists
    else if (line.match(/^\d+\.\s/)) {
      const items: string[] = [];

      while (i < lines.length) {
        const currentListItem = lines[i];
        if (currentListItem === undefined) break;
        if (!currentListItem.trim().match(/^\d+\.\s/)) break;
        const item = currentListItem.trim().replace(/^\d+\.\s/, "");
        items.push(item);
        i++;
      }
      i--; // Adjust for the loop increment

      blocks.push({
        id: generateBlockId(),
        type: "list",
        data: {
          style: "ordered",
          items: items,
        },
      });
    }
    // Unordered lists
    else if (line.startsWith("- ")) {
      const items: string[] = [];

      while (i < lines.length) {
        const currentListItem = lines[i];
        if (currentListItem === undefined) break;
        if (!currentListItem.trim().startsWith("- ")) break;
        const item = currentListItem.trim().substring(2);
        items.push(item);
        i++;
      }
      i--; // Adjust for the loop increment

      blocks.push({
        id: generateBlockId(),
        type: "list",
        data: {
          style: "unordered",
          items: items,
        },
      });
    }
    // Links (simple detection)
    else if (line.match(/^\[([^\]]+)\]\(([^)]+)\)$/)) {
      const match = line.match(/^\[([^\]]+)\]\(([^)]+)\)$/);
      if (match) {
        const title = match[1];
        const url = match[2];
        if (title !== undefined && url !== undefined) {
          blocks.push({
            id: generateBlockId(),
            type: "linkTool",
            data: {
              link: url,
              meta: {
                title: title,
              },
            },
          });
        }
      }
    }
    // Regular paragraphs
    else if (line) {
      // Collect consecutive non-empty lines for paragraph
      let paragraphText = line;
      let j = i + 1;

      while (j < lines.length) {
        const currentParagraphLine = lines[j];
        if (currentParagraphLine === undefined) break;
        const trimmed = currentParagraphLine.trim();
        if (
          trimmed === "" ||
          trimmed.startsWith("#") ||
          trimmed.startsWith("> ") ||
          trimmed.startsWith("- ") ||
          trimmed.match(/^\d+\.\s/) ||
          trimmed === "```" ||
          trimmed.match(/^!\[([^\]]*)\]\(([^)]+)\)$/)
        ) {
          break;
        }
        paragraphText += " " + trimmed;
        j++;
      }

      blocks.push({
        id: generateBlockId(),
        type: "paragraph",
        data: {
          text: paragraphText,
        },
      });

      i = j - 1; // Set i to the last line we processed
    }

    i++;
  }

  return {
    blocks: blocks,
  };
}

function generateBlockId(): string {
  return Math.random().toString(36).substr(2, 9);
}

