/**
 * Get effective hashtags for a draft post
 */
async function getEffectiveHashtags(
  useHashtagPresets: boolean,
  selectedHashtags: string,
  selectedQueue: string,
  userId: string,
  user: UserData
): Promise<string> {
  if (useHashtagPresets) {
    // Manual hashtag presets are enabled
    if (selectedHashtags) {
      // Use manually selected hashtag preset
      return selectedHashtags;
    }
    // If useHashtagPresets is true but no manual preset selected, use no hashtags
    return "";
  } else {
    // Manual hashtag presets are disabled, use queue type's default hashtags
    try {
      const response = await fetch("/api/effective-hashtags", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          userId,
          queueTypeName: selectedQueue,
        }),
      });

      if (response.ok) {
        const dataRaw: unknown = await response.json();
        const data =
          dataRaw && typeof dataRaw === "object" && !Array.isArray(dataRaw)
            ? (dataRaw as { hashtags?: unknown })
            : {};
        const hashtags =
          typeof data.hashtags === "string" ? data.hashtags : null;
        return hashtags ?? "";
      } else {
        // Fallback to user's default hashtags
        // Note: hashTags property doesn't exist on UserData, using empty string as fallback
        return "";
      }
    } catch (error) {
      logError(error instanceof Error ? error : new Error(String(error)), {
        userId: user.id,
        selectedQueue,
        message: "Error fetching effective hashtags",
      });
      // Fallback to user's default hashtags
      // Note: hashTags property doesn't exist on UserData, using empty string as fallback
      return "";
    }
  }
}

/**
 * Get image URLs from post fileUrl
 */
function getImageUrls(fileUrl: string[] | null | undefined): string[] {
  if (!fileUrl || fileUrl.length === 0) return [];

  // Handle case where fileUrl is an array of JSON strings
  if (typeof fileUrl[0] === "string" && fileUrl[0].startsWith("[")) {
    try {
      const parsed: unknown = JSON.parse(fileUrl[0]);
      return Array.isArray(parsed)
        ? parsed.filter((item): item is string => typeof item === "string")
        : [];
    } catch (e) {
      logError(e instanceof Error ? e : new Error(String(e)), {
        fileUrl: fileUrl[0],
        message: "Error parsing fileUrl",
      });
      return [];
    }
  }

  // Handle direct URLs
  return fileUrl;
}

/**
 * Calculate scheduled time in Unix timestamp
 */
function calculateScheduledTime(
  scheduledFor: string,
  userTimezone: string
): number {
  let scheduledTime: number;

  if (userTimezone !== "UTC" && userTimezone !== "Etc/GMT") {
    const utcDate = new Date(scheduledFor);
    const userDate = new Date(scheduledFor).toLocaleString("en-US", {
      timeZone: userTimezone,
    });
    const userOffset =
      (new Date(userDate).getTime() - new Date(scheduledFor).getTime()) / 60000;
    utcDate.setMinutes(utcDate.getMinutes() - userOffset);
    scheduledTime = utcDate.getTime();
  } else {
    const dateObj = new Date(scheduledFor + "Z");
    scheduledTime = dateObj.getTime();
  }

  return Math.floor(scheduledTime / 1000);
}

/**
 * Sign and prepare draft for scheduling
 */
export async function signDraftForScheduling(params: SignDraftParams): Promise<{
  signedEvent: SignedEvent;
  nostrEvent: NostrEventType;
  scheduledForUnix: number;
}> {
  const {
    content,
    caption,
    scheduledFor,
    selectedQueue,
    useHashtagPresets,
    selectedHashtags,
    user,
    currentUser,
    post,
  } = params;

  const userTimezone =
    currentUser &&
    typeof currentUser === "object" &&
    "timezone" in currentUser &&
    typeof currentUser.timezone === "string"
      ? currentUser.timezone
      : "UTC";
  const scheduledForUnix = calculateScheduledTime(scheduledFor, userTimezone);

  // Get effective hashtags
  const effectiveHashtags = await getEffectiveHashtags(
    useHashtagPresets,
    selectedHashtags,
    selectedQueue,
    currentUser?.id ?? "",
    user
  );

  const tagArray = effectiveHashtags
    .split(" ")
    .filter((tag) => tag.length > 0)
    .map((tag) => ["t", tag.replace("#", "")]);

  // Include image URLs in the content to sign (caption first, then image URLs)
  const imageUrls = getImageUrls(post.fileUrl);
  const imageUrlsText = imageUrls.length > 0 ? imageUrls.join(" ") : "";

  let baseContent = content || caption;
  if (imageUrlsText) {
    baseContent = baseContent
      ? `${baseContent} ${imageUrlsText}`
      : imageUrlsText;
  }

  const contentToSign = currentUser?.showHashTagsinPosts
    ? `${baseContent}\n${effectiveHashtags}`
    : baseContent;

  const { nostrEvent, signedEvent } = await nostrAdapter.signEvent({
    content: contentToSign,
    created_at: scheduledForUnix,
    kind: 1,
    tags: tagArray,
  });

  return { signedEvent, nostrEvent, scheduledForUnix };
}

/**
 * Longform Post Status Calculator
 *
 * Business logic for determining longform post status and publishedAt dates.
 * This logic was moved from the model layer to maintain clear boundaries.
 */

import type { SignedEvent } from "~/features/nostr/types";
export type LongFormStatus = "DRAFT" | "ACTIVE" | "SCHEDULED";

export interface LongFormStatusCalculation {
  status: LongFormStatus;
  isScheduled: boolean;
  isDraft: boolean;
  publishedAt: Date | null;
  nostrEventId: string | null;
  finalScheduledFor: string | null;
}

/**
 * Calculate longform post status and related fields
 */
export function calculateLongFormStatus({
  isPublished,
  scheduledFor,
  signedEvent,
}: {
  isPublished: boolean;
  scheduledFor?: string | null;
  signedEvent?: SignedEvent | null;
}): LongFormStatusCalculation {
  // Extract published_at from NOSTR event tags if not provided as scheduledFor
  let finalScheduledFor = scheduledFor;
  if (!finalScheduledFor && !isPublished && signedEvent?.tags) {
    const publishedAtTag = signedEvent.tags.find(
      (tag) => Array.isArray(tag) && tag[0] === "published_at",
    );
    if (publishedAtTag?.[1]) {
      finalScheduledFor = publishedAtTag[1].toString();
    }
  }

  // Determine status based on publishing state and scheduling
  const isScheduled = Boolean(finalScheduledFor && !isPublished);
  const isDraft = !isPublished && !isScheduled;

  let status: LongFormStatus;
  if (isPublished) {
    status = "ACTIVE";
  } else if (isScheduled) {
    status = "SCHEDULED";
  } else {
    status = "DRAFT";
  }

  // Extract nostrEventId from signedEvent if available
  const nostrEventId = signedEvent?.id ?? null;

  // Calculate publishedAt based on scheduling
  let publishedAt: Date | null = null;
  if (isPublished) {
    // For published posts, extract published_at from tags if available, otherwise current time
    let publishedAtTimestamp: number | null = null;
    if (signedEvent?.tags) {
      const publishedAtTag = signedEvent.tags.find(
        (tag: unknown) => Array.isArray(tag) && tag[0] === "published_at",
      );
      if (
        publishedAtTag &&
        Array.isArray(publishedAtTag) &&
        publishedAtTag[1]
      ) {
        publishedAtTimestamp =
          typeof publishedAtTag[1] === "number"
            ? publishedAtTag[1]
            : parseInt(String(publishedAtTag[1]), 10);
      }
    }
    publishedAt = publishedAtTimestamp
      ? new Date(publishedAtTimestamp * 1000)
      : new Date();
  } else if (isScheduled && finalScheduledFor) {
    // For scheduled posts, set publishedAt to the scheduled time
    publishedAt = new Date(parseInt(finalScheduledFor) * 1000);
  }

  return {
    status,
    isScheduled,
    isDraft,
    publishedAt,
    nostrEventId,
    finalScheduledFor: finalScheduledFor ?? null,
  };
}

