/**
 * Recyclable Posts Service
 *
 * Handles recyclable posts data loading and actions (repost, quote, delete)
 */

import { json } from "@remix-run/node";

import type { UserWithHashTagPresets } from "~/features/user";
import { getUserById, getQueueTypes } from "~/features/user";
import {
  recyclableActionSchema,
  validateFormDataOrRespond,
} from "~/lib/validation";
import { deletePost } from "~/models/post.commands.server";
import {
  getRecyclablePosts,
  getPostsByIds,
} from "~/models/post.queries.server";

import { toPostDTOArray, type PostDTO } from "../dtos";
import { getPostStats } from "../stats.server";
import type { PostData } from "../types";
import { convertPrismaQueueTypeToQueueType } from "../types";

const ERROR_POST_NOT_FOUND = "Post not found";

/**
 * Get recyclable posts dashboard data
 */
export async function getRecyclableDashboardData({
  userId,
  params,
  url,
}: {
  userId: string;
  params: { queueType?: string };
  url: URL;
}) {
  const page = parseInt(url.searchParams.get("page") ?? "1");
  const limit = 50;
  const queueType = params.queueType ?? "all";

  const [{ posts, pagination }, userResult, queueTypesResult] =
    await Promise.all([
      getRecyclablePosts({
        userId,
        page,
        limit,
        queueType,
      }),
      getUserById(userId),
      getQueueTypes(userId),
    ]);

  if (!userResult) {
    throw new Error("User not found");
  }

  const user: UserWithHashTagPresets = userResult;
  const queueTypes = Array.isArray(queueTypesResult) ? queueTypesResult : [];

  // Get event IDs from signedEvent.id
  const eventIds = posts
    .map((post) => {
      const signedEvent = post.signedEvent;
      if (
        signedEvent &&
        typeof signedEvent === "object" &&
        "id" in signedEvent &&
        typeof signedEvent["id"] === "string"
      ) {
        return signedEvent["id"];
      }
      return "";
    })
    .filter((id) => id !== "");

  // Use the extracted stats fetching logic
  const stats = await getPostStats(eventIds);

  // Convert PostWithQueueType[] to PostData[] and serialize to DTOs
  const postsData: PostData[] = posts.map((post) => {
    const { queueType, ...rest } = post;
    const signedEventValue: PostData["signedEvent"] =
      post.signedEvent as PostData["signedEvent"];
    const nostrEventValue: PostData["nostrEvent"] =
      post.nostrEvent as PostData["nostrEvent"];
    const result: PostData = {
      ...rest,
      queueType: convertPrismaQueueTypeToQueueType(queueType),
      signedEvent: signedEventValue,
      nostrEvent: nostrEventValue,
    };
    return result;
  });

  const postsDTO: PostDTO[] = toPostDTOArray(postsData);

  return {
    posts: postsDTO,
    pagination,
    stats,
    user,
    queueTypes: queueTypes.filter(
      (qt: unknown) =>
        typeof qt === "object" &&
        qt !== null &&
        "isEnabled" in qt &&
        qt.isEnabled !== false
    ),
    selectedQueueType: queueType,
  };
}

/**
 * Handle recyclable post actions (delete, repost, quote)
 */
export async function handleRecyclablePostAction(
  formData: FormData,
  userId: string
) {
  // Validate with Zod
  const result = validateFormDataOrRespond(formData, recyclableActionSchema);
  if (!result.success) {
    return result.response;
  }

  const validatedData = result.data;

  // Handle delete action
  if (validatedData._action === "delete") {
    await deletePost({ id: validatedData.postId, userId });
    return json({ success: true });
  }

  // Handle bulk delete
  if (validatedData._action === "bulkDelete") {
    await Promise.all(
      validatedData.postIds.map((id: string) => deletePost({ id, userId }))
    );
    return json({ success: true });
  }

  // Handle bulk repost
  if (validatedData._action === "bulkRepost") {
    const postsData = await getPostsByIds({
      ids: validatedData.postIds,
      userId,
    });
    return json({ repostData: postsData });
  }

  // Handle bulk scheduled repost
  if (validatedData._action === "bulkScheduledRepost") {
    const postsData = await getPostsByIds({
      ids: validatedData.postIds,
      userId,
    });
    return json({ scheduledRepostData: postsData });
  }

  // Handle bulk quote
  if (validatedData._action === "bulkQuote") {
    const postsData = await getPostsByIds({
      ids: validatedData.postIds,
      userId,
    });

    // Transform posts data into quote post format
    const quotePostsData = postsData.map((post) => {
      const signedEvent = post.signedEvent;
      let eventId = "";
      let eventPubkey = "";

      if (
        signedEvent &&
        typeof signedEvent === "object" &&
        !Array.isArray(signedEvent)
      ) {
        if ("id" in signedEvent && typeof signedEvent["id"] === "string") {
          eventId = signedEvent["id"];
        }
        if (
          "pubkey" in signedEvent &&
          typeof signedEvent["pubkey"] === "string"
        ) {
          eventPubkey = signedEvent["pubkey"];
        }
      }

      const fileUrl = Array.isArray(post.fileUrl)
        ? post.fileUrl
        : typeof post.fileUrl === "string"
          ? [post.fileUrl]
          : [];
      const caption = typeof post.caption === "string" ? post.caption : "";
      const queueTypeName =
        post.queueType &&
        typeof post.queueType === "object" &&
        "name" in post.queueType &&
        typeof post.queueType.name === "string"
          ? post.queueType.name
          : "unassigned";

      return {
        caption: "", // Empty caption - user can add content
        fileUrl: fileUrl.length > 0 ? (fileUrl[0] ?? "") : "",
        queueType: queueTypeName,
        scheduledFor: "",
        originalPostId: post.id,
        originalEventId: eventId,
        originalEventPubkey: eventPubkey,
        isQuotePost: true,
        originalCaption: caption,
      };
    });

    return json({ quotePostData: quotePostsData });
  }

  // Handle single repost
  if (validatedData._action === "repost") {
    try {
      const repostData = validatedData;
      // Get the original post data
      const postsData = await getPostsByIds({
        ids: [repostData.postId],
        userId,
      });
      if (postsData.length === 0) {
        const { NotFoundError } = await import("~/lib/errors");
        throw new NotFoundError(ERROR_POST_NOT_FOUND, {
          postId: repostData.postId,
          userId,
        });
      }

      const originalPost = postsData[0];
      if (!originalPost) {
        return json({ error: ERROR_POST_NOT_FOUND }, { status: 404 });
      }
      const originalEvent = originalPost.signedEvent;

      if (
        !originalEvent ||
        typeof originalEvent !== "object" ||
        !("id" in originalEvent) ||
        !("pubkey" in originalEvent)
      ) {
        return json({ error: "Invalid event data" }, { status: 400 });
      }

      const eventId =
        typeof originalEvent["id"] === "string"
          ? originalEvent["id"]
          : String(originalEvent["id"]);
      const eventPubkey =
        typeof originalEvent["pubkey"] === "string"
          ? originalEvent["pubkey"]
          : String(originalEvent["pubkey"]);

      // Create kind 6 repost event structure according to NIP-18
      const kind6EventData = {
        kind: 6,
        content: "", // Empty content as recommended by NIP-18
        tags: [
          // e tag with the id of the note being reposted and relay URL
          ["e", eventId, "wss://relay.primal.net"],
          // p tag with the pubkey of the event being reposted
          ["p", eventPubkey],
        ],
        created_at: Math.floor(Date.now() / 1000),
      };

      // Return the unsigned event data for client-side signing
      return json({
        repostEventData: kind6EventData,
        originalPost: originalPost,
      });
    } catch (error) {
      const { handleActionError } = await import("~/lib/error-handler.server");
      return handleActionError(error);
    }
  }

  // Handle single quote - TypeScript guarantees this is "quote" after previous checks
  try {
    const quoteData = validatedData;
    // Get the original post data
    const postsData = await getPostsByIds({
      ids: [quoteData.postId],
      userId,
    });
    if (postsData.length === 0) {
      const { NotFoundError } = await import("~/lib/errors");
      throw new NotFoundError(ERROR_POST_NOT_FOUND, {
        postId: quoteData.postId,
        userId,
      });
    }

    const originalPost = postsData[0];
    if (!originalPost) {
      return json({ error: ERROR_POST_NOT_FOUND }, { status: 404 });
    }
    const originalEvent = originalPost.signedEvent;

    if (
      !originalEvent ||
      typeof originalEvent !== "object" ||
      !("id" in originalEvent) ||
      !("pubkey" in originalEvent)
    ) {
      return json({ error: "Invalid event data" }, { status: 400 });
    }

    const eventId =
      typeof originalEvent["id"] === "string"
        ? originalEvent["id"]
        : String(originalEvent["id"]);
    const eventPubkey =
      typeof originalEvent["pubkey"] === "string"
        ? originalEvent["pubkey"]
        : String(originalEvent["pubkey"]);

    // Create quote post data for bulk posts page
    const fileUrl =
      "fileUrl" in originalPost
        ? Array.isArray(originalPost.fileUrl)
          ? originalPost.fileUrl[0]
          : typeof originalPost.fileUrl === "string"
            ? originalPost.fileUrl
            : ""
        : "";
    const queueTypeName =
      originalPost.queueType &&
      typeof originalPost.queueType === "object" &&
      "name" in originalPost.queueType &&
      typeof originalPost.queueType.name === "string"
        ? originalPost.queueType.name
        : "unassigned";
    const caption =
      "caption" in originalPost && typeof originalPost.caption === "string"
        ? originalPost.caption
        : "";
    const originalPostId =
      "id" in originalPost && typeof originalPost.id === "string"
        ? originalPost.id
        : "";

    const quotePostData = {
      caption: "", // Empty caption - user can add content
      fileUrl,
      queueType: queueTypeName,
      scheduledFor: "",
      originalPostId: originalPostId,
      originalEventId: eventId,
      originalEventPubkey: eventPubkey,
      isQuotePost: true,
      originalCaption: caption,
    };

    return json({ quotePostData: [quotePostData] });
  } catch (error) {
    const { handleActionError } = await import("~/lib/error-handler.server");
    return handleActionError(error);
  }
}

/**
 * Scheduled Posts Service
 *
 * Handles scheduled posts data loading and actions
 */

import { json } from "@remix-run/node";

import {
  getUserById,
  getQueueTypes,
  getUserHashTagPresets,
} from "~/features/user";
import {
  enqueuePostJob as schedulePost,
  cancelPostJob as cancelScheduledPost,
} from "~/infra/queue";
import { logError } from "~/lib/error-logger.server";
import {
  getScheduledLongFormPosts,
  deleteLongFormPost,
  updateLongFormPost,
  getLongFormPost as getLongFormPostModel,
} from "~/models/longformpost.server";
import {
  deletePost,
  reschedulePost,
  updatePost,
} from "~/models/post.commands.server";
import { getScheduledPosts, getPostById } from "~/models/post.queries.server";

const ERROR_POST_NOT_FOUND = "Post not found";
const ERROR_LONGFORM_POST_NOT_FOUND = "Longform post not found";
const ERROR_PARSING_SIGNED_EVENTS = "Error parsing signed events";
// eslint-disable-next-line @typescript-eslint/no-unused-vars -- Reserved for future use
const QUEUE_SCHEDULED_POSTS = "scheduled-posts";
// eslint-disable-next-line @typescript-eslint/no-unused-vars -- Reserved for future use
const QUEUE_SCHEDULED_LONGFORM_POSTS = "scheduled-longform-posts";

import { combineContent } from "../combined.server";
import { convertPrismaQueueTypeToQueueType } from "../types";
import type { PostData, LongFormPostData } from "../types";

/**
 * Get scheduled posts dashboard data
 */
export async function getScheduledDashboardData({
  userId,
  queueType,
}: {
  userId: string;
  queueType: string;
}) {
  const [posts, allLongformPosts, user, queueTypesRaw, hashTagPresetsRaw] =
    await Promise.all([
      getScheduledPosts({ userId, queueType }),
      getScheduledLongFormPosts({ userId }),
      getUserById(userId),
      getQueueTypes(userId),
      getUserHashTagPresets(userId),
    ]);

  const queueTypes = Array.isArray(queueTypesRaw) ? queueTypesRaw : [];
  const hashTagPresets = Array.isArray(hashTagPresetsRaw)
    ? hashTagPresetsRaw
    : [];

  // Filter longform posts by queue type if specific queue is selected
  const longformPosts =
    queueType === "all"
      ? allLongformPosts
      : allLongformPosts.filter((post) => post.queueType?.name === queueType);

  // Convert PostWithQueueType[] to PostData[] for combineContent
  const postsData: PostData[] = posts.map((post) => {
    const { queueType, ...rest } = post;
    const signedEventValue: PostData["signedEvent"] =
      post.signedEvent as PostData["signedEvent"];
    const nostrEventValue: PostData["nostrEvent"] =
      post.nostrEvent as PostData["nostrEvent"];
    const postData: PostData = {
      ...rest,
      queueType: convertPrismaQueueTypeToQueueType(queueType),
      signedEvent: signedEventValue,
      nostrEvent: nostrEventValue,
    };
    return postData;
  });

  // Convert LongFormPost[] to LongFormPostData[] for combineContent
  const longformPostsData: LongFormPostData[] = longformPosts.map((post) => {
    const signedEventValue: LongFormPostData["signedEvent"] =
      post.signedEvent as LongFormPostData["signedEvent"];
    const nostrEventValue: LongFormPostData["nostrEvent"] =
      post.nostrEvent as LongFormPostData["nostrEvent"];
    const longformPostData: LongFormPostData = {
      ...post,
      queueType: convertPrismaQueueTypeToQueueType(
        "queueType" in post ? post.queueType : undefined
      ),
      signedEvent: signedEventValue,
      nostrEvent: nostrEventValue,
    };
    return longformPostData;
  });

  // Combine posts and longform posts for the "All" tab
  const allContent = combineContent(
    postsData,
    longformPostsData,
    "scheduledFor",
    "asc"
  );

  return {
    posts,
    longformPosts,
    allContent,
    user,
    queueTypes: queueTypes.filter(
      (qt: unknown) =>
        typeof qt === "object" &&
        qt !== null &&
        "isEnabled" in qt &&
        qt.isEnabled !== false
    ),
    selectedQueueType: queueType,
    hashTagPresets,
  };
}

/**
 * Handle scheduled post actions (delete, reschedule, edit)
 */
export async function handleScheduledPostAction(
  formData: FormData,
  userId: string
) {
  const postId = formData.get("postId") as string;
  const _action = formData.get("_action");

  if (_action === "delete") {
    await deletePost({ id: postId, userId });
    return json({ success: true });
  }

  if (_action === "deleteLongForm") {
    await deleteLongFormPost({ id: postId, userId });
    return json({ success: true });
  }

  if (_action === "bulkDelete") {
    const postIdsValue = formData.get("postIds");
    const postIdsStr = postIdsValue ? String(postIdsValue) : "[]";
    let postIds: string[] = [];
    try {
      const parsed: unknown = JSON.parse(postIdsStr);
      postIds = Array.isArray(parsed)
        ? parsed.filter((id: unknown): id is string => typeof id === "string")
        : [];
    } catch {
      postIds = [];
    }
    await Promise.all(postIds.map((id: string) => deletePost({ id, userId })));
    return json({ success: true });
  }

  if (_action === "bulkDeleteLongForm") {
    const postIdsValue = formData.get("postIds");
    const postIdsStr = postIdsValue ? String(postIdsValue) : "[]";
    let postIds: string[] = [];
    try {
      const parsed: unknown = JSON.parse(postIdsStr);
      postIds = Array.isArray(parsed)
        ? parsed.filter((id: unknown): id is string => typeof id === "string")
        : [];
    } catch {
      postIds = [];
    }
    await Promise.all(
      postIds.map((id: string) => deleteLongFormPost({ id, userId }))
    );
    return json({ success: true });
  }

  if (_action === "bulkDeleteMixed") {
    const itemDataValue = formData.get("itemData");
    const itemDataStr = itemDataValue ? String(itemDataValue) : "[]";
    let itemData: Array<{ id: string; type: string }> = [];
    try {
      const parsed: unknown = JSON.parse(itemDataStr);
      if (Array.isArray(parsed)) {
        itemData = parsed.filter(
          (item: unknown): item is { id: string; type: string } =>
            typeof item === "object" &&
            item !== null &&
            "id" in item &&
            "type" in item &&
            typeof (item as { id: unknown; type: unknown }).id === "string" &&
            typeof (item as { id: unknown; type: unknown }).type === "string"
        );
      }
    } catch {
      itemData = [];
    }
    const promises = itemData.map((item: { id: string; type: string }) => {
      if (item.type === "post") {
        return deletePost({ id: item.id, userId });
      } else {
        return deleteLongFormPost({ id: item.id, userId });
      }
    });
    await Promise.all(promises);
    return json({ success: true });
  }

  // Reschedule a regular post (with optional re-signed event)
  if (_action === "reschedule") {
    const newTime = formData.get("newTime") as string;
    const overrideQueue = formData.get("overrideQueue") === "true";
    const signedEventStr = formData.get("signedEvent") as string;
    const nostrEventStr = formData.get("nostrEvent") as string;
    const queueTypeId = formData.get("queueTypeId") as string;

    if (!postId || !newTime) {
      return json({ error: "Missing required fields" }, { status: 400 });
    }

    const originalPost = await getPostById({ id: postId, userId });
    if (!originalPost) {
      return json({ error: ERROR_POST_NOT_FOUND }, { status: 404 });
    }

    await cancelScheduledPost(postId);

    let parsedSignedEvent = null;
    let parsedNostrEvent = null;
    if (signedEventStr && nostrEventStr) {
      try {
        const parsedSigned: unknown = JSON.parse(signedEventStr);
        const parsedNostr: unknown = JSON.parse(nostrEventStr);
        parsedSignedEvent =
          typeof parsedSigned === "object" && parsedSigned !== null
            ? (parsedSigned as {
                id: string;
                pubkey: string;
                created_at: number;
                kind: number;
                content: string;
                tags: string[][];
                sig: string;
              })
            : null;
        parsedNostrEvent =
          typeof parsedNostr === "object" && parsedNostr !== null
            ? (parsedNostr as {
                id: string;
                pubkey: string;
                created_at: number;
                kind: number;
                content: string;
                tags: string[][];
              })
            : null;
      } catch (e) {
        logError(e instanceof Error ? e : new Error(String(e)), {
          userId,
          postId,
          message: ERROR_PARSING_SIGNED_EVENTS,
        });
      }
    }

    const updatedPost = await reschedulePost({
      id: postId,
      userId,
      newScheduledFor: newTime,
      overrideQueue,
      queueTypeId,
      signedEvent: parsedSignedEvent ?? undefined,
      nostrEvent: parsedNostrEvent ?? undefined,
    });

    if (parsedSignedEvent && parsedNostrEvent) {
      await schedulePost(postId, userId, parsedSignedEvent, parseInt(newTime));
      return json({ success: true, post: updatedPost, signed: true });
    }

    return json({ success: true, post: updatedPost, needsSigning: true });
  }

  // Reschedule a longform post (with optional re-signed event)
  if (_action === "rescheduleLongform") {
    const newTime = formData.get("newTime") as string;
    const signedEventStr = formData.get("signedEvent") as string;
    const nostrEventStr = formData.get("nostrEvent") as string;

    if (!postId || !newTime) {
      return json({ error: "Missing required fields" }, { status: 400 });
    }

    const originalPost = await getLongFormPostModel({ id: postId, userId });
    if (!originalPost) {
      return json({ error: ERROR_LONGFORM_POST_NOT_FOUND }, { status: 404 });
    }

    let parsedSignedEvent = null;
    let parsedNostrEvent = null;
    if (signedEventStr && nostrEventStr) {
      try {
        const parsedSigned: unknown = JSON.parse(signedEventStr);
        const parsedNostr: unknown = JSON.parse(nostrEventStr);
        parsedSignedEvent =
          typeof parsedSigned === "object" && parsedSigned !== null
            ? (parsedSigned as {
                id: string;
                pubkey: string;
                created_at: number;
                kind: number;
                content: string;
                tags: string[][];
                sig: string;
              })
            : null;
        parsedNostrEvent =
          typeof parsedNostr === "object" && parsedNostr !== null
            ? (parsedNostr as {
                id: string;
                pubkey: string;
                created_at: number;
                kind: number;
                content: string;
                tags: string[][];
              })
            : null;
      } catch (e) {
        logError(e instanceof Error ? e : new Error(String(e)), {
          userId,
          postId,
          message: ERROR_PARSING_SIGNED_EVENTS,
        });
      }
    }

    const updatedPost = await updateLongFormPost({
      id: postId,
      userId,
      publishedAt: new Date(parseInt(newTime) * 1000),
      status: "SCHEDULED",
      signedEvent: parsedSignedEvent ?? undefined,
      nostrEvent: parsedNostrEvent ?? undefined,
    });

    return json({
      success: true,
      post: updatedPost,
      signed: !!parsedSignedEvent,
    });
  }

  // Edit a regular post's content/media/hashtags and re-sign
  if (_action === "editPost") {
    const caption = (formData.get("caption") ?? "") as string;
    const fileUrl = (formData.get("fileUrl") ?? "") as string;
    const hashtags = (formData.get("hashtags") ?? "") as string;
    const signedEventStr = formData.get("signedEvent") as string;
    const nostrEventStr = formData.get("nostrEvent") as string;
    const queueTypeId = (formData.get("queueTypeId") as string | null) ?? null;
    const scheduledFor =
      (formData.get("scheduledFor") as string | null) ?? null;
    const hashTagPresetId =
      (formData.get("hashTagPresetId") as string | null) ?? null;

    if (!postId) {
      return json({ error: "Missing postId" }, { status: 400 });
    }

    let parsedSignedEvent = null;
    let parsedNostrEvent = null;
    if (signedEventStr && nostrEventStr) {
      try {
        const parsedSigned: unknown = JSON.parse(signedEventStr);
        const parsedNostr: unknown = JSON.parse(nostrEventStr);
        parsedSignedEvent =
          typeof parsedSigned === "object" && parsedSigned !== null
            ? (parsedSigned as {
                id: string;
                pubkey: string;
                created_at: number;
                kind: number;
                content: string;
                tags: string[][];
                sig: string;
              })
            : null;
        parsedNostrEvent =
          typeof parsedNostr === "object" && parsedNostr !== null
            ? (parsedNostr as {
                id: string;
                pubkey: string;
                created_at: number;
                kind: number;
                content: string;
                tags: string[][];
              })
            : null;
      } catch (e) {
        logError(e instanceof Error ? e : new Error(String(e)), {
          userId,
          postId,
          message: ERROR_PARSING_SIGNED_EVENTS,
        });
      }
    }

    let parsedFileUrl: string[] = [];
    if (fileUrl) {
      try {
        const parsed: unknown = JSON.parse(fileUrl);
        parsedFileUrl = Array.isArray(parsed)
          ? parsed.filter(
              (item: unknown): item is string => typeof item === "string"
            )
          : [];
      } catch (e) {
        logError(e instanceof Error ? e : new Error(String(e)), {
          userId,
          postId,
          fileUrl,
          message: "Error parsing fileUrl",
        });
        parsedFileUrl = [];
      }
    }

    const updated = await updatePost({
      id: postId,
      userId,
      data: {
        caption,
        fileUrl: parsedFileUrl,
        tags: hashtags
          ? hashtags
              .toString()
              .split(" ")
              .filter((tag) => tag.trim())
          : [],
        queueTypeId,
        scheduledFor: scheduledFor ? String(Number(scheduledFor)) : undefined,
        signedEvent: parsedSignedEvent ?? undefined,
        nostrEvent: parsedNostrEvent ?? undefined,
        hashTagPresetId,
      },
    });

    if (scheduledFor && parsedSignedEvent) {
      await cancelScheduledPost(postId);
      await schedulePost(
        postId,
        userId,
        parsedSignedEvent,
        Number(scheduledFor)
      );
    }

    return json({
      success: true,
      post: updated,
      signed: !!parsedSignedEvent,
    });
  }

  // Edit a longform post's content and re-sign
  if (_action === "editLongform") {
    const title = (formData.get("title") ?? "") as string;
    const summary = (formData.get("summary") ?? "") as string;
    const content = (formData.get("content") ?? "") as string;
    const image = (formData.get("image") ?? "") as string;
    const signedEventStr = formData.get("signedEvent") as string;
    const nostrEventStr = formData.get("nostrEvent") as string;
    const scheduledFor =
      (formData.get("scheduledFor") as string | null) ?? null;

    if (!postId) {
      return json({ error: "Missing postId" }, { status: 400 });
    }

    let parsedSignedEvent = null;
    let parsedNostrEvent = null;
    if (signedEventStr && nostrEventStr) {
      try {
        const parsedSigned: unknown = JSON.parse(signedEventStr);
        const parsedNostr: unknown = JSON.parse(nostrEventStr);
        parsedSignedEvent =
          typeof parsedSigned === "object" && parsedSigned !== null
            ? (parsedSigned as {
                id: string;
                pubkey: string;
                created_at: number;
                kind: number;
                content: string;
                tags: string[][];
                sig: string;
              })
            : null;
        parsedNostrEvent =
          typeof parsedNostr === "object" && parsedNostr !== null
            ? (parsedNostr as {
                id: string;
                pubkey: string;
                created_at: number;
                kind: number;
                content: string;
                tags: string[][];
              })
            : null;
      } catch (e) {
        logError(e instanceof Error ? e : new Error(String(e)), {
          userId,
          postId,
          message: ERROR_PARSING_SIGNED_EVENTS,
        });
      }
    }

    const updated = await updateLongFormPost({
      id: postId,
      userId,
      title,
      summary,
      content,
      image,
      publishedAt: scheduledFor
        ? new Date(Number(scheduledFor) * 1000)
        : undefined,
      status: "SCHEDULED",
      signedEvent: parsedSignedEvent ?? undefined,
      nostrEvent: parsedNostrEvent ?? undefined,
    });

    return json({
      success: true,
      post: updated,
      signed: !!parsedSignedEvent,
    });
  }

  return json({ error: "Invalid action" }, { status: 400 });
}

import { env } from "~/lib/env.server";
import { fetchJsonWithRetry } from "~/lib/fetch.server";

export interface PostStats {
  likes: number;
  replies: number;
  mentions: number;
  reposts: number;
  zaps: number;
  satszapped: number;
}

export async function getPostStats(
  eventIds: string[]
): Promise<Record<string, PostStats>> {
  let stats: Record<string, PostStats> = {};

  if (eventIds.length === 0) {
    return stats;
  }

  try {
    const controller = new AbortController();
    const timeoutId = setTimeout(() => controller.abort(), 5000);

    // Fetch stats for each event ID
    const statsPromises = eventIds.map(async (eventId) => {
      // Read directly from process.env to support test environment changes
      const primalUrl =
        process.env["PRIMAL_CACHING_URL"] ?? env.PRIMAL_CACHING_URL;
      if (!primalUrl) {
        throw new Error("PRIMAL_CACHING_URL environment variable is not set");
      }
      const response = await fetchJsonWithRetry<unknown[]>(primalUrl, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          requestType: "thread_view",
          params: {
            event_id: eventId,
          },
        }),
        timeout: 5000, // 5 seconds for cache requests
        maxRetries: 1, // Single retry for stats
      });

      const data: unknown[] = Array.isArray(response) ? response : [];
      // Find the stats event in the response array
      // The stats event has kind 10000100 and contains engagement metrics
      const statsEvent: unknown = data.find((event: unknown) => {
        if (!Array.isArray(event) || event.length < 3 || event[0] !== "EVENT")
          return false;
        const eventDataRaw: unknown = event[2];
        const eventData: unknown = eventDataRaw;
        if (
          !eventData ||
          typeof eventData !== "object" ||
          Array.isArray(eventData)
        )
          return false;
        const eventTyped = eventData as { kind?: unknown; content?: unknown };
        return (
          typeof eventTyped.kind === "number" &&
          eventTyped.kind === 10000100 &&
          eventTyped.content &&
          typeof eventTyped.content === "string" &&
          eventTyped.content.includes(eventId)
        );
      });

      if (
        Array.isArray(statsEvent) &&
        statsEvent[2] &&
        typeof statsEvent[2] === "object" &&
        !Array.isArray(statsEvent[2])
      ) {
        const eventData = statsEvent[2] as {
          kind?: unknown;
          content?: unknown;
        };
        if (eventData.content && typeof eventData.content === "string") {
          let content: {
            likes?: number;
            replies?: number;
            mentions?: number;
            reposts?: number;
            zaps?: number;
            satszapped?: number;
          } = {};
          try {
            const parsed: unknown = JSON.parse(eventData.content ?? "");
            if (
              typeof parsed === "object" &&
              parsed !== null &&
              !Array.isArray(parsed)
            ) {
              const parsedObj = parsed as Record<string, unknown>;
              content = {
                likes:
                  typeof parsedObj["likes"] === "number"
                    ? parsedObj["likes"]
                    : undefined,
                replies:
                  typeof parsedObj["replies"] === "number"
                    ? parsedObj["replies"]
                    : undefined,
                mentions:
                  typeof parsedObj["mentions"] === "number"
                    ? parsedObj["mentions"]
                    : undefined,
                reposts:
                  typeof parsedObj["reposts"] === "number"
                    ? parsedObj["reposts"]
                    : undefined,
                zaps:
                  typeof parsedObj["zaps"] === "number"
                    ? parsedObj["zaps"]
                    : undefined,
                satszapped:
                  typeof parsedObj["satszapped"] === "number"
                    ? parsedObj["satszapped"]
                    : undefined,
              };
            }
          } catch {
            // If parsing fails, use empty content
          }
          return {
            [eventId]: {
              likes: content.likes ?? 0,
              replies: content.replies ?? 0,
              mentions: content.mentions ?? 0,
              reposts: content.reposts ?? 0,
              zaps: content.zaps ?? 0,
              satszapped: content.satszapped ?? 0,
            },
          };
        }
      }

      const statsValue: PostStats = {
        likes: 0,
        replies: 0,
        mentions: 0,
        reposts: 0,
        zaps: 0,
        satszapped: 0,
      };
      const result: Record<string, PostStats> = {
        [eventId]: statsValue,
      };
      return result;
    });

    const statsResults = await Promise.all(statsPromises);
    stats = statsResults.reduce((acc, curr) => ({ ...acc, ...curr }), {});
    clearTimeout(timeoutId);
  } catch (error) {
    console.error("Error fetching stats:", error);
    // Initialize empty stats object with 0 values for each post
    const emptyStats: Record<string, PostStats> = {};
    stats = eventIds.reduce((acc, eventId) => {
      acc[eventId] = {
        likes: 0,
        replies: 0,
        mentions: 0,
        reposts: 0,
        zaps: 0,
        satszapped: 0,
      };
      return acc;
    }, emptyStats);
  }

  return stats;
}

import { type FetcherWithComponents } from "@remix-run/react";
import { nip19 } from "nostr-tools";
import { useEffect, useRef, useCallback } from "react";

import { type ToastMessage } from "~/components/types";
import { uploadMultipleFiles } from "~/features/upload/upload.client";
import type { User } from "~/features/user";
import { logClientError } from "~/lib/error-handler.client";

import { type BulkPost, type PreparedEvent } from "./types";

const DEFAULT_RELAY_URL = "wss://relay.primal.net";

interface FetcherData {
  fileUrls?: Array<{ fileUrl: string; scheduledFor: string }>;
}

interface UseBulkPostEventsProps {
  posts: BulkPost[];
  fetcher: FetcherWithComponents<FetcherData>;
  user: User | null;
  tags: string[];
  useHashtagPresets: boolean;
  selectedHashtags: string;
  setToast: (toast: ToastMessage | null) => void;
  setPreparedEvents: (events: PreparedEvent[]) => void;
  setShowConfirmation: (show: boolean) => void;
  setIsPreviewSubmitting: (isSubmitting: boolean) => void;
  setIsProcessing: (isProcessing: boolean) => void;
}

export function useBulkPostEvents({
  posts,
  fetcher,
  user,
  tags,
  useHashtagPresets,
  selectedHashtags,
  setToast,
  setPreparedEvents,
  setShowConfirmation,
  setIsPreviewSubmitting,
  setIsProcessing: _setIsProcessing,
}: UseBulkPostEventsProps) {
  const isWaitingForUpload = useRef(false);

  // Validation function to check if all posts are ready for preview
  const validatePostsForPreview = () => {
    const errors: string[] = [];

    posts.forEach((post, index) => {
      // Check if schedule time is set
      if (!post.scheduledFor || post.scheduledFor.trim() === "") {
        errors.push(`Post ${index + 1}: Schedule time is required`);
      }

      // Check if schedule time is in the future
      if (post.scheduledFor) {
        const userTimezone = user?.timezone ?? "UTC";

        // The scheduledFor value is in user's timezone (from datetime-local input)
        // We need to compare it with current time in the same user timezone
        // Get current time in user's timezone as a comparable string
        const nowInUserTz = new Date()
          .toLocaleString("en-US", {
            timeZone: userTimezone,
            year: "numeric",
            month: "2-digit",
            day: "2-digit",
            hour: "2-digit",
            minute: "2-digit",
            hour12: false,
          })
          .replace(/(\d+)\/(\d+)\/(\d+),\s(\d+):(\d+)/, "$3-$1-$2T$4:$5");

        // Compare as strings since both are in the same format (YYYY-MM-DDTHH:mm)
        // This avoids timezone conversion issues
        if (post.scheduledFor <= nowInUserTz) {
          errors.push(`Post ${index + 1}: Schedule time must be in the future`);
        }
      }

      // Check if queue type is assigned (for new uploads)
      if (
        !post.isRepost &&
        !post.isKind6Repost &&
        !post.isQuotePost &&
        post.queueType === "unassigned"
      ) {
        errors.push(`Post ${index + 1}: Please assign a queue type`);
      }
    });

    return { isValid: errors.length === 0, errors };
  };

  const processEvents = useCallback(async () => {
    // Create events with image URLs and hashtags
    const events = await Promise.all(
      posts.map(async (post, index) => {
        // Get effective hashtags - use manual selection if enabled, otherwise queue default
        let effectiveHashtags = "";

        if (useHashtagPresets && selectedHashtags) {
          // Use manually selected hashtag preset
          effectiveHashtags = selectedHashtags;
        } else {
          // Use queue type's default hashtags
          try {
            const res = await fetch("/api/effective-hashtags", {
              method: "POST",
              headers: {
                "Content-Type": "application/json",
              },
              body: JSON.stringify({
                userId: user?.id,
                queueTypeName: post.queueType,
              }),
            });
            const dataRaw: unknown = await res.json();
            const data =
              dataRaw && typeof dataRaw === "object" && !Array.isArray(dataRaw)
                ? (dataRaw as { hashtags?: unknown })
                : {};
            const hashtags =
              typeof data.hashtags === "string" ? data.hashtags : null;
            effectiveHashtags = hashtags ?? tags.join(" ");
          } catch {
            effectiveHashtags = tags.join(" ");
          }
        }

        const tagsString = effectiveHashtags;
        const addTags =
          user &&
          typeof user === "object" &&
          "showHashTagsinPosts" in user &&
          user.showHashTagsinPosts
            ? `${tagsString}`
            : "";

        // Build content array, filtering out null/undefined/empty values
        const fetcherDataRaw = fetcher.data;
        const fetcherData =
          fetcherDataRaw &&
          typeof fetcherDataRaw === "object" &&
          !Array.isArray(fetcherDataRaw)
            ? (fetcherDataRaw as { fileUrls?: unknown })
            : null;
        const fileUrls =
          fetcherData &&
          "fileUrls" in fetcherData &&
          Array.isArray(fetcherData.fileUrls)
            ? fetcherData.fileUrls
            : null;
        const fileUrlItem =
          fileUrls?.[index] &&
          typeof fileUrls[index] === "object" &&
          fileUrls[index] !== null &&
          !Array.isArray(fileUrls[index])
            ? (fileUrls[index] as { fileUrl?: unknown; scheduledFor?: unknown })
            : null;
        const fileUrl =
          fileUrlItem &&
          "fileUrl" in fileUrlItem &&
          typeof fileUrlItem.fileUrl === "string"
            ? fileUrlItem.fileUrl
            : "";

        const contentParts = [fileUrl, post.caption, addTags].filter(
          (part) => part !== ""
        ); // Filter out empty strings

        const content = contentParts.join("\n");

        // Convert space-separated tags string into array of ["t", tag] pairs
        const tagArray: string[][] = tagsString
          .split(" ")
          .filter((tag: string) => tag.length > 0)
          .map((tag: string) => ["t", tag.replace("#", "")]);

        const userTimezone =
          user &&
          typeof user === "object" &&
          "timezone" in user &&
          typeof user.timezone === "string"
            ? user.timezone
            : "UTC";
        const scheduledForValue =
          fileUrlItem &&
          "scheduledFor" in fileUrlItem &&
          typeof fileUrlItem.scheduledFor === "string"
            ? fileUrlItem.scheduledFor
            : "";
        const userTimezoneDateStr = scheduledForValue;
        let scheduledTime;

        // Only convert timezone if not UTC/Etc/GMT
        if (userTimezone !== "UTC" && userTimezone !== "Etc/GMT") {
          const utcDate = new Date(userTimezoneDateStr);

          // Get timezone offset in minutes between user timezone and UTC
          const userDate = new Date(userTimezoneDateStr).toLocaleString(
            "en-US",
            {
              timeZone: userTimezone,
            }
          );
          const userOffset =
            (new Date(userDate).getTime() -
              new Date(userTimezoneDateStr).getTime()) /
            60000;

          // Adjust the date by the offset
          utcDate.setMinutes(utcDate.getMinutes() - userOffset);
          scheduledTime = utcDate.getTime();
        } else {
          // Parse date string and ensure it's in UTC
          const dateObj = new Date(userTimezoneDateStr + "Z");
          scheduledTime = dateObj.getTime();
        }

        // Handle kind 6 reposts differently
        if (post.isKind6Repost) {
          // For kind 6 reposts, use the original file URL for display purposes
          let displayFileUrl = "";
          if (post.originalFileUrl && post.originalFileUrl.length > 0) {
            // Handle case where fileUrl might be a JSON string array
            if (
              typeof post.originalFileUrl === "string" &&
              post.originalFileUrl.startsWith("[")
            ) {
              try {
                const parsed = JSON.parse(post.originalFileUrl) as string[];
                if (Array.isArray(parsed) && parsed.length > 0) {
                  displayFileUrl = parsed[0] ?? "";
                }
              } catch (_e) {
                // If parsing fails, use as is
                displayFileUrl = post.originalFileUrl ?? "";
              }
            } else if (
              Array.isArray(post.originalFileUrl) &&
              post.originalFileUrl.length > 0
            ) {
              displayFileUrl = post.originalFileUrl[0] ?? "";
            } else {
              displayFileUrl = post.originalFileUrl as string;
            }
          }

          return {
            fileUrl: displayFileUrl, // Use original file URL for display
            scheduledFor: Math.floor(
              (post.scheduledFor
                ? new Date(post.scheduledFor).getTime()
                : Date.now()) / 1000
            ),
            caption: "", // No caption for kind 6 reposts
            queueType: post.queueType,
            isRecyclable: post.isRecyclable,
            originalPostId: post.originalPostId,
            originalEventId: post.originalEventId,
            originalEventPubkey: post.originalEventPubkey,
            events: {
              content: "", // Empty content for kind 6 reposts
              created_at: Math.floor(scheduledTime / 1000),
              kind: 6, // Kind 6 for reposts
              tags: [
                ["e", post.originalEventId ?? "", DEFAULT_RELAY_URL],
                ["p", post.originalEventPubkey ?? ""],
              ],
            },
          };
        } else if (post.isQuotePost) {
          // Handle quote posts (kind 1 with e and p tags)
          let quoteContent;
          let quoteTags;

          if (post.isLongformQuote) {
            // For longform quote posts, the caption already contains the naddr reference
            // Don't add an additional nevent reference
            quoteContent = [
              post.caption, // This already contains nostr:naddr1... for longform
              addTags.length > 10 ? "" : addTags, // Hide tags if longer than 10 characters
            ]
              .filter(Boolean)
              .join("\n");

            // For longform quotes, use 'a' tag instead of 'e' tag
            // Extract dTag from naddr if available
            let aTag = null;
            if (post.naddr) {
              try {
                const decoded = nip19.decode(post.naddr.replace("nostr:", ""));
                if (decoded.type === "naddr") {
                  const { identifier, pubkey, kind } = decoded.data;
                  aTag = [
                    "a",
                    `${kind}:${pubkey}:${identifier}`,
                    DEFAULT_RELAY_URL,
                    "mention",
                  ];
                }
              } catch (e) {
                logClientError(
                  e instanceof Error ? e : new Error(String(e)),
                  {
                    component: "useBulkPostEvents",
                    action: "decodeNaddr",
                    message: "Failed to decode naddr for longform quote",
                  },
                  "warning"
                );
              }
            }

            quoteTags = [
              ...tagArray, // Hashtag tags
              ...(aTag ? [aTag] : []), // 'a' tag for longform reference if available
              ["p", post.originalEventPubkey ?? "", "", "mention"], // Reference to quoted author
            ];
          } else {
            // Create nevent1 format for regular quoted events
            const neventEncoded = nip19.neventEncode({
              id: post.originalEventId ?? "",
              relays: [DEFAULT_RELAY_URL],
              author: post.originalEventPubkey,
            });

            // For regular quote posts, content should include caption + nevent + hashtags
            quoteContent = [
              post.caption,
              `nostr:${neventEncoded}`,
              addTags.length > 10 ? "" : addTags, // Hide tags if longer than 10 characters
            ]
              .filter(Boolean)
              .join("\n");

            // Include hashtag t tags plus e and p tags for quote posts
            quoteTags = [
              ...tagArray, // Hashtag tags
              ["e", post.originalEventId ?? "", DEFAULT_RELAY_URL, "mention"], // Reference to quoted event
              ["p", post.originalEventPubkey ?? "", "", "mention"], // Reference to quoted author
            ];
          }

          return {
            fileUrl,
            scheduledFor: Math.floor(scheduledTime / 1000),
            caption: post.caption,
            queueType: post.queueType,
            isRecyclable: post.isRecyclable,
            originalPostId: post.originalPostId,
            originalEventId: post.originalEventId,
            originalEventPubkey: post.originalEventPubkey,
            events: {
              content: quoteContent,
              created_at: Math.floor(scheduledTime / 1000),
              kind: 1, // Kind 1 for quote posts
              tags: quoteTags,
              isQuotePost: true, // Flag to identify quote posts
            },
          };
        } else {
          return {
            fileUrl,
            scheduledFor: Math.floor(scheduledTime / 1000),
            caption: post.caption,
            queueType: post.queueType,
            isRecyclable: post.isRecyclable,
            originalPostId: post.originalPostId,
            events: {
              content,
              created_at: Math.floor(scheduledTime / 1000),
              kind: 1,
              tags: tagArray,
            },
          };
        }
      })
    );

    setPreparedEvents(events);
    setShowConfirmation(true);

    // Reset loading state when events are processed successfully
    setIsPreviewSubmitting(false);
  }, [
    posts,
    useHashtagPresets,
    selectedHashtags,
    user,
    tags,
    fetcher.data,
    setPreparedEvents,
    setShowConfirmation,
    setIsPreviewSubmitting,
  ]);

  const prepareEvents = async (e: React.FormEvent) => {
    e.preventDefault();

    // Validate posts before proceeding
    const { isValid, errors } = validatePostsForPreview();
    if (!isValid) {
      // Show toast notification with validation errors
      const errorMessage =
        errors.length === 1
          ? (errors[0] ?? "Validation error")
          : `${errors.length} issues found:\n• ${errors.slice(0, 3).join("\n• ")}${errors.length > 3 ? "\n• And more..." : ""}`;

      setToast({
        type: "error",
        message: errorMessage,
      });

      // Hide toast after 5 seconds
      setTimeout(() => setToast(null), 5000);
      return;
    }

    // Set loading state for preview submission
    setIsPreviewSubmitting(true);

    try {
      // Check if this is a repost with existing URLs, kind 6 repost, or quote post
      const hasRepostData = posts.some((post) => post.isRepost && post.fileUrl);
      const hasKind6RepostData = posts.some((post) => post.isKind6Repost);
      const hasQuotePostData = posts.some((post) => post.isQuotePost);

      if (hasRepostData || hasKind6RepostData || hasQuotePostData) {
        // For reposts and quote posts, create fake upload response with existing URLs
        const fakeFileUrls = posts.map((post) => {
          let fileUrl = "";

          if (post.isKind6Repost) {
            // For kind 6 reposts, use the original file URL for display
            if (post.originalFileUrl && post.originalFileUrl.length > 0) {
              if (Array.isArray(post.originalFileUrl)) {
                fileUrl = post.originalFileUrl[0] ?? "";
              } else if (
                typeof post.originalFileUrl === "string" &&
                post.originalFileUrl.startsWith("[")
              ) {
                try {
                  const parsed: unknown = JSON.parse(post.originalFileUrl);
                  if (Array.isArray(parsed) && parsed.length > 0) {
                    fileUrl =
                      typeof (parsed as unknown[])[0] === "string"
                        ? ((parsed as string[])[0] ?? "")
                        : "";
                  }
                } catch (_e) {
                  // If parsing fails, use as is
                  fileUrl = post.originalFileUrl;
                }
              } else {
                fileUrl = post.originalFileUrl;
              }
            }
          } else {
            // For regular reposts and quote posts, use the fileUrl
            fileUrl = Array.isArray(post.fileUrl)
              ? typeof post.fileUrl[0] === "string"
                ? post.fileUrl[0]
                : ""
              : typeof post.fileUrl === "string"
                ? post.fileUrl
                : "";
          }

          return {
            fileUrl,
            scheduledFor: post.scheduledFor,
            queueType: post.queueType,
            isRecyclable: post.isRecyclable,
          };
        });

        // Simulate the fetcher response
        // Note: Direct assignment to fetcher.data is not recommended, but this is a workaround for repost flow
        (fetcher as { data?: unknown }).data = { fileUrls: fakeFileUrls };

        // Trigger the event creation manually
        const customEvent = new CustomEvent("repostEventsPrepared");
        document.dispatchEvent(customEvent);
      } else {
        // Use client-side upload system
        const filesToUpload = posts
          .map((post) => post.file)
          .filter((file) => file !== null);

        if (filesToUpload.length > 0) {
          try {
            // Upload all files using the new upload system
            const uploadResults = await uploadMultipleFiles(filesToUpload);

            // Check for failed uploads
            const failedUploads = uploadResults.filter(
              (result) => !result.success
            );
            if (failedUploads.length > 0) {
              const errorMessages = failedUploads
                .map((result) => result.error)
                .join(", ");
              throw new Error(`Upload failed: ${errorMessages}`);
            }

            // Map upload results back to posts (maintaining order)
            let uploadIndex = 0;
            const mappedResults = posts.map((post) => {
              if (post.file) {
                return uploadResults[uploadIndex++];
              }
              return { success: true, file: { url: "" } }; // Placeholder for posts without files
            });

            // Send results to server
            const formData = new FormData();
            formData.append("uploadResults", JSON.stringify(mappedResults));
            posts.forEach((post) => {
              formData.append("scheduledDates", post.scheduledFor);
              formData.append("queueTypes", post.queueType);
              formData.append("isRecyclable", post.isRecyclable.toString());
            });
            formData.append("_action", "_upload_images_preview");

            // Submit to server for processing
            isWaitingForUpload.current = true;
            fetcher.submit(formData, {
              method: "post",
            });
          } catch (error: unknown) {
            const { handleAsyncErrorWithMessage, getErrorMessage } =
              await import("~/lib/error-handler.client");
            const errorMessage = `Upload failed: ${getErrorMessage(error)}`;
            handleAsyncErrorWithMessage(
              error,
              errorMessage,
              {
                component: "useBulkPostEvents",
                action: "prepareEvents",
              },
              false // Don't show toast, we set toast state instead
            );
            setToast({
              type: "error",
              message: errorMessage,
            });
            setTimeout(() => setToast(null), 5000);
            setIsPreviewSubmitting(false);
            return;
          }
        } else {
          // No files to upload, just proceed with existing URLs (for reposts/quotes)
          const formData = new FormData();
          formData.append("uploadResults", JSON.stringify([])); // Empty results for no uploads
          posts.forEach((post) => {
            formData.append("scheduledDates", post.scheduledFor);
            formData.append("queueTypes", post.queueType);
            formData.append("isRecyclable", post.isRecyclable.toString());
          });
          formData.append("_action", "_upload_images_preview");

          // Submit to server for processing
          isWaitingForUpload.current = true;
          fetcher.submit(formData, {
            method: "post",
          });
        }
      }
    } catch (error: unknown) {
      const { handleAsyncErrorWithMessage } =
        await import("~/lib/error-handler.client");
      handleAsyncErrorWithMessage(
        error,
        "An error occurred while preparing posts. Please try again.",
        {
          component: "useBulkPostEvents",
          action: "prepareEvents",
        },
        false // Don't show toast, we set toast state instead
      );
      setToast({
        type: "error",
        message: "An error occurred while preparing posts. Please try again.",
      });

      // Hide toast after 5 seconds
      setTimeout(() => setToast(null), 5000);
      setIsPreviewSubmitting(false);
    }
  };

  // Add event listener for repost events
  useEffect(() => {
    const handleRepostEventsPrepared = () => {
      // Manually trigger the event creation logic
      const fetcherDataRaw = fetcher.data;
      const fetcherData =
        fetcherDataRaw &&
        typeof fetcherDataRaw === "object" &&
        !Array.isArray(fetcherDataRaw)
          ? (fetcherDataRaw as { fileUrls?: unknown })
          : null;
      if (
        fetcherData &&
        "fileUrls" in fetcherData &&
        Array.isArray(fetcherData.fileUrls)
      ) {
        void processEvents();
      }
    };

    document.addEventListener(
      "repostEventsPrepared",
      handleRepostEventsPrepared
    );

    return () => {
      document.removeEventListener(
        "repostEventsPrepared",
        handleRepostEventsPrepared
      );
    };
  }, [fetcher.data, processEvents]);

  // Watch for upload completion
  useEffect(() => {
    const fetcherDataRaw = fetcher.data;
    const fetcherData =
      fetcherDataRaw &&
      typeof fetcherDataRaw === "object" &&
      !Array.isArray(fetcherDataRaw)
        ? (fetcherDataRaw as { fileUrls?: unknown })
        : null;
    if (
      isWaitingForUpload.current &&
      fetcher.state === "idle" &&
      fetcherData &&
      "fileUrls" in fetcherData &&
      Array.isArray(fetcherData.fileUrls)
    ) {
      isWaitingForUpload.current = false;
      void processEvents();
    }
  }, [fetcher.state, fetcher.data, processEvents]);

  return { prepareEvents };
}

import { useEffect } from "react";

import { handleErrorSafely } from "~/lib/error-handler.client";

import { type BulkPost } from "./components/BulkPostCard";
interface RepostDataItem {
  fileUrl?: string | string[];
  caption?: string;
  queueType?: string;
  scheduledFor?: string;
  isRecyclable?: boolean;
  originalPostId?: string;
}

interface UseBulkPostsStateProps {
  mode: string | null;
  posts: BulkPost[];
  setPosts: (posts: BulkPost[]) => void;
}

export function useBulkPostsState({
  mode,
  posts: _posts,
  setPosts,
}: UseBulkPostsStateProps) {
  // Load repost data from sessionStorage if in recycle mode
  useEffect(() => {
    if (mode === "recycle") {
      const repostData = sessionStorage.getItem("repostData");
      if (repostData) {
        try {
          const parsed: unknown = JSON.parse(repostData);
          const parsedData = Array.isArray(parsed)
            ? (parsed as RepostDataItem[])
            : [];

          // Convert repost data to posts format with file objects from URLs
          const repostPosts = parsedData.map(
            (item: RepostDataItem, _index: number) => {
              let fileUrl = item.fileUrl;

              // Handle case where fileUrl might be a JSON string array
              if (typeof fileUrl === "string") {
                try {
                  const parsed = JSON.parse(fileUrl) as string[];
                  if (Array.isArray(parsed) && parsed.length > 0) {
                    fileUrl = parsed[0]; // Take first URL from array
                  }
                } catch (_e) {
                  // If it's not JSON, keep as is
                }
              } else if (Array.isArray(fileUrl) && fileUrl.length > 0) {
                fileUrl = fileUrl[0]; // Take first URL from array
              }

              return {
                file: null, // We'll handle URL-based files differently
                caption: item.caption ?? "",
                queueType: item.queueType ?? "unassigned",
                scheduledFor: item.scheduledFor ?? "",
                fileUrl: typeof fileUrl === "string" ? fileUrl : undefined, // Ensured to be a single URL string
                isRepost: true, // Flag to indicate this is a repost
                isRecyclable: item.isRecyclable ?? false,
                originalPostId: item.originalPostId, // Include original post ID for tracking
              };
            }
          );

          setPosts(repostPosts);

          // Clear sessionStorage after loading
          sessionStorage.removeItem("repostData");
        } catch (error) {
          handleErrorSafely(error, {
            component: "useBulkPostsState",
            action: "loadRepostData",
          });
        }
      }
    } else if (mode === "repost") {
      // Load scheduled repost data for kind 6 reposts
      const scheduledRepostData = sessionStorage.getItem("scheduledRepostData");
      if (scheduledRepostData) {
        try {
          const parsed: unknown = JSON.parse(scheduledRepostData);
          const parsedData = Array.isArray(parsed)
            ? (parsed as RepostDataItem[])
            : [];

          // We need to fetch the original posts to get their images
          const fetchOriginalPosts = async () => {
            try {
              const response = await fetch("/api/posts/batch", {
                method: "POST",
                headers: {
                  "Content-Type": "application/json",
                },
                body: JSON.stringify({
                  postIds: parsedData
                    .map((item: RepostDataItem) => item.originalPostId)
                    .filter(
                      (id: string | undefined): id is string => id !== undefined
                    ),
                }),
              });

              if (response.ok) {
                const dataRaw: unknown = await response.json();
                return Array.isArray(dataRaw)
                  ? (dataRaw as OriginalPost[])
                  : [];
              }
            } catch (error) {
              handleErrorSafely(error, {
                component: "useBulkPostsState",
                action: "fetchOriginalPosts",
              });
            }
            return [];
          };

          interface ScheduledRepostDataItem {
            caption?: string;
            queueType?: string;
            scheduledFor?: string;
            originalPostId?: string;
            originalEventId?: string;
            originalEventPubkey?: string;
            isRecyclable?: boolean;
          }
          interface OriginalPost {
            id: string;
            fileUrl?: string | string[];
            caption?: string;
          }
          // Fetch original posts and merge with repost data
          void (async () => {
            try {
              const originalPosts = await fetchOriginalPosts();
              const repostPosts = parsedData.map(
                (item: ScheduledRepostDataItem) => {
                  const originalPost = originalPosts.find(
                    (p: OriginalPost) => p.id === item.originalPostId
                  );

                  const originalFileUrl = originalPost?.fileUrl;
                  const fileUrlString = Array.isArray(originalFileUrl)
                    ? originalFileUrl.length > 0
                      ? originalFileUrl[0]
                      : undefined
                    : originalFileUrl;

                  return {
                    file: null, // No file for kind 6 reposts
                    caption: item.caption ?? "", // Empty for kind 6
                    queueType: item.queueType ?? "unassigned",
                    scheduledFor: item.scheduledFor ?? "",
                    fileUrl: fileUrlString, // Use original post's images for display (single string)
                    originalFileUrl: originalFileUrl ?? [], // Keep original file URLs for display (can be array)
                    isKind6Repost: true, // Flag to indicate this is a kind 6 repost
                    originalPostId: item.originalPostId,
                    originalEventId: item.originalEventId,
                    originalEventPubkey: item.originalEventPubkey,
                    originalCaption: originalPost?.caption ?? "", // Store original caption for context
                    isRecyclable: item.isRecyclable ?? false,
                  };
                }
              );

              setPosts(repostPosts);
            } catch (error) {
              handleErrorSafely(error, {
                component: "useBulkPostsState",
                action: "fetchOriginalPosts",
              });
            }
          })();

          // Clear sessionStorage after loading
          sessionStorage.removeItem("scheduledRepostData");
        } catch (error) {
          handleErrorSafely(error, {
            component: "useBulkPostsState",
            action: "loadScheduledRepostData",
          });
        }
      }
    } else if (mode === "quote") {
      // Load quote post data
      const quotePostData = sessionStorage.getItem("quotePostData");
      if (quotePostData) {
        try {
          const parsed: unknown = JSON.parse(quotePostData);
          const parsedData = Array.isArray(parsed)
            ? (parsed as QuotePostDataItem[])
            : [];

          interface QuotePostDataItem {
            fileUrl?: string | string[];
            caption?: string;
            queueType?: string;
            scheduledFor?: string;
            isQuotePost?: boolean;
            isLongformQuote?: boolean;
            naddr?: string;
            originalPostId?: string;
            originalEventId?: string;
            originalEventPubkey?: string;
            originalCaption?: string;
            originalTitle?: string;
            isRecyclable?: boolean;
          }
          // Convert quote post data to posts format
          const quotePosts = parsedData.map((item: QuotePostDataItem) => {
            let fileUrl = item.fileUrl;

            // Handle case where fileUrl might be a JSON string array
            if (typeof fileUrl === "string") {
              try {
                const parsed = JSON.parse(fileUrl) as string[];
                if (Array.isArray(parsed) && parsed.length > 0) {
                  fileUrl = parsed[0]; // Take first URL from array
                }
              } catch (_e) {
                // If it's not JSON, keep as is
              }
            } else if (Array.isArray(fileUrl) && fileUrl.length > 0) {
              fileUrl = fileUrl[0]; // Take first URL from array
            }

            return {
              file: null, // We'll handle URL-based files differently
              caption: item.caption ?? "", // Start with empty caption for user to add content
              queueType: item.queueType ?? "unassigned",
              scheduledFor: item.scheduledFor ?? "",
              fileUrl: typeof fileUrl === "string" ? fileUrl : undefined, // Ensured to be a single URL string
              isQuotePost: true, // Flag to indicate this is a quote post
              isLongformQuote: item.isLongformQuote ?? false, // Preserve longform quote flag
              naddr: item.naddr ?? "", // Preserve naddr for longform quotes
              originalPostId: item.originalPostId,
              originalEventId: item.originalEventId,
              originalEventPubkey: item.originalEventPubkey,
              originalCaption: item.originalCaption ?? "",
              originalTitle: item.originalTitle ?? "", // Preserve original title for longform
              isRecyclable: item.isRecyclable ?? false,
            };
          });

          setPosts(quotePosts);

          // Clear sessionStorage after loading
          sessionStorage.removeItem("quotePostData");
        } catch (error) {
          handleErrorSafely(error, {
            component: "useBulkPostsState",
            action: "loadQuotePostData",
          });
        }
      }
    }
  }, [mode, setPosts]);
}

import { useState, useEffect, useRef, useCallback } from "react";

import { logClientError } from "~/lib/error-handler.client";

import type { EditorJSInstance, EditorJSAPI } from "./types/editorjs.types";
import {
  disableCaptions,
  setupCaptionObserver,
} from "./utils/editorjs-captions";
import { createEditorJSToolsConfig } from "./utils/editorjs-config";
import {
  loadEditorJSContent,
  insertAssetsIntoEditor,
  generateSummaryFromContent as generateSummary,
} from "./utils/editorjs-content";
import { setupCustomDragDrop } from "./utils/editorjs-dragdrop";

interface UseLongFormEditorOptions {
  uploadProvider: string | null;
  initialContent?: string;
  onContentChange: (content: string) => void;
}

export function useLongFormEditor({
  uploadProvider,
  initialContent: _initialContent,
  onContentChange,
}: UseLongFormEditorOptions) {
  const editorRef = useRef<EditorJSInstance | null>(null);
  const editorInitialized = useRef(false);
  const [editorReady, setEditorReady] = useState(false);
  const isMountedRef = useRef(true);

  // Helper function to safely check if component is mounted
  // This function makes the ref check explicit to TypeScript
  const isMounted = useCallback((): boolean => {
    return isMountedRef.current === true;
  }, []);

  // Helper to safely execute a callback only if mounted
  const safeExecute = useCallback(
    // eslint-disable-next-line promise/prefer-await-to-callbacks -- Synchronous helper function, not a promise callback
    <T,>(callback: () => T): T | undefined => {
      if (isMountedRef.current) {
        // eslint-disable-next-line promise/prefer-await-to-callbacks -- Synchronous helper function, not a promise callback
        return callback();
      }
      return undefined;
    },
    []
  );

  // Disable captions function
  const disableCaptionsFn = useCallback(() => {
    disableCaptions();
  }, []);

  // Main editor initialization effect
  useEffect(() => {
    // Mark component as mounted
    isMountedRef.current = true;

    const loadEditor = async () => {
      // Prevent multiple initializations more aggressively
      if (
        typeof window !== "undefined" &&
        !editorRef.current &&
        !editorInitialized.current &&
        isMounted()
      ) {
        editorInitialized.current = true;

        // Check if editor is already initialized in DOM
        const existingEditor = document.getElementById("editorjs");
        if (existingEditor) {
          // If there's already EditorJS content, don't reinitialize
          const hasEditorContent =
            existingEditor.querySelector(".codex-editor") ??
            existingEditor.querySelector(".ce-block") ??
            existingEditor.innerHTML.trim().length > 0;

          if (hasEditorContent) {
            logClientError(
              "EditorJS already initialized, skipping...",
              {
                component: "useLongFormEditor",
                action: "loadEditor",
              },
              "info"
            );
            editorInitialized.current = false; // Reset flag so it can try again if needed
            return;
          }

          existingEditor.innerHTML = "";

          // Remove any existing EditorJS classes that might interfere
          existingEditor.className = existingEditor.className
            .split(" ")
            .filter((cls) => !cls.startsWith("codex-editor"))
            .join(" ");
        }

        // Also check for any existing editor instances globally
        if (window.EditorJSInstances) {
          window.EditorJSInstances.forEach((instance) => {
            try {
              instance.destroy();
            } catch (_e) {
              /* ignore cleanup errors */
            }
          });
          window.EditorJSInstances = [];
        } else {
          window.EditorJSInstances = [];
        }

        const EditorJS = (await import("@editorjs/editorjs")).default;

        // Add a small delay to ensure DOM is fully ready
        await new Promise((resolve) => setTimeout(resolve, 100));

        // Check if component is still mounted and element exists before creating editor
        if (!isMounted()) {
          editorInitialized.current = false;
          return;
        }

        const editorElement = document.getElementById("editorjs");
        if (!editorElement) {
          editorInitialized.current = false;
          return;
        }

        // Create tools configuration
        const tools = await createEditorJSToolsConfig(uploadProvider);

        // Double-check component is still mounted before creating editor instance
        if (!isMounted()) {
          editorInitialized.current = false;
          return;
        }

        let editorInstance: EditorJSInstance;
        try {
          editorInstance = new EditorJS({
            holder: "editorjs",
            minHeight: 300,
            // @ts-expect-error - EditorJS types don't match exactly but work at runtime
            tools: tools,
            data: undefined, // Initial data will be loaded separately
            // @ts-expect-error - EditorJS onChange signature doesn't match types but works at runtime
            // eslint-disable-next-line @typescript-eslint/no-misused-promises -- EditorJS onChange is async but types don't reflect this
            onChange: async (api: EditorJSAPI) => {
              // Check if component is still mounted and editor element exists
              if (!isMounted()) {
                return;
              }

              const editorElement = document.getElementById("editorjs");
              if (!editorElement) {
                return;
              }

              try {
                const outputData = await api.saver.save();
                // Double-check component is still mounted before calling callback
                safeExecute(() => {
                  onContentChange(JSON.stringify(outputData));
                });
              } catch (error) {
                // Only log errors if component is still mounted
                safeExecute(() => {
                  void (async () => {
                    const { handleErrorSafely } =
                      await import("~/lib/error-handler.client");
                    handleErrorSafely(error, {
                      component: "useLongFormEditor",
                      action: "onChange",
                    });
                  })();
                });
              }
            },
          }) as EditorJSInstance;
        } catch (error) {
          // If editor creation fails, reset flag and return
          editorInitialized.current = false;
          safeExecute(() => {
            logClientError(
              error instanceof Error ? error : new Error(String(error)),
              {
                component: "useLongFormEditor",
                action: "createEditor",
                message: "Failed to create EditorJS instance",
              },
              "warning"
            );
          });
          return;
        }

        // Store the editor reference and add to global tracking
        editorRef.current = editorInstance;
        window.EditorJSInstances.push(editorInstance);

        // Initialize custom drag and drop functionality after editor is ready
        void (async () => {
          try {
            if (!editorRef.current || !isMounted()) return;

            // Check if element still exists before waiting for isReady
            const editorElement = document.getElementById("editorjs");
            if (!editorElement || !isMounted()) return;

            await editorRef.current.isReady;

            // Check again after isReady resolves
            // eslint-disable-next-line @typescript-eslint/no-unnecessary-condition -- Runtime safety check: ref value can change between async operations
            if (!editorRef.current || !isMounted()) return;

            const editorElementAfterReady = document.getElementById("editorjs");
            if (!editorElementAfterReady || !isMounted()) return;

            const dragObserver = setupCustomDragDrop(
              editorRef as unknown as React.RefObject<EditorJSInstance>,
              editorElementAfterReady,
              onContentChange,
              disableCaptionsFn
            );
            editorRef.current._dragObserver = dragObserver;

            safeExecute(() => {
              setEditorReady(true);
            });
          } catch (error) {
            // Only log if component is still mounted
            safeExecute(() => {
              logClientError(
                error instanceof Error ? error : new Error(String(error)),
                {
                  component: "useLongFormEditor",
                  action: "initializeDragDrop",
                },
                "warning"
              );
            });
          }
        })();

        // Run caption disabling immediately and on editor changes
        // Only if component is still mounted
        safeExecute(() => {
          setTimeout(() => {
            if (isMounted()) {
              disableCaptionsFn();
            }
          }, 100);
        });

        // Set up a mutation observer to remove captions whenever they appear
        // Only if component is still mounted
        safeExecute(() => {
          const editorElement = document.getElementById("editorjs");
          if (editorElement && editorRef.current) {
            const captionObserver = setupCaptionObserver(
              editorElement,
              disableCaptionsFn
            );
            editorRef.current._captionObserver = captionObserver;
          }
        });
      }
    };

    void loadEditor();

    return () => {
      // Mark component as unmounted to prevent onChange callbacks
      isMountedRef.current = false;

      if (editorRef.current) {
        try {
          // Clean up mutation observers
          if (editorRef.current._captionObserver) {
            editorRef.current._captionObserver.disconnect();
          }
          if (editorRef.current._dragObserver) {
            editorRef.current._dragObserver.disconnect();
          }

          // Destroy the editor instance
          // eslint-disable-next-line @typescript-eslint/no-unnecessary-condition -- Runtime safety: destroy method exists but TypeScript types may not reflect it
          if (editorRef.current.destroy) {
            editorRef.current.destroy();
          }
        } catch (error) {
          logClientError(
            error instanceof Error ? error : new Error(String(error)),
            {
              component: "useLongFormEditor",
              action: "cleanup",
              message: "Error during editor cleanup",
            },
            "warning"
          );
        } finally {
          editorRef.current = null;
          editorInitialized.current = false;
          setEditorReady(false);

          // Remove from global tracking
          if (window.EditorJSInstances) {
            window.EditorJSInstances = window.EditorJSInstances.filter(
              (instance) => instance !== editorRef.current
            );
          }

          // Also clear the DOM container to prevent issues
          const editorContainer = document.getElementById("editorjs");
          if (editorContainer) {
            editorContainer.innerHTML = "";

            // Remove any EditorJS classes
            editorContainer.className = editorContainer.className
              .split(" ")
              .filter((cls) => !cls.startsWith("codex-editor"))
              .join(" ");
          }
        }
      }
    };
  }, [uploadProvider, onContentChange, disableCaptionsFn, isMounted, safeExecute]);

  // Load initial content when editor is ready
  const loadInitialData = useCallback(
    async (content: string) => {
      if (editorReady && editorRef.current && content) {
        await loadEditorJSContent(
          editorRef as unknown as React.RefObject<EditorJSInstance>,
          content,
          onContentChange
        );
      }
    },
    [editorReady, onContentChange]
  );

  // Insert assets into the editor
  const insertAssetIntoEditor = useCallback(
    async (
      selectedAssets: Array<{
        assetType: string;
        fileUrl?: string;
        content?: string;
        title?: string;
      }>
    ) => {
      await insertAssetsIntoEditor(
        editorRef as unknown as React.RefObject<EditorJSInstance>,
        selectedAssets,
        onContentChange
      );
    },
    [onContentChange]
  );

  // Generate summary from editor content
  const generateSummaryFromContent = useCallback((content: string) => {
    return generateSummary(content);
  }, []);

  return {
    editorRef,
    editorReady,
    loadInitialData,
    insertAssetIntoEditor,
    generateSummaryFromContent,
  };
}

/**
 * Client-side submit handler logic for editing posts
 * Extracted from EditPostModal for better separation of concerns
 */

import { uploadMultipleFiles } from "~/features/upload/upload.client";
import { nostrAdapter } from "~/lib/nostr-adapter.client";

import type { PostData, LongFormPostData, UserData } from "../types";

interface EditPostSubmitParams {
  post: PostData | LongFormPostData;
  isLongform: boolean;
  caption?: string;
  title?: string;
  summary?: string;
  content?: string;
  image?: string;
  existingImages: string[];
  newFiles: File[];
  selectedHashtagPresetTags: string;
  manualHashtags: string;
  useHashtagPresets: boolean;
  selectedQueueType: string;
  selectedHashtagPresetId: string | null;
  scheduledFor: Date | null;
  user?: UserData;
}

export async function prepareEditPostSubmission({
  post,
  isLongform,
  caption,
  title,
  summary,
  content,
  image,
  existingImages,
  newFiles,
  selectedHashtagPresetTags,
  manualHashtags,
  useHashtagPresets,
  selectedQueueType,
  selectedHashtagPresetId,
  scheduledFor,
  user,
}: EditPostSubmitParams) {
  // Handle image uploads first if there are new files
  const allImageUrls = [...existingImages];
  if (newFiles.length > 0) {
    const uploadResults = await uploadMultipleFiles(newFiles);
    const failedUploads = uploadResults.filter((result) => !result.success);
    if (failedUploads.length > 0) {
      throw new Error(
        `Upload failed: ${failedUploads.map((r) => r.error).join(", ")}`,
      );
    }
    const newUrls = uploadResults
      .filter((result) => result.success && result.file)
      .map((result) => result.file!.url);
    allImageUrls.push(...newUrls);
  }

  let eventContent = "";
  let eventTags: string[][] = [];
  let finalHashtags = "";

  if (isLongform) {
    // Create longform event content (NIP-23)
    eventContent = content ?? "";
    eventTags = [
      ["d", post.id], // identifier tag
      ["title", title ?? ""],
      ["summary", summary ?? ""],
    ];
    if (image) {
      eventTags.push(["image", image]);
    }
  } else {
    // Determine final hashtags to use
    if (useHashtagPresets && selectedHashtagPresetTags) {
      finalHashtags = selectedHashtagPresetTags;
    } else {
      finalHashtags = manualHashtags;
    }

    // Create post content with images below text
    eventContent = caption ?? "";

    // Add image URLs to content (below the text)
    if (allImageUrls.length > 0) {
      const imageContent = allImageUrls.join("\n");
      eventContent = eventContent
        ? `${eventContent}\n\n${imageContent}`
        : imageContent;
    }

    // Add hashtags if applicable and user setting is enabled
    if (user?.showHashTagsinPosts && finalHashtags) {
      eventContent = `${eventContent}\n${finalHashtags}`;
    }

    // Parse hashtags and add as 't' tags
    if (finalHashtags) {
      const hashtagList = finalHashtags
        .split(/\s+/)
        .filter((tag) => tag.startsWith("#") && tag.length > 1);
      hashtagList.forEach((tag) => {
        eventTags.push(["t", tag.replace("#", "")]);
      });
    }
  }

  const eventKind = isLongform ? 30023 : 1;
  const eventTime = scheduledFor
    ? Math.floor(scheduledFor.getTime() / 1000)
    : Math.floor(Date.now() / 1000);

  // Re-sign the event with new content
  const { nostrEvent, signedEvent } = await nostrAdapter.signEvent({
    content: eventContent,
    created_at: eventTime,
    kind: eventKind,
    tags: eventTags,
  });

  // Build form data
  const formData = new FormData();
  formData.append("_action", isLongform ? "editLongform" : "editPost");
  formData.append("postId", post.id);
  formData.append("signedEvent", JSON.stringify(signedEvent));
  formData.append("nostrEvent", JSON.stringify(nostrEvent));

  if (scheduledFor) {
    formData.append(
      "scheduledFor",
      Math.floor(scheduledFor.getTime() / 1000).toString(),
    );
  }

  if (isLongform) {
    formData.append("title", title ?? "");
    formData.append("summary", summary ?? "");
    formData.append("content", content ?? "");
    formData.append("image", image ?? "");
  } else {
    formData.append("caption", caption ?? "");
    formData.append("fileUrl", JSON.stringify(allImageUrls));
    formData.append("hashtags", finalHashtags);
    if (selectedQueueType) {
      formData.append("queueTypeId", selectedQueueType);
    }
    if (useHashtagPresets && selectedHashtagPresetId) {
      formData.append("hashTagPresetId", selectedHashtagPresetId);
    }
  }

  return formData;
}

/**
 * EditorJS content loading and manipulation utilities
 */

import type React from "react";

import { handleErrorSafely, logClientError } from "~/lib/error-handler.client";

import type { EditorJSInstance, EditorJSBlock } from "../types/editorjs.types";

import { convertMarkdownToEditorJS } from "./editorjs-conversion";

/**
 * Load initial content into EditorJS
 */
export async function loadEditorJSContent(
  editorRef: React.RefObject<EditorJSInstance>,
  content: string,
  onContentChange: (content: string) => void
) {
  // eslint-disable-next-line @typescript-eslint/no-unnecessary-condition -- Runtime safety check: ref value can change between async operations
  if (!editorRef.current) return;

  try {
    await editorRef.current.isReady;

    let parsedContent;

    // Try to parse as JSON first (for legacy EditorJS format)
    if (content.trim().startsWith("{")) {
      try {
        parsedContent = JSON.parse(content) as {
          blocks?: unknown[];
          time?: number;
          version?: string;
        };
        // Validate it has EditorJS structure
        if (!parsedContent.blocks || !Array.isArray(parsedContent.blocks)) {
          throw new Error("Not valid EditorJS format");
        }
      } catch (jsonError) {
        logClientError(
          jsonError instanceof Error ? jsonError : new Error(String(jsonError)),
          {
            component: "loadEditorJSContent",
            action: "parseContent",
            message: "Content is not valid EditorJS JSON, treating as markdown",
          },
          "warning"
        );
        // If JSON parsing fails, treat as markdown and convert to EditorJS
        parsedContent = convertMarkdownToEditorJS(content);
      }
    } else {
      // Content is in markdown format, convert to EditorJS
      logClientError(
        "Converting markdown content to EditorJS format",
        {
          component: "loadEditorJSContent",
          action: "convertMarkdown",
        },
        "info"
      );
      parsedContent = convertMarkdownToEditorJS(content);
    }

    await editorRef.current.render({
      blocks: (parsedContent.blocks ?? []) as EditorJSBlock[],
      time: parsedContent.time,
      version: parsedContent.version,
    });
    onContentChange(JSON.stringify(parsedContent));
  } catch (error) {
    const { handleAsyncError } = await import("~/lib/error-handler.client");
    handleAsyncError(
      error,
      {
        component: "useLongFormEditor",
        action: "loadInitialData",
      },
      false
    );
    // Fallback to empty editor if all else fails
    try {
      const emptyContent = { blocks: [] };
      await editorRef.current.render(emptyContent);
      onContentChange(JSON.stringify(emptyContent));
    } catch (fallbackError) {
      const { handleAsyncError: handleFallbackError } =
        await import("~/lib/error-handler.client");
      handleFallbackError(
        fallbackError,
        {
          component: "useLongFormEditor",
          action: "loadInitialDataFallback",
        },
        false
      );
    }
  }
}

/**
 * Insert assets into the editor
 */
export async function insertAssetsIntoEditor(
  editorRef: React.RefObject<EditorJSInstance>,
  selectedAssets: Array<{
    assetType: string;
    fileUrl?: string;
    content?: string;
    title?: string;
  }>,
  onContentChange: (content: string) => void
) {
  // eslint-disable-next-line @typescript-eslint/no-unnecessary-condition -- Runtime safety check: ref value can change between async operations
  if (!editorRef.current) return;

  try {
    // Wait for editor to be ready
    await editorRef.current.isReady;

    // Get current editor data and insert at current block position
    const currentData = await editorRef.current.saver.save();
    const blocks = [...currentData.blocks];

    // Try to get current block index
    let insertIndex = blocks.length; // Default to end
    try {
      const currentBlockIndex = editorRef.current.blocks.getCurrentBlockIndex();
      if (currentBlockIndex >= 0) {
        insertIndex = currentBlockIndex + 1; // Insert after current block
      }
    } catch (error) {
      logClientError(
        "Using default insertion position at end",
        {
          component: "insertAssetsIntoEditor",
          action: "getCurrentBlockIndex",
          error: error instanceof Error ? error.message : String(error),
        },
        "info"
      );
    }

    // Create new blocks for assets
    const newBlocks: EditorJSBlock[] = [];
    for (const asset of selectedAssets) {
      if (asset.assetType === "TEXT") {
        const textContent = asset.content ?? asset.title ?? "";
        if (textContent) {
          newBlocks.push({
            id: Math.random().toString(36).substr(2, 9),
            type: "paragraph",
            data: {
              text: textContent,
            },
          });
        }
      } else if (asset.assetType === "IMAGE") {
        newBlocks.push({
          id: Math.random().toString(36).substr(2, 9),
          type: "image",
          data: {
            file: {
              url: asset.fileUrl,
            },
            caption: "",
            withBorder: false,
            withBackground: false,
            stretched: false,
          },
        });
      }
    }

    // Insert new blocks at the determined position
    blocks.splice(insertIndex, 0, ...newBlocks);

    // Render the updated data
    const updatedData = {
      ...currentData,
      blocks: blocks,
    };

    await editorRef.current.render(updatedData);
    onContentChange(JSON.stringify(updatedData));

    // Focus editor
    setTimeout(() => {
      editorRef.current.focus();
    }, 100);
  } catch (error) {
    const { handleAsyncError } = await import("~/lib/error-handler.client");
    handleAsyncError(
      error,
      {
        component: "useLongFormEditor",
        action: "insertAssetIntoEditor",
      },
      false
    );
    // Fallback to simple insertion
    try {
      for (const asset of selectedAssets) {
        if (asset.assetType === "TEXT") {
          const textContent = asset.content ?? asset.title ?? "";
          if (textContent) {
            editorRef.current.blocks.insert("paragraph", {
              text: textContent,
            });
          }
        } else if (asset.assetType === "IMAGE") {
          editorRef.current.blocks.insert("image", {
            file: {
              url: asset.fileUrl,
            },
            caption: "",
            withBorder: false,
            withBackground: false,
            stretched: false,
          });
        }
      }
      const saveResult = editorRef.current.saver.save();
      const isPromise =
        typeof saveResult === "object" &&
        "then" in saveResult &&
        typeof (saveResult as { then?: unknown }).then === "function";
      const updatedData = isPromise
        ? await (saveResult as Promise<unknown>)
        : (saveResult as unknown);
      onContentChange(JSON.stringify(updatedData));
    } catch (fallbackError) {
      const { handleAsyncError: handleFallbackError } =
        await import("~/lib/error-handler.client");
      handleFallbackError(
        fallbackError,
        {
          component: "useLongFormEditor",
          action: "insertAssetIntoEditorFallback",
        },
        false
      );
    }
  }
}

/**
 * Generate summary from editor content
 */
export function generateSummaryFromContent(content: string): string {
  if (!content) return "";

  try {
    const parsed: unknown = JSON.parse(content);
    const editorData =
      parsed && typeof parsed === "object" && !Array.isArray(parsed)
        ? (parsed as { blocks?: EditorJSBlock[] })
        : { blocks: [] };
    let textContent = "";

    if (Array.isArray(editorData.blocks)) {
      editorData.blocks.forEach((block: EditorJSBlock) => {
        if (block.type === "paragraph" || block.type === "header") {
          const textValue =
            typeof block.data === "object" &&
            "text" in block.data &&
            typeof (block.data as { text?: unknown }).text === "string"
              ? (block.data as { text: string }).text
              : "";
          textContent += textValue + " ";
        } else if (block.type === "list") {
          if (Array.isArray(block.data["items"])) {
            block.data["items"].forEach((item: string) => {
              textContent += item + " ";
            });
          }
        }
      });
    }

    const plainText = textContent.replace(/<[^>]*>/g, "").trim();
    return plainText.length > 280
      ? plainText.substring(0, 280) + "..."
      : plainText;
  } catch (error) {
    handleErrorSafely(error, {
      component: "useLongFormEditor",
      action: "generateSummaryFromContent",
    });
    return "";
  }
}

/**
 * EditorJS conversion utilities
 * Converts between EditorJS format and Markdown
 */

import type { EditorJSBlock, EditorJSOutput } from "../types/editorjs.types";

function generateBlockId(): string {
  return Math.random().toString(36).substr(2, 9);
}

/**
 * Generate article identifier from title (for NIP-23 long-form posts)
 */
export function generateArticleIdentifier(title: string): string {
  return title
    .toLowerCase()
    .replace(/[^a-z0-9\s-]/g, "")
    .replace(/\s+/g, "-")
    .replace(/-+/g, "-")
    .trim()
    .substring(0, 64);
}

export function convertEditorJSToMarkdown(
  editorData: EditorJSOutput | string | null | undefined
): string {
  // Handle string input (JSON string)
  let parsedData: EditorJSOutput | null = null;
  if (typeof editorData === "string") {
    try {
      parsedData = JSON.parse(editorData) as EditorJSOutput;
    } catch {
      return "";
    }
  } else if (editorData && typeof editorData === "object") {
    parsedData = editorData;
  }

  if (!parsedData?.blocks || !Array.isArray(parsedData.blocks)) {
    return "";
  }

  let markdown = "";

  parsedData.blocks.forEach((block: EditorJSBlock) => {
    const data = block.data;

    switch (block.type) {
      case "header": {
        const level = "#".repeat(
          typeof data["level"] === "number" ? data["level"] : 1
        );
        const text = typeof data["text"] === "string" ? data["text"] : "";
        markdown += `${level} ${text}\n\n`;
        break;
      }

      case "paragraph": {
        const text = typeof data["text"] === "string" ? data["text"] : "";
        markdown += `${text}\n\n`;
        break;
      }

      case "list": {
        const style = data["style"];
        const items = Array.isArray(data["items"]) ? data["items"] : [];
        if (style === "ordered") {
          items.forEach((item: unknown, index: number) => {
            const itemText = typeof item === "string" ? item : String(item);
            markdown += `${index + 1}. ${itemText}\n`;
          });
        } else {
          items.forEach((item: unknown) => {
            const itemText = typeof item === "string" ? item : String(item);
            markdown += `- ${itemText}\n`;
          });
        }
        markdown += "\n";
        break;
      }

      case "quote": {
        const text = typeof data["text"] === "string" ? data["text"] : "";
        markdown += `> ${text}\n`;
        if (data["caption"] && typeof data["caption"] === "string") {
          markdown += `> \n> — ${data["caption"]}\n`;
        }
        markdown += "\n";
        break;
      }

      case "code": {
        const code = typeof data["code"] === "string" ? data["code"] : "";
        markdown += "```\n";
        markdown += code;
        markdown += "\n```\n\n";
        break;
      }

      case "linkTool": {
        const link = typeof data["link"] === "string" ? data["link"] : "";
        const meta =
          data["meta"] && typeof data["meta"] === "object"
            ? (data["meta"] as Record<string, unknown>)
            : {};
        const title = typeof meta["title"] === "string" ? meta["title"] : null;
        if (title) {
          markdown += `[${title}](${link})\n\n`;
        } else {
          markdown += `${link}\n\n`;
        }
        break;
      }

      case "embed": {
        const service =
          typeof data["service"] === "string" ? data["service"] : "";
        const source = typeof data["source"] === "string" ? data["source"] : "";
        if (service === "youtube") {
          markdown += `[![YouTube Video](https://img.youtube.com/vi/${source}/0.jpg)](${source})\n\n`;
        } else {
          markdown += `${source}\n\n`;
        }
        break;
      }

      case "image": {
        const file =
          data["file"] && typeof data["file"] === "object"
            ? (data["file"] as Record<string, unknown>)
            : null;
        const fileUrl =
          file && typeof file["url"] === "string" ? file["url"] : null;
        const url = typeof data["url"] === "string" ? data["url"] : null;
        const imageUrl = fileUrl ?? url;
        const caption =
          typeof data["caption"] === "string" ? data["caption"] : "";
        if (imageUrl) {
          if (caption.trim()) {
            markdown += `![${caption}](${imageUrl})\n\n`;
          } else {
            markdown += `![](${imageUrl})\n\n`;
          }
        }
        break;
      }

      default: {
        const text = typeof data["text"] === "string" ? data["text"] : null;
        if (text) {
          markdown += `${text}\n\n`;
        }
        break;
      }
    }
  });

  return markdown.trim();
}

export function convertMarkdownToEditorJS(markdown: string): EditorJSOutput {
  if (!markdown || markdown.trim() === "") {
    return { blocks: [] };
  }

  const blocks: EditorJSBlock[] = [];
  const lines = markdown.split("\n");
  let i = 0;

  while (i < lines.length) {
    const currentLine = lines[i];
    if (currentLine === undefined) break;
    const line = currentLine.trim();

    if (line === "") {
      i++;
      continue;
    }

    // Headers
    if (line.startsWith("#")) {
      const match = line.match(/^#+/);
      const level = match?.[0]?.length ?? 1;
      const text = line.replace(/^#+\s*/, "");
      blocks.push({
        id: generateBlockId(),
        type: "header",
        data: {
          text: text,
          level: Math.min(Math.max(level, 1), 6),
        },
      });
    }
    // Images
    else if (line.match(/^!\[([^\]]*)\]\(([^)]+)\)$/)) {
      const match = line.match(/^!\[([^\]]*)\]\(([^)]+)\)$/);
      if (match) {
        const caption = match[1];
        const url = match[2];
        if (caption !== undefined && url !== undefined) {
          blocks.push({
            id: generateBlockId(),
            type: "image",
            data: {
              file: {
                url: url,
              },
              caption: caption,
              withBorder: false,
              withBackground: false,
              stretched: false,
            },
          });
        }
      }
    }
    // Blockquotes
    else if (line.startsWith("> ")) {
      let quoteText = "";
      let caption = "";

      // Collect all consecutive quote lines
      while (i < lines.length) {
        const currentLine = lines[i];
        if (currentLine === undefined) break;
        if (!currentLine.trim().startsWith("> ")) break;
        const quoteLine = currentLine.trim().substring(2);
        if (quoteLine.startsWith("— ")) {
          caption = quoteLine.substring(2);
        } else if (quoteLine !== "") {
          if (quoteText) quoteText += " ";
          quoteText += quoteLine;
        }
        i++;
      }
      i--; // Adjust for the loop increment

      blocks.push({
        id: generateBlockId(),
        type: "quote",
        data: {
          text: quoteText,
          caption: caption,
        },
      });
    }
    // Code blocks
    else if (line === "```") {
      let code = "";
      i++; // Skip the opening ```

      while (i < lines.length) {
        const currentLine = lines[i];
        if (currentLine === undefined) break;
        if (currentLine.trim() === "```") break;
        if (code) code += "\n";
        code += currentLine;
        i++;
      }

      blocks.push({
        id: generateBlockId(),
        type: "code",
        data: {
          code: code,
        },
      });
    }
    // Ordered lists
    else if (line.match(/^\d+\.\s/)) {
      const items: string[] = [];

      while (i < lines.length) {
        const currentLine = lines[i];
        if (currentLine === undefined) break;
        if (!currentLine.trim().match(/^\d+\.\s/)) break;
        const item = currentLine.trim().replace(/^\d+\.\s/, "");
        items.push(item);
        i++;
      }
      i--; // Adjust for the loop increment

      blocks.push({
        id: generateBlockId(),
        type: "list",
        data: {
          style: "ordered",
          items: items,
        },
      });
    }
    // Unordered lists
    else if (line.startsWith("- ")) {
      const items: string[] = [];

      while (i < lines.length) {
        const currentLine = lines[i];
        if (currentLine === undefined) break;
        if (!currentLine.trim().startsWith("- ")) break;
        const item = currentLine.trim().substring(2);
        items.push(item);
        i++;
      }
      i--; // Adjust for the loop increment

      blocks.push({
        id: generateBlockId(),
        type: "list",
        data: {
          style: "unordered",
          items: items,
        },
      });
    }
    // Links (simple detection)
    else if (line.match(/^\[([^\]]+)\]\(([^)]+)\)$/)) {
      const match = line.match(/^\[([^\]]+)\]\(([^)]+)\)$/);
      if (match) {
        const title = match[1];
        const url = match[2];
        if (title !== undefined && url !== undefined) {
          blocks.push({
            id: generateBlockId(),
            type: "linkTool",
            data: {
              link: url,
              meta: {
                title: title,
              },
            },
          });
        }
      }
    }
    // Regular paragraphs
    else if (line) {
      // Collect consecutive non-empty lines for paragraph
      let paragraphText = line;
      let j = i + 1;

      while (j < lines.length) {
        const currentLine = lines[j];
        if (currentLine === undefined) break;
        const trimmed = currentLine.trim();
        if (
          trimmed === "" ||
          trimmed.startsWith("#") ||
          trimmed.startsWith("> ") ||
          trimmed.startsWith("- ") ||
          trimmed.match(/^\d+\.\s/) ||
          trimmed === "```" ||
          trimmed.match(/^!\[([^\]]*)\]\(([^)]+)\)$/)
        ) {
          break;
        }
        paragraphText += " " + trimmed;
        j++;
      }

      blocks.push({
        id: generateBlockId(),
        type: "paragraph",
        data: {
          text: paragraphText,
        },
      });

      i = j - 1; // Set i to the last line we processed
    }

    i++;
  }

  return {
    blocks: blocks,
  };
}

/**
 * Search action handlers
 * Centralized action processing for search page
 */

import { nip19 } from "nostr-tools";

import { connectToPrimalCache } from "~/features/cache/primalCache.server";
import type { NostrEvent } from "~/features/nostr/types";
/**
 * Extended NostrEvent with pubkey and id (from Primal cache)
 */
type NostrEventWithMetadata = NostrEvent & {
  pubkey?: string;
  id?: string;
};

/**
 * Decode event ID from various formats (nevent1, note1, hex)
 */
function decodeEventId(eventInput: string): string {
  const eventId = eventInput.trim();

  // Check if input is in nevent1 format
  if (eventId.startsWith("nevent1")) {
    try {
      const decoded = nip19.decode(eventId);
      if (decoded.type === "nevent") {
        return decoded.data.id;
      }
    } catch (_e) {
      throw new Error("Invalid nevent1 format");
    }
  } else if (eventId.startsWith("nostr:nevent1")) {
    try {
      const decoded = nip19.decode(eventId.replace("nostr:", ""));
      if (decoded.type === "nevent") {
        return decoded.data.id;
      }
    } catch (_e) {
      throw new Error("Invalid nevent1 format");
    }
  } else if (eventId.startsWith("note1")) {
    try {
      const decoded = nip19.decode(eventId);
      if (decoded.type === "note") {
        return decoded.data;
      }
    } catch (_e) {
      throw new Error("Invalid note1 format");
    }
  }

  // Validate hex format (64 character hex string)
  if (!/^[a-f0-9]{64}$/i.test(eventId)) {
    throw new Error(
      "Invalid event ID format. Must be a 64-character hex string, note1, or nevent1"
    );
  }

  return eventId;
}

/**
 * Fetch author profile information
 */
async function fetchAuthorInfo(pubkey: string): Promise<{
  name: string;
  image: string | null;
}> {
  let authorName = pubkey.substring(0, 8) + "...";
  let authorImage = null;

  try {
    const userInfoResponses = await connectToPrimalCache("user_infos", {
      pubkeys: [pubkey],
    });

    const userMetadataEvent = userInfoResponses.find(
      (res): res is [string, string, NostrEventWithMetadata] =>
        Array.isArray(res) &&
        res[0] === "EVENT" &&
        res[2] !== undefined &&
        (res[2] as NostrEventWithMetadata).kind === 0 &&
        (res[2] as NostrEventWithMetadata).pubkey === pubkey
    );

    if (userMetadataEvent?.[2]) {
      const event = userMetadataEvent[2];
      const metadata = JSON.parse(event.content) as {
        name?: string;
        display_name?: string;
        picture?: string;
      };
      authorName = metadata.name ?? metadata.display_name ?? authorName;
      authorImage = metadata.picture ?? null;
    }
  } catch (error) {
    console.error("[Search] Error fetching author info:", error);
  }

  return { name: authorName, image: authorImage };
}

/**
 * Fetch engagement stats for an event
 */
async function fetchEventStats(eventId: string): Promise<{
  likes: number;
  replies: number;
  mentions: number;
  reposts: number;
  zaps: number;
  satszapped: number;
}> {
  let stats = {
    likes: 0,
    replies: 0,
    mentions: 0,
    reposts: 0,
    zaps: 0,
    satszapped: 0,
  };

  try {
    const threadResponses = await connectToPrimalCache("thread_view", {
      event_id: eventId,
    });

    const statsEvent = threadResponses.find(
      (res): res is [string, string, NostrEventWithMetadata] =>
        Array.isArray(res) &&
        res[0] === "EVENT" &&
        res[2] !== undefined &&
        (res[2] as NostrEventWithMetadata).kind === 10000100 &&
        typeof (res[2] as NostrEventWithMetadata).content === "string" &&
        (res[2] as NostrEventWithMetadata).content.includes(eventId)
    );

    if (statsEvent?.[2]) {
      const event = statsEvent[2];
      const content = JSON.parse(event.content) as {
        likes?: number;
        replies?: number;
        mentions?: number;
        reposts?: number;
        zaps?: number;
        satszapped?: number;
      };
      stats = {
        likes: content.likes ?? 0,
        replies: content.replies ?? 0,
        mentions: content.mentions ?? 0,
        reposts: content.reposts ?? 0,
        zaps: content.zaps ?? 0,
        satszapped: content.satszapped ?? 0,
      };
    }
  } catch (error) {
    // Log but continue - stats are optional
    const { logWarning } = await import("~/lib/error-logger.server");
    logWarning("Failed to fetch stats for searched event", {
      eventId,
      error: error instanceof Error ? error.message : String(error),
    });
  }

  return stats;
}

/**
 * Extract media URLs from event content
 */
function extractMediaUrls(content: string): string[] {
  const urlRegex =
    /(https?:\/\/[^\s]+\.(jpg|jpeg|png|gif|webp|mp4|webm|mov))/gi;
  return content.match(urlRegex) ?? [];
}

/**
 * Handle search event action
 */
export async function handleSearchEvent(eventInput: string) {
  if (!eventInput || eventInput.trim() === "") {
    const { ValidationError } = await import("~/lib/errors");
    throw new ValidationError("Please enter an event ID or nevent1");
  }

  // Decode event ID from various formats
  let eventId: string;
  try {
    eventId = decodeEventId(eventInput);
  } catch (error) {
    const { ValidationError } = await import("~/lib/errors");
    throw new ValidationError(
      error instanceof Error ? error.message : "Invalid event ID format",
      { input: eventInput }
    );
  }

  // Fetch event from Primal cache
  let responses: unknown;
  try {
    responses = await connectToPrimalCache("events", {
      event_ids: [eventId],
    });
  } catch (error) {
    const { ExternalServiceError } = await import("~/lib/errors");
    throw new ExternalServiceError("Failed to fetch event from cache", 502, {
      service: "PrimalCache",
      eventId,
      originalError: error instanceof Error ? error.message : String(error),
    });
  }

  // Find the EVENT response
  const eventResponse = Array.isArray(responses)
    ? responses.find(
        (res): res is [string, string, NostrEventWithMetadata] =>
          Array.isArray(res) && res[0] === "EVENT" && res[2] !== undefined
      )
    : null;

  if (!eventResponse?.[2]) {
    const { NotFoundError } = await import("~/lib/errors");
    throw new NotFoundError(
      "Event not found. Please check the event ID and try again.",
      { eventId }
    );
  }

  const event = eventResponse[2];
  // eslint-disable-next-line @typescript-eslint/no-unnecessary-condition -- Runtime safety: defensive check for array access
  if (!event) {
    const { NotFoundError } = await import("~/lib/errors");
    throw new NotFoundError(
      "Event not found. Please check the event ID and try again.",
      { eventId }
    );
  }

  // Fetch author profile info and stats in parallel
  const eventPubkey = typeof event.pubkey === "string" ? event.pubkey : "";
  const eventContent = typeof event.content === "string" ? event.content : "";
  const [authorInfo, stats] = await Promise.all([
    fetchAuthorInfo(eventPubkey),
    fetchEventStats(eventId),
  ]);

  // Extract media URLs from content
  const mediaUrls = extractMediaUrls(eventContent);

  return {
    success: true,
    event: {
      id: typeof event.id === "string" ? event.id : eventId,
      pubkey: eventPubkey,
      created_at: typeof event.created_at === "number" ? event.created_at : 0,
      kind: typeof event.kind === "number" ? event.kind : 1,
      content: eventContent,
      tags: Array.isArray(event.tags) ? event.tags : [],
      authorName: authorInfo.name,
      authorImage: authorInfo.image,
      mediaUrls,
    },
    stats,
  };
}

/**
 * Accounts management action handlers
 */

import { json } from "@remix-run/node";

import {
  getUserBasicInfo,
  searchUsersByProfileName,
  requestChildLink,
  cancelChildLinkRequest,
  unlinkParent,
  unlinkChildByParent,
  getUserIdByNpub,
} from "~/features/user";
import { logWarning } from "~/lib/error-logger.server";
import {
  searchAccountsSchema,
  requestChildSchema,
  cancelChildRequestSchema,
  unlinkChildSchema,
  validateFormDataOrRespond,
} from "~/lib/validation";
import {
  updateUserSubscription,
  getUserSubscription,
} from "~/models/payment.server";

export async function handleAccountsAction(
  userId: string,
  action: string,
  formData: FormData,
) {
  const me = await getUserBasicInfo(userId);
  const sub = await getUserSubscription(userId);
  const planName = sub?.Plan?.name ?? "";

  // Check access for account management actions
  const requiresPremium = [
    "search_accounts",
    "request_child",
    "cancel_child_request",
    "unlink_child",
  ].includes(action);
  if (requiresPremium && !(planName === "Founder" || planName === "Premium")) {
    return json(
      {
        error:
          "Accounts management requires Founder or Premium. Please upgrade.",
      },
      { status: 403 },
    );
  }

  if (action === "search_accounts") {
    const result = validateFormDataOrRespond(formData, searchAccountsSchema);
    if (!result.success) {
      return result.response;
    }
    if (me?.isChild) {
      return json(
        { error: "Child accounts cannot search or manage child accounts." },
        { status: 403 },
      );
    }
    const results = await searchUsersByProfileName(
      result.data.q,
      me?.npub ?? undefined,
    );
    return json({ results });
  }

  if (action === "request_child") {
    const result = validateFormDataOrRespond(formData, requestChildSchema);
    if (!result.success) {
      return result.response;
    }
    if (me?.isChild) {
      return json(
        { error: "Child accounts cannot link child accounts." },
        { status: 403 },
      );
    }
    const parentNpub = me?.npub ?? "";
    const res = await requestChildLink(parentNpub, result.data.childNpub);
    if (!res.ok) {
      return json({ error: res.reason }, { status: 400 });
    }
    return json({ success: true });
  }

  if (action === "cancel_child_request") {
    const result = validateFormDataOrRespond(
      formData,
      cancelChildRequestSchema,
    );
    if (!result.success) {
      return result.response;
    }
    if (me?.isChild) {
      return json(
        { error: "Child accounts cannot manage child requests." },
        { status: 403 },
      );
    }
    const res = await cancelChildLinkRequest(
      me?.npub ?? "",
      result.data.childNpub,
    );
    if (!res.ok) {
      return json({ error: res.reason }, { status: 400 });
    }
    return json({ success: true });
  }

  if (action === "unlink_parent") {
    if (!me?.isChild) {
      return json(
        { error: "This account is not a child account." },
        { status: 400 },
      );
    }
    if (!me.npub) {
      return json({ error: "User npub not found" }, { status: 400 });
    }
    const res = await unlinkParent(me.npub);
    if (!res.ok) {
      return json({ error: res.reason }, { status: 400 });
    }
    // Demote child back to free plan
    try {
      await updateUserSubscription(
        userId,
        "free",
        `free_child_unlink_${Date.now()}_${userId}`,
      );
    } catch (e) {
      logWarning("Failed to demote child to free after unlink", {
        userId,
        error: e instanceof Error ? e.message : String(e),
      });
    }
    return json({ success: true });
  }

  if (action === "unlink_child") {
    const result = validateFormDataOrRespond(formData, unlinkChildSchema);
    if (!result.success) {
      return result.response;
    }
    if (!me?.npub || me.isChild) {
      return json(
        { error: "Only a parent account can unlink a child." },
        { status: 403 },
      );
    }
    const res = await unlinkChildByParent(me.npub, result.data.childNpub);
    if (!res.ok) {
      return json({ error: res.reason }, { status: 400 });
    }
    // Demote child to free plan
    try {
      const childId = await getUserIdByNpub(result.data.childNpub);
      if (childId) {
        await updateUserSubscription(
          childId,
          "free",
          `free_child_unlink_${Date.now()}_${childId}`,
        );
      }
    } catch (e) {
      logWarning("Failed to demote unlinked child to free", {
        childNpub: result.data.childNpub,
        error: e instanceof Error ? e.message : String(e),
      });
    }
    return json({ success: true });
  }

  return null;
}

/**
 * Queue type action handlers
 */

import { json } from "@remix-run/node";

import {
  deleteQueueType,
  hashTagPresetExistsForUser,
  updateQueueType,
} from "~/features/user";
import {
  createQueueTypeSchema,
  updateQueueTypeSchema,
  deleteQueueTypeSchema,
  validateFormDataOrRespond,
} from "~/lib/validation";
import { getUserSubscription } from "~/models/payment.server";

export async function handleQueueTypeAction(
  userId: string,
  action: string,
  formData: FormData
) {
  if (action === "create_queue_type") {
    // Check if user has a free subscription
    const subscription = await getUserSubscription(userId);
    if (subscription?.Plan && Number(subscription.Plan.price) === 0) {
      return json(
        {
          error:
            "Creating queue types is not available on the free plan. Please upgrade your subscription.",
        },
        { status: 403 }
      );
    }

    const result = validateFormDataOrRespond(formData, createQueueTypeSchema);
    if (!result.success) {
      return result.response;
    }

    const { data } = result;

    // Validate hashtag preset exists if provided
    if (data.hashTagPresetId) {
      const presetExists = await hashTagPresetExistsForUser(
        userId,
        data.hashTagPresetId
      );
      if (!presetExists) {
        return json(
          { error: "Selected hashtag preset does not exist" },
          { status: 400 }
        );
      }
    }

    // Build schedule config based on schedule type
    // Schema validation ensures slots is defined when scheduleType is "FIXED_SLOTS"
    let scheduleConfig: {
      useGlobalInterval?: boolean;
      intervalHours?: number;
      slots?: string[];
    } = {};
    if (data.scheduleType === "INTERVAL") {
      scheduleConfig = data.useGlobalInterval
        ? { useGlobalInterval: true }
        : { intervalHours: data.intervalHours };
    } else {
      // scheduleType must be "FIXED_SLOTS" here (enum has only two values)
      // Schema validation ensures slots is defined
      scheduleConfig = { slots: data.slots! };
    }

    await updateQueueType(userId, {
      name: data.name,
      scheduleType: data.scheduleType,
      scheduleConfig,
      color: data.color,
      description: data.description,
      hashTagPresetId: data.hashTagPresetId,
    });
    return json({ success: true });
  }

  if (action === "update_queue_type") {
    const result = validateFormDataOrRespond(formData, updateQueueTypeSchema);
    if (!result.success) {
      return result.response;
    }

    const { data } = result;

    // Validate hashtag preset exists if provided
    if (data.hashTagPresetId) {
      const presetExists = await hashTagPresetExistsForUser(
        userId,
        data.hashTagPresetId
      );
      if (!presetExists) {
        return json(
          { error: "Selected hashtag preset does not exist" },
          { status: 400 }
        );
      }
    }

    // Build schedule config based on schedule type
    // Schema validation ensures slots is defined when scheduleType is "FIXED_SLOTS"
    let scheduleConfig: {
      useGlobalInterval?: boolean;
      intervalHours?: number;
      slots?: string[];
    } = {};
    if (data.scheduleType === "INTERVAL") {
      scheduleConfig = data.useGlobalInterval
        ? { useGlobalInterval: true }
        : { intervalHours: data.intervalHours };
    } else {
      // scheduleType must be "FIXED_SLOTS" here (enum has only two values)
      // Schema validation ensures slots is defined
      scheduleConfig = { slots: data.slots! };
    }

    await updateQueueType(userId, {
      id: data.id,
      name: data.name,
      scheduleType: data.scheduleType,
      scheduleConfig,
      color: data.color,
      description: data.description,
      isEnabled: data.isEnabled,
      hashTagPresetId: data.hashTagPresetId,
    });
    return json({ success: true });
  }

  if (action === "delete_queue_type") {
    const result = validateFormDataOrRespond(formData, deleteQueueTypeSchema);
    if (!result.success) {
      return result.response;
    }
    await deleteQueueType(userId, result.data.id);
    return json({ success: true });
  }

  return null;
}

import { useNavigate } from "@remix-run/react";
import { useState, useCallback } from "react";
import { toast } from "react-hot-toast";
interface UploadProvider {
  provider: "S3" | "BLOSSOM_PRIMAL" | "BLOSSOM_BLOSSTR";
  isUsingBlossom: boolean;
  enableMirrorBlossom?: boolean;
  mirrorUploadUrls?: string[];
}

interface SubmitOptions {
  method: string;
  encType?: string;
  action?: string;
}

const TOAST_ID_BLOSSOM_AUTH = "blossom-auth";

export function useBlossomAwareUpload() {
  const [isUploading, setIsUploading] = useState(false);
  const [uploadProgress, setUploadProgress] = useState(0);
  const [response, setResponse] = useState<Record<string, unknown> | null>(
    null
  );
  const [error, setError] = useState<string | null>(null);
  const navigate = useNavigate();

  const checkUploadProvider = async (): Promise<UploadProvider> => {
    try {
      const response = await fetch("/api/user-upload-provider");
      if (!response.ok) throw new Error("Failed to check provider");
      const data = (await response.json()) as {
        provider?: string;
        enableMirrorBlossom?: boolean;
        mirrorUploadUrls?: string[];
      };

      const {
        provider,
        enableMirrorBlossom = false,
        mirrorUploadUrls = [],
      } = data;

      // Handle legacy BLOSSOM value as BLOSSOM_PRIMAL
      if (provider === "BLOSSOM" || provider === "BLOSSOM_PRIMAL") {
        return {
          provider: "BLOSSOM_PRIMAL",
          isUsingBlossom: true,
          enableMirrorBlossom,
          mirrorUploadUrls,
        };
      }
      if (provider === "BLOSSOM_BLOSSTR") {
        return {
          provider: "BLOSSOM_BLOSSTR",
          isUsingBlossom: true,
          enableMirrorBlossom,
          mirrorUploadUrls,
        };
      }
      return {
        provider: "S3",
        isUsingBlossom: false,
        enableMirrorBlossom: false,
        mirrorUploadUrls: [],
      };
    } catch (error) {
      console.error("Failed to check upload provider:", error);
      return {
        provider: "S3",
        isUsingBlossom: false,
        enableMirrorBlossom: false,
        mirrorUploadUrls: [],
      };
    }
  };

  const createBlossomAuthHeaders = async (
    provider: "BLOSSOM_PRIMAL" | "BLOSSOM_BLOSSTR"
  ) => {
    if (!window.nostr) {
      throw new Error(
        "NOSTR extension not found. Please install Alby, Amber, or another NOSTR extension to upload to Blossom."
      );
    }

    const _uploadUrl =
      provider === "BLOSSOM_PRIMAL"
        ? "https://blossom.primal.net/upload"
        : "https://blosstr.com/upload";

    // Note: Authentication should be handled by the upload service directly
    throw new Error(
      "Blossom auth not implemented in useBlossomAwareUpload. Use upload.client.ts instead."
    );
  };

  const submitForm = useCallback(
    async (formData: FormData, options: SubmitOptions) => {
      setIsUploading(true);
      setUploadProgress(10);
      setError(null);

      try {
        // Check upload provider
        const providerInfo = await checkUploadProvider();
        setUploadProgress(20);

        let headers: Record<string, string> = {};

        // If using any Blossom provider, create auth headers and show progress
        if (providerInfo.isUsingBlossom) {
          setUploadProgress(30);
          const providerName =
            providerInfo.provider === "BLOSSOM_PRIMAL" ? "Primal" : "Blosstr";

          // Log mirror configuration if enabled
          if (
            providerInfo.enableMirrorBlossom &&
            providerInfo.mirrorUploadUrls?.length
          ) {
            // Mirror configuration is active
          }

          toast.loading(
            `Signing upload request with NOSTR extension for ${providerName}...`,
            {
              id: TOAST_ID_BLOSSOM_AUTH,
            }
          );
          try {
            headers = await createBlossomAuthHeaders(
              providerInfo.provider as "BLOSSOM_PRIMAL" | "BLOSSOM_BLOSSTR"
            );
            toast.success("Upload authorized!", { id: "blossom-auth" });
            setUploadProgress(60);
          } catch (authError: unknown) {
            const errorMessage =
              authError instanceof Error
                ? authError.message
                : String(authError);
            toast.error("Failed to authorize upload: " + errorMessage, {
              id: TOAST_ID_BLOSSOM_AUTH,
            });
            throw authError;
          }
        }

        setUploadProgress(70);

        // Get the action URL (default to current page)
        const actionUrl = options.action ?? window.location.pathname;

        // Make the request with custom headers for Blossom Primal
        const fetchResponse = await fetch(actionUrl, {
          method: options.method,
          body: formData,
          headers: {
            ...headers,
            // Don't set Content-Type for FormData, let the browser set it
          },
        });

        setUploadProgress(90);

        if (!fetchResponse.ok) {
          let errorData: { error?: string };
          try {
            errorData = (await fetchResponse.json()) as { error?: string };
          } catch {
            // If response is not JSON, try to get text
            const errorText = await fetchResponse
              .text()
              .catch(() => `HTTP ${fetchResponse.status}`);
            errorData = {
              error: errorText.includes("<!DOCTYPE")
                ? `HTTP ${fetchResponse.status}`
                : errorText,
            };
          }
          throw new Error(errorData.error ?? "Upload failed");
        }

        let result;
        const responseText = await fetchResponse.text();

        try {
          // Try to parse as JSON first
          result = JSON.parse(responseText) as Record<string, unknown>;
        } catch (_parseError: unknown) {
          // If response is HTML (redirect or error page), handle gracefully
          if (
            responseText.includes("<!DOCTYPE") ||
            responseText.includes("<html")
          ) {
            if (
              responseText.includes("success") ||
              responseText.includes("uploaded") ||
              fetchResponse.status === 200
            ) {
              result = {
                success: true,
                redirect: true,
                message:
                  "Upload completed, but received HTML response instead of JSON",
              };
            } else {
              result = {
                success: false,
                error: "Server returned HTML instead of expected JSON response",
              };
            }
          } else {
            const parseError = _parseError as Error;
            throw new Error(
              "Invalid response format: " +
                parseError.message +
                ". Response: " +
                responseText.substring(0, 100)
            );
          }
        }

        setResponse(result);
        setUploadProgress(100);

        // Handle successful response
        if (result["success"] !== false) {
          // Check if this was a redirect response
          if (fetchResponse.redirected || result["redirect"]) {
            const redirectUrl = result["redirect"] ?? fetchResponse.url;
            navigate(redirectUrl);
          }
        }

        return result;
      } catch (error: unknown) {
        const { handleAsyncError } = await import("~/lib/error-handler.client");
        const errorMessage =
          error instanceof Error ? error.message : "Upload failed";
        handleAsyncError(error, {
          component: "useBlossomAwareUpload",
          action: "submitForm",
        });
        setError(errorMessage);
        throw error;
      } finally {
        setTimeout(() => {
          setIsUploading(false);
          setUploadProgress(0);
        }, 1000);
      }
    },
    [navigate]
  );

  return {
    submitForm,
    isUploading,
    uploadProgress,
    response,
    error,
  };
}

import { useFetcher, useRevalidator } from "@remix-run/react";
import * as React from "react";

import { Avatar, AvatarImage } from "~/components/ui/avatar";
import { Button } from "~/components/ui/button";
import { Card } from "~/components/ui/card";
import { Input } from "~/components/ui/input";
import type { ProfileData } from "~/features/nostr/types";
interface AccountInfo {
  npub: string;
  nostrProfile?: ProfileData | null;
}

interface SearchResult {
  id: string;
  npub: string;
  profileName?: string;
  profileDisplayName?: string;
  profilePicture?: string;
  isChild?: boolean;
  parentNpub?: string | null;
  pendingParentRequests?: string[];
}

const ACTION_REQUEST_CHILD = "request_child";
const DASHBOARD_SETTINGS_ACTION = "/dashboard/settings";

function extractProfileBits(nostrProfile: ProfileData | null | undefined) {
  if (!nostrProfile)
    return {
      name: undefined,
      display_name: undefined,
      picture: undefined,
    } as const;
  try {
    if (typeof nostrProfile === "string") {
      const p = JSON.parse(nostrProfile) as {
        name?: string;
        display_name?: string;
        picture?: string;
      };
      return {
        name: p.name,
        display_name: p.display_name,
        picture: p.picture,
      } as const;
    }
    if (typeof nostrProfile === "object") {
      const p = nostrProfile;
      return {
        name: p.name,
        display_name: p.display_name,
        picture: p.picture,
      } as const;
    }
  } catch {
    // Ignore parsing errors, return defaults
  }
  return {
    name: undefined,
    display_name: undefined,
    picture: undefined,
  } as const;
}

export function AccountsSettings({
  parentNpub,
  confirmedChildren,
  pendingChildren,
  isChild = false,
  parentUser,
}: {
  parentNpub?: string;
  confirmedChildren?: AccountInfo[];
  pendingChildren?: AccountInfo[];
  isChild?: boolean;
  parentUser?: AccountInfo | null;
}) {
  const fetcher = useFetcher<{ results?: SearchResult[]; error?: string }>();
  const [q, setQ] = React.useState("");
  const revalidator = useRevalidator();

  // Prevent duplicate submissions due to re-renders by remembering last query
  const lastSubmittedRef = React.useRef("");

  React.useEffect(() => {
    const value = q.trim();
    if (!value) {
      lastSubmittedRef.current = "";
      return;
    }
    if (lastSubmittedRef.current === value) return;

    const i = setTimeout(() => {
      lastSubmittedRef.current = value;
      fetcher.submit(
        { _action: "search_accounts", q: value },
        { method: "post" }
      );
    }, 300);

    return () => clearTimeout(i);
  }, [q, fetcher]);

  const onRequestChild = (childNpub: string) => {
    const np = childNpub.trim();
    fetcher.submit(
      { _action: ACTION_REQUEST_CHILD, childNpub: np },
      { method: "post", action: DASHBOARD_SETTINGS_ACTION }
    );
  };

  // Submission state feedback
  const submittingAction =
    (fetcher.formData?.get("_action") as string) || undefined;
  const submittingChildNpub =
    (fetcher.formData?.get("childNpub") as string) || undefined;
  const isUnlinking =
    submittingAction === "unlink_parent" && fetcher.state !== "idle";

  React.useEffect(() => {
    if (
      (submittingAction === "unlink_parent" ||
        submittingAction === "unlink_child" ||
        submittingAction === "cancel_child_request") &&
      fetcher.state === "idle" &&
      (fetcher.data as { success?: boolean } | undefined)?.success
    ) {
      revalidator.revalidate();
    }
  }, [fetcher.state, fetcher.data, submittingAction, revalidator]);

  const _renderAccountRow = (
    npub: string,
    nostrProfile?: ProfileData | null
  ) => {
    const bits = extractProfileBits(nostrProfile);
    return (
      <div
        key={npub}
        className="flex items-center justify-between border-b py-2 last:border-0"
      >
        <div className="flex min-w-0 items-center gap-3">
          <Avatar className="h-8 w-8">
            {bits.picture ? (
              <AvatarImage
                src={bits.picture}
                alt={bits.name ?? bits.display_name ?? npub}
              />
            ) : null}
          </Avatar>
          <div className="min-w-0">
            <div className="truncate font-medium">
              {bits.name ?? bits.display_name ?? npub}
            </div>
            <div className="text-muted-foreground truncate text-xs">{npub}</div>
          </div>
        </div>
      </div>
    );
  };

  const results = fetcher.data?.results ?? [];

  if (isChild) {
    const bits = extractProfileBits(parentUser?.nostrProfile);
    const parentName =
      bits.name ?? bits.display_name ?? parentUser?.npub ?? "Parent";
    return (
      <Card className="p-4">
        <div className="mb-4">
          <h2 className="text-xl font-semibold">Accounts</h2>
          <p className="text-muted-foreground text-sm">
            This account is managed by a parent account.
          </p>
        </div>

        <div className="bg-muted/30 mb-6 flex items-center justify-between rounded-md border p-4">
          <div className="flex min-w-0 items-center gap-3">
            <Avatar className="h-10 w-10">
              {bits.picture ? (
                <AvatarImage src={bits.picture} alt={parentName} />
              ) : null}
            </Avatar>
            <div className="min-w-0">
              <div className="truncate font-medium">
                Managed by {parentName}
              </div>
              {parentUser?.npub ? (
                <div className="text-muted-foreground truncate text-xs">
                  {parentUser.npub}
                </div>
              ) : null}
            </div>
          </div>
          <Button
            size="sm"
            variant="destructive"
            disabled={isUnlinking}
            onClick={() =>
              fetcher.submit(
                { _action: "unlink_parent" },
                { method: "post", action: DASHBOARD_SETTINGS_ACTION }
              )
            }
          >
            {isUnlinking ? "Unlinking..." : "Unlink from Parent"}
          </Button>
        </div>

        <p className="text-muted-foreground text-sm">
          As a child account, you cannot search for or link child accounts.
        </p>
      </Card>
    );
  }

  return (
    <Card className="p-4">
      <div className="mb-4">
        <h2 className="text-xl font-semibold">Accounts</h2>
        <p className="text-muted-foreground text-sm">
          Search Nostr users by profile name and request to add them as child
          accounts.
        </p>
      </div>

      <div className="mb-6">
        <label
          htmlFor="accounts-search"
          className="mb-2 block text-sm font-medium"
        >
          Search users
        </label>
        <Input
          id="accounts-search"
          placeholder="Search by name or npub..."
          value={q}
          onChange={(e) => setQ(e.target.value)}
        />
      </div>

      {q.trim() ? (
        <div className="mb-8">
          <h3 className="mb-2 text-sm font-medium">Search results</h3>
          <div className="divide-y rounded-md border">
            {results.length === 0 ? (
              <div className="text-muted-foreground p-3 text-sm">
                No results
              </div>
            ) : (
              results.map((r) => {
                const isSubmittingThis =
                  submittingAction === ACTION_REQUEST_CHILD &&
                  submittingChildNpub === r.npub &&
                  fetcher.state !== "idle";
                const disabled =
                  isSubmittingThis ||
                  r.npub === parentNpub ||
                  (r.pendingParentRequests ?? []).includes(parentNpub ?? "") ||
                  r.parentNpub === parentNpub ||
                  r.isChild === true;
                const label = isSubmittingThis
                  ? "Requesting..."
                  : r.npub === parentNpub
                    ? "This is you"
                    : (r.pendingParentRequests ?? []).includes(parentNpub ?? "")
                      ? "Requested"
                      : r.parentNpub
                        ? "Has a parent"
                        : r.isChild
                          ? "Is a child"
                          : "Request";

                return (
                  <div
                    key={r.id}
                    className="flex items-center justify-between p-3"
                  >
                    <div className="flex min-w-0 items-center gap-3">
                      <Avatar className="h-8 w-8">
                        {r.profilePicture ? (
                          <AvatarImage
                            src={r.profilePicture}
                            alt={
                              r.profileName ?? r.profileDisplayName ?? r.npub
                            }
                          />
                        ) : null}
                      </Avatar>
                      <div className="min-w-0">
                        <div className="truncate font-medium">
                          {r.profileName ?? r.profileDisplayName ?? r.npub}
                        </div>
                        <div className="text-muted-foreground truncate text-xs">
                          {r.npub}
                        </div>
                      </div>
                    </div>
                    <Button
                      size="sm"
                      variant={disabled ? "secondary" : "default"}
                      disabled={disabled}
                      onClick={() => onRequestChild(r.npub)}
                    >
                      {label}
                    </Button>
                  </div>
                );
              })
            )}
          </div>
          {fetcher.data?.error ? (
            <p className="mt-2 text-sm text-red-600">{fetcher.data.error}</p>
          ) : null}
        </div>
      ) : null}

      <div className="grid gap-6 md:grid-cols-2">
        <div>
          <h3 className="mb-2 text-sm font-medium">Confirmed children</h3>
          <div className="divide-y rounded-md border">
            {confirmedChildren?.length === 0 ? (
              <div className="text-muted-foreground p-3 text-sm">
                No confirmed children
              </div>
            ) : (
              (confirmedChildren ?? []).map((u) => {
                const bits = extractProfileBits(u.nostrProfile);
                const removingThis =
                  submittingAction === "unlink_child" &&
                  (fetcher.formData?.get("childNpub") as string) === u.npub &&
                  fetcher.state !== "idle";
                return (
                  <div
                    key={u.npub}
                    className="flex items-center justify-between p-3"
                  >
                    <div className="flex min-w-0 items-center gap-3">
                      <Avatar className="h-8 w-8">
                        {bits.picture ? (
                          <AvatarImage
                            src={bits.picture}
                            alt={bits.name ?? bits.display_name ?? u.npub}
                          />
                        ) : null}
                      </Avatar>
                      <div className="min-w-0">
                        <div className="truncate font-medium">
                          {bits.name ?? bits.display_name ?? u.npub}
                        </div>
                        <div className="text-muted-foreground truncate text-xs">
                          {u.npub}
                        </div>
                      </div>
                    </div>
                    <Button
                      size="sm"
                      variant="destructive"
                      disabled={removingThis}
                      onClick={() =>
                        fetcher.submit(
                          { _action: "unlink_child", childNpub: u.npub },
                          { method: "post", action: DASHBOARD_SETTINGS_ACTION }
                        )
                      }
                    >
                      {removingThis ? "Removing..." : "Remove"}
                    </Button>
                  </div>
                );
              })
            )}
          </div>
        </div>
        <div>
          <h3 className="mb-2 text-sm font-medium">Pending requests</h3>
          <div className="divide-y rounded-md border">
            {pendingChildren?.length === 0 ? (
              <div className="text-muted-foreground p-3 text-sm">
                No pending requests
              </div>
            ) : (
              (pendingChildren ?? []).map((u) => {
                const bits = extractProfileBits(u.nostrProfile);
                const cancelingThis =
                  submittingAction === "cancel_child_request" &&
                  (fetcher.formData?.get("childNpub") as string) === u.npub &&
                  fetcher.state !== "idle";
                return (
                  <div
                    key={u.npub}
                    className="flex items-center justify-between p-3"
                  >
                    <div className="flex min-w-0 items-center gap-3">
                      <Avatar className="h-8 w-8">
                        {bits.picture ? (
                          <AvatarImage
                            src={bits.picture}
                            alt={bits.name ?? bits.display_name ?? u.npub}
                          />
                        ) : null}
                      </Avatar>
                      <div className="min-w-0">
                        <div className="truncate font-medium">
                          {bits.name ?? bits.display_name ?? u.npub}
                        </div>
                        <div className="text-muted-foreground truncate text-xs">
                          {u.npub}
                        </div>
                      </div>
                    </div>
                    <Button
                      size="sm"
                      variant="secondary"
                      disabled={cancelingThis}
                      onClick={() =>
                        fetcher.submit(
                          {
                            _action: "cancel_child_request",
                            childNpub: u.npub,
                          },
                          { method: "post", action: DASHBOARD_SETTINGS_ACTION }
                        )
                      }
                    >
                      {cancelingThis ? "Canceling..." : "Cancel"}
                    </Button>
                  </div>
                );
              })
            )}
          </div>
        </div>
      </div>
    </Card>
  );
}

/**
 * Parent API service layer
 * Handles parent account information for child accounts
 */

import { json } from "@remix-run/node";

import type { ProfileData } from "~/features/nostr/types";
import { getUserBasicInfo, getUserByNpubWithProfile } from "~/features/user";
import { logError } from "~/lib/error-logger.server";
import { normalizeError } from "~/lib/errors";
function extractProfileBits(nostrProfile: ProfileData | null | undefined) {
  if (!nostrProfile) {
    return {
      name: undefined,
      display_name: undefined,
      picture: undefined,
    } as const;
  }
  try {
    if (typeof nostrProfile === "string") {
      const pParsed: unknown = JSON.parse(nostrProfile);
      if (pParsed && typeof pParsed === "object" && !Array.isArray(pParsed)) {
        const p = pParsed as unknown as {
          name?: string;
          display_name?: string;
          picture?: string;
        };
        return {
          name: typeof p.name === "string" ? p.name : undefined,
          display_name:
            typeof p.display_name === "string" ? p.display_name : undefined,
          picture: typeof p.picture === "string" ? p.picture : undefined,
        } as const;
      }
    }
    if (typeof nostrProfile === "object" && !Array.isArray(nostrProfile)) {
      const p = nostrProfile as {
        name?: string;
        display_name?: string;
        picture?: string;
      };
      return {
        name: typeof p.name === "string" ? p.name : undefined,
        display_name:
          typeof p.display_name === "string" ? p.display_name : undefined,
        picture: typeof p.picture === "string" ? p.picture : undefined,
      } as const;
    }
  } catch {
    // Silently ignore parse errors - return defaults
  }
  return {
    name: undefined,
    display_name: undefined,
    picture: undefined,
  } as const;
}

/**
 * Load parent information for a child account
 */
export async function loadParentData(userId: string) {
  const me = await getUserBasicInfo(userId);

  if (!me?.isChild || !me.parentNpub) {
    return json({ parent: null });
  }

  const parent = await getUserByNpubWithProfile(me.parentNpub);

  if (!parent) {
    return json({ parent: null });
  }

  const bits = extractProfileBits(parent.nostrProfile);

  return json({
    parent: {
      npub: parent.npub,
      name: bits.name,
      displayName: bits.display_name,
      picture: bits.picture,
    },
  });
}

/**
 * Handle errors for parent API
 */
export function handleParentApiError(error: unknown, requestUrl: string) {
  // If error is a Response (e.g., redirect from requireUserId), rethrow it
  if (error instanceof Response) {
    throw error;
  }

  // Gracefully handle other errors by returning null parent
  // Log error but don't expose it to client
  logError(normalizeError(error), { path: requestUrl });
  return json({ parent: null });
}

/**
 * Centralized environment variable validation and typed exports
 *
 * This module validates all environment variables at boot time and exports
 * a typed object that can be safely used throughout the application.
 *
 * Usage:
 *   import { env } from "~/lib/env.server";
 *   const url = env.NOSTR_PUBLISHER_URL; // Type-safe, guaranteed to exist
 */

interface EnvConfig {
  // Required
  DATABASE_URL: string;
  SESSION_SECRET: string;
  NOSTR_PUBLISHER_URL: string;
  REDIS_URL: string;

  // Storage (required if any storage var is set)
  STORAGE_ACCESS_KEY?: string;
  STORAGE_SECRET?: string;
  STORAGE_REGION?: string;
  STORAGE_BUCKET?: string;

  // Optional
  PRIMAL_CACHING_URL?: string;
  OWNER_NWC?: string;
  NOSTR_NSEC?: string;
  SENTRY_DSN?: string;
  NODE_ENV?: string;
  PORT?: string;
  METRICS_PORT?: string;
  FLY_REGION?: string;
  PRIMARY_REGION?: string;
  TEST_DATABASE_URL?: string;
  ENABLE_SOURCE_MAPS?: string;
  E2E_TEST?: string;

  // Security (CSRF protection)
  APP_URL?: string; // Canonical app URL (e.g., https://yourdomain.com)
  ALLOWED_ORIGINS?: string; // Comma-separated list of allowed origins for CSRF protection

  // Metrics endpoint security
  METRICS_TOKEN?: string; // Token required to access /metrics endpoint
  METRICS_ALLOWED_IPS?: string; // Comma-separated list of allowed IPs for metrics endpoint
}

interface ValidationError {
  key: string;
  reason: string;
}

/**
 * Validates environment variables and returns typed config
 * Throws error if validation fails (prevents app from starting)
 */
function validateAndGetEnv(): EnvConfig {
  // Provide default values for E2E tests if variables are not set
  if (process.env["E2E_TEST"] === "true") {
    process.env["DATABASE_URL"] ??=
      process.env["TEST_DATABASE_URL"] ??
      "postgresql://postgres:postgres@localhost:5432/smartflow_test";
    process.env["SESSION_SECRET"] ??=
      "test-session-secret-very-long-and-secure-32-chars-minimum";
    process.env["NOSTR_PUBLISHER_URL"] ??= "http://localhost:3001/publish";
    process.env["REDIS_URL"] ??= "redis://localhost:6379";
  }

  const required = [
    "DATABASE_URL",
    "SESSION_SECRET",
    "NOSTR_PUBLISHER_URL",
    "REDIS_URL",
  ] as const;

  // Storage variables are optional - only required if using image uploads
  // If any storage variable is set, all must be set
  const storageVariables = [
    "STORAGE_ACCESS_KEY",
    "STORAGE_SECRET",
    "STORAGE_REGION",
    "STORAGE_BUCKET",
  ] as const;

  const missing: string[] = [];
  const invalid: ValidationError[] = [];

  // Validate required variables
  for (const key of required) {
    const value = process.env[key];
    if (!value || value.trim() === "") {
      missing.push(key);
    } else {
      // Additional validation for specific variables
      if (key === "SESSION_SECRET" && value.length < 32) {
        invalid.push({
          key,
          reason: "must be at least 32 characters long",
        });
      }
      if (key === "DATABASE_URL" && !value.startsWith("postgresql://")) {
        invalid.push({
          key,
          reason:
            "must be a valid PostgreSQL connection string (postgresql://...)",
        });
      }
      if (key === "REDIS_URL" && !value.startsWith("redis://")) {
        invalid.push({
          key,
          reason: "must be a valid Redis connection string (redis://...)",
        });
      }
    }
  }

  // Validate storage variables: if any is set, all must be set
  const storageValues = storageVariables.map((key) => process.env[key]);
  const hasSomeStorage = storageValues.some((v) => v && v.trim() !== "");
  const hasAllStorage = storageValues.every((v) => v && v.trim() !== "");

  if (hasSomeStorage && !hasAllStorage) {
    missing.push(
      ...storageVariables.filter((key) => {
        const value = process.env[key];
        return !value || value.trim() === "";
      })
    );
  }

  // Report errors
  if (missing.length > 0 || invalid.length > 0) {
    console.error("❌ Environment validation failed:");

    if (missing.length > 0) {
      console.error("\nMissing required environment variables:");
      missing.forEach((key) => console.error(`  - ${key}`));
    }

    if (invalid.length > 0) {
      console.error("\nInvalid environment variables:");
      invalid.forEach(({ key, reason }) =>
        console.error(`  - ${key}: ${reason}`)
      );
    }

    console.error(
      "\nPlease check your .env file or environment configuration."
    );
    console.error(
      "See docs/getting-started/environment-setup.md for detailed configuration instructions."
    );

    process.exit(1);
  }

  // Build typed config object
  const config: EnvConfig = {
    DATABASE_URL: process.env["DATABASE_URL"]!,
    SESSION_SECRET: process.env["SESSION_SECRET"]!,
    NOSTR_PUBLISHER_URL: process.env["NOSTR_PUBLISHER_URL"]!,
    REDIS_URL: process.env["REDIS_URL"]!,
  };

  // Add optional storage config if all are set
  if (hasAllStorage) {
    config.STORAGE_ACCESS_KEY = process.env["STORAGE_ACCESS_KEY"];
    config.STORAGE_SECRET = process.env["STORAGE_SECRET"];
    config.STORAGE_REGION = process.env["STORAGE_REGION"];
    config.STORAGE_BUCKET = process.env["STORAGE_BUCKET"];
  }

  // Add other optional variables
  if (process.env["PRIMAL_CACHING_URL"]) {
    config.PRIMAL_CACHING_URL = process.env["PRIMAL_CACHING_URL"];
  }
  if (process.env["OWNER_NWC"]) {
    config.OWNER_NWC = process.env["OWNER_NWC"];
  }
  if (process.env["NOSTR_NSEC"]) {
    config.NOSTR_NSEC = process.env["NOSTR_NSEC"];
  }
  if (process.env["SENTRY_DSN"]) {
    config.SENTRY_DSN = process.env["SENTRY_DSN"];
  }
  // eslint-disable-next-line @typescript-eslint/no-unnecessary-condition -- Runtime safety: process.env.NODE_ENV may be undefined in some environments
  config.NODE_ENV = process.env["NODE_ENV"] ?? "development";
  if (process.env["PORT"]) {
    config.PORT = process.env["PORT"];
  }
  if (process.env["METRICS_PORT"]) {
    config.METRICS_PORT = process.env["METRICS_PORT"];
  }
  if (process.env["FLY_REGION"]) {
    config.FLY_REGION = process.env["FLY_REGION"];
  }
  if (process.env["PRIMARY_REGION"]) {
    config.PRIMARY_REGION = process.env["PRIMARY_REGION"];
  }
  if (process.env["TEST_DATABASE_URL"]) {
    config.TEST_DATABASE_URL = process.env["TEST_DATABASE_URL"];
  }
  if (process.env["ENABLE_SOURCE_MAPS"]) {
    config.ENABLE_SOURCE_MAPS = process.env["ENABLE_SOURCE_MAPS"];
  }
  if (process.env["E2E_TEST"]) {
    config.E2E_TEST = process.env["E2E_TEST"];
  }

  // Add security configuration
  if (process.env["APP_URL"]) {
    config.APP_URL = process.env["APP_URL"];
  }
  if (process.env["ALLOWED_ORIGINS"]) {
    config.ALLOWED_ORIGINS = process.env["ALLOWED_ORIGINS"];
  }
  if (process.env["METRICS_TOKEN"]) {
    config.METRICS_TOKEN = process.env["METRICS_TOKEN"];
  }
  if (process.env["METRICS_ALLOWED_IPS"]) {
    config.METRICS_ALLOWED_IPS = process.env["METRICS_ALLOWED_IPS"];
  }

  console.info("✅ Environment variables validated");
  return config;
}

// Validate and export typed environment config
// This runs at module load time, so validation happens before app starts
export const env = validateAndGetEnv();

// Export type for use in other modules
export type { EnvConfig };

/**
 * Client-side Error Handling Utilities
 *
 * Provides standardized error handling for client-side code
 */

import { toast } from "react-hot-toast";

import type { ErrorResponse } from "./error-handler.server";
import { captureException } from "./sentry.client";
export type ClientErrorLevel = "error" | "warning" | "info";

export interface ClientErrorContext {
  component?: string;
  action?: string;
  userId?: string;
  [key: string]: unknown;
}

/**
 * Client-side error logger
 * Logs errors to console with structured format
 */
export function logClientError(
  error: Error | string,
  context?: ClientErrorContext,
  level: ClientErrorLevel = "error"
): void {
  const errorMessage = error instanceof Error ? error.message : error;
  const errorStack = error instanceof Error ? error.stack : undefined;

  const logEntry = {
    timestamp: new Date().toISOString(),
    level,
    message: errorMessage,
    ...(errorStack && { stack: errorStack }),
    ...(context && { context }),
    environment:
      typeof window !== "undefined" ? String(window.location.href) : "unknown",
  };

  if (process.env.NODE_ENV === "production") {
    // In production, log as JSON for log aggregation
    console.error(JSON.stringify(logEntry));
  } else {
    // In development, use readable format
    const emoji = level === "error" ? "❌" : level === "warning" ? "⚠️" : "ℹ️";
    console[
      level === "error" ? "error" : level === "warning" ? "warn" : "info"
    ](
      `${emoji} [CLIENT ${level.toUpperCase()}]`,
      errorMessage,
      context ? String(context) : ""
    );
    if (errorStack && level === "error") {
      console.error("Stack:", errorStack);
    }
  }

  // Send to Sentry if configured
  if (error instanceof Error) {
    const tags: Record<string, string> = { level };
    if (context?.component) {
      tags["component"] = String(context["component"]);
    }
    if (context?.action) {
      tags["action"] = String(context["action"]);
    }
    captureException(error, {
      tags,
      extra: context,
      user: context?.userId ? { id: context.userId } : undefined,
      level:
        level === "error" ? "error" : level === "warning" ? "warning" : "info",
    });
  }
}

/**
 * Handle API error responses
 * Extracts error message from standardized error response format
 */
export function handleApiError(
  response: Response | { error?: ErrorResponse["error"]; success?: boolean }
): string {
  // Handle Response object
  if (response instanceof Response) {
    // Try to parse JSON error response
    return response.statusText || `HTTP ${String(response.status)} Error`;
  }

  // Handle error response object
  if (response.error) {
    return response.error.message || "An error occurred";
  }

  return "An unexpected error occurred";
}

/**
 * Display error to user via toast notification
 */
export function showErrorToast(
  error: ErrorResponse["error"] | Error | string,
  options?: {
    duration?: number;
    position?:
      | "top-left"
      | "top-center"
      | "top-right"
      | "bottom-left"
      | "bottom-center"
      | "bottom-right";
  }
): void {
  let message: string;

  if (typeof error === "string") {
    message = error;
  } else if (error instanceof Error) {
    message = error.message;
  } else {
    message = error.message || "An error occurred";
  }

  toast.error(message, {
    duration: options?.duration ?? 5000,
    position: options?.position ?? "top-right",
  });
}

/**
 * Type guard to safely convert unknown to Error
 */

function toError(error: unknown): Error {
  if (error instanceof Error) {
    return error;
  }
  return new Error(String(error));
}

/**
 * Handle error in async operations with logging and user notification
 */
export function handleAsyncError(
  error: unknown,
  context?: ClientErrorContext,
  showToast = true
): void {
  const errorObj = toError(error);

  // Log the error
  logClientError(errorObj, context, "error");

  // Show toast to user
  if (showToast) {
    showErrorToast(errorObj.message);
  }
}

/**
 * Handle error in async operations with custom message
 */
export function handleAsyncErrorWithMessage(
  error: unknown,
  userMessage: string,
  context?: ClientErrorContext,
  showToast = true
): void {
  const errorObj = error instanceof Error ? error : new Error(String(error));

  // Log the error with original message
  logClientError(errorObj, context, "error");

  // Show custom message to user
  if (showToast) {
    showErrorToast(userMessage);
  }
}

/**
 * Safe error handler that doesn't throw
 * Useful for non-critical operations
 */
export function handleErrorSafely(
  error: unknown,
  context?: ClientErrorContext,
  fallback?: () => void
): void {
  try {
    handleAsyncError(error, context, false);
    if (fallback) {
      fallback();
    }
  } catch (handlingError) {
    // Even error handling can fail, so we catch it
    console.error("Error in error handler:", handlingError);
  }
}

/**
 * Extract error message from various error types
 */
export function getErrorMessage(error: unknown): string {
  if (typeof error === "string") {
    return error;
  }

  if (error instanceof Error) {
    return error.message;
  }

  if (error && typeof error === "object" && "message" in error) {
    return String(error.message);
  }

  return "An unexpected error occurred";
}

/**
 * Check if error is a network error
 */
export function isNetworkError(error: unknown): boolean {
  if (error instanceof Error) {
    return (
      error.message.includes("fetch") ||
      error.message.includes("network") ||
      error.message.includes("Failed to fetch") ||
      error.name === "NetworkError" ||
      error.name === "TypeError"
    );
  }
  return false;
}

/**
 * Check if error is a timeout error
 */
export function isTimeoutError(error: unknown): boolean {
  if (error instanceof Error) {
    return (
      error.message.includes("timeout") ||
      error.message.includes("Timeout") ||
      error.name === "TimeoutError"
    );
  }
  return false;
}

/**
 * Centralized Error Handling System
 *
 * This module provides a comprehensive error handling system with:
 * - Custom error classes for different error types
 * - Structured error responses
 * - Error logging
 * - Type-safe error handling
 */

/**
 * Base error class for all application errors
 */
export class AppError extends Error {
  public readonly statusCode: number;
  public readonly code: string;
  public readonly isOperational: boolean;
  public readonly context?: Record<string, unknown>;
  public readonly timestamp: string;

  constructor(
    message: string,
    statusCode = 500,
    code = "INTERNAL_ERROR",
    isOperational = true,
    context?: Record<string, unknown>
  ) {
    super(message);
    this.name = this.constructor.name;
    this.statusCode = statusCode;
    this.code = code;
    this.isOperational = isOperational;
    this.context = context;
    this.timestamp = new Date().toISOString();

    // Maintains proper stack trace for where our error was thrown (only available on V8)
    // eslint-disable-next-line @typescript-eslint/no-unnecessary-condition -- Runtime check: Error.captureStackTrace exists in V8 but not in all JS engines
    if (Error.captureStackTrace) {
      Error.captureStackTrace(this, this.constructor);
    }
  }

  toJSON() {
    return {
      name: this.name,
      message: this.message,
      code: this.code,
      statusCode: this.statusCode,
      timestamp: this.timestamp,
      ...(this.context && { context: this.context }),
    };
  }
}

/**
 * Validation errors (400)
 */
export class ValidationError extends AppError {
  constructor(message: string, context?: Record<string, unknown>) {
    super(message, 400, "VALIDATION_ERROR", true, context);
  }
}

/**
 * Authentication errors (401)
 */
export class AuthenticationError extends AppError {
  constructor(
    message = "Authentication required",
    context?: Record<string, unknown>
  ) {
    super(message, 401, "AUTHENTICATION_ERROR", true, context);
  }
}

/**
 * Authorization errors (403)
 */
export class AuthorizationError extends AppError {
  constructor(
    message = "Insufficient permissions",
    context?: Record<string, unknown>
  ) {
    super(message, 403, "AUTHORIZATION_ERROR", true, context);
  }
}

/**
 * Not found errors (404)
 */
export class NotFoundError extends AppError {
  constructor(
    message = "Resource not found",
    context?: Record<string, unknown>
  ) {
    super(message, 404, "NOT_FOUND_ERROR", true, context);
  }
}

/**
 * Conflict errors (409)
 */
export class ConflictError extends AppError {
  constructor(
    message = "Resource conflict",
    context?: Record<string, unknown>
  ) {
    super(message, 409, "CONFLICT_ERROR", true, context);
  }
}

/**
 * Rate limit errors (429)
 */
export class RateLimitError extends AppError {
  constructor(
    message = "Rate limit exceeded",
    context?: Record<string, unknown>
  ) {
    super(message, 429, "RATE_LIMIT_ERROR", true, context);
  }
}

/**
 * External service errors (502, 503, 504)
 */
export class ExternalServiceError extends AppError {
  constructor(
    message: string,
    statusCode = 502,
    context?: Record<string, unknown>
  ) {
    super(message, statusCode, "EXTERNAL_SERVICE_ERROR", true, context);
  }
}

/**
 * Database errors (500)
 */
export class DatabaseError extends AppError {
  constructor(
    message = "Database operation failed",
    context?: Record<string, unknown>
  ) {
    super(message, 500, "DATABASE_ERROR", true, context);
  }
}

/**
 * Type guard to check if error is an AppError
 */
export function isAppError(error: unknown): error is AppError {
  return (
    error instanceof AppError ||
    (typeof error === "object" &&
      error !== null &&
      "statusCode" in error &&
      "code" in error)
  );
}

/**
 * Type guard to check if error is an Error
 */
export function isError(error: unknown): error is Error {
  return error instanceof Error;
}

/**
 * Normalize any error to an AppError
 */
export function normalizeError(error: unknown): AppError {
  if (isAppError(error)) {
    return error;
  }

  if (isError(error)) {
    const message = error.message.trim();

    // Check for common Prisma errors
    if (message.includes("Unique constraint")) {
      return new ConflictError(
        "A record with this information already exists",
        { originalError: error.message }
      );
    }

    if (message.includes("Record to update not found")) {
      return new NotFoundError(
        "The record you're trying to update doesn't exist",
        {
          originalError: error.message,
        }
      );
    }

    // Check for authentication errors
    if (
      message.toLowerCase().includes("authentication required") ||
      message.toLowerCase().includes("authentication error") ||
      message.toLowerCase().includes("not authenticated")
    ) {
      return new AuthenticationError(message, {
        originalError: error.message,
      });
    }

    // Check for authorization/subscription errors
    if (
      message.toLowerCase().includes("subscription required") ||
      message.toLowerCase().includes("subscription error")
    ) {
      return new AuthorizationError(message, {
        originalError: error.message,
      });
    }

    // Check for feature access errors
    if (
      message.toLowerCase().includes("feature access denied") ||
      message.toLowerCase().includes("feature not available")
    ) {
      return new AuthorizationError(message, {
        originalError: error.message,
      });
    }

    // Check for database errors
    if (
      message.toLowerCase().includes("database error") ||
      message.toLowerCase().includes("database connection failed") ||
      message.toLowerCase().includes("database operation failed")
    ) {
      return new DatabaseError(message, {
        originalError: error.message,
      });
    }

    // Generic error - use default message if empty
    const errorMessage =
      message && message !== "" ? message : "An unexpected error occurred";
    return new AppError(errorMessage, 500, "INTERNAL_ERROR", false, {
      originalError: error.message,
    });
  }

  // Unknown error type
  return new AppError(
    "An unexpected error occurred",
    500,
    "UNKNOWN_ERROR",
    false,
    { originalError: String(error) }
  );
}

/**
 * Get user-friendly error message
 */
export function getUserFriendlyMessage(error: AppError): string {
  // Always return the actual message in test/development mode
  const isTestOrDev =
    process.env.NODE_ENV === "test" || process.env.NODE_ENV === "development";

  if (isTestOrDev) {
    return error.message;
  }

  // Don't expose internal errors to users in production
  if (!error.isOperational && process.env.NODE_ENV === "production") {
    return "An unexpected error occurred. Please try again later.";
  }

  return error.message;
}

/**
 * Error codes enum for type safety
 */
export const ErrorCodes = {
  VALIDATION_ERROR: "VALIDATION_ERROR",
  AUTHENTICATION_ERROR: "AUTHENTICATION_ERROR",
  AUTHORIZATION_ERROR: "AUTHORIZATION_ERROR",
  NOT_FOUND_ERROR: "NOT_FOUND_ERROR",
  CONFLICT_ERROR: "CONFLICT_ERROR",
  RATE_LIMIT_ERROR: "RATE_LIMIT_ERROR",
  EXTERNAL_SERVICE_ERROR: "EXTERNAL_SERVICE_ERROR",
  DATABASE_ERROR: "DATABASE_ERROR",
  INTERNAL_ERROR: "INTERNAL_ERROR",
  UNKNOWN_ERROR: "UNKNOWN_ERROR",
};

export type ErrorCode = (typeof ErrorCodes)[keyof typeof ErrorCodes];

/**
 * Hardened fetch wrapper with timeouts, retries, and structured error handling
 *
 * This module provides a robust fetch wrapper that:
 * - Enforces timeouts on all requests
 * - Implements retry logic with exponential backoff
 * - Provides typed error responses
 * - Includes correlation IDs for request tracking
 * - Handles common failure modes (network errors, timeouts, rate limits)
 *
 * Usage:
 *   import { fetchWithRetry } from "~/lib/fetch.server";
 *   const response = await fetchWithRetry(url, options);
 */

import { v4 as uuidv4 } from "uuid";

import { logError } from "~/lib/error-logger.server";

/**
 * Structured error types for fetch operations
 */
export class FetchError extends Error {
  constructor(
    message: string,
    public readonly status?: number,
    public readonly statusText?: string,
    public readonly correlationId?: string,
    public readonly retries?: number,
  ) {
    super(message);
    this.name = "FetchError";
  }
}

export class FetchTimeoutError extends FetchError {
  constructor(
    message: string,
    public readonly timeout: number,
    correlationId?: string,
  ) {
    super(message, undefined, undefined, correlationId);
    this.name = "FetchTimeoutError";
  }
}

export class FetchNetworkError extends FetchError {
  constructor(
    message: string,
    public readonly originalError: unknown,
    correlationId?: string,
  ) {
    super(message, undefined, undefined, correlationId);
    this.name = "FetchNetworkError";
  }
}

export class FetchRateLimitError extends FetchError {
  constructor(
    message: string,
    public readonly retryAfter?: number,
    correlationId?: string,
  ) {
    super(message, 429, "Too Many Requests", correlationId);
    this.name = "FetchRateLimitError";
  }
}

/**
 * Options for fetchWithRetry
 */
export interface FetchRetryOptions extends RequestInit {
  /**
   * Timeout in milliseconds (default: 10000)
   */
  timeout?: number;

  /**
   * Maximum number of retries (default: 2)
   */
  maxRetries?: number;

  /**
   * Base delay for exponential backoff in milliseconds (default: 1000)
   */
  retryDelay?: number;

  /**
   * Custom correlation ID (auto-generated if not provided)
   */
  correlationId?: string;

  /**
   * Whether to retry on 5xx errors (default: true)
   */
  retryOn5xx?: boolean;

  /**
   * Whether to retry on network errors (default: true)
   */
  retryOnNetworkError?: boolean;

  /**
   * Custom function to determine if a response should be retried
   */
  shouldRetry?: (response: Response, attempt: number) => boolean;
}

/**
 * Default fetch options
 */
const DEFAULT_OPTIONS: Required<
  Pick<
    FetchRetryOptions,
    | "timeout"
    | "maxRetries"
    | "retryDelay"
    | "retryOn5xx"
    | "retryOnNetworkError"
  >
> = {
  timeout: 10000, // 10 seconds
  maxRetries: 2,
  retryDelay: 1000, // 1 second base delay
  retryOn5xx: true,
  retryOnNetworkError: true,
};

/**
 * Creates an AbortController that aborts after the specified timeout
 */
function createTimeoutController(timeout: number): AbortController {
  const controller = new AbortController();
  setTimeout(() => {
    controller.abort();
  }, timeout);

  // Note: The timeout will fire and abort the request if it takes too long
  // If the request completes before timeout, the abort signal will be ignored
  return controller;
}

/**
 * Calculates exponential backoff delay with jitter
 */
function calculateBackoffDelay(attempt: number, baseDelay: number): number {
  const exponentialDelay = baseDelay * Math.pow(2, attempt);
  // Add jitter (±25%) to prevent thundering herd
  const jitter = exponentialDelay * 0.25 * (Math.random() * 2 - 1);
  return Math.min(exponentialDelay + jitter, 30000); // Cap at 30 seconds
}

/**
 * Determines if a response should be retried
 */
function shouldRetryResponse(
  response: Response,
  attempt: number,
  maxRetries: number,
  retryOn5xx: boolean,
  customShouldRetry?: (response: Response, attempt: number) => boolean,
): boolean {
  if (attempt >= maxRetries) {
    return false;
  }

  // Use custom retry logic if provided
  if (customShouldRetry) {
    return customShouldRetry(response, attempt);
  }

  // Retry on 5xx errors if enabled
  if (retryOn5xx && response.status >= 500 && response.status < 600) {
    return true;
  }

  // Retry on 429 (rate limit) with exponential backoff
  if (response.status === 429) {
    return true;
  }

  // Don't retry on client errors (4xx except 429)
  if (response.status >= 400 && response.status < 500) {
    return false;
  }

  // Don't retry on success
  if (response.status >= 200 && response.status < 300) {
    return false;
  }

  return false;
}

/**
 * Hardened fetch with timeout, retries, and structured error handling
 *
 * @param url - The URL to fetch
 * @param options - Fetch options including retry configuration
 * @returns Promise resolving to Response
 * @throws FetchError, FetchTimeoutError, FetchNetworkError, or FetchRateLimitError
 */
export async function fetchWithRetry(
  url: string | URL,
  options: FetchRetryOptions = {},
): Promise<Response> {
  const {
    timeout = DEFAULT_OPTIONS.timeout,
    maxRetries = DEFAULT_OPTIONS.maxRetries,
    retryDelay = DEFAULT_OPTIONS.retryDelay,
    retryOn5xx = DEFAULT_OPTIONS.retryOn5xx,
    retryOnNetworkError = DEFAULT_OPTIONS.retryOnNetworkError,
    correlationId = uuidv4(),
    shouldRetry: customShouldRetry,
    ...fetchOptions
  } = options;

  let lastError: Error | undefined;
  let lastResponse: Response | undefined;

  for (let attempt = 0; attempt <= maxRetries; attempt++) {
    try {
      // Create timeout controller for this attempt
      const timeoutController = createTimeoutController(timeout);

      // Merge abort signals if both are provided
      const abortController = new AbortController();
      if (fetchOptions.signal) {
        // If original signal aborts, abort our controller
        fetchOptions.signal.addEventListener("abort", () => {
          abortController.abort();
        });
      }
      timeoutController.signal.addEventListener("abort", () => {
        abortController.abort();
      });

      // Make the fetch request
      const response = await fetch(url, {
        ...fetchOptions,
        signal: abortController.signal,
        headers: {
          ...fetchOptions.headers,
          "X-Correlation-Id": correlationId,
        },
      });

      // Check if we should retry
      if (
        shouldRetryResponse(
          response,
          attempt,
          maxRetries,
          retryOn5xx,
          customShouldRetry,
        )
      ) {
        lastResponse = response;

        // Handle rate limiting
        if (response.status === 429) {
          const retryAfter = response.headers.get("Retry-After");
          const retryAfterSeconds = retryAfter
            ? parseInt(retryAfter, 10)
            : undefined;

          if (attempt < maxRetries) {
            const delay = retryAfterSeconds
              ? retryAfterSeconds * 1000
              : calculateBackoffDelay(attempt, retryDelay);

            logError(
              new FetchRateLimitError(
                `Rate limited (429) on attempt ${attempt + 1}/${maxRetries + 1}`,
                retryAfterSeconds,
                correlationId,
              ),
              {
                url: String(url),
                attempt: attempt + 1,
                maxRetries: maxRetries + 1,
                delay,
                correlationId,
              },
            );

            await new Promise((resolve) => setTimeout(resolve, delay));
            continue;
          } else {
            throw new FetchRateLimitError(
              `Rate limited after ${maxRetries + 1} attempts`,
              retryAfterSeconds,
              correlationId,
            );
          }
        }

        // Retry on 5xx errors
        if (response.status >= 500 && response.status < 600) {
          if (attempt < maxRetries) {
            const delay = calculateBackoffDelay(attempt, retryDelay);

            logError(
              new FetchError(
                `Server error (${response.status}) on attempt ${attempt + 1}/${maxRetries + 1}`,
                response.status,
                response.statusText,
                correlationId,
                attempt + 1,
              ),
              {
                url: String(url),
                attempt: attempt + 1,
                maxRetries: maxRetries + 1,
                delay,
                correlationId,
              },
            );

            await new Promise((resolve) => setTimeout(resolve, delay));
            continue;
          }
        }
      }

      // Success or non-retryable error
      return response;
    } catch (error) {
      lastError = error instanceof Error ? error : new Error(String(error));

      // Handle AbortError (timeout)
      if (error instanceof Error && error.name === "AbortError") {
        if (attempt < maxRetries && retryOnNetworkError) {
          const delay = calculateBackoffDelay(attempt, retryDelay);

          logError(
            new FetchTimeoutError(
              `Request timeout after ${timeout}ms on attempt ${attempt + 1}/${maxRetries + 1}`,
              timeout,
              correlationId,
            ),
            {
              url: String(url),
              attempt: attempt + 1,
              maxRetries: maxRetries + 1,
              delay,
              correlationId,
            },
          );

          await new Promise((resolve) => setTimeout(resolve, delay));
          continue;
        } else {
          throw new FetchTimeoutError(
            `Request timeout after ${timeout}ms (${maxRetries + 1} attempts)`,
            timeout,
            correlationId,
          );
        }
      }

      // Handle network errors
      if (
        error instanceof TypeError ||
        (error instanceof Error &&
          (error.message.includes("fetch") ||
            error.message.includes("network") ||
            error.message.includes("ECONNREFUSED") ||
            error.message.includes("ENOTFOUND")))
      ) {
        if (attempt < maxRetries && retryOnNetworkError) {
          const delay = calculateBackoffDelay(attempt, retryDelay);

          logError(
            new FetchNetworkError(
              `Network error on attempt ${attempt + 1}/${maxRetries + 1}: ${error.message}`,
              error,
              correlationId,
            ),
            {
              url: String(url),
              attempt: attempt + 1,
              maxRetries: maxRetries + 1,
              delay,
              correlationId,
            },
          );

          await new Promise((resolve) => setTimeout(resolve, delay));
          continue;
        } else {
          throw new FetchNetworkError(
            `Network error after ${maxRetries + 1} attempts: ${error.message}`,
            error,
            correlationId,
          );
        }
      }

      // Re-throw unknown errors
      throw error;
    }
  }

  // If we get here, we've exhausted retries
  if (lastResponse) {
    throw new FetchError(
      `Request failed after ${maxRetries + 1} attempts with status ${lastResponse.status}`,
      lastResponse.status,
      lastResponse.statusText,
      correlationId,
      maxRetries + 1,
    );
  }

  if (lastError) {
    throw new FetchNetworkError(
      `Request failed after ${maxRetries + 1} attempts: ${lastError.message}`,
      lastError,
      correlationId,
    );
  }

  throw new FetchError(
    `Request failed after ${maxRetries + 1} attempts`,
    undefined,
    undefined,
    correlationId,
    maxRetries + 1,
  );
}

/**
 * Convenience wrapper for JSON requests with retry
 */
export async function fetchJsonWithRetry<T = unknown>(
  url: string | URL,
  options: FetchRetryOptions = {},
): Promise<T> {
  const response = await fetchWithRetry(url, {
    ...options,
    headers: {
      "Content-Type": "application/json",
      ...options.headers,
    },
  });

  if (!response.ok) {
    throw new FetchError(
      `JSON request failed with status ${response.status}`,
      response.status,
      response.statusText,
      options.correlationId,
    );
  }

  return response.json() as Promise<T>;
}

/**
 * Canonical Nostr Adapter (Client-side)
 *
 * This module provides a unified interface for client-side Nostr operations.
 * It wraps window.nostr (NIP-07) and nostr-tools for consistent event signing.
 *
 * Usage:
 *   import { nostrAdapter } from "~/lib/nostr-adapter.client";
 *   const result = await nostrAdapter.signEvent(eventData);
 */

import { nip19 } from "nostr-tools";

import type {
  NostrEvent,
  SignedEvent,
  SignEventResult,
  NostrEventData,
  LongFormEventData,
} from "~/features/nostr/types";

/**
 * Canonical Nostr adapter for client-side operations
 */
export const nostrAdapter = {
  /**
   * Encode hex public key to npub (bech32)
   */
  encodeNpub(hex: string): string | null {
    try {
      return nip19.npubEncode(hex);
    } catch {
      return null;
    }
  },

  /**
   * Decode npub (bech32) to hex public key
   */
  decodeNpub(npub: string): string | null {
    try {
      if (!npub.startsWith("npub")) {
        return npub; // Already hex
      }
      const { data } = nip19.decode(npub);
      return typeof data === "string" ? data : null;
    } catch {
      return null;
    }
  },

  /**
   * Sign an event using NIP-07 (window.nostr)
   * This is the canonical way to sign events client-side
   */
  async signEvent(eventData: NostrEventData): Promise<SignEventResult> {
    try {
      // Add retry logic to handle extension loading
      let retries = 0;
      const maxRetries = 5;

      while (retries < maxRetries) {
        // @ts-ignore - window.nostr is injected by browser extensions at runtime
        if (window.nostr) {
          const nostrEvent: NostrEvent = {
            content: eventData.content,
            created_at: eventData.created_at,
            kind: eventData.kind ?? 1,
            tags: eventData.tags ?? [],
          };

          // @ts-ignore - window.nostr is injected by browser extensions at runtime
          const signResult = await window.nostr.signEvent(nostrEvent);

          // Handle different return types from different extensions
          // TypeScript knows signResult is SignedEvent, but some extensions return string
          const signedEvent: SignedEvent = {
            id: typeof signResult === "string" ? "unknown" : signResult.id,
            pubkey:
              typeof signResult === "string" ? "unknown" : signResult.pubkey,
            created_at: nostrEvent.created_at,
            kind: nostrEvent.kind,
            tags: nostrEvent.tags,
            content: nostrEvent.content,
            sig: typeof signResult === "string" ? signResult : signResult.sig,
          };

          return { nostrEvent, signedEvent };
        }

        retries++;
        await new Promise((resolve) => setTimeout(resolve, 500));
      }

      throw new Error(
        "Nostr extension not found after retries. Please install a Nostr extension."
      );
    } catch (error) {
      // Only log on client side
      if (typeof window !== "undefined") {
        // @ts-ignore - Dynamic imports work in client-side Remix bundles
        const { logClientError } = await import("~/lib/error-handler.client");
        logClientError(
          error instanceof Error ? error : new Error(String(error)),
          {
            component: "nostr-adapter",
            action: "signEvent",
          },
          "error"
        );
      }
      throw error;
    }
  },

  /**
   * Sign a long-form event (NIP-23) using NIP-07
   */
  async signLongFormEvent(
    eventData: LongFormEventData
  ): Promise<SignEventResult> {
    try {
      // Add retry logic to handle extension loading
      let retries = 0;
      const maxRetries = 5;

      while (retries < maxRetries) {
        // @ts-ignore - window.nostr is injected by browser extensions at runtime
        if (window.nostr) {
          // Build NIP-23 tags
          const eventTags: string[][] = [];

          if (eventData.title) {
            eventTags.push(["title", eventData.title]);
          }
          eventTags.push(["r", "wss://relay.primal.net/"]);
          eventTags.push(["client", "SmartFlow"]);
          if (eventData.summary) {
            eventTags.push(["summary", eventData.summary]);
          }
          if (eventData.image) {
            eventTags.push(["image", eventData.image]);
          }
          if (eventData.identifier) {
            eventTags.push(["d", eventData.identifier]);
          }
          if (eventData.publishedAt) {
            eventTags.push(["published_at", eventData.publishedAt.toString()]);
          }
          if (eventData.tags && eventData.tags.length > 0) {
            eventData.tags.forEach((tag) => {
              if (tag.trim()) {
                eventTags.push(["t", tag.trim().toLowerCase()]);
              }
            });
          }

          const nostrEvent: NostrEvent = {
            content: eventData.content,
            created_at: Math.floor(Date.now() / 1000),
            kind: 30023, // NIP-23 long-form content
            tags: eventTags,
          };

          // @ts-ignore - window.nostr is injected by browser extensions at runtime
          const signResult = await window.nostr.signEvent(nostrEvent);

          // Handle different return types from different extensions
          // TypeScript knows signResult is SignedEvent, but some extensions return string
          const signedEvent: SignedEvent = {
            id: typeof signResult === "string" ? "unknown" : signResult.id,
            pubkey:
              typeof signResult === "string" ? "unknown" : signResult.pubkey,
            created_at: nostrEvent.created_at,
            kind: nostrEvent.kind,
            tags: nostrEvent.tags,
            content: nostrEvent.content,
            sig: typeof signResult === "string" ? signResult : signResult.sig,
          };

          return { nostrEvent, signedEvent };
        }

        retries++;
        await new Promise((resolve) => setTimeout(resolve, 500));
      }

      throw new Error(
        "Nostr extension not found after retries. Please install a Nostr extension."
      );
    } catch (error) {
      // Only log on client side
      if (typeof window !== "undefined") {
        // @ts-ignore - Dynamic imports work in client-side Remix bundles
        const { logClientError } = await import("~/lib/error-handler.client");
        logClientError(
          error instanceof Error ? error : new Error(String(error)),
          {
            component: "nostr-adapter",
            action: "signLongFormEvent",
          },
          "error"
        );
      }
      throw error;
    }
  },
};

/**
 * Re-export types for convenience
 */
export type {
  NostrEvent,
  SignedEvent,
  SignEventResult,
} from "~/features/nostr/types";

import { nip04, finalizeEvent, nip19 } from "nostr-tools";

import { logWarning, logError } from "~/lib/error-logger.server";

import { convertToHex } from "./nostr-conversion";
import { relaysArray } from "./relays";

interface SendNostrDirectMessageResult {
  success: boolean;
  event?: unknown;
  status?: number;
  error?: string;
}

export async function sendNostrDirectMessage(
  receiverPubkey: string,
  content: string
): Promise<SendNostrDirectMessageResult | false> {
  try {
    if (!content) {
      return Promise.resolve(false);
    }
    const nsecEnv = process.env["NOSTR_NSEC"];
    if (!nsecEnv) {
      return Promise.resolve({
        success: false,
        error: "NOSTR_NSEC is not set.",
      });
    }
    const nsecHex: string | null = convertToHex(nsecEnv);

    if (!nsecHex) {
      return {
        success: false,
        error: "NOSTR_NSEC could not be converted to hex.",
      };
    }

    // Convert hex string to Uint8Array for finalizeEvent
    let privateKeyBytes: Uint8Array;
    try {
      if (nsecEnv.startsWith("nsec")) {
        const decoded = nip19.decode(nsecEnv);
        if (decoded.type === "nsec") {
          privateKeyBytes = decoded.data;
        } else {
          throw new Error("Invalid nsec format");
        }
      } else {
        // Assume hex string
        privateKeyBytes = new Uint8Array(
          nsecHex.match(/.{1,2}/g)?.map((byte) => parseInt(byte, 16)) ?? []
        );
      }
    } catch {
      // Fallback: treat as hex string
      privateKeyBytes = new Uint8Array(
        nsecHex.match(/.{1,2}/g)?.map((byte) => parseInt(byte, 16)) ?? []
      );
    }

    // Ensure receiver pubkey is hex. Convert if an npub/bech32 is provided.
    let receiverHex: string = receiverPubkey;
    try {
      if (
        typeof receiverPubkey === "string" &&
        receiverPubkey.startsWith("npub")
      ) {
        const converted = convertToHex(receiverPubkey);
        if (converted) receiverHex = converted;
      }
    } catch (e) {
      logWarning(
        "Failed to convert receiver pubkey to hex; using original value",
        {
          receiverPubkey,
          error: e instanceof Error ? e.message : String(e),
        }
      );
    }

    // Encrypt the content
    const encryptedContent: string = nip04.encrypt(
      nsecHex,
      receiverHex,
      content
    );

    // Create event template
    const eventTemplate = {
      kind: 4, // NIP-04 encrypted direct message
      created_at: Math.floor(Date.now() / 1000),
      tags: [
        ["p", receiverHex], // Recipient's pubkey
      ],
      content: encryptedContent,
    };

    // Sign the event
    const signedEvent = finalizeEvent(eventTemplate, privateKeyBytes);

    // Send the event to the publisher
    const publisherUrl = process.env["NOSTR_PUBLISHER_URL"];
    if (!publisherUrl) {
      return {
        success: false,
        error: "NOSTR_PUBLISHER_URL is not set.",
        event: signedEvent,
      };
    }

    const response = await fetch(publisherUrl, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
      },
      body: JSON.stringify({
        relays: relaysArray,
        event: signedEvent,
      }),
    });

    if (!response.ok) {
      let errorText = "";
      try {
        errorText = await response.text();
      } catch (_err) {
        // ignore
      }
      return {
        success: false,
        status: response.status,
        error: errorText,
        event: signedEvent,
      };
    }

    return { success: true, event: signedEvent };
  } catch (error: unknown) {
    logError(error instanceof Error ? error : new Error(String(error)), {
      receiverPubkey,
      message: "Error sending Nostr direct message",
    });
    const errorMessage = error instanceof Error ? error.message : String(error);
    return {
      success: false,
      error: errorMessage,
    };
  }
}

/**
 * Security utilities for CSRF protection and request validation
 *
 * This module provides utilities for validating request origins and protecting
 * against CSRF attacks.
 */

import { env } from "./env.server";

/**
 * CSRF validation error
 */
export class CSRFValidationError extends Error {
  constructor(message: string) {
    super(message);
    this.name = "CSRFValidationError";
  }
}

/**
 * Validates Origin header for CSRF protection
 *
 * @param request - The incoming request
 * @throws {CSRFValidationError} If origin validation fails
 */
export function validateOrigin(request: Request): void {
  const origin = request.headers.get("Origin");
  const referer = request.headers.get("Referer");

  // Allow same-origin requests (no Origin header)
  // This handles same-origin form submissions and navigation
  if (!origin && !referer) {
    return; // Same-origin request, allow it
  }

  // Get allowed origins from env
  const allowedOrigins: string[] = [];

  // Add APP_URL if set
  if (env.APP_URL) {
    try {
      const appUrl = new URL(env.APP_URL);
      allowedOrigins.push(appUrl.origin);
    } catch (_error) {
      console.warn("Invalid APP_URL in environment:", env.APP_URL);
    }
  }

  // Add ALLOWED_ORIGINS if set (comma-separated)
  if (env.ALLOWED_ORIGINS) {
    const origins = env.ALLOWED_ORIGINS.split(",").map((o) => o.trim());
    for (const originStr of origins) {
      try {
        const originUrl = new URL(originStr);
        allowedOrigins.push(originUrl.origin);
      } catch (_error) {
        console.warn("Invalid origin in ALLOWED_ORIGINS:", originStr);
      }
    }
  }

  // If no allowed origins configured, default to same-origin only
  // In development, allow localhost origins
  const isDevelopment = env.NODE_ENV === "development";
  if (allowedOrigins.length === 0 && !isDevelopment) {
    // In production without configuration, only allow same-origin
    // This is strict but safe
    if (origin || referer) {
      throw new CSRFValidationError(
        "CSRF protection enabled but no allowed origins configured"
      );
    }
    return;
  }

  // In development, add localhost origins
  if (isDevelopment) {
    allowedOrigins.push("http://localhost:3000");
    allowedOrigins.push("http://127.0.0.1:3000");
  }

  // Validate Origin if present (preferred header)
  if (origin) {
    try {
      const originUrl = new URL(origin);
      const isValid = allowedOrigins.some((allowed) => {
        try {
          const allowedUrl = new URL(allowed);
          return originUrl.origin === allowedUrl.origin;
        } catch {
          return false;
        }
      });

      if (!isValid) {
        throw new CSRFValidationError(
          `Invalid origin: ${origin}. Allowed origins: ${allowedOrigins.join(", ")}`
        );
      }
      return; // Origin is valid
    } catch (error) {
      if (error instanceof CSRFValidationError) {
        throw error;
      }
      throw new CSRFValidationError(`Invalid origin header format: ${origin}`);
    }
  }

  // Fallback to Referer if Origin not present (some browsers don't send Origin for same-origin)
  if (!origin && referer) {
    try {
      const refererUrl = new URL(referer);
      const isValid = allowedOrigins.some((allowed) => {
        try {
          const allowedUrl = new URL(allowed);
          return refererUrl.origin === allowedUrl.origin;
        } catch {
          return false;
        }
      });

      if (!isValid) {
        throw new CSRFValidationError(
          `Invalid referer: ${referer}. Allowed origins: ${allowedOrigins.join(", ")}`
        );
      }
      return; // Referer is valid
    } catch (error) {
      if (error instanceof CSRFValidationError) {
        throw error;
      }
      throw new CSRFValidationError(`Invalid referer header format: ${referer}`);
    }
  }
}

/**
 * Checks if a request method is state-changing
 */
export function isStateChangingMethod(method: string): boolean {
  return ["POST", "PUT", "PATCH", "DELETE"].includes(method.toUpperCase());
}

/**
 * Validation utilities for HashTagPreset from loader responses
 * Replaces unsafe type casts with runtime validation
 */

import { z } from "zod";

import type { HashTagPreset } from "~/features/posts/types";
import { logError } from "~/lib/error-logger.server";

import { hashTagPresetSchema } from "./schemas/loader-responses.schemas";

/**
 * Safely validate and convert unknown array to HashTagPreset[]
 * Returns empty array if validation fails (logs error but doesn't throw)
 * Normalizes createdAt/updatedAt from string | Date to Date | undefined
 */
export function validateHashTagPresets(
  value: unknown,
): HashTagPreset[] {
  if (!Array.isArray(value)) {
    return [];
  }

  const validated: HashTagPreset[] = [];

  for (const item of value) {
    try {
      const parsed = hashTagPresetSchema.parse(item);
      // Normalize createdAt/updatedAt from string | Date to Date | undefined
      validated.push({
        id: parsed.id,
        name: parsed.name,
        tags: parsed.tags,
        description: parsed.description,
        userId: parsed.userId,
        createdAt: parsed.createdAt instanceof Date 
          ? parsed.createdAt 
          : typeof parsed.createdAt === "string" 
            ? new Date(parsed.createdAt) 
            : undefined,
        updatedAt: parsed.updatedAt instanceof Date 
          ? parsed.updatedAt 
          : typeof parsed.updatedAt === "string" 
            ? new Date(parsed.updatedAt) 
            : undefined,
      });
    } catch (error) {
      if (error instanceof z.ZodError) {
        logError(error, {
          message: "Invalid HashTagPreset structure in array",
          context: { issues: error.issues, item: JSON.stringify(item) },
        });
      }
      // Skip invalid items, continue with valid ones
    }
  }

  return validated;
}

