export function reschedulePost({
  id,
  userId,
  newScheduledFor,
  overrideQueue,
  signedEvent,
  nostrEvent,
  queueTypeId,
}: {
  id: string;
  userId: string;
  newScheduledFor: string;
  overrideQueue: boolean;
  signedEvent?: SignedEvent;
  nostrEvent?: NostrEvent;
  queueTypeId?: string | null;
}): Promise<Post> {
  const updateData: Prisma.PostUpdateInput = {
    scheduledFor: newScheduledFor,
    manual_override: overrideQueue,
    updatedAt: new Date(),
  };

  // If new signed events are provided, update them, otherwise clear them
  if (signedEvent && nostrEvent) {
    // Prisma expects InputJsonValue for these fields
    updateData.signedEvent = signedEvent as unknown as Prisma.InputJsonValue;
    updateData.nostrEvent = nostrEvent as unknown as Prisma.InputJsonValue;
    updateData.nostrEventId = signedEvent.id;
  } else {
    // Clear signed event since timing changed - needs re-signing
    updateData.signedEvent = Prisma.DbNull;
    updateData.nostrEvent = Prisma.DbNull;
    updateData.nostrEventId = null;
  }

  // Handle queueTypeId connection/disconnection
  if (queueTypeId !== undefined) {
    if (queueTypeId) {
      updateData.queueType = {
        connect: {
          id: queueTypeId,
        },
      };
    } else {
      updateData.queueType = {
        disconnect: true,
      };
    }
  }

  return prisma.post.update({
    where: {
      id,
      userId,
    },
    data: updateData,
  });
}

export function updatePost({
  id,
  userId,
  data,
}: {
  id: string;
  userId: string;
  data: Partial<CreatePostData>;
}): Promise<Post> {
  // Prepare the update data
  const updateData: Prisma.PostUpdateInput = {
    updatedAt: new Date(),
  };

  // Only include defined fields
  if (data.scheduledFor !== undefined)
    updateData.scheduledFor = data.scheduledFor.toString();
  if (data.userId !== undefined)
    updateData.user = { connect: { id: data.userId } };
  if (data.content !== undefined) updateData.content = data.content;
  if (data.caption !== undefined) updateData.caption = data.caption;
  if (data.postedAt !== undefined) updateData.postedAt = data.postedAt;
  if (data.fileUrl !== undefined) updateData.fileUrl = data.fileUrl;
  if (data.nostrEventId !== undefined)
    updateData.nostrEventId = data.nostrEventId;
  if (data.signedEvent !== undefined)
    updateData.signedEvent =
      data.signedEvent as unknown as Prisma.InputJsonValue;
  if (data.nostrEvent !== undefined)
    updateData.nostrEvent = data.nostrEvent as unknown as Prisma.InputJsonValue;
  if (data.tags !== undefined) updateData.tags = data.tags;
  // Note: status, isPublished, isScheduled, draft are Prisma Post model fields, not in CreatePostData
  // They should be set via separate update calls if needed
  if (data.draft !== undefined) updateData.draft = data.draft;
  if (data.isScheduled !== undefined) updateData.isScheduled = data.isScheduled;
  // templateId is not in CreatePostData, handle separately if needed
  if ("templateId" in data && data.templateId !== undefined) {
    if (data.templateId === null) {
      updateData.template = { disconnect: true };
    } else {
      updateData.template = { connect: { id: String(data.templateId) } };
    }
  }
  if (data.hashTagPresetId !== undefined) {
    if (data.hashTagPresetId === null) {
      updateData.hashTagPreset = { disconnect: true };
    } else {
      updateData.hashTagPreset = { connect: { id: data.hashTagPresetId } };
    }
  }

  // Handle queueTypeId connection/disconnection
  if (data.queueTypeId !== undefined) {
    if (data.queueTypeId) {
      updateData.queueType = {
        connect: {
          id: data.queueTypeId,
        },
      };
    } else {
      // Disconnect from queue type if null
      updateData.queueType = {
        disconnect: true,
      };
    }
  }

  return prisma.post.update({
    where: {
      id,
      userId,
    },
    data: updateData,
  });
}

import { json, type LoaderFunctionArgs } from "@remix-run/node";

import { ValidationError, ExternalServiceError } from "~/lib/errors";

type AssertFunction = (
  condition: boolean,
  message: string,
  context?: Record<string, unknown>
) => asserts condition;

export async function loader({ request }: LoaderFunctionArgs) {
  try {
    const errorHandler = await import("~/lib/error-handler.server");
    const assert: AssertFunction = errorHandler.assert;

    const url = new URL(request.url);
    const targetUrlParam = url.searchParams.get("url");

    assert(targetUrlParam !== null, "URL parameter is required", {
      searchParams: Array.from(url.searchParams.entries()),
    });

    const targetUrl = targetUrlParam;

    // Validate URL format
    try {
      new URL(targetUrl);
    } catch {
      throw new ValidationError("Invalid URL format", { targetUrl });
    }

    assert(
      targetUrl.startsWith("http://") || targetUrl.startsWith("https://"),
      "URL must start with http:// or https://",
      { targetUrl }
    );

    // Fetch the URL
    let response: Response;
    try {
      response = await fetch(targetUrl, {
        headers: {
          "User-Agent": "Mozilla/5.0 (compatible; LinkPreview/1.0)",
        },
        signal: AbortSignal.timeout(5000),
      });
    } catch (error) {
      throw new ExternalServiceError("Failed to fetch URL", 502, {
        service: "LinkPreview",
        targetUrl,
        originalError: error instanceof Error ? error.message : String(error),
      });
    }

    if (!response.ok) {
      throw new ExternalServiceError(
        `Failed to fetch URL: HTTP ${response.status}`,
        response.status >= 500 ? 502 : response.status,
        {
          service: "LinkPreview",
          targetUrl,
          status: response.status,
          statusText: response.statusText,
        }
      );
    }

    let html: string;
    try {
      html = await response.text();
    } catch (error) {
      throw new ExternalServiceError("Failed to read response from URL", 502, {
        service: "LinkPreview",
        targetUrl,
        originalError: error instanceof Error ? error.message : String(error),
      });
    }

    const titleMatch = html.match(/<title[^>]*>([^<]+)<\/title>/i);
    const descriptionMatch =
      html.match(
        /<meta[^>]*name=["']description["'][^>]*content=["']([^"']+)["'][^>]*>/i
      ) || // eslint-disable-line @typescript-eslint/prefer-nullish-coalescing -- Boolean OR for trying multiple regex patterns
      html.match(
        /<meta[^>]*content=["']([^"']+)["'][^>]*name=["']description["'][^>]*>/i
      );
    const imageMatch =
      html.match(
        /<meta[^>]*property=["']og:image["'][^>]*content=["']([^"']+)["'][^>]*>/i
      ) || // eslint-disable-line @typescript-eslint/prefer-nullish-coalescing -- Boolean OR for trying multiple regex patterns
      html.match(
        /<meta[^>]*content=["']([^"']+)["'][^>]*property=["']og:image["'][^>]*>/i
      );

    const title = titleMatch?.[1] ? titleMatch[1].trim() : "";
    const description = descriptionMatch?.[1] ? descriptionMatch[1].trim() : "";
    const image = imageMatch?.[1] ? imageMatch[1].trim() : "";

    return {
      success: 1,
      meta: {
        title,
        description,
        image: {
          url: image,
        },
      },
    };
  } catch (error) {
    // If error is a Response (e.g., redirect from requireUserId), return it
    if (error instanceof Response) {
      return error;
    }
    // Use dynamic import to avoid bundling issues
    const { createErrorResponse } = await import("~/lib/error-handler.server");
    const [errorResponse, statusCode] = createErrorResponse(error);
    return json(
      { success: false, error: errorResponse.error },
      { status: statusCode }
    );
  }
}

import { json } from "@remix-run/node";
import type { ActionFunctionArgs } from "@remix-run/node";

import { requireUserId } from "~/features/auth";
import { withCSRFProtection } from "~/lib/csrf";
import { ValidationError, ExternalServiceError } from "~/lib/errors";

const CONTENT_TYPE_JSON = "application/json";

type AssertFunction = (
  condition: boolean,
  message: string,
  context?: Record<string, unknown>
) => asserts condition;

export const action = withCSRFProtection(
  async ({ request }: ActionFunctionArgs) => {
    try {
      const errorHandler = await import("~/lib/error-handler.server");
      const assert: AssertFunction = errorHandler.assert;

      // Validate HTTP method
      assert(request.method === "POST", "Method not allowed", {
        method: request.method,
      });

      // Ensure user is authenticated
      await requireUserId(request);

      // Parse and validate request body
      let bodyRaw: unknown;
      try {
        bodyRaw = await request.json();
      } catch (error) {
        throw new ValidationError("Invalid JSON in request body", {
          originalError: error instanceof Error ? error.message : String(error),
        });
      }

      const body =
        typeof bodyRaw === "object" && bodyRaw !== null
          ? (bodyRaw as { relays?: unknown; event?: unknown })
          : {};
      const { relays, event } = body;

      // Validate event
      assert(event !== null && event !== undefined, "Event is required", {
        hasEvent: event !== null && event !== undefined,
      });

      // Validate relays
      assert(
        Array.isArray(relays) && relays.length > 0,
        "Relays array is required and must not be empty",
        { relaysType: typeof relays, isArray: Array.isArray(relays) }
      );

      // Validate NOSTR_PUBLISHER_URL is configured
      const publisherUrl = process.env["NOSTR_PUBLISHER_URL"];
      assert(
        publisherUrl !== undefined && publisherUrl !== "",
        "NOSTR publisher URL is not configured"
      );

      // Publish to NOSTR_PUBLISHER_URL
      let publishResponse: Response;
      try {
        publishResponse = await fetch(publisherUrl, {
          method: "POST",
          headers: {
            "Content-Type": CONTENT_TYPE_JSON,
          },
          body: JSON.stringify({
            relays,
            event,
          }),
        });
      } catch (error) {
        throw new ExternalServiceError(
          "Failed to connect to NOSTR publisher service",
          503,
          {
            service: "NOSTR_PUBLISHER",
            originalError:
              error instanceof Error ? error.message : String(error),
          }
        );
      }

      if (!publishResponse.ok) {
        const errorText = await publishResponse
          .text()
          .catch(() => "Unknown error");
        throw new ExternalServiceError(
          `Failed to publish to nostr: ${publishResponse.status}`,
          publishResponse.status >= 500 ? 502 : publishResponse.status,
          {
            service: "NOSTR_PUBLISHER",
            status: publishResponse.status,
            statusText: publishResponse.statusText,
            errorText,
          }
        );
      }

      // Handle both JSON and text responses
      const contentType = publishResponse.headers.get("content-type");
      let result: unknown;

      try {
        if (
          contentType &&
          typeof contentType === "string" &&
          contentType.includes(CONTENT_TYPE_JSON)
        ) {
          const jsonResult: unknown = await publishResponse.json();
          result = jsonResult;
        } else {
          result = await publishResponse.text();
        }
      } catch (error) {
        throw new ExternalServiceError(
          "Failed to parse response from NOSTR publisher",
          502,
          {
            service: "NOSTR_PUBLISHER",
            originalError:
              error instanceof Error ? error.message : String(error),
          }
        );
      }

      // Return simple success response
      // If result is a string (text response), include it as message
      if (typeof result === "string") {
        return json({ success: true, message: result });
      }
      // For JSON responses, just return success
      return json({ success: true });
    } catch (error) {
      // If error is a Response (e.g., redirect from requireUserId), return it
      if (error instanceof Response) {
        return error;
      }
      // Use dynamic import to avoid bundling issues
      const { handleActionError } = await import("~/lib/error-handler.server");
      return handleActionError(error);
    }
  }
);

import type { LoaderFunctionArgs } from "@remix-run/node";

import { connectToPrimalCache } from "~/features/cache/primalCache.server";
import { ExternalServiceError } from "~/lib/errors";

/**
 * API route to fetch thread view data from Primal cache
 * GET /api/thread-view?event_id=<event_id>
 */
type AssertFunction = (
  condition: boolean,
  message: string,
  context?: Record<string, unknown>,
) => asserts condition;

export async function loader({ request }: LoaderFunctionArgs) {
  try {
    const errorHandler = await import("~/lib/error-handler.server");
    const assert: AssertFunction = errorHandler.assert;
    const url = new URL(request.url);
    const eventIdParam = url.searchParams.get("event_id");

    assert(eventIdParam !== null, "Missing event_id parameter", {
      searchParams: Array.from(url.searchParams.entries()),
    });

    const eventId = eventIdParam;

    // Fetch thread view data using centralized cache utility
    let threadViewData: unknown;
    try {
      threadViewData = await connectToPrimalCache("thread_view", {
        event_id: eventId,
      });
    } catch (error) {
      throw new ExternalServiceError(
        "Failed to fetch thread view data from cache",
        502,
        {
          service: "PrimalCache",
          eventId,
          originalError: error instanceof Error ? error.message : String(error),
        },
      );
    }

    // Parse the response to extract events and metadata
    const events: unknown[] = [];
    const metadata: Record<string, unknown> = {};

    if (Array.isArray(threadViewData)) {
      for (const item of threadViewData) {
        if (!Array.isArray(item) || item[0] !== "EVENT" || !item[2]) continue;
        const eventData: unknown = item[2] as unknown;
        if (
          !eventData ||
          typeof eventData !== "object" ||
          Array.isArray(eventData)
        )
          continue;
        const event = eventData as {
          kind?: number;
          pubkey?: string;
          content?: string;
          id?: string;
          tags?: string[][];
          created_at?: number;
        };

        // Add to events array if it's a regular event (not metadata)
        if (event.kind !== 0 && event.kind !== 10000100) {
          events.push(event);
        }

        // Extract user metadata (kind 0 events)
        if (
          event.kind === 0 &&
          event.pubkey &&
          typeof event.pubkey === "string"
        ) {
          metadata[event.pubkey] = event;
        }
      }
    }

    return {
      events,
      metadata,
      raw: threadViewData, // Include raw data for debugging
    };
  } catch (error) {
    // If error is a Response (e.g., redirect from requireUserId), return it
    if (error instanceof Response) {
      return error;
    }
    // Use dynamic import to avoid bundling issues
    const { handleLoaderError } = await import("~/lib/error-handler.server");
    return handleLoaderError(error, {});
  }
}

import type { ActionFunctionArgs } from "@remix-run/node";
import {
  json,
  unstable_composeUploadHandlers as composeUploadHandlers,
  unstable_createMemoryUploadHandler as createMemoryUploadHandler,
  unstable_parseMultipartFormData as parseMultipartFormData,
} from "@remix-run/node";

import { requireUserId } from "~/features/auth";
import {
  processImageForWeb,
  validateImageBuffer,
  getImageInfo,
} from "~/features/upload/image-resize.server";
import { uploadEditorJSImage } from "~/features/upload/s3.server";
import { loadUploadProviderSettings } from "~/features/user";
import { withCSRFProtection } from "~/lib/csrf";
import { ValidationError, ExternalServiceError } from "~/lib/errors";

const CONTENT_TYPE_MULTIPART_FORM_DATA = "multipart/form-data";

type AssertFunction = (
  condition: boolean,
  message: string,
  context?: Record<string, unknown>
) => asserts condition;

export const action = withCSRFProtection(
  async ({ request }: ActionFunctionArgs) => {
    try {
      const errorHandler = await import("~/lib/error-handler.server");
      const assert: AssertFunction = errorHandler.assert;

      // Ensure user is authenticated
      const userId = await requireUserId(request);

      // Check user's upload provider preference
      const { provider } = await loadUploadProviderSettings(userId);
      const uploadProvider = provider;

      // If user prefers blossom, handle it differently
      if (uploadProvider.includes("BLOSSOM")) {
        throw new ValidationError(
          "EditorJS uploads with Blossom are not supported. Please use the Asset Browser to insert images into your content."
        );
      }

      // Continue with S3 upload for EditorJS

      // Check content type
      const contentType = request.headers.get("content-type") ?? "";
      assert(
        contentType.includes(CONTENT_TYPE_MULTIPART_FORM_DATA),
        "Request must be multipart/form-data",
        { contentType }
      );

      let formData: FormData;
      try {
        const uploadHandler = composeUploadHandlers(
          createMemoryUploadHandler({
            maxPartSize: 10 * 1024 * 1024, // 10MB max
          })
        );
        formData = await parseMultipartFormData(request, uploadHandler);
      } catch (error) {
        throw new ExternalServiceError(
          "Failed to parse multipart form data",
          400,
          {
            originalError:
              error instanceof Error ? error.message : String(error),
          }
        );
      }

      const imageFile = formData.get("image") ?? formData.get("imageFile");
      assert(imageFile !== null, "No image file provided", {
        formDataKeys: Array.from(formData.keys()),
      });

      // Handle File object
      if (imageFile instanceof File) {
        // Validate file type
        assert(imageFile.type.startsWith("image/"), "File must be an image", {
          fileType: imageFile.type,
        });

        // Validate file size (5MB limit)
        assert(
          imageFile.size <= 5 * 1024 * 1024,
          "Image must be smaller than 5MB",
          { fileSize: imageFile.size, maxSize: 5 * 1024 * 1024 }
        );

        // Convert File to Buffer for upload
        const arrayBuffer = await imageFile.arrayBuffer();
        const buffer = Buffer.from(arrayBuffer);

        // Validate the image buffer
        const isValidImage = await validateImageBuffer(buffer);
        assert(isValidImage, "Invalid image file format");

        // Get image info for logging
        const _imageInfo = await getImageInfo(buffer);

        // Process the image with Sharp for optimization and metadata removal
        let processedBuffer: Buffer;
        try {
          processedBuffer = await processImageForWeb(buffer, {
            maxWidth: 1200,
            maxHeight: 1200,
            quality: 85,
            format: "jpeg",
          });
        } catch (error) {
          throw new ExternalServiceError("Failed to process image", 500, {
            service: "ImageProcessing",
            originalError:
              error instanceof Error ? error.message : String(error),
          });
        }

        // Upload to S3 using EditorJS-specific function
        let imageUrl: string;
        try {
          imageUrl = await uploadEditorJSImage(
            processedBuffer,
            userId,
            imageFile.name
          );
        } catch (error) {
          throw new ExternalServiceError(
            "Failed to upload image to storage",
            500,
            {
              service: "S3",
              fileName: imageFile.name,
              originalError:
                error instanceof Error ? error.message : String(error),
            }
          );
        }

        // Return EditorJS compatible response
        return json({
          success: 1,
          file: {
            url: imageUrl,
            size: processedBuffer.length,
            name: imageFile.name.replace(/\.[^/.]+$/, ".jpg"), // Always .jpg since we convert
            extension: "jpg",
          },
        });
      }

      // Handle string URL (if it's already a URL)
      if (typeof imageFile === "string" && imageFile.startsWith("https://")) {
        return json({
          success: 1,
          file: {
            url: imageFile,
            size: 0,
            name: "asset-image",
            extension: "jpg",
          },
        });
      }

      // Check if it's a File object
      // typeof null === "object" in JavaScript, but we've already asserted imageFile !== null above
      const isFile =
        typeof imageFile === "object" &&
        "name" in imageFile &&
        "size" in imageFile;
      throw new ValidationError("Invalid file format", {
        fileType: typeof imageFile,
        isFile,
      });
    } catch (error) {
      // If error is a Response (e.g., redirect from requireUserId), return it
      if (error instanceof Response) {
        return error;
      }
      // Use dynamic import to avoid bundling issues
      const { handleActionError } = await import("~/lib/error-handler.server");
      return handleActionError(error);
    }
  }
);

