          : // eslint-disable-next-line @typescript-eslint/no-unnecessary-condition -- Runtime safety: handle serialized Date strings
            a.postedAt
            ? new Date(a.postedAt)
            : new Date(0)
      ).getTime();
      const dateB = (
        b.postedAt instanceof Date
